_SCENES_63 = ("cherry", "mocha", "mint", "cobalt", "lavender", "rust", "emerald", "graphite", "goldrush", "pulse",
              "abyss", "rosegold")


def _shop_scene_63(p: QPainter, style: str, w: float, h: float, c1: QColor, c2: QColor, unit: float, rnd) -> None:
    from PyQt6.QtCore import QPointF
    from PyQt6.QtGui import QLinearGradient, QPainterPath, QPolygonF, QRadialGradient
    p.setPen(Qt.PenStyle.NoPen)
    full = QRectF(0, 0, w, h)

    def sky(top: str, a_top: float, a_bot: float, bottom: QColor = None) -> None:
        g = QLinearGradient(0, 0, 0, h)
        g.setColorAt(0, alpha(top, a_top))
        g.setColorAt(1, alpha(bottom if bottom is not None else c1, a_bot))
        p.fillRect(full, g)

    if style == "cherry":                                  # a bowl of glossy cherries on deep red
        sky("#3A0614", 0.6, 0.35, c1)
        for k in range(7):
            cx, cy, r = w * rnd.uniform(0.05, 0.95), h * rnd.uniform(0.2, 0.9), h * rnd.uniform(0.07, 0.15)
            for dx in (-0.9, 0.9):
                g = QRadialGradient(QPointF(cx + dx * r - r * 0.3, cy - r * 0.3), r * 1.3)
                g.setColorAt(0, alpha("#FFD0DA", 0.55))
                g.setColorAt(0.4, alpha(c1, 0.55))
                g.setColorAt(1, alpha("#5A0A1E", 0.6))
                p.setBrush(g)
                p.drawEllipse(QPointF(cx + dx * r, cy), r, r)
            stem = QPainterPath(QPointF(cx - 0.9 * r, cy - r * 0.9))
            stem.quadTo(QPointF(cx, cy - r * 2.4), QPointF(cx + 0.9 * r, cy - r * 0.9))
            p.setPen(QPen(alpha("#4F8F3A", 0.7), 1.4 * unit))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawPath(stem)
            p.setPen(Qt.PenStyle.NoPen)
    elif style == "mocha":                                 # latte art rings and a curl of steam
        sky("#2A1A10", 0.65, 0.5, c2)
        cen = QPointF(w * 0.7, h * 0.58)
        for k in range(7):
            f = 1 - k / 7
            p.setBrush(alpha(mix(c1, QColor("#FFF1DC"), (k % 2) * 0.7), 0.30))
            p.drawEllipse(QPointF(cen.x() - k * 1.2 * unit, cen.y() - k * 0.8 * unit), h * 0.5 * f, h * 0.36 * f)
        p.setBrush(Qt.BrushStyle.NoBrush)
        for k in range(3):
            steam = QPainterPath(QPointF(w * (0.18 + 0.07 * k), h))
            for y in range(0, int(h), 8):
                steam.lineTo(w * (0.18 + 0.07 * k) + math.sin(y / h * 6 + k) * 8 * unit, h - y)
            p.setPen(QPen(alpha("#FFF1DC", 0.22), 3 * unit, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
            p.drawPath(steam)
        p.setPen(Qt.PenStyle.NoPen)
    elif style == "mint":                                  # fresh green stripes and rising bubbles
        sky("#0B3A33", 0.5, 0.32, c2)
        for k in range(-2, 9):
            band = QPolygonF([QPointF(w * k / 6, 0), QPointF(w * (k + 0.5) / 6, 0),
                              QPointF(w * (k + 0.5) / 6 - h * 0.5, h), QPointF(w * k / 6 - h * 0.5, h)])
            p.setBrush(alpha("#FFFFFF" if k % 2 else c1, 0.09))
            p.drawPolygon(band)
        for k in range(18):
            r = rnd.uniform(2, 7) * unit
            p.setPen(QPen(alpha("#E6FFF6", 0.5), 1.0 * unit))
            p.setBrush(alpha("#E6FFF6", 0.10))
            p.drawEllipse(QPointF(w * rnd.random(), h * rnd.random()), r, r)
        p.setPen(Qt.PenStyle.NoPen)
    elif style == "cobalt":                                # blue low-poly facets
        p.fillRect(full, alpha("#061233", 0.7))
        cols, rows = 9, 5
        pts = [[QPointF(w * (i + rnd.uniform(-0.25, 0.25)) / (cols - 1), h * (j + rnd.uniform(-0.25, 0.25)) / (rows - 1))
                for i in range(cols)] for j in range(rows)]
        for j in range(rows - 1):
            for i in range(cols - 1):
                for tri in ((pts[j][i], pts[j][i + 1], pts[j + 1][i]), (pts[j][i + 1], pts[j + 1][i + 1], pts[j + 1][i])):
                    p.setBrush(alpha(mix(c1, c2, rnd.random()), rnd.uniform(0.10, 0.42)))
                    p.setPen(QPen(alpha(c2, 0.22), 0.8 * unit))
                    p.drawPolygon(QPolygonF(list(tri)))
        p.setPen(Qt.PenStyle.NoPen)
    elif style == "lavender":                              # a lavender field running to the horizon
        sky("#6B4FA8", 0.55, 0.45, c2)
        ground = QLinearGradient(0, h * 0.44, 0, h)
        ground.setColorAt(0, alpha(c1, 0.25))
        ground.setColorAt(1, alpha("#3A2570", 0.85))
        p.fillRect(QRectF(0, h * 0.44, w, h * 0.56), ground)
        for row in range(9):
            y = h * (0.45 + 0.06 * row)
            for x in range(0, int(w) + 10, max(5, int(9 - row * 0.5))):
                p.setPen(QPen(alpha(mix(c1, QColor("#5B3E9E"), row / 9), 0.35 + 0.05 * row), (1.0 + row * 0.35) * unit,
                              Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
                p.drawLine(QPointF(x + row * 2, y), QPointF(x + row * 2 + rnd.uniform(-2, 2), y - (5 + row * 2.2) * unit))
        p.setPen(Qt.PenStyle.NoPen)
    elif style == "rust":                                  # canyon mesas in layers of orange
        sky("#4A1E10", 0.55, 0.4, c2)
        for k, y0 in enumerate((0.45, 0.58, 0.72, 0.86)):
            path = QPainterPath(QPointF(0, h))
            x = 0.0
            while x < w + 20:
                top = h * (y0 + rnd.uniform(-0.06, 0.04))
                span = rnd.uniform(w * 0.08, w * 0.2)
                path.lineTo(x, top)
                path.lineTo(x + span, top)
                x += span
            path.lineTo(w, h)
            p.setBrush(alpha(mix(c1, QColor("#2A0E06"), 0.2 + k * 0.2), 0.8))
            p.drawPath(path)
    elif style == "emerald":                               # an emerald cut: nested facets and a sweep of light
        p.fillRect(full, alpha("#02201A", 0.7))
        for k in range(7):
            m = k * h * 0.07
            rr = QRectF(w * 0.12 + m * 1.3, m * 0.8 + h * 0.04, w * 0.76 - m * 2.6, h * 0.92 - m * 1.6)
            p.setBrush(alpha(mix(c1, c2, k / 7), 0.10 + 0.03 * k))
            p.setPen(QPen(alpha("#BFFFE8", 0.30), 1.0 * unit))
            p.drawRoundedRect(rr, h * 0.12, h * 0.12)
        p.setPen(Qt.PenStyle.NoPen)
        shine = QLinearGradient(QPointF(w * 0.25, 0), QPointF(w * 0.55, h))
        shine.setColorAt(0, alpha("#FFFFFF", 0.0))
        shine.setColorAt(0.5, alpha("#FFFFFF", 0.22))
        shine.setColorAt(1, alpha("#FFFFFF", 0.0))
        p.fillRect(full, shine)
    elif style == "graphite":                              # brushed steel with a soft glint
        sky("#14181D", 0.8, 0.6, c2)
        for k in range(int(h / (2.2 * unit))):
            p.fillRect(QRectF(0, k * 2.2 * unit, w, 1.0 * unit), alpha("#FFFFFF" if k % 3 else "#000000", 0.05))
        glint = QLinearGradient(QPointF(w * 0.1, 0), QPointF(w * 0.9, 0))
        glint.setColorAt(0, alpha(c1, 0.0))
        glint.setColorAt(0.35, alpha(c1, 0.30))
        glint.setColorAt(0.5, alpha("#FFFFFF", 0.35))
        glint.setColorAt(0.65, alpha(c1, 0.30))
        glint.setColorAt(1, alpha(c1, 0.0))
        p.fillRect(full, glint)
    elif style == "goldrush":                              # a treasure glow: rays of gold light and flying dust
        sky("#2A1704", 0.8, 0.5, c2)
        src = QPointF(w * 0.5, h * 1.05)
        for k in range(9):
            a = math.radians(205 + k * 16.5)
            ray = QPolygonF([src, QPointF(src.x() + math.cos(a - 0.07) * w, src.y() + math.sin(a - 0.07) * w),
                             QPointF(src.x() + math.cos(a + 0.07) * w, src.y() + math.sin(a + 0.07) * w)])
            p.setBrush(alpha(c1, 0.12))
            p.drawPolygon(ray)
        for k in range(46):
            p.setBrush(alpha(mix(c1, QColor("#FFFFFF"), rnd.random() * 0.6), rnd.uniform(0.3, 0.9)))
            r = rnd.uniform(0.8, 2.6) * unit
            p.drawEllipse(QPointF(w * rnd.random(), h * rnd.random()), r, r)
    elif style == "pulse":                                 # radar rings of neon spreading from one point
        p.fillRect(full, alpha("#14052B", 0.7))
        cen = QPointF(w * 0.3, h * 0.55)
        for k in range(9):
            r = h * (0.18 + 0.18 * k)
            p.setPen(QPen(alpha(mix(c1, c2, k / 9), max(0.05, 0.5 - 0.05 * k)), (1.6 - k * 0.1) * unit))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawEllipse(cen, r, r)
        p.setPen(Qt.PenStyle.NoPen)
        core = QRadialGradient(cen, h * 0.5)
        core.setColorAt(0, alpha(c1, 0.55))
        core.setColorAt(1, alpha(c1, 0.0))
        p.setBrush(core)
        p.drawEllipse(cen, h * 0.5, h * 0.5)
    elif style == "abyss":                                 # deep sea: glowing jellyfish drifting in the dark
        sky("#010A1C", 0.85, 0.7, c2)
        for k in range(6):
            cx, cy, r = w * rnd.uniform(0.08, 0.92), h * rnd.uniform(0.15, 0.7), h * rnd.uniform(0.07, 0.14)
            glow = QRadialGradient(QPointF(cx, cy), r * 2.6)
            glow.setColorAt(0, alpha(c1, 0.35))
            glow.setColorAt(1, alpha(c1, 0.0))
            p.setBrush(glow)
            p.drawEllipse(QPointF(cx, cy), r * 2.6, r * 2.6)
            bell = QPainterPath(QPointF(cx - r, cy))
            bell.arcTo(QRectF(cx - r, cy - r, 2 * r, 2 * r), 180, -180)
            bell.closeSubpath()
            p.setBrush(alpha(c1, 0.35))
            p.drawPath(bell)
            p.setPen(QPen(alpha(c1, 0.35), 1.1 * unit))
            for t in range(5):
                x = cx - r * 0.8 + t * r * 0.4
                tent = QPainterPath(QPointF(x, cy))
                tent.quadTo(QPointF(x + rnd.uniform(-6, 6) * unit, cy + r * 1.1), QPointF(x + rnd.uniform(-4, 4) * unit, cy + r * 2.1))
                p.setBrush(Qt.BrushStyle.NoBrush)
                p.drawPath(tent)
            p.setPen(Qt.PenStyle.NoPen)
        for k in range(30):
            p.setBrush(alpha(c1, rnd.uniform(0.15, 0.5)))
            p.drawEllipse(QPointF(w * rnd.random(), h * rnd.random()), 1.2 * unit, 1.2 * unit)
    elif style == "rosegold":                              # satin folds in rose gold
        sky("#5A2A33", 0.6, 0.5, c2)
        for k in range(6):
            path = QPainterPath(QPointF(0, h))
            for x in range(0, int(w) + 8, 8):
                path.lineTo(x, h * (0.25 + 0.13 * k) + math.sin(x / w * 4.5 + k * 0.9) * h * 0.14)
            path.lineTo(w, h)
            g = QLinearGradient(0, h * 0.2, 0, h)
            g.setColorAt(0, alpha(mix(c1, QColor("#FFFFFF"), 0.35), 0.38))
            g.setColorAt(1, alpha(c2, 0.30))
            p.setBrush(g)
            p.setPen(QPen(alpha("#FFE6DC", 0.35), 1.0 * unit))
            p.drawPath(path)
        p.setPen(Qt.PenStyle.NoPen)
        for k in range(12):
            _s = rnd.uniform(1.5, 4) * unit
            p.setBrush(alpha("#FFFFFF", rnd.uniform(0.35, 0.8)))
            p.drawEllipse(QPointF(w * rnd.random(), h * rnd.random()), _s * 0.5, _s * 0.5)


# --------------------------------------------------------------------------- #
# 6.5: the pictures behind ten more app colour themes
# --------------------------------------------------------------------------- #
_SCENES_65 = ("peach", "slate", "honey", "berry", "twilight", "coral", "wasabi", "solar", "nightbloom", "cyber")


def _shop_scene_65(p: QPainter, style: str, w: float, h: float, c1: QColor, c2: QColor, unit: float, rnd) -> None:
    from PyQt6.QtCore import QPointF
    from PyQt6.QtGui import QLinearGradient, QPainterPath, QPolygonF, QRadialGradient
    p.setPen(Qt.PenStyle.NoPen)
    full = QRectF(0, 0, w, h)

    def sky(top, a_top, a_bot, bottom=None) -> None:
        g = QLinearGradient(0, 0, 0, h)
        g.setColorAt(0, alpha(top, a_top))
        g.setColorAt(1, alpha(bottom if bottom is not None else c1, a_bot))
        p.fillRect(full, g)

    if style == "peach":                                   # soft light and big round shapes
        sky("#7A3B3B", 0.45, 0.4, c2)
        for k in range(8):
            r = h * rnd.uniform(0.2, 0.6)
            cen = QPointF(w * rnd.random(), h * rnd.random())
            g = QRadialGradient(cen, r)
            g.setColorAt(0, alpha(mix(c1, c2, rnd.random()), 0.45))
            g.setColorAt(1, alpha(c1, 0.0))
            p.setBrush(g)
            p.drawEllipse(cen, r, r)
    elif style == "slate":                                 # layered grey-blue shards
        p.fillRect(full, alpha("#10151B", 0.75))
        for k in range(14):
            x = w * rnd.random()
            poly = QPolygonF([QPointF(x, 0), QPointF(x + w * rnd.uniform(0.1, 0.3), 0), QPointF(x + w * rnd.uniform(-0.2, 0.1), h)])
            p.setBrush(alpha(mix(c1, c2, rnd.random()), rnd.uniform(0.08, 0.3)))
            p.setPen(QPen(alpha(c1, 0.15), 1.0 * unit))
            p.drawPolygon(poly)
        p.setPen(Qt.PenStyle.NoPen)
    elif style == "honey":                                 # a hexagon comb full of amber light
        sky("#2A1A04", 0.7, 0.45, c2)
        s = h * 0.17
        for row in range(-1, int(h / (s * 1.5)) + 2):
            for col in range(-1, int(w / (s * 1.75)) + 2):
                cx = col * s * 1.75 + (s * 0.87 if row % 2 else 0)
                cy = row * s * 1.5
                hexa = QPolygonF([QPointF(cx + math.cos(math.radians(60 * i + 30)) * s * 0.92, cy + math.sin(math.radians(60 * i + 30)) * s * 0.92) for i in range(6)])
                p.setBrush(alpha(c1, rnd.uniform(0.04, 0.34)))
                p.setPen(QPen(alpha("#FFE08A", 0.3), 1.0 * unit))
                p.drawPolygon(hexa)
        p.setPen(Qt.PenStyle.NoPen)
    elif style == "berry":                                 # clusters of glossy berries
        sky("#2A0830", 0.7, 0.4, c2)
        for k in range(5):
            cx, cy = w * rnd.uniform(0.1, 0.9), h * rnd.uniform(0.2, 0.8)
            for j in range(9):
                r = h * rnd.uniform(0.04, 0.07)
                pt = QPointF(cx + rnd.uniform(-1, 1) * h * 0.14, cy + rnd.uniform(-1, 1) * h * 0.14)
                g = QRadialGradient(QPointF(pt.x() - r * 0.3, pt.y() - r * 0.3), r * 1.4)
                g.setColorAt(0, alpha("#F6C8FF", 0.6))
                g.setColorAt(0.4, alpha(c1, 0.6))
                g.setColorAt(1, alpha("#3A0A4A", 0.7))
                p.setBrush(g)
                p.drawEllipse(pt, r, r)
    elif style == "twilight":                              # dusk sky, a first moon and star, dark hills
        g = QLinearGradient(0, 0, 0, h)
        g.setColorAt(0, alpha("#1B1050", 0.8))
        g.setColorAt(0.6, alpha(c1, 0.5))
        g.setColorAt(1, alpha(c2, 0.5))
        p.fillRect(full, g)
        for k in range(30):
            p.setBrush(alpha("#FFFFFF", rnd.uniform(0.2, 0.8)))
            p.drawEllipse(QPointF(w * rnd.random(), h * rnd.random() * 0.55), 1.0 * unit, 1.0 * unit)
        p.setBrush(QColor("#FFF1C8"))
        p.drawEllipse(QPointF(w * 0.78, h * 0.25), h * 0.08, h * 0.08)
        for k, y0 in enumerate((0.68, 0.8)):
            path = QPainterPath(QPointF(0, h))
            for x in range(0, int(w) + 10, 10):
                path.lineTo(x, h * y0 + math.sin(x / w * 5 + k * 2) * h * 0.06)
            path.lineTo(w, h)
            p.setBrush(alpha("#0C0620", 0.7 + 0.2 * k))
            p.drawPath(path)
    elif style == "coral":                                 # branching coral on a teal sea floor
        sky("#03323A", 0.6, 0.5, c2)
        for k in range(6):
            x0 = w * (0.08 + 0.16 * k)
            stack = [(QPointF(x0, h), -90.0, h * 0.3, 3.2 * unit, 0)]
            while stack:
                pt, ang, ln, wd, dep = stack.pop()
                end = QPointF(pt.x() + math.cos(math.radians(ang)) * ln, pt.y() + math.sin(math.radians(ang)) * ln)
                p.setPen(QPen(alpha(mix(c1, c2, dep / 4), 0.75), wd, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
                p.drawLine(pt, end)
                if dep < 3:
                    stack.append((end, ang - rnd.uniform(15, 40), ln * 0.7, wd * 0.7, dep + 1))
                    stack.append((end, ang + rnd.uniform(15, 40), ln * 0.7, wd * 0.7, dep + 1))
        p.setPen(Qt.PenStyle.NoPen)
    elif style == "wasabi":                                # a lime sunburst
        sky("#103A0A", 0.55, 0.4, c2)
        cen = QPointF(w * 0.5, h * 0.5)
        for k in range(18):
            a0 = math.radians(k * 20)
            tri = QPolygonF([cen, QPointF(cen.x() + math.cos(a0) * w, cen.y() + math.sin(a0) * w),
                             QPointF(cen.x() + math.cos(a0 + 0.17) * w, cen.y() + math.sin(a0 + 0.17) * w)])
            p.setBrush(alpha(c1 if k % 2 else "#FFFFFF", 0.12))
            p.drawPolygon(tri)
        core = QRadialGradient(cen, h * 0.5)
        core.setColorAt(0, alpha("#F4FFD0", 0.7))
        core.setColorAt(1, alpha(c1, 0.0))
        p.setBrush(core)
        p.drawEllipse(cen, h * 0.5, h * 0.5)
    elif style == "solar":                                 # a sun with flares
        sky("#1A0602", 0.85, 0.6, c2)
        cen = QPointF(w * 0.7, h * 0.5)
        for k in range(14):
            a = math.radians(k * 25.7)
            ln = h * rnd.uniform(0.5, 0.95)
            p.setPen(QPen(alpha(c1, 0.35), 2.4 * unit, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
            p.drawLine(QPointF(cen.x() + math.cos(a) * h * 0.3, cen.y() + math.sin(a) * h * 0.3),
                       QPointF(cen.x() + math.cos(a) * ln, cen.y() + math.sin(a) * ln))
        p.setPen(Qt.PenStyle.NoPen)
        glow = QRadialGradient(cen, h * 0.7)
        glow.setColorAt(0, alpha("#FFF2B0", 0.95))
        glow.setColorAt(0.3, alpha(c1, 0.7))
        glow.setColorAt(1, alpha(c2, 0.0))
        p.setBrush(glow)
        p.drawEllipse(cen, h * 0.7, h * 0.7)
    elif style == "nightbloom":                            # glowing flowers in the dark
        p.fillRect(full, alpha("#05030F", 0.85))
        for k in range(6):
            cen = QPointF(w * rnd.uniform(0.08, 0.92), h * rnd.uniform(0.25, 0.8))
            r = h * rnd.uniform(0.12, 0.22)
            glow = QRadialGradient(cen, r * 2)
            glow.setColorAt(0, alpha(c1, 0.35))
            glow.setColorAt(1, alpha(c1, 0.0))
            p.setBrush(glow)
            p.drawEllipse(cen, r * 2, r * 2)
            for j in range(8):
                p.save()
                p.translate(cen)
                p.rotate(j * 45)
                p.setBrush(alpha(mix(c1, c2, j / 8), 0.45))
                p.setPen(QPen(alpha("#FFFFFF", 0.25), 0.8 * unit))
                p.drawEllipse(QPointF(r * 0.55, 0), r * 0.55, r * 0.22)
                p.restore()
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(alpha("#FFF6C8", 0.8))
            p.drawEllipse(cen, r * 0.12, r * 0.12)
    elif style == "cyber":                                 # circuit traces with glowing nodes
        p.fillRect(full, alpha("#04081A", 0.85))
        for k in range(16):
            x, y = w * rnd.random(), h * rnd.random()
            path = QPainterPath(QPointF(x, y))
            for j in range(4):
                if rnd.random() < 0.5:
                    x += rnd.choice((-1, 1)) * w * rnd.uniform(0.05, 0.2)
                else:
                    y += rnd.choice((-1, 1)) * h * rnd.uniform(0.1, 0.3)
                path.lineTo(x, y)
            col = c1 if k % 2 else c2
            p.setPen(QPen(alpha(col, 0.55), 1.4 * unit))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawPath(path)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(alpha(col, 0.95))
            p.drawEllipse(QPointF(x, y), 2.4 * unit, 2.4 * unit)


# --------------------------------------------------------------------------- #
# 6.7: the pictures behind ten more app colour themes (all moving)
# --------------------------------------------------------------------------- #
_SCENES_66 = ("monsoon", "sahara", "bamboo", "neonrain", "lanterns", "quartz", "lavalamp", "wormhole", "polarlights", "chrome")


def _shop_scene_66(p: QPainter, style: str, w: float, h: float, c1: QColor, c2: QColor, unit: float, rnd) -> None:
    from PyQt6.QtCore import QPointF
    from PyQt6.QtGui import QLinearGradient, QPainterPath, QPolygonF, QRadialGradient
    t = time.time() % 100000
    p.setPen(Qt.PenStyle.NoPen)
    full = QRectF(0, 0, w, h)

    def vgrad(a, b, aa=1.0, ba=1.0) -> None:
        g = QLinearGradient(0, 0, 0, h)
        g.setColorAt(0, alpha(a, aa))
        g.setColorAt(1, alpha(b, ba))
        p.fillRect(full, g)

    def glow(cx: float, cy: float, r: float, col, a: float) -> None:
        g = QRadialGradient(QPointF(cx, cy), r)
        g.setColorAt(0, alpha(col, a))
        g.setColorAt(1, alpha(col, 0.0))
        p.setBrush(g)
        p.drawEllipse(QPointF(cx, cy), r, r)

    if style == "monsoon":                                 # heavy rain on a dark teal sky, rings spreading on the water, far lightning
        vgrad("#03141B", c2, 0.95, 0.9)
        fl = max(0.0, math.sin(t * 0.55)) ** 40
        if fl > 0.02:
            p.fillRect(full, alpha("#DFF6FF", 0.16 * fl))
        for k in range(110):
            x0, sp, ph = w * rnd.random(), rnd.uniform(0.6, 1.4), rnd.random()
            u = (t * sp * 0.9 + ph) % 1.0
            y = (u * 1.15 - 0.1) * h
            ln = h * 0.05 * sp
            p.setPen(QPen(alpha(mix(c1, QColor("#FFFFFF"), 0.5), 0.15 + 0.3 * sp / 1.4), 1.0 * unit))
            p.drawLine(QPointF(x0 + y * 0.12, y), QPointF(x0 + (y + ln) * 0.12 - 1, y + ln))
        p.setPen(Qt.PenStyle.NoPen)
        p.fillRect(QRectF(0, h * 0.86, w, h * 0.14), alpha(c2, 0.55))
        for k in range(16):
            u = (t * 0.55 + rnd.random()) % 1.0
            cx, cy = w * rnd.random(), h * (0.88 + 0.1 * rnd.random())
            p.setPen(QPen(alpha(c1, 0.55 * (1 - u)), 1.0 * unit))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawEllipse(QPointF(cx, cy), u * w * 0.05, u * w * 0.012)
        p.setPen(Qt.PenStyle.NoPen)
    elif style == "sahara":                                # a low sun over sand dunes, heat shimmer and blowing sand
        vgrad("#FFD79A", c2, 0.9, 0.95)
        glow(w * 0.72, h * 0.3, h * 0.55, "#FFF1C2", 0.7)
        p.setBrush(alpha("#FFF8DC", 0.95))
        p.drawEllipse(QPointF(w * 0.72, h * 0.3), h * 0.07, h * 0.07)
        for j, (by, col) in enumerate(((0.52, "#E9A25A"), (0.62, "#D9823F"), (0.74, "#B8612C"), (0.88, "#8C4521"))):
            path = QPainterPath(QPointF(0, h))
            ph = rnd.uniform(0, 6)
            for x in range(0, int(w) + 10, 10):
                y = h * by + math.sin(x / w * (2.6 + j) + ph + t * 0.03 * (j + 1)) * h * 0.05 + math.sin(x / w * 7 + ph) * h * 0.012
                path.lineTo(x, y)
            path.lineTo(w, h)
            p.setBrush(QColor(col))
            p.drawPath(path)
        for k in range(5):
            y = h * (0.5 + 0.02 * k)
            path = QPainterPath()
            for x in range(0, int(w) + 8, 8):
                yy = y + math.sin(x / w * 18 + t * 1.6 + k) * h * 0.004
                path.lineTo(x, yy) if x else path.moveTo(x, yy)
            p.setPen(QPen(alpha("#FFFFFF", 0.10), 1.6 * unit))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawPath(path)
        p.setPen(Qt.PenStyle.NoPen)
        for k in range(45):
            x = (w * rnd.random() + t * w * 0.05 * (0.5 + rnd.random())) % w
            p.setBrush(alpha("#FFE3B0", 0.35))
            p.drawEllipse(QPointF(x, h * (0.55 + 0.4 * rnd.random())), 1.3 * unit, 1.0 * unit)
    elif style == "bamboo":                                # tall stalks swaying in light shafts, leaves drifting down
        vgrad("#06180C", c2, 0.95, 0.95)
        for k in range(5):
            x = w * (0.1 + 0.2 * k) + math.sin(t * 0.3 + k) * w * 0.02
            poly = QPolygonF([QPointF(x, 0), QPointF(x + w * 0.06, 0), QPointF(x - w * 0.12, h), QPointF(x - w * 0.2, h)])
            p.setBrush(alpha("#E8FFD0", 0.05 + 0.03 * math.sin(t * 0.8 + k * 2)))
            p.drawPolygon(poly)
        for k in range(10):
            x0 = w * (0.04 + 0.1 * k + rnd.uniform(-0.02, 0.02))
            rnd.random()                                   # one draw kept so the pattern stays the same
            seg = 9
            pts = [QPointF(x0 + math.sin(t * 0.7 + k) * w * 0.012 * (j / seg) ** 2, h * (1 - j / seg)) for j in range(seg + 1)]
            thick = w * 0.016 * (0.7 + 0.5 * rnd.random())
            for a, b in zip(pts, pts[1:]):
                g = QLinearGradient(a.x() - thick, 0, a.x() + thick, 0)
                g.setColorAt(0, mix(c2, QColor("#000000"), 0.3))
                g.setColorAt(0.5, c1)
                g.setColorAt(1, mix(c2, QColor("#000000"), 0.4))
                p.setPen(QPen(g, thick * 2, Qt.PenStyle.SolidLine, Qt.PenCapStyle.FlatCap))
                p.drawLine(a, b)
            p.setPen(QPen(alpha("#0A2A12", 0.8), 1.6 * unit))
            for a in pts[1:-1]:
                p.drawLine(QPointF(a.x() - thick, a.y()), QPointF(a.x() + thick, a.y()))
            p.setPen(Qt.PenStyle.NoPen)
            for j in (3, 6):
                a = pts[j]
                sway = math.sin(t * 1.3 + k + j) * 8
                for side in (-1, 1):
                    p.save()
                    p.translate(a)
                    p.rotate(side * (35 + sway))
                    p.setBrush(alpha(mix(c1, QColor("#C8FFB0"), 0.4), 0.8))
                    p.drawEllipse(QPointF(side * w * 0.03, 0), w * 0.032, w * 0.007)
                    p.restore()
        for k in range(12):
            u = (t * 0.05 * (0.6 + rnd.random()) + rnd.random()) % 1.0
            p.save()
            p.translate(w * ((rnd.random() + u * 0.2) % 1.0), u * h)
            p.rotate(u * 400 + k * 30)
            p.setBrush(alpha("#B9F29A", 0.55))
            p.drawEllipse(QPointF(0, 0), w * 0.012, w * 0.004)
            p.restore()
    elif style == "neonrain":                              # a wet night street: neon tubes flickering, coloured rain, reflections
        p.fillRect(full, QColor("#05020F"))
        horizon = h * 0.62
        for k in range(8):
            x = w * (0.06 + 0.125 * k)
            col = c1 if k % 2 else c2
            fl = 0.75 + 0.25 * math.sin(t * (2 + k * 0.7) + k) * (1 if (int(t * 3 + k) % 9) else 0.3)
            top, bot = h * (0.18 + 0.06 * (k % 3)), horizon - h * 0.02
            glow(x, (top + bot) / 2, h * 0.3, col, 0.28 * fl)
            p.setPen(QPen(alpha(col, 0.95 * fl), 3.2 * unit, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
            p.drawLine(QPointF(x, top), QPointF(x, bot))
            p.setPen(QPen(alpha("#FFFFFF", 0.7 * fl), 1.0 * unit))
            p.drawLine(QPointF(x, top), QPointF(x, bot))
            g = QLinearGradient(0, horizon, 0, h)
            g.setColorAt(0, alpha(col, 0.38 * fl))
            g.setColorAt(1, alpha(col, 0.0))
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(g)
            p.drawRect(QRectF(x - w * 0.012 + math.sin(t * 2 + k) * 2, horizon, w * 0.024, h - horizon))
        p.setPen(Qt.PenStyle.NoPen)
        p.fillRect(QRectF(0, horizon - 1, w, 2 * unit), alpha("#FFFFFF", 0.12))
        for k in range(90):
            x0, sp = w * rnd.random(), rnd.uniform(0.8, 1.6)
            u = (t * sp * 1.2 + rnd.random()) % 1.0
            y = u * h
            col = c1 if k % 2 else c2
            p.setPen(QPen(alpha(col, 0.5), 1.0 * unit))
            p.drawLine(QPointF(x0, y), QPointF(x0 - 2, y + h * 0.04))
        p.setPen(Qt.PenStyle.NoPen)
    elif style == "lanterns":                              # paper lanterns floating up into a night sky
        vgrad("#080414", c2, 1.0, 0.55)
        for k in range(50):
            p.setBrush(alpha("#FFFFFF", 0.25 + 0.3 * abs(math.sin(t * 1.2 + k * 1.7))))
            p.drawEllipse(QPointF(w * rnd.random(), h * rnd.random() * 0.7), 1.1 * unit, 1.1 * unit)
        lan = []
        for k in range(26):
            depth = rnd.uniform(0.35, 1.0)
            lan.append((depth, k, rnd.random(), rnd.random(), rnd.uniform(0.03, 0.06)))
        for depth, k, ph, xr, sp in sorted(lan):
            u = (t * sp * depth + ph) % 1.0
            x = w * xr + math.sin(t * 0.5 + k) * w * 0.02
            y = h * (1.08 - u * 1.2)
            sz = h * 0.07 * depth
            glow(x, y, sz * 3.4, c1, 0.34 * depth)
            body = QRectF(x - sz * 0.62, y - sz, sz * 1.24, sz * 1.7)
            g = QLinearGradient(body.topLeft(), body.bottomLeft())
            g.setColorAt(0, mix(c1, QColor("#FFFFFF"), 0.35))
            g.setColorAt(0.6, c1)
            g.setColorAt(1, c2)
            p.setBrush(g)
            p.drawRoundedRect(body, sz * 0.4, sz * 0.5)
            p.setBrush(alpha("#5A1E10", 0.7))
            p.drawRect(QRectF(x - sz * 0.45, y - sz * 1.03, sz * 0.9, sz * 0.12))
            p.drawRect(QRectF(x - sz * 0.45, y + sz * 0.66, sz * 0.9, sz * 0.12))
            p.setBrush(alpha("#FFF3B0", 0.8 * depth))
            p.drawEllipse(QPointF(x, y), sz * 0.16, sz * 0.26)
    elif style == "quartz":                                # a cluster of crystals with light sweeping across their facets
        vgrad("#0D0820", c2, 1.0, 0.45)
        glow(w * 0.5, h * 0.9, h * 0.8, c1, 0.25)
        crystals = []
        for k in range(9):
            crystals.append((rnd.uniform(0.04, 0.96), rnd.uniform(0.18, 0.34), rnd.uniform(0.5, 0.9), rnd.uniform(-0.04, 0.04)))
        tips = []
        for x, bw, ht, tilt in sorted(crystals, key=lambda c: -c[2]):
            cx, bwp, top = w * x, w * bw * 0.45, h * (1 - ht * 0.8)
            pts = [QPointF(cx - bwp, h), QPointF(cx - bwp * 0.8, top + h * 0.12), QPointF(cx + w * tilt, top),
                   QPointF(cx + bwp * 0.8, top + h * 0.12), QPointF(cx + bwp, h)]
            mid = QPointF(cx + w * tilt * 0.4, h)
            p.setBrush(alpha(mix(c1, QColor("#FFFFFF"), 0.2), 0.62))
            p.setPen(QPen(alpha("#FFFFFF", 0.3), 1.0 * unit))
            p.drawPolygon(QPolygonF([pts[0], pts[1], pts[2], mid]))
            p.setBrush(alpha(mix(c2, QColor("#FFFFFF"), 0.15), 0.62))
            p.drawPolygon(QPolygonF([mid, pts[2], pts[3], pts[4]]))
            tips.append(pts[2])
        sweep = ((t * 0.22) % 1.6 - 0.3) * w
        p.setPen(Qt.PenStyle.NoPen)
        g = QLinearGradient(QPointF(sweep - w * 0.12, 0), QPointF(sweep + w * 0.12, h * 0.4))
        g.setColorAt(0, alpha("#FFFFFF", 0.0))
        g.setColorAt(0.5, alpha("#FFFFFF", 0.20))
        g.setColorAt(1, alpha("#FFFFFF", 0.0))
        p.setBrush(g)
        p.drawPolygon(QPolygonF([QPointF(sweep - w * 0.1, 0), QPointF(sweep + w * 0.1, 0), QPointF(sweep + w * 0.02, h), QPointF(sweep - w * 0.18, h)]))
        for k, tip in enumerate(tips):
            a = max(0.0, math.sin(t * 1.5 + k * 1.9))
            r = h * 0.03 * a
            p.setBrush(alpha("#FFFFFF", 0.9 * a))
            p.drawPolygon(QPolygonF([QPointF(tip.x(), tip.y() - r * 2), QPointF(tip.x() + r * 0.5, tip.y()), QPointF(tip.x(), tip.y() + r * 2),
                                     QPointF(tip.x() - r * 0.5, tip.y())]))
    elif style == "lavalamp":                              # a lava lamp: warm blobs rising, merging and sinking
        vgrad(mix(c2, QColor("#000000"), 0.55), c2, 1.0, 0.9)
        glow(w * 0.5, h * 1.05, h * 0.9, c1, 0.45)
        for k in range(11):
            sp, ph = rnd.uniform(0.16, 0.34), rnd.uniform(0, 6.28)
            x = w * (0.14 + 0.72 * rnd.random()) + math.sin(t * 0.45 + k) * w * 0.04
            y = h * (0.5 - 0.5 * math.cos(t * sp + ph) * 0.95)
            r = h * rnd.uniform(0.09, 0.19)
            sx = 1 + 0.18 * math.sin(t * 0.9 + k)
            for rr, a in ((1.55, 0.18), (1.2, 0.34), (0.9, 0.9)):
                g = QRadialGradient(QPointF(x, y), r * rr)
                g.setColorAt(0, alpha(mix(c1, QColor("#FFE0A0"), 0.25), a))
                g.setColorAt(1, alpha(c1, 0.0 if rr > 1 else a * 0.7))
                p.setBrush(g)
                p.drawEllipse(QPointF(x, y), r * rr * sx, r * rr / sx)
            p.setBrush(alpha("#FFFFFF", 0.3))
            p.drawEllipse(QPointF(x - r * 0.3, y - r * 0.3), r * 0.18, r * 0.12)
    elif style == "wormhole":                              # flying down a tunnel of glowing rings, stars streaking past
        p.fillRect(full, QColor("#02030C"))
        cx, cy = w * 0.5, h * 0.5
        R = math.hypot(w, h) * 0.55
        for k in range(20):
            u = (t * 0.32 + k / 20) % 1.0
            r = (u ** 2.3) * R
            col = mix(c1, c2, (k / 20 + t * 0.05) % 1.0)
            p.setPen(QPen(alpha(col, min(1.0, u * 3) * (1 - u * 0.35) * 0.75), (1 + 4 * u) * unit))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawEllipse(QPointF(cx, cy), r * 1.12, r * 0.86)
        for k in range(16):
            a = k * math.pi / 8 + t * 0.15
            p.setPen(QPen(alpha(c2, 0.10), 1.0 * unit))
            p.drawLine(QPointF(cx + math.cos(a) * R * 0.1, cy + math.sin(a) * R * 0.1), QPointF(cx + math.cos(a) * R * 1.12, cy + math.sin(a) * R * 0.86))
        for k in range(70):
            a, ph = rnd.uniform(0, 6.283), rnd.random()
            u = (t * 0.5 + ph) % 1.0
            d0, d1 = (u ** 2) * R, (min(1.0, u + 0.06) ** 2) * R
            p.setPen(QPen(alpha("#FFFFFF", 0.2 + 0.7 * u), (0.8 + 1.6 * u) * unit, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
            p.drawLine(QPointF(cx + math.cos(a) * d0 * 1.12, cy + math.sin(a) * d0 * 0.86), QPointF(cx + math.cos(a) * d1 * 1.12, cy + math.sin(a) * d1 * 0.86))
        p.setPen(Qt.PenStyle.NoPen)
        glow(cx, cy, h * 0.22 * (1 + 0.1 * math.sin(t * 2)), "#FFFFFF", 0.7)
        glow(cx, cy, h * 0.5, c1, 0.25)
    elif style == "polarlights":                           # curtains of green and violet light waving over mountains and stars
        vgrad("#01040C", "#08122A", 1.0, 1.0)
        for k in range(70):
            p.setBrush(alpha("#FFFFFF", 0.2 + 0.5 * abs(math.sin(t * 0.9 + k * 2.3))))
            p.drawEllipse(QPointF(w * rnd.random(), h * rnd.random() * 0.75), 1.0 * unit, 1.0 * unit)
        for k in range(4):
            top, bot = [], []
            for x in range(0, int(w) + 12, 12):
                y0 = h * (0.2 + 0.07 * k) + math.sin(x / w * 3.2 + t * 0.35 + k * 1.3) * h * 0.07
                ht = h * (0.22 + 0.12 * math.sin(x / w * 6.5 - t * 0.6 + k)) + h * 0.05
                top.append(QPointF(x, y0))
                bot.append(QPointF(x, y0 + ht))
            path = QPainterPath(top[0])
            for q in top[1:]:
                path.lineTo(q)
            for q in reversed(bot):
                path.lineTo(q)
            path.closeSubpath()
            col = mix(c1, c2, (k / 4 + 0.15 * math.sin(t * 0.2)) % 1.0)
            g = QLinearGradient(0, h * 0.15, 0, h * 0.7)
            g.setColorAt(0, alpha(col, 0.55))
            g.setColorAt(0.6, alpha(col, 0.22))
            g.setColorAt(1, alpha(col, 0.0))
            p.setBrush(g)
            p.drawPath(path)
            p.setPen(QPen(alpha(col, 0.14), 1.0 * unit))
            for q, q2 in list(zip(top, bot))[::2]:
                p.drawLine(q, q2)
            p.setPen(Qt.PenStyle.NoPen)
        ground = QPainterPath(QPointF(0, h))
        for x in range(0, int(w) + 10, 10):
            ground.lineTo(x, h * 0.84 - abs(math.sin(x / w * 4.1 + 1)) * h * 0.1 - abs(math.sin(x / w * 9.3)) * h * 0.03)
        ground.lineTo(w, h)
        p.setBrush(QColor("#030711"))
        p.drawPath(ground)
    elif style == "chrome":                                # liquid chrome: bands of mirror-bright metal flowing past
        p.fillRect(full, QColor("#080A12"))
        n = 9
        waves = []
        for k in range(n + 1):
            pts = []
            for x in range(0, int(w) + 14, 14):
                y = h * (k / n) + math.sin(x / w * 3.4 + t * 0.5 + k * 0.8) * h * 0.06 + math.sin(x / w * 8 - t * 0.7 + k) * h * 0.02
                pts.append(QPointF(x, y))
            waves.append(pts)
        for k in range(n):
            path = QPainterPath(waves[k][0])
            for q in waves[k][1:]:
                path.lineTo(q)
            for q in reversed(waves[k + 1]):
                path.lineTo(q)
            path.closeSubpath()
            off = (t * 0.12 + k * 0.13) % 1.0
            g = QLinearGradient(QPointF(w * (off - 0.5), 0), QPointF(w * (off + 0.5), h * 0.3))
            for pos, col in ((0.0, QColor("#F4F8FF")), (0.25, c1), (0.5, QColor("#1B2030")), (0.75, c2), (1.0, QColor("#F4F8FF"))):
                g.setColorAt(pos, col)
            g.setSpread(QLinearGradient.Spread.ReflectSpread)
            p.setBrush(g)
            p.setPen(QPen(alpha("#FFFFFF", 0.35), 1.0 * unit))
            p.drawPath(path)
        p.setPen(Qt.PenStyle.NoPen)
    p.setPen(Qt.PenStyle.NoPen)


def _shop_scene(p: QPainter, style: str, w: float, h: float, c1: QColor, c2: QColor, unit: float) -> None:
    """3.1: the shop themes each have their own picture, not the night sky. The dearer, the richer."""
    import random
    from PyQt6.QtCore import QPointF
    from PyQt6.QtGui import QLinearGradient, QPainterPath, QPolygonF, QRadialGradient
    p.setPen(Qt.PenStyle.NoPen)
    rnd = random.Random(hash(style) & 0xFFFF)
    cw = _CW.get(("theme", style))
    if cw:                                                     # 6.5: a colourway: the scene, recoloured (drawn at half size)
        bt = next(t for t in THEME_LOOKS if t[0] == cw[0])
        img, ip = _cw_layer(p, w, h, 0.5)
        _shop_scene(ip, cw[0], w, h, QColor(bt[2]), QColor(bt[3]), unit)
        ip.end()
        p.save()
        p.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform)
        p.drawImage(QRectF(0, 0, w, h), recolour_image(img, cw[1]))
        p.restore()
        return
    if style in _SCENES_66:
        return _shop_scene_66(p, style, w, h, c1, c2, unit, random.Random(sum(map(ord, style))))
    if style in _SCENES_65:
        return _shop_scene_65(p, style, w, h, c1, c2, unit, random.Random(sum(map(ord, style))))
    if style in _SCENES_63:
        return _shop_scene_63(p, style, w, h, c1, c2, unit, random.Random(sum(map(ord, style))))
    if style == "sunset":                                 # warm sky, a striped sun on the horizon, dark hills
        g = QLinearGradient(0, 0, 0, h)
        g.setColorAt(0, alpha("#5B1E5F", 0.55))
        g.setColorAt(0.6, alpha(c2, 0.35))
        g.setColorAt(1, alpha(c1, 0.30))
        p.fillRect(QRectF(0, 0, w, h), g)
        sun = QPointF(w * 0.72, h * 0.62)
        sg = QLinearGradient(0, sun.y() - h * 0.32, 0, sun.y())
        sg.setColorAt(0, QColor("#FFD36B"))
        sg.setColorAt(1, c2)
        p.setBrush(sg)
        p.drawEllipse(sun, h * 0.32, h * 0.32)
        disc = QPainterPath()
        disc.addEllipse(sun, h * 0.32, h * 0.32)
        p.save()
        p.setClipPath(disc)
        for k in range(4):                                # stripes cut through the sun
            p.fillRect(QRectF(sun.x() - h * 0.34, sun.y() - h * (0.05 + 0.065 * k), h * 0.68, h * 0.018 * (k + 1) * 0.6),
                       alpha("#2B0F3D", 0.8))
        p.restore()
        for k, (y0, a) in enumerate(((0.66, 0.75), (0.76, 0.9))):
            path = QPainterPath(QPointF(0, h))
            for x in range(0, int(w) + 10, 10):
                path.lineTo(x, h * y0 + math.sin(x / w * 7 + k * 2) * h * 0.05)
            path.lineTo(w, h)
            p.setBrush(alpha("#1A0A22", a))
            p.drawPath(path)
    elif style == "ocean":                                # light from above and layers of waves
        g = QLinearGradient(0, 0, 0, h)
        g.setColorAt(0, alpha(c1, 0.40))
        g.setColorAt(1, alpha("#03203F", 0.55))
        p.fillRect(QRectF(0, 0, w, h), g)
        for k in range(5):
            x0 = w * (0.1 + 0.2 * k)
            ray = QPainterPath(QPointF(x0 - w * 0.03, 0))
            ray.lineTo(x0 + w * 0.03, 0)
            ray.lineTo(x0 + w * 0.14, h)
            ray.lineTo(x0 - w * 0.02, h)
            rg = QLinearGradient(0, 0, 0, h)
            rg.setColorAt(0, alpha("#BFF4FF", 0.16))
            rg.setColorAt(1, alpha("#BFF4FF", 0.0))
            p.setBrush(rg)
            p.drawPath(ray)
        for k in range(4):
            path = QPainterPath(QPointF(0, h))
            for x in range(0, int(w) + 8, 8):
                path.lineTo(x, h * (0.45 + 0.13 * k) + math.sin(x / w * 9 * (1 + 0.2 * k) + k) * h * 0.04)
            path.lineTo(w, h)
            p.setBrush(alpha(mix(c1, c2, k / 3), 0.14 + 0.06 * k))
            p.drawPath(path)
    elif style == "forest":                               # rows of pines in the mist, fireflies
        g = QLinearGradient(0, 0, 0, h)
        g.setColorAt(0, alpha("#0B3D1E", 0.55))
        g.setColorAt(1, alpha(c1, 0.20))
        p.fillRect(QRectF(0, 0, w, h), g)
        for row, (base, scale, a) in enumerate(((0.75, 0.55, 0.55), (0.9, 0.75, 0.8), (1.05, 1.0, 1.0))):
            col = mix(QColor("#041A0B"), c1, 0.45 - 0.15 * row)
            x = -rnd.uniform(0, 30) * unit
            while x < w + 20:
                th = h * rnd.uniform(0.35, 0.55) * scale
                tw = th * 0.42
                tree = QPainterPath(QPointF(x, h * base - th))
                tree.lineTo(x + tw / 2, h * base)
                tree.lineTo(x - tw / 2, h * base)
                tree.closeSubpath()
                p.setBrush(alpha(col, a))
                p.drawPath(tree)
                x += tw * rnd.uniform(0.55, 0.9)
            mist = QLinearGradient(0, h * (base - 0.25), 0, h * base)
            mist.setColorAt(0, alpha("#CFFFE0", 0.0))
            mist.setColorAt(1, alpha("#CFFFE0", 0.05))
            p.fillRect(QRectF(0, 0, w, h), mist)
        for _ in range(18):
            fx, fy = rnd.uniform(0, w), rnd.uniform(h * 0.2, h * 0.85)
            fg = QRadialGradient(QPointF(fx, fy), 5 * unit)
            fg.setColorAt(0, alpha(c2, 0.9))
            fg.setColorAt(1, alpha(c2, 0.0))
            p.setBrush(fg)
            p.drawEllipse(QPointF(fx, fy), 5 * unit, 5 * unit)
    elif style == "candy":                                # bubbles, sprinkles and a lollipop swirl
        g = QLinearGradient(0, 0, w, h)
        g.setColorAt(0, alpha(c1, 0.35))
        g.setColorAt(1, alpha(c2, 0.30))
        p.fillRect(QRectF(0, 0, w, h), g)
        for _ in range(22):
            bx, by, br = rnd.uniform(0, w), rnd.uniform(0, h), rnd.uniform(4, 16) * unit
            p.setBrush(alpha("#FFFFFF", 0.08))
            p.setPen(QPen(alpha("#FFFFFF", 0.25), max(1.0, unit)))
            p.drawEllipse(QPointF(bx, by), br, br)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(alpha("#FFFFFF", 0.35))
            p.drawEllipse(QPointF(bx - br * 0.35, by - br * 0.35), br * 0.22, br * 0.22)
        cols = ["#FF5CB8", "#FFD36B", "#5CE0FF", "#9B5CFF", "#7CFF8A"]
        for _ in range(60):
            sx, sy, a = rnd.uniform(0, w), rnd.uniform(0, h), rnd.uniform(0, math.pi)
            pen = QPen(alpha(rnd.choice(cols), 0.75), 2.2 * unit, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap)
            p.setPen(pen)
            p.drawLine(QPointF(sx, sy), QPointF(sx + math.cos(a) * 5 * unit, sy + math.sin(a) * 5 * unit))
        c = QPointF(w * 0.84, h * 0.4)
        for k in range(12, 0, -1):
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(alpha("#FFFFFF" if k % 2 else c1, 0.5))
            p.drawEllipse(c, k * 2.2 * unit, k * 2.2 * unit)
    elif style == "storm":                                # heavy clouds, rain and a frozen lightning bolt
        g = QLinearGradient(0, 0, 0, h)
        g.setColorAt(0, alpha("#0B1020", 0.7))
        g.setColorAt(1, alpha(c2, 0.18))
        p.fillRect(QRectF(0, 0, w, h), g)
        flash = QRadialGradient(QPointF(w * 0.62, h * 0.2), w * 0.5)
        flash.setColorAt(0, alpha(c1, 0.35))
        flash.setColorAt(1, alpha(c1, 0.0))
        p.setBrush(flash)
        p.drawRect(QRectF(0, 0, w, h))
        for k in range(10):
            p.setBrush(alpha(mix(QColor("#2A3550"), c1, 0.15), 0.85))
            p.drawEllipse(QPointF(w * k / 9 + rnd.uniform(-10, 10) * unit, h * rnd.uniform(0.02, 0.18)),
                          w * 0.12, h * 0.2)
        bolt = QPainterPath(QPointF(w * 0.62, h * 0.18))
        for dx, dy in ((-0.04, 0.16), (0.03, 0.12), (-0.05, 0.18), (0.02, 0.16)):
            cur = bolt.currentPosition()
            bolt.lineTo(cur.x() + w * dx, cur.y() + h * dy)
        p.setBrush(Qt.BrushStyle.NoBrush)
        for width, a in ((7, 0.15), (3, 0.45), (1.4, 1.0)):
            p.setPen(QPen(alpha(mix(c1, QColor("#FFFFFF"), 0.6), a), width * unit, Qt.PenStyle.SolidLine,
                          Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin))
            p.drawPath(bolt)
        p.setPen(QPen(alpha("#9FC3FF", 0.3), max(1.0, 0.9 * unit)))
        for _ in range(70):
            rx, ry = rnd.uniform(0, w), rnd.uniform(h * 0.2, h)
            p.drawLine(QPointF(rx, ry), QPointF(rx - 3 * unit, ry + 9 * unit))
        p.setPen(Qt.PenStyle.NoPen)
    elif style == "retro":                                # synthwave: striped sun, wire mountains, a moving-floor grid
        g = QLinearGradient(0, 0, 0, h)
        g.setColorAt(0, alpha("#1A0B2E", 0.65))
        g.setColorAt(0.6, alpha(c1, 0.25))
        g.setColorAt(1, alpha("#0A0418", 0.6))
        p.fillRect(QRectF(0, 0, w, h), g)
        for _ in range(26):
            p.setBrush(alpha("#FFFFFF", rnd.uniform(0.2, 0.7)))
            r = rnd.uniform(0.5, 1.2) * unit
            p.drawEllipse(QPointF(rnd.uniform(0, w), rnd.uniform(0, h * 0.45)), r, r)
        horizon = h * 0.58
        sun = QPointF(w * 0.5, horizon)
        sg = QLinearGradient(0, horizon - h * 0.36, 0, horizon)
        sg.setColorAt(0, QColor("#FFD36B"))
        sg.setColorAt(1, QColor("#FF2BD6"))
        p.setBrush(sg)
        p.drawEllipse(sun, h * 0.36, h * 0.36)
        disc = QPainterPath()
        disc.addEllipse(sun, h * 0.36, h * 0.36)
        p.save()
        p.setClipPath(disc)
        for k in range(5):
            p.fillRect(QRectF(sun.x() - h * 0.4, horizon - h * (0.04 + 0.06 * k), h * 0.8, h * 0.012 * (k + 1)),
                       alpha("#1A0B2E", 0.9))
        p.restore()
        p.setPen(QPen(alpha(c2, 0.8), max(1.0, 1.2 * unit)))
        p.setBrush(alpha("#0A0418", 0.9))
        mount = QPainterPath(QPointF(0, horizon))
        for x, y in ((0.08, 0.42), (0.16, 0.5), (0.26, 0.36), (0.36, horizon / h)):
            mount.lineTo(w * x, h * y)
        mount.lineTo(0, horizon)
        p.drawPath(mount)
        mount2 = QPainterPath(QPointF(w, horizon))
        for x, y in ((0.92, 0.4), (0.82, 0.48), (0.72, 0.38), (0.62, horizon / h)):
            mount2.lineTo(w * x, h * y)
        mount2.lineTo(w, horizon)
        p.drawPath(mount2)
        p.fillRect(QRectF(0, horizon, w, h - horizon), alpha("#0A0418", 0.85))
        p.setPen(QPen(alpha(c1, 0.75), max(1.0, unit)))
        for k in range(-12, 13):
            p.drawLine(QPointF(w / 2 + k * w * 0.02, horizon), QPointF(w / 2 + k * w * 0.13, h))
        for k in range(1, 8):
            y = horizon + (h - horizon) * (k / 7) ** 1.8
            p.drawLine(QPointF(0, y), QPointF(w, y))
        p.setPen(Qt.PenStyle.NoPen)
    elif style == "lagoon":                               # 3.2 Rare: a calm turquoise lagoon, a palm and its reflection
        g = QLinearGradient(0, 0, 0, h)
        g.setColorAt(0, alpha(c2, 0.35))
        g.setColorAt(0.55, alpha(c1, 0.30))
        g.setColorAt(1, alpha("#03363A", 0.55))
        p.fillRect(QRectF(0, 0, w, h), g)
        water = h * 0.6
        p.fillRect(QRectF(0, water, w, h - water), alpha("#0A5A62", 0.35))
        for k in range(6):
            y = water + (h - water) * (k + 1) / 7
            p.setPen(QPen(alpha("#BFF8F0", 0.12), max(1.0, unit)))
            p.drawLine(QPointF(w * 0.1 + k * 7 * unit, y), QPointF(w * 0.9 - k * 9 * unit, y))
        p.setPen(Qt.PenStyle.NoPen)
        trunk = QPainterPath(QPointF(w * 0.18, water))
        trunk.quadTo(w * 0.2, h * 0.3, w * 0.26, h * 0.2)
        p.setPen(QPen(alpha("#0B2A22", 0.9), 4 * unit, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
        p.drawPath(trunk)
        p.setPen(Qt.PenStyle.NoPen)
        for k in range(6):
            ang = math.radians(-160 + k * 40)
            leaf = QPainterPath(QPointF(w * 0.26, h * 0.2))
            leaf.quadTo(w * 0.26 + math.cos(ang) * 30 * unit, h * 0.2 + math.sin(ang) * 10 * unit - 8 * unit,
                        w * 0.26 + math.cos(ang) * 46 * unit, h * 0.2 + math.sin(ang) * 22 * unit)
            p.setPen(QPen(alpha("#0B2A22", 0.9), 3 * unit, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
            p.drawPath(leaf)
        p.setPen(Qt.PenStyle.NoPen)
        moon = QPointF(w * 0.76, h * 0.22)
        mg = QRadialGradient(moon, h * 0.3)
        mg.setColorAt(0, alpha("#FFFFFF", 0.45))
        mg.setColorAt(1, alpha("#FFFFFF", 0.0))
        p.setBrush(mg)
        p.drawEllipse(moon, h * 0.3, h * 0.3)
        p.setBrush(alpha("#F4FFFD", 0.85))
        p.drawEllipse(moon, h * 0.07, h * 0.07)
        for k in range(5):                                  # the moon's path on the water
            p.setBrush(alpha("#F4FFFD", 0.25 - k * 0.04))
            p.drawRoundedRect(QRectF(moon.x() - (18 - k * 3) * unit, water + (6 + k * 7) * unit, (36 - k * 6) * unit, 2 * unit),
                              unit, unit)
    elif style == "midnight":                             # 3.2 Epic: a deep blue city skyline under a huge moon
        g = QLinearGradient(0, 0, 0, h)
        g.setColorAt(0, alpha("#070B24", 0.75))
        g.setColorAt(1, alpha(c2, 0.45))
        p.fillRect(QRectF(0, 0, w, h), g)
        for _ in range(50):
            p.setBrush(alpha("#FFFFFF", rnd.uniform(0.2, 0.8)))
            r = rnd.uniform(0.4, 1.1) * unit
            p.drawEllipse(QPointF(rnd.uniform(0, w), rnd.uniform(0, h * 0.6)), r, r)
        moon = QPointF(w * 0.7, h * 0.32)
        mg = QRadialGradient(moon, h * 0.5)
        mg.setColorAt(0, alpha(c1, 0.45))
        mg.setColorAt(1, alpha(c1, 0.0))
        p.setBrush(mg)
        p.drawEllipse(moon, h * 0.5, h * 0.5)
        p.setBrush(alpha("#E8ECFF", 0.9))
        p.drawEllipse(moon, h * 0.16, h * 0.16)
        p.setBrush(alpha("#C5CCF2", 0.6))
        for dx, dy, rr in ((-0.04, -0.03, 0.03), (0.05, 0.04, 0.02), (0.01, 0.07, 0.015)):
            p.drawEllipse(QPointF(moon.x() + dx * h, moon.y() + dy * h), rr * h, rr * h)
        x = 0.0
        while x < w:
            bw = rnd.uniform(14, 34) * unit
            bh = h * rnd.uniform(0.18, 0.5)
            p.setBrush(alpha("#05081A", 0.95))
            p.drawRect(QRectF(x, h - bh, bw - 2 * unit, bh))
            for wy in range(int(bh // (7 * unit))):
                for wx in range(int(bw // (6 * unit))):
                    if rnd.random() < 0.28:
                        p.setBrush(alpha("#FFD98A", rnd.uniform(0.35, 0.85)))
                        p.drawRect(QRectF(x + 3 * unit + wx * 6 * unit, h - bh + 4 * unit + wy * 7 * unit, 2 * unit, 3 * unit))
            x += bw
    elif style == "inferno":                              # 4.5 Legendary: cooled basalt plates over glowing seams
        g = QLinearGradient(0, 0, 0, h)
        g.setColorAt(0, alpha("#120402", 0.85))
        g.setColorAt(0.55, alpha("#2A0802", 0.6))
        g.setColorAt(1, alpha("#4A1004", 0.7))
        p.fillRect(QRectF(0, 0, w, h), g)
        heat = QRadialGradient(QPointF(w * 0.5, h * 1.05), w * 0.7)
        heat.setColorAt(0, alpha(c1, 0.55))
        heat.setColorAt(0.5, alpha(c1, 0.18))
        heat.setColorAt(1, alpha(c1, 0.0))
        p.setBrush(heat)
        p.drawRect(QRectF(0, 0, w, h))
        cell = 26 * unit                                   # basalt plates: a jittered grid of dark polygons
        top = h * 0.42
        cols, rows = int(w / cell) + 2, int((h - top) / cell) + 2
        pts = {}
        for i in range(cols + 1):
            for j in range(rows + 1):
                pts[(i, j)] = QPointF(i * cell + rnd.uniform(-0.3, 0.3) * cell, top + j * cell * 0.8 + rnd.uniform(-0.25, 0.25) * cell)
        for i in range(cols):
            for j in range(rows):
                poly = QPainterPath(pts[(i, j)])
                for q in (pts[(i + 1, j)], pts[(i + 1, j + 1)], pts[(i, j + 1)]):
                    poly.lineTo(q)
                poly.closeSubpath()
                depth = j / max(1, rows)
                p.setPen(QPen(alpha(c2, 0.25 + 0.55 * depth), (1.0 + 1.6 * depth) * unit))
                p.setBrush(alpha(mix(QColor("#1A0703"), QColor("#2E0C05"), rnd.random()), 0.95))
                p.drawPath(poly)
        p.setPen(Qt.PenStyle.NoPen)
        fade = QLinearGradient(0, top - 6 * unit, 0, top + cell)      # the plates melt into the heat above
        fade.setColorAt(0, alpha("#120402", 0.9))
        fade.setColorAt(1, alpha("#120402", 0.0))
        p.setBrush(fade)
        p.drawRect(QRectF(0, top - 6 * unit, w, cell + 6 * unit))
        for _ in range(14):                                  # a few soft embers, not a firework
            ex, ey = rnd.uniform(0.05, 0.95) * w, rnd.uniform(0.08, 0.45) * h
            rr = rnd.uniform(1.0, 2.2) * unit
            glow = QRadialGradient(QPointF(ex, ey), rr * 4)
            glow.setColorAt(0, alpha("#FFD08A", rnd.uniform(0.5, 0.85)))
            glow.setColorAt(0.3, alpha(c1, 0.3))
            glow.setColorAt(1, alpha(c1, 0.0))
            p.setBrush(glow)
            p.drawEllipse(QPointF(ex, ey), rr * 4, rr * 4)
    elif style == "glacier":                              # 4.5 Rare: pale sky, ice ridges with sharp light edges
        g = QLinearGradient(0, 0, 0, h)
        g.setColorAt(0, alpha("#0B2A44", 0.6))
        g.setColorAt(1, alpha(c1, 0.25))
        p.fillRect(QRectF(0, 0, w, h), g)
        for layer, (base_y, col, a) in enumerate(((0.55, "#9FDBFF", 0.35), (0.68, "#CFEFFF", 0.55), (0.8, "#FFFFFF", 0.75))):
            path = QPainterPath(QPointF(0, h))
            x = 0.0
            while x <= w:
                path.lineTo(x, h * base_y - rnd.uniform(0.02, 0.18) * h)
                x += rnd.uniform(22, 48) * unit
            path.lineTo(w, h)
            path.closeSubpath()
            p.setBrush(alpha(col, a * 0.5))
            p.setPen(QPen(alpha("#FFFFFF", a), 1.2 * unit))
            p.drawPath(path)
        p.setPen(Qt.PenStyle.NoPen)
    elif style == "jade":                                 # 4.5 Rare: misty jade hills and a thin gold sun
        p.fillRect(QRectF(0, 0, w, h), alpha("#06231A", 0.55))
        sun = QPointF(w * 0.72, h * 0.32)
        p.setBrush(alpha(c2, 0.85))
        p.drawEllipse(sun, 14 * unit, 14 * unit)
        halo = QRadialGradient(sun, 60 * unit)
        halo.setColorAt(0, alpha(c2, 0.35))
        halo.setColorAt(1, alpha(c2, 0.0))
        p.setBrush(halo)
        p.drawEllipse(sun, 60 * unit, 60 * unit)
        for k in range(4):
            y0 = h * (0.5 + k * 0.12)
            path = QPainterPath(QPointF(0, h))
            for x in range(0, int(w) + 10, 10):
                path.lineTo(x, y0 - math.sin(x / w * math.pi * (1.4 + k * 0.5) + k * 1.7) * h * 0.08)
            path.lineTo(w, h)
            path.closeSubpath()
            p.setBrush(alpha(mix(c1, QColor("#03140E"), 0.25 + k * 0.2), 0.55 + 0.1 * k))
            p.drawPath(path)
    elif style == "mirage":                               # 4.5 Special: soft dunes in warm light
        g = QLinearGradient(0, 0, 0, h)
        g.setColorAt(0, alpha("#3A1530", 0.6))
        g.setColorAt(0.5, alpha(c2, 0.3))
        g.setColorAt(1, alpha(c1, 0.35))
        p.fillRect(QRectF(0, 0, w, h), g)
        sun = QPointF(w * 0.3, h * 0.42)
        p.setBrush(alpha("#FFE2B0", 0.8))
        p.drawEllipse(sun, 22 * unit, 22 * unit)
        for k in range(4):
            y0 = h * (0.58 + k * 0.1)
            path = QPainterPath(QPointF(0, h))
            for x in range(0, int(w) + 8, 8):
                path.lineTo(x, y0 - (math.sin(x / w * 3.1 + k * 1.3) * 0.5 + 0.5) * h * 0.09)
            path.lineTo(w, h)
            path.closeSubpath()
            dg = QLinearGradient(0, y0 - h * 0.1, 0, h)
            dg.setColorAt(0, alpha(mix(c1, QColor("#FFE2B0"), 0.4 - k * 0.1), 0.7))
            dg.setColorAt(1, alpha(mix(c1, QColor("#3A1530"), 0.3 + k * 0.15), 0.8))
            p.setBrush(dg)
            p.drawPath(path)
    elif style == "nebula":                               # 4.5 Special: clouds of colour and a field of stars
        p.fillRect(QRectF(0, 0, w, h), alpha("#06041A", 0.6))
        for k in range(7):
            cx, cy = rnd.uniform(0.1, 0.9) * w, rnd.uniform(0.15, 0.85) * h
            rr = rnd.uniform(0.18, 0.35) * w
            g = QRadialGradient(QPointF(cx, cy), rr)
            g.setColorAt(0, alpha(c1 if k % 2 else c2, 0.32))
            g.setColorAt(1, alpha(c1 if k % 2 else c2, 0.0))
            p.setBrush(g)
            p.drawEllipse(QPointF(cx, cy), rr, rr * 0.6)
        for _ in range(70):
            p.setBrush(alpha("#FFFFFF", rnd.uniform(0.3, 0.9)))
            sr = rnd.uniform(0.4, 1.2) * unit
            p.drawEllipse(QPointF(rnd.uniform(0, w), rnd.uniform(0, h)), sr, sr)
    elif style == "obsidian":                             # 4.5 Epic: black volcanic glass, cut facets with violet light
        p.fillRect(QRectF(0, 0, w, h), alpha("#05040A", 0.8))
        x = -w * 0.1
        while x < w * 1.1:
            span = rnd.uniform(40, 90) * unit
            facet = QPainterPath(QPointF(x, 0))
            facet.lineTo(x + span, 0)
            facet.lineTo(x + span * 0.4, h)
            facet.lineTo(x - span * 0.6, h)
            facet.closeSubpath()
            g = QLinearGradient(QPointF(x, 0), QPointF(x + span, h))
            g.setColorAt(0, alpha(c2, rnd.uniform(0.15, 0.45)))
            g.setColorAt(1, alpha("#000000", 0.4))
            p.setBrush(g)
            p.setPen(QPen(alpha(c1, rnd.uniform(0.15, 0.5)), 1.0 * unit))
            p.drawPath(facet)
            x += span
        p.setPen(Qt.PenStyle.NoPen)
        shine = QLinearGradient(QPointF(w * 0.2, 0), QPointF(w * 0.6, h))
        shine.setColorAt(0, alpha("#FFFFFF", 0.0))
        shine.setColorAt(0.5, alpha(c1, 0.18))
        shine.setColorAt(1, alpha("#FFFFFF", 0.0))
        p.setBrush(shine)
        p.drawRect(QRectF(0, 0, w, h))
    elif style == "prism":                                # 4.5 Epic: white light through a prism, fanned into colour
        p.fillRect(QRectF(0, 0, w, h), alpha("#07070D", 0.75))
        apex = QPointF(w * 0.42, h * 0.22)
        tri = QPolygonF([apex, QPointF(apex.x() - 34 * unit, apex.y() + 58 * unit), QPointF(apex.x() + 34 * unit, apex.y() + 58 * unit)])
        hit = QPointF(apex.x() - 14 * unit, apex.y() + 30 * unit)
        p.setPen(QPen(alpha("#FFFFFF", 0.8), 2.2 * unit))
        p.drawLine(QPointF(0, h * 0.48), hit)
        p.setPen(Qt.PenStyle.NoPen)
        out = QPointF(apex.x() + 16 * unit, apex.y() + 32 * unit)
        cols = ["#FF4B4B", "#FF8A3D", "#F4F04A", "#3DDC84", "#2EC5FF", "#4B6BFF", "#B36BFF"]
        for k, col in enumerate(cols):
            y0 = h * (0.25 + k * 0.1)
            band = QPolygonF([out, QPointF(w, y0), QPointF(w, y0 + h * 0.1)])
            g = QLinearGradient(out, QPointF(w, y0))
            g.setColorAt(0, alpha(col, 0.15))
            g.setColorAt(1, alpha(col, 0.55))
            p.setBrush(g)
            p.drawPolygon(band)
        p.setBrush(alpha("#DDEBFF", 0.18))
        p.setPen(QPen(alpha("#FFFFFF", 0.75), 1.4 * unit))
        p.drawPolygon(tri)
        p.setPen(Qt.PenStyle.NoPen)


def _draw_theme(p: QPainter, theme: dict, w: float, h: float, accent: QColor, second, unit: float) -> None:
    from PyQt6.QtCore import QPointF
    from PyQt6.QtGui import QLinearGradient, QRadialGradient
    if theme.get("scene") and theme.get("tint"):
        return _shop_scene(p, theme["scene"], w, h, QColor(theme["tint"][0]), QColor(theme["tint"][1]), unit)
    col = theme_colour(theme, accent)
    gold = theme.get("gold", 0.0)
    white = QColor("#FFFFFF")
    if second is not None:
        other = mix(second, QColor(GOLD), gold * 0.5)
    else:
        shifted = QColor.fromHsvF((max(0.0, accent.hsvHueF()) + 0.14) % 1.0, max(0.35, accent.hsvSaturationF()),
                                  max(0.6, accent.valueF()))
        other = mix(shifted, QColor("#FFD98A"), gold)
    p.setPen(Qt.PenStyle.NoPen)
    n = theme.get("glow_n", 0)
    if n:                                                # light from the top-left corner
        g = QRadialGradient(QPointF(w * 0.16, -h * 0.05), w * (0.55 + 0.1 * n))
        g.setColorAt(0, alpha(col, 0.12 + 0.05 * n))
        g.setColorAt(1, alpha(col, 0.0))
        p.setBrush(g)
        p.drawRect(QRectF(0, 0, w, h))
    if theme.get("aurora") or second is not None:        # a second light from the other corner
        g = QRadialGradient(QPointF(w * 0.86, -h * 0.12), w * 0.6)
        g.setColorAt(0, alpha(other, 0.24 if theme.get("aurora") else 0.16))
        g.setColorAt(1, alpha(other, 0.0))
        p.setBrush(g)
        p.drawRect(QRectF(0, 0, w, h))
    sky = _sky(theme, w, h, unit)
    links = theme.get("links", 0)
    if links and len(sky) > 3:                           # lines between the brightest stars
        bright = sorted(sorted(sky, key=lambda s: -s[3])[:links + 4], key=lambda s: s[0])
        pen = QPen(alpha(mix(col, white, 0.25), 0.26), max(1.0, 0.8 * unit))
        pen.setCapStyle(Qt.PenCapStyle.RoundCap)
        p.setPen(pen)
        drawn = 0
        for a, b in zip(bright, bright[1:]):
            if drawn >= links:
                break
            if math.hypot(b[0] - a[0], b[1] - a[1]) < w * 0.34:
                p.drawLine(QPointF(a[0], a[1]), QPointF(b[0], b[1]))
                drawn += 1
        p.setPen(Qt.PenStyle.NoPen)
    for x, y, r, a in sky:
        p.setBrush(alpha(mix(white, col, 0.25 + 0.55 * gold), a))
        p.drawEllipse(QPointF(x, y), r, r)
        if r > 1.15 * unit:                              # the biggest ones get a soft halo
            p.setBrush(alpha(col, 0.16))
            p.drawEllipse(QPointF(x, y), r * 2.6, r * 2.6)
    comets = theme.get("comets", 0)
    if comets:
        import random
        rnd = random.Random(5)
        for _ in range(comets):
            x, y = rnd.uniform(0.08, 0.80) * w, rnd.uniform(0.12, 0.62) * h
            length = rnd.uniform(26, 54) * unit
            tail = QPointF(x + length, y - length * 0.42)
            g = QLinearGradient(QPointF(x, y), tail)
            g.setColorAt(0.0, alpha(mix(col, white, 0.5), 0.6))
            g.setColorAt(1.0, alpha(col, 0.0))
            pen = QPen(g, 1.4 * unit)
            pen.setCapStyle(Qt.PenCapStyle.RoundCap)
            p.setPen(pen)
            p.drawLine(QPointF(x, y), tail)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(alpha(white, 0.8))
            p.drawEllipse(QPointF(x, y), 1.3 * unit, 1.3 * unit)
    if gold >= 0.6:                                      # fine gold dust along the top
        import random
        rnd = random.Random(31)
        for _ in range(int(40 * gold)):
            p.setBrush(alpha(GOLD, rnd.uniform(0.15, 0.5)))
            r = rnd.uniform(0.35, 0.8) * unit
            p.drawEllipse(QPointF(rnd.uniform(0, w), rnd.uniform(0, h * 0.5) ** 1.0), r, r)


def theme_pattern(theme: dict, w: int, h: int, accent: QColor, dpr: float, unit: float, band: float = 0.0):
    """Cached pixmap of a theme's background, faded out below `band` pixels (None when there is nothing)."""
    from PyQt6.QtGui import QLinearGradient, QPixmap
    second = ui.accent2
    if (not theme["layers"] and second is None) or w < 2 or h < 2:
        return None
    band = band or h
    key = (theme["id"], w, h, accent.rgb(), second.rgb() if second is not None else 0, round(dpr * 100),
           round(unit * 100), round(band))
    pm = _pattern_cache.get(key)
    if pm is None:
        if len(_pattern_cache) > 40:
            _pattern_cache.clear()
        pm = QPixmap(int(w * dpr), int(h * dpr))
        pm.setDevicePixelRatio(dpr)
        pm.fill(Qt.GlobalColor.transparent)
        p = QPainter(pm)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        _draw_theme(p, theme, w, min(h, band), accent, second, unit)
        fade = QLinearGradient(0, 0, 0, band)                 # strongest under the header, gone below it
        fade.setColorAt(0.0, QColor(0, 0, 0, 255))
        fade.setColorAt(0.55, QColor(0, 0, 0, 150))
        fade.setColorAt(1.0, QColor(0, 0, 0, 0))
        p.setCompositionMode(QPainter.CompositionMode.CompositionMode_DestinationIn)
        p.fillRect(QRectF(0, 0, w, h), fade)
        p.end()
        _pattern_cache[key] = pm
    return pm


def theme_sparkles(theme: dict, w: float, h: float, band: float = 0.0) -> list:
    """[(x, y, size, phase, speed, gold)] twinkling stars, stable for a theme; kept inside the header band."""
    import random
    n = theme.get("sparkles", 0)
    if not n:
        return []
    band = min(h, band or h)
    rnd = random.Random(77)                                    # the same ones in every theme, just more of them
    return [(rnd.uniform(0.06, 0.94) * w, rnd.uniform(0.10, 0.85) * band, rnd.uniform(1.4, 2.6),
             rnd.uniform(0, 6.28), rnd.uniform(0.6, 1.2), theme.get("gold", 0.0)) for _ in range(n)]


def paint_sparkles(p: QPainter, sparks: list, ox: float, oy: float, accent: QColor, now: float, unit: float) -> None:
    from PyQt6.QtCore import QPointF
    white = QColor("#FFFFFF")
    for x, y, size, phase, speed, gold in sparks:
        b = max(0.0, math.sin(now * speed + phase)) ** 3
        if b < 0.03:
            continue
        col = mix(accent, QColor(GOLD), gold)
        r = size * unit * (0.6 + 0.4 * b)
        c = QPointF(ox + x, oy + y)
        pen = QPen(alpha(mix(col, white, 0.55 - 0.3 * gold), 0.6 * b), max(1.0, 0.8 * unit))
        pen.setCapStyle(Qt.PenCapStyle.RoundCap)
        p.setPen(pen)
        p.drawLine(QPointF(c.x() - r, c.y()), QPointF(c.x() + r, c.y()))
        p.drawLine(QPointF(c.x(), c.y() - r), QPointF(c.x(), c.y() + r))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(alpha(white, 0.7 * b))
        p.drawEllipse(c, 0.8 * unit, 0.8 * unit)


def paint_theme_edge(p: QPainter, theme: dict, shape: QRectF, radius: float, level: float, halo: bool,
                     now: float) -> None:
    """Card outline: your colour (two colours if a second one is set), then a travelling light, then gold."""
    from PyQt6.QtGui import QConicalGradient, QLinearGradient
    p.setBrush(Qt.BrushStyle.NoBrush)
    a = (80 + 110 * level) / 255 if halo else 0.35
    r = shape.adjusted(0.6, 0.6, -0.6, -0.6)
    style = theme.get("edge", "")
    golden = style in ("gold", "goldshine", "legend")
    if golden:
        base = QLinearGradient(shape.topLeft(), shape.bottomRight())
        base.setColorAt(0.0, alpha("#FFF1C2", min(1.0, a + 0.2)))
        base.setColorAt(0.5, alpha(GOLD, min(1.0, a + 0.15)))
        base.setColorAt(1.0, alpha("#B8862B", min(1.0, a + 0.15)))
        p.setPen(QPen(base, 1.3))
    elif ui.accent2 is not None:
        base = QLinearGradient(shape.topLeft(), shape.bottomRight())
        base.setColorAt(0.0, alpha(ui.accent, a))
        base.setColorAt(1.0, alpha(ui.accent2, a))
        p.setPen(QPen(base, 1.2))
    else:
        p.setPen(QPen(alpha(ui.accent, a), 1.2))
    p.drawRoundedRect(r, radius, radius)
    if style == "legend":                                # a second, fine line just inside
        inner = shape.adjusted(3.4, 3.4, -3.4, -3.4)
        p.setPen(QPen(alpha(GOLD, min(1.0, a * 0.55)), 1.0))
        p.drawRoundedRect(inner, max(0.0, radius - 3.0), max(0.0, radius - 3.0))
    if style in ("shine", "goldshine", "legend"):        # a light travelling around the outline
        tint = QColor("#FFF6D8") if golden else mix(ui.accent, QColor("#FFFFFF"), 0.6)
        for offset in ((0.0, 0.5) if style == "legend" else (0.0,)):
            g = QConicalGradient(shape.center(), (now * 40.0 + offset * 360.0) % 360.0)
            g.setColorAt(0.0, alpha("#FFFFFF", 0.0))
            g.setColorAt(0.04, alpha(tint, min(1.0, a + 0.3)))
            g.setColorAt(0.09, alpha("#FFFFFF", 0.0))
            g.setColorAt(1.0, alpha("#FFFFFF", 0.0))
            p.setPen(QPen(g, 1.7))
            p.drawRoundedRect(r, radius, radius)


# --------------------------------------------------------------------------- #
# Run timer
# --------------------------------------------------------------------------- #
def run_clock(seconds: float) -> str:
    seconds = max(0.0, seconds)
    cs = int(seconds * 100) % 100
    s = int(seconds)
    if s >= 3600:
        return f"{s // 3600}:{s % 3600 // 60:02d}:{s % 60:02d}.{cs:02d}"
    return f"{s // 60}:{s % 60:02d}.{cs:02d}"


class TimerEngine(QObject):
    changed = pyqtSignal()

    def __init__(self, cfg) -> None:
        super().__init__()
        self.cfg = cfg
        self.state = "idle"            # idle | running | paused
        self._base = 0.0
        self._t0 = 0.0
        self.splits: list = []

    def elapsed(self) -> float:
        return self._base + (time.monotonic() - self._t0 if self.state == "running" else 0.0)

    def start_split(self) -> None:
        if self.state == "idle":
            self._base, self._t0, self.splits, self.state = 0.0, time.monotonic(), [], "running"
        elif self.state == "paused":
            self._t0, self.state = time.monotonic(), "running"
        else:
            self.splits.append(self.elapsed())
        self.changed.emit()

    def pause(self) -> None:
        if self.state == "running":
            self._base, self.state = self.elapsed(), "paused"
        elif self.state == "paused":
            self._t0, self.state = time.monotonic(), "running"
        self.changed.emit()

    def finish(self) -> None:
        """Stop the run and keep it as the best time if it is faster."""
        if self.state == "idle":
            return
        total = self.elapsed()
        self._base, self.state = total, "paused"
        best = self.cfg["timer"]["best"]
        if total > 0.5 and (best <= 0 or total < best):
            self.cfg["timer"]["best"] = total
            self.cfg.save()
        self.changed.emit()

    def reset(self) -> None:
        self.state, self._base, self.splits = "idle", 0.0, []
        self.changed.emit()


class TimerOverlay(QWidget):
    """Click-through timer at the top of the screen."""

    def __init__(self, cfg, engine: TimerEngine) -> None:
        super().__init__()
        self.cfg, self.engine = cfg, engine
        self.setWindowFlags(OVERLAY_FLAGS)
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
        self.setAttribute(Qt.WidgetAttribute.WA_ShowWithoutActivating)
        self.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents)
        self._tick = QTimer(self)
        self._tick.setInterval(40)
        self._tick.timeout.connect(self.update)
        engine.changed.connect(self._sync)

    def refresh(self) -> None:
        if self.cfg["timer"]["overlay"]:
            w, h = S(150), S(38)
            g = QGuiApplication.primaryScreen().geometry()
            self.setGeometry(g.center().x() - w // 2, g.top() + S(10), w, h)
            self.show()
            win.make_overlay(int(self.winId()))
        else:
            self.hide()
        self._sync()

    def _sync(self) -> None:
        if self.isVisible() and self.engine.state == "running":
            self._tick.start()
        else:
            self._tick.stop()
        self.update()

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        r = QRectF(self.rect()).adjusted(0.5, 0.5, -0.5, -0.5)
        p.setPen(QPen(alpha(ui.accent, 0.5), 1))
        p.setBrush(QColor(10, 14, 15, 210))
        p.drawRoundedRect(r, S(9), S(9))
        f = font(19, QFont.Weight.Bold)
        f.setStyleHint(QFont.StyleHint.Monospace)
        p.setFont(f)
        p.setPen(QColor(TEXT) if self.engine.state != "paused" else alpha(TEXT, 0.6))
        p.drawText(r, int(Qt.AlignmentFlag.AlignCenter), run_clock(self.engine.elapsed()))


# --------------------------------------------------------------------------- #
# Keyboard shortcuts (RegisterHotKey: no hooks)
# --------------------------------------------------------------------------- #
class _KeyFilter(QAbstractNativeEventFilter):
    def __init__(self, callback) -> None:
        super().__init__()
        self._cb = callback

    def nativeEventFilter(self, event_type, message):
        try:
            if bytes(event_type) == b"windows_generic_MSG":
                msg = wintypes.MSG.from_address(int(message))
                if msg.message == 0x0312:       # WM_HOTKEY
                    self._cb(int(msg.wParam))
                    return True, 0
        except Exception:  # noqa: BLE001
            pass
        return False, 0


class Hotkeys(QObject):
    """Fixed keys. Ctrl+Alt+Shift+R: normal screen colours. Ctrl+F1 / F2 / F3: run timer."""
    triggered = pyqtSignal(str)
    KEYS = {1: ("panic", 0x2 | 0x1 | 0x4, 0x52),          # Ctrl+Alt+Shift+R
            2: ("timer_split", 0x2, 0x70), 3: ("timer_pause", 0x2, 0x71), 4: ("timer_reset", 0x2, 0x72)}

    def __init__(self, app) -> None:
        super().__init__()
        self._last = (0, 0.0)
        self._on: set = set()
        self._filter = _KeyFilter(self._hit)
        app.installNativeEventFilter(self._filter)

    def _hit(self, ident: int) -> None:
        now = time.monotonic()
        if self._last[0] == ident and now - self._last[1] < 0.12:
            return                                   # Qt can deliver the same message twice
        self._last = (ident, now)
        if ident in self.KEYS:
            self.triggered.emit(self.KEYS[ident][0])

    def apply(self, timer_keys: bool) -> None:
        if not win.IS_WIN:
            return
        user32 = ctypes.windll.user32  # type: ignore[attr-defined]
        for ident, (name, mods, vk) in self.KEYS.items():
            want = name == "panic" or timer_keys
            if want and ident not in self._on:
                if user32.RegisterHotKey(None, ident, mods | 0x4000, vk):
                    self._on.add(ident)
            elif not want and ident in self._on:
                user32.UnregisterHotKey(None, ident)
                self._on.discard(ident)

    def close(self) -> None:
        if win.IS_WIN:
            for ident in list(self._on):
                ctypes.windll.user32.UnregisterHotKey(None, ident)  # type: ignore[attr-defined]
        self._on.clear()


