# --------------------------------------------------------------------------- #
# 6.9: animations. How the Rubenium banner leaves (and comes back): the simple default, or one of four Mythic ones,
# each in five finishes. Every one is drawn from the same two pictures: the banner and the ball.
# --------------------------------------------------------------------------- #
from PyQt6.QtGui import QPolygonF, QRadialGradient  # noqa: E402

ANIMS = (("nova", "Supernova"), ("shatter", "Shatter"), ("rift", "Rift"), ("phoenix", "Phoenix"))
ANIM_IDS = tuple(a[0] for a in ANIMS)
ANIM_FINS = (("", "Original"), ("prismatic", "Prismatic"), ("gold", "Gold"), ("blacktitan", "Black Titan"),
             ("whitetitan", "White Titan"))
ANIM_FIN_IDS = tuple(f[0] for f in ANIM_FINS)
ANIM_SHORT = {"": "Base", "prismatic": "Prismatic", "gold": "Gold", "blacktitan": "Black", "whitetitan": "White"}
ANIM_LOOK = {"nova": ("#FF8A2B", "#FFD27A"), "shatter": ("#4FD8FF", "#B4F0FF"), "rift": ("#9B5CFF", "#E0C8FF"),
             "phoenix": ("#FF4A1C", "#FFB627")}


def anim_id(design: str, fin: str = "") -> str:
    return "anim:" + design + ("-" + fin if fin else "")


def _e3_safe(x: float) -> float:
    x = max(0.0, min(1.0, x))
    return x * x * (3 - 2 * x)


def anim_split(item: str):
    """"anim:nova-gold" -> ("nova", "gold"); None when it is not one of ours."""
    kind, base, _ = parts(item)
    if kind != "anim":
        return None
    design, _, fin = base.partition("-")
    if design not in ANIM_IDS or fin not in ANIM_FIN_IDS:
        return None
    return design, fin


def _e3(x: float) -> float:
    x = max(0.0, min(1.0, x))
    return x * x * (3 - 2 * x)


def _lerp(a: QPointF, b: QPointF, t: float) -> QPointF:
    return QPointF(a.x() + (b.x() - a.x()) * t, a.y() + (b.y() - a.y()) * t)


def anim_cols(design: str, fin: str, now: float, i: float = 0.0):
    """(main, light, core) colours of an animation in a finish."""
    if fin == "prismatic":
        h = (now * 0.3 + i * 0.11) % 1.0
        return QColor.fromHsvF(h, 0.78, 1.0), QColor.fromHsvF((h + 0.14) % 1.0, 0.45, 1.0), QColor("#FFFFFF")
    if fin == "gold":
        return QColor("#FFC83D"), QColor("#FFF0A8"), QColor("#FFFFFF")
    if fin == "blacktitan":
        return QColor("#2A2142"), QColor("#B9A6FF"), QColor("#EDE6FF")
    if fin == "whitetitan":
        return QColor("#F2F6FF"), QColor("#9FC4FF"), QColor("#FFFFFF")
    a, b = ANIM_LOOK.get(design, ANIM_LOOK["nova"])
    return QColor(a), QColor(b), QColor("#FFFFFF")


def _a_glow(p: QPainter, c: QPointF, r: float, col: QColor, a: float, fin: str = "") -> None:
    if r < 1 or a <= 0.01:
        return
    p.setPen(Qt.PenStyle.NoPen)
    if fin == "blacktitan":                                    # a dark hole with a violet rim
        g = QRadialGradient(c, r)
        g.setColorAt(0, QColor(6, 4, 14, int(255 * min(1, a * 1.2))))
        g.setColorAt(0.6, QColor(6, 4, 14, int(200 * min(1, a))))
        g.setColorAt(0.85, alpha(col, 0.55 * a))
        g.setColorAt(1, alpha(col, 0.0))
    else:
        g = QRadialGradient(c, r)
        g.setColorAt(0, alpha(col, min(1.0, a)))
        g.setColorAt(0.45, alpha(col, 0.35 * a))
        g.setColorAt(1, alpha(col, 0.0))
    p.setBrush(g)
    p.drawEllipse(c, r, r)


def _a_dot(p: QPainter, pt: QPointF, r: float, a: QColor, b: QColor, fin: str, op: float, star: bool = False) -> None:
    if r < 0.3 or op <= 0.02:
        return
    if fin == "blacktitan":
        p.setPen(QPen(alpha(b, 0.9 * op), max(0.8, r * 0.4)))
    else:
        p.setPen(Qt.PenStyle.NoPen)
    p.setBrush(alpha(a, op))
    p.drawEllipse(pt, r, r)
    if star and fin in ("gold", "prismatic", "whitetitan"):          # a little glint
        p.setPen(QPen(alpha("#FFFFFF", 0.9 * op), max(0.8, r * 0.3)))
        p.drawLine(QPointF(pt.x() - r * 2.4, pt.y()), QPointF(pt.x() + r * 2.4, pt.y()))
        p.drawLine(QPointF(pt.x(), pt.y() - r * 2.4), QPointF(pt.x(), pt.y() + r * 2.4))
        p.setPen(Qt.PenStyle.NoPen)


def _a_ring(p: QPainter, c: QPointF, r: float, col: QColor, a: float, w: float) -> None:
    if r < 1 or a <= 0.01:
        return
    p.setBrush(Qt.BrushStyle.NoBrush)
    p.setPen(QPen(alpha(col, 0.18 * a), w * 3))
    p.drawEllipse(c, r, r)
    p.setPen(QPen(alpha(col, min(1.0, a)), w))
    p.drawEllipse(c, r, r)
    p.setPen(Qt.PenStyle.NoPen)


# ---- 1. Supernova: the banner caves into a star that blows up, and the ball is born from the flash
def _anim_nova(p, k, now, m, hole, d, fin, banner, ball) -> None:
    c = m.center()
    te = 0.44
    e = _e3(k / te)
    a, b, core = anim_cols("nova", fin, now)
    if k < te + 0.02:
        s = 1.0 - 0.97 * e
        w, h = m.width() * s, m.height() * s
        banner(QRectF(c.x() - w / 2, c.y() - h / 2, w, h), 1.0 - 0.45 * e)
        rnd = random.Random(5)
        for i in range(28):                                    # light streaming into the core
            ang = rnd.uniform(0, math.tau)
            r0 = m.width() * rnd.uniform(0.25, 0.5)
            f = (e * 1.2 + rnd.random() * 0.3) % 1.0
            r1 = r0 * (1 - f)
            col = anim_cols("nova", fin, now, i)[1] if fin == "prismatic" else b
            p.setPen(QPen(alpha(col, 0.7 * (1 - f)), S(1.4)))
            p.drawLine(QPointF(c.x() + math.cos(ang) * r1, c.y() + math.sin(ang) * r1 * 0.55),
                       QPointF(c.x() + math.cos(ang) * (r1 + S(16) * (1 - f)), c.y() + math.sin(ang) * (r1 + S(16) * (1 - f)) * 0.55))
        p.setPen(Qt.PenStyle.NoPen)
        _a_glow(p, c, S(14) + m.height() * 0.8 * e, a, 0.55 * e + 0.1, fin)
        _a_glow(p, c, S(8) + m.height() * 0.35 * e, core, 0.9 * e, "")
    q = (k - te) / (1 - te)
    if q > 0:
        flash = max(0.0, 1.0 - q * 3.5)
        _a_glow(p, c, m.width() * 0.5 * (0.3 + q), core, flash, "")
        _a_glow(p, c, m.width() * 0.35 * (0.3 + q), a, 0.6 * max(0.0, 1 - q * 1.6), fin)
        for j, (sp, wd) in enumerate(((0.62, 6.0), (0.42, 3.5))):          # two shock rings
            qq = max(0.0, q - j * 0.08)
            if qq > 0:
                col = anim_cols("nova", fin, now, j * 3)[0] if fin == "prismatic" else (b if j else a if fin != "blacktitan" else b)
                p.setBrush(Qt.BrushStyle.NoBrush)
                _a_ring(p, c, m.width() * sp * (qq ** 0.55), col, 1.0 - qq, S(wd) * (1 - qq))
        rnd = random.Random(9)
        for i in range(80):                                    # the debris
            ang = rnd.uniform(0, math.tau)
            sp = rnd.uniform(0.15, 0.62)
            r = m.width() * sp * (q ** 0.6)
            pt = QPointF(c.x() + math.cos(ang) * r, c.y() + math.sin(ang) * r * 0.6 + q * q * S(14))
            aa, bb, _ = anim_cols("nova", fin, now, i)
            _a_dot(p, pt, S(rnd.uniform(1.2, 3.4)) * (1 - q * 0.6), aa if i % 3 else bb, bb, fin, max(0.0, 1.0 - q) ** 0.8, i % 7 == 0)
    t = _e3((k - 0.5) / 0.5)
    op = min(1.0, max(0.0, (k - 0.46) / 0.14))
    if op > 0:
        pos = _lerp(c, hole, t)
        grow = 0.35 + 0.65 * min(1.0, (k - 0.46) / 0.3) + 0.12 * math.sin(min(1.0, (k - 0.46) / 0.3) * math.pi)
        ball(pos, d * grow, op)


# ---- 2. Shatter: the banner breaks into glass that bursts out, then every piece is pulled into the ball
def _shard_polys(m: QRectF):
    cols, rows = 9, 3
    cw, ch = m.width() / cols, m.height() / rows
    rnd = random.Random(31)
    pts = [[QPointF(m.left() + i * cw + (rnd.uniform(-0.3, 0.3) * cw if 0 < i < cols else 0),
                    m.top() + j * ch + (rnd.uniform(-0.3, 0.3) * ch if 0 < j < rows else 0)) for i in range(cols + 1)]
           for j in range(rows + 1)]
    out = []
    for j in range(rows):
        for i in range(cols):
            tl, tr_, bl, br = pts[j][i], pts[j][i + 1], pts[j + 1][i], pts[j + 1][i + 1]
            out.append(QPolygonF([tl, tr_, bl]))
            out.append(QPolygonF([tr_, br, bl]))
    return out


def _anim_shatter(p, k, now, m, hole, d, fin, banner, ball) -> None:
    c = m.center()
    a, b, core = anim_cols("shatter", fin, now)
    u = _e3(k / 0.5)
    v = _e3((k - 0.42) / 0.5)
    polys = _shard_polys(m)
    rnd = random.Random(77)
    if k < 0.06:                                               # the crack of impact
        _a_glow(p, c, m.width() * 0.35 * (k / 0.06), core, 0.6 * (1 - k / 0.06), "")
    for i, poly in enumerate(polys):
        cen = poly.boundingRect().center()
        ang = math.atan2(cen.y() - c.y(), cen.x() - c.x()) + rnd.uniform(-0.5, 0.5)
        dist = rnd.uniform(0.12, 0.42) * m.width()
        rot = rnd.uniform(-220, 220)
        lift = rnd.uniform(0.0, S(30))
        blown = QPointF(cen.x() + math.cos(ang) * dist * u, cen.y() + math.sin(ang) * dist * 0.55 * u - lift * u + u * u * S(18))
        cur = _lerp(blown, hole, v ** 1.3)
        sc = (1.0 - 0.15 * u) * (1.0 - 0.93 * v)
        op = (1.0 - 0.3 * u) * max(0.0, 1.0 - max(0.0, v - 0.7) / 0.3)
        if op <= 0.01 or sc <= 0.02:
            continue
        p.save()
        p.translate(cur)
        p.rotate(rot * u * (1 - v))
        p.scale(sc, sc)
        p.translate(-cen.x(), -cen.y())
        path = QPainterPath()
        path.addPolygon(poly)
        path.closeSubpath()
        p.setClipPath(path)
        banner(m, op, True)
        p.setClipping(False)
        edge = b if fin != "blacktitan" else b
        p.setPen(QPen(alpha(edge, 0.75 * op * (0.4 + 0.6 * u)), S(1.2) / max(0.2, sc)))
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawPolygon(poly)
        p.restore()
    p.setPen(Qt.PenStyle.NoPen)
    rnd = random.Random(12)
    for i in range(46):                                        # dust and glints thrown off
        ang = rnd.uniform(0, math.tau)
        r = m.width() * rnd.uniform(0.1, 0.5) * u * (1 - v * 0.6)
        pt = _lerp(QPointF(c.x() + math.cos(ang) * r, c.y() + math.sin(ang) * r * 0.55), hole, v * 0.9)
        aa, bb, _ = anim_cols("shatter", fin, now, i)
        _a_dot(p, pt, S(rnd.uniform(1.0, 2.6)), bb, bb, fin, (1 - v) * 0.9 * min(1, u * 3), i % 5 == 0)
    if v > 0:
        _a_glow(p, hole, d * (0.8 + 1.4 * v) * (1 - v * 0.2), a if fin != "blacktitan" else b, 0.5 * v * (1 - max(0.0, v - 0.8) * 4), fin)
        _a_ring(p, hole, d * 2.2 * v, b, (1 - v) * 0.9, S(2.4) * (1 - v))
    op = min(1.0, max(0.0, (k - 0.78) / 0.18))
    if op > 0:
        ball(hole, d * (0.5 + 0.5 * _e3((k - 0.78) / 0.22) + 0.08 * math.sin(min(1.0, (k - 0.78) / 0.22) * math.pi)), op)


# ---- 3. Rift: lightning cracks the banner open, both halves are squeezed into the slit, and the ball steps out
def _bolt(rnd, a: QPointF, b: QPointF, n: int, jag: float) -> QPainterPath:
    path = QPainterPath(a)
    for i in range(1, n):
        t = i / n
        path.lineTo(QPointF(a.x() + (b.x() - a.x()) * t + rnd.uniform(-jag, jag), a.y() + (b.y() - a.y()) * t + rnd.uniform(-jag, jag) * 0.4))
    path.lineTo(b)
    return path


def _anim_rift(p, k, now, m, hole, d, fin, banner, ball) -> None:
    cx = m.center().x()
    cy = m.center().y()
    a, b, core = anim_cols("rift", fin, now)
    top, bot = m.top() - S(4), m.bottom() + S(4)
    grow = _e3(k / 0.3)
    sq = _e3((k - 0.25) / 0.5)
    close = _e3((k - 0.72) / 0.28)
    # the two halves of the banner, squeezed towards the slit
    if sq < 0.995:
        for half in (0, 1):
            p.save()
            r = QRectF(m.left(), top - S(8), cx - m.left(), bot - top + S(16)) if half == 0 else \
                QRectF(cx, top - S(8), m.right() - cx, bot - top + S(16))
            p.setClipRect(r)
            p.translate(cx, 0)
            p.scale(max(0.005, 1 - sq), 1.0)
            p.translate(-cx, 0)
            banner(m, 1.0 - 0.3 * sq)
            p.restore()
    slit_h = (m.height() * 0.5 + S(4)) * (1 - close)
    if slit_h > 1:
        wdt = (S(3) + sq * S(15)) * (1 - close * 0.7)
        _a_glow(p, QPointF(cx, cy), max(slit_h, wdt * 4), a if fin != "blacktitan" else b, 0.45 * min(1, grow * 1.5), fin)
        # the slit itself: a tall pointed shape
        sl = QPainterPath()
        sl.moveTo(cx, cy - slit_h * grow)
        sl.quadTo(cx + wdt * 2.2, cy, cx, cy + slit_h * grow)
        sl.quadTo(cx - wdt * 2.2, cy, cx, cy - slit_h * grow)
        p.setPen(QPen(alpha(b, 0.9), S(1.4)))
        p.setBrush(QColor(4, 3, 10, 250) if fin != "whitetitan" else QColor(250, 252, 255, 250))
        p.drawPath(sl)
        p.setPen(Qt.PenStyle.NoPen)
    # lightning along and around the crack
    rnd = random.Random(int(now * 16))
    for i in range(6 if k < 0.9 else 2):
        if k < 0.04:
            break
        ang = rnd.uniform(-1.2, 1.2) + (0 if i % 2 else math.pi)
        ln = m.width() * rnd.uniform(0.08, 0.28) * (0.4 + sq) * min(1, grow * 2)
        beg = QPointF(cx, cy + rnd.uniform(-1, 1) * slit_h * 0.7)
        end = QPointF(cx + math.cos(ang) * ln, beg.y() + math.sin(ang) * ln * 0.7)
        path = _bolt(rnd, beg, end, 6, S(5))
        col = anim_cols("rift", fin, now, i)[1] if fin == "prismatic" else b
        for w_, al in ((S(5), 0.16), (S(2.2), 0.55), (S(1), 1.0)):
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.setPen(QPen(alpha(core if w_ < S(1.5) else col, al * (1 - close)), w_, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
            p.drawPath(path)
    p.setPen(Qt.PenStyle.NoPen)
    # the long vertical crack
    if k < 0.75:
        h = (m.height() * 0.5 + S(10)) * grow
        path = _bolt(random.Random(3), QPointF(cx, cy - h), QPointF(cx, cy + h), 14, S(3.5) * (1 - sq * 0.6))
        for w_, al in ((S(6), 0.14), (S(2.6), 0.5), (S(1.1), 1.0)):
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.setPen(QPen(alpha(core if w_ < S(2) else b, al), w_, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
            p.drawPath(path)
        p.setPen(Qt.PenStyle.NoPen)
    rnd = random.Random(21)
    for i in range(40):                                        # sparks pulled into the slit
        f = (now * 0.9 + rnd.random()) % 1.0
        side = -1 if i % 2 else 1
        x = cx + side * m.width() * 0.45 * (1 - f) * rnd.uniform(0.3, 1.0)
        y = cy + rnd.uniform(-1, 1) * m.height() * 0.5
        aa, bb, _ = anim_cols("rift", fin, now, i)
        _a_dot(p, QPointF(x, y), S(rnd.uniform(1, 2.2)), bb, bb, fin, 0.85 * sq * (1 - close) * (1 - f * 0.4), i % 6 == 0)
    t = _e3((k - 0.66) / 0.34)
    op = min(1.0, max(0.0, (k - 0.64) / 0.12))
    if op > 0:
        pos = _lerp(QPointF(cx, cy), hole, t)
        _a_glow(p, pos, d * 1.7, b if fin != "blacktitan" else a, 0.45 * (1 - t * 0.8), fin)
        ball(pos, d * (0.5 + 0.5 * min(1.0, (k - 0.64) / 0.25)), op)
        _a_ring(p, QPointF(cx, cy), m.width() * 0.3 * close, b, (1 - close) * 0.8, S(2.2))


# ---- 4. Phoenix: fire climbs the banner and burns it into feathers; two flaming wings carry it to the ball
def _anim_phoenix(p, k, now, m, hole, d, fin, banner, ball) -> None:
    a, b, core = anim_cols("phoenix", fin, now)
    burn = _e3(k / 0.5)
    yb = m.bottom() - m.height() * burn
    if burn < 0.995:
        p.save()
        p.setClipRect(QRectF(m.left() - S(4), m.top() - S(40), m.width() + S(8), yb - m.top() + S(40)))
        banner(m.translated(0, -S(14) * burn), 1.0 - 0.35 * burn)
        p.restore()
    p.setPen(Qt.PenStyle.NoPen)
    if 0.0 < k < 0.58:                                          # the flames along the burning edge
        fade = 1.0 - max(0.0, (k - 0.46) / 0.12)
        n = 46
        for i in range(n):
            x = m.left() + m.width() * (i + 0.5) / n
            hh = S(14 + 30 * abs(math.sin(i * 1.7 + now * 9 + k * 6))) * fade
            wd = m.width() / n * 1.2
            aa, bb, cc = anim_cols("phoenix", fin, now, i * 0.6)
            tongue = QPainterPath()
            tongue.moveTo(x - wd / 2, yb + S(4))
            tongue.quadTo(x - wd * 0.2, yb - hh * 0.5, x + math.sin(now * 7 + i) * wd * 0.3, yb - hh)
            tongue.quadTo(x + wd * 0.2, yb - hh * 0.5, x + wd / 2, yb + S(4))
            g = QLinearGradient(x, yb + S(4), x, yb - hh)
            g.setColorAt(0, alpha(bb if fin != "blacktitan" else cc, 0.95))
            g.setColorAt(0.5, alpha(aa, 0.8))
            g.setColorAt(1, alpha(aa, 0.0))
            p.setBrush(g)
            p.drawPath(tongue)
    rnd = random.Random(44)
    for i in range(110):                                       # embers spiralling up into the ball's place
        tb = rnd.uniform(0.0, 0.55)
        life = rnd.uniform(0.3, 0.5)
        uu = (k - tb) / life
        if not 0 < uu < 1:
            continue
        sx = m.left() + m.width() * rnd.random()
        sy = m.bottom() - m.height() * _e3(tb / 0.5)
        pt = _lerp(QPointF(sx, sy), hole, uu ** 1.6)
        sw = math.sin(uu * math.pi * 2 + i) * S(26) * (1 - uu)
        pt = QPointF(pt.x() + sw, pt.y())
        aa, bb, _ = anim_cols("phoenix", fin, now, i)
        _a_dot(p, pt, S(rnd.uniform(1.2, 3.2)) * (1 - uu * 0.5), aa if i % 2 else bb, bb, fin, math.sin(uu * math.pi) * 0.95, i % 9 == 0)
    # two wings of feathers made of fire
    wing = _e3((k - 0.42) / 0.3) * (1.0 - _e3((k - 0.82) / 0.18))
    if wing > 0.01:
        flap = math.sin(now * 8.0) * 0.07
        for side in (-1, 1):
            for j in range(9):
                f = j / 8
                ang = math.radians(-8 - 70 * f) + flap * (0.4 + f)
                ln = (m.width() * 0.34) * (0.55 + 0.45 * math.sin(f * math.pi * 0.8 + 0.35)) * wing
                dx, dy = math.cos(ang) * side, math.sin(ang)
                tip = QPointF(hole.x() + dx * ln, hole.y() + dy * ln * 0.8)
                mid = QPointF(hole.x() + dx * ln * 0.55, hole.y() + dy * ln * 0.55 * 0.8 - ln * 0.12)
                w0 = S(7) * (1 - f * 0.4) * wing
                feather = QPainterPath()
                feather.moveTo(hole.x(), hole.y() - w0 * 0.2)
                feather.quadTo(mid.x(), mid.y() - w0, tip.x(), tip.y())
                feather.quadTo(mid.x(), mid.y() + w0, hole.x(), hole.y() + w0 * 0.2)
                aa, bb, cc = anim_cols("phoenix", fin, now, j * side)
                g = QLinearGradient(hole, tip)
                g.setColorAt(0, alpha(cc if fin != "blacktitan" else bb, 0.95 * wing))
                g.setColorAt(0.45, alpha(bb, 0.85 * wing))
                g.setColorAt(1, alpha(aa, 0.0))
                p.setBrush(g)
                p.setPen(QPen(alpha(bb if fin == "blacktitan" else cc, 0.35 * wing), S(0.8)))
                p.drawPath(feather)
        p.setPen(Qt.PenStyle.NoPen)
        _a_glow(p, hole, d * 2.0 * wing, a if fin != "blacktitan" else b, 0.5 * wing, fin)
    op = min(1.0, max(0.0, (k - 0.58) / 0.22))
    if op > 0:
        e = _e3((k - 0.58) / 0.3)
        ball(hole, d * (0.55 + 0.45 * e + 0.1 * math.sin(e * math.pi)), op)


_ANIM_PAINT = {"nova": _anim_nova, "shatter": _anim_shatter, "rift": _anim_rift, "phoenix": _anim_phoenix}


def paint_anim(p: QPainter, design: str, fin: str, k: float, now: float, m: QRectF, hole: QPointF, d: float, banner, ball) -> None:
    """k 0 = the banner is showing, 1 = only the ball is. banner(box, opacity, light) and ball(centre, size, opacity)
    draw the two pictures."""
    p.save()
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    p.setPen(Qt.PenStyle.NoPen)
    try:
        _ANIM_PAINT[design](p, max(0.0, min(1.0, k)), now, m, hole, d, fin, banner, ball)
    finally:
        p.restore()


def paint_anim_thumb(p: QPainter, item: str, box: QRectF, now: float) -> None:
    """The small picture of an animation (shop, inventory, cases, market): a glowing ball in its colours."""
    sp = anim_split(item) or ("nova", "")
    design, fin = sp
    a, b, core = anim_cols(design, fin, now)
    c = box.center()
    r = box.width() * 0.5
    p.save()
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    pulse = 0.5 + 0.5 * math.sin(now * 2.4)
    _a_glow(p, c, r * (0.95 + 0.08 * pulse), a if fin != "blacktitan" else b, 0.55, fin)
    p.setPen(Qt.PenStyle.NoPen)
    g = QRadialGradient(QPointF(c.x() - r * 0.12, c.y() - r * 0.15), r * 0.55)
    g.setColorAt(0, core)
    g.setColorAt(0.5, b if fin != "blacktitan" else a)
    g.setColorAt(1, a)
    p.setBrush(g)
    p.drawEllipse(c, r * 0.36, r * 0.36)
    if fin == "blacktitan":
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.setPen(QPen(alpha(b, 0.9), max(1.0, r * 0.05)))
        p.drawEllipse(c, r * 0.36, r * 0.36)
    p.setPen(QPen(alpha(b, 0.7), max(1.0, r * 0.04)))
    p.setBrush(Qt.BrushStyle.NoBrush)
    if design == "nova":
        p.drawEllipse(c, r * (0.55 + 0.15 * pulse), r * (0.55 + 0.15 * pulse))
    elif design == "shatter":
        for i in range(6):
            ang = i * math.pi / 3 + 0.3
            p.drawLine(QPointF(c.x() + math.cos(ang) * r * 0.5, c.y() + math.sin(ang) * r * 0.5),
                       QPointF(c.x() + math.cos(ang + 0.3) * r * 0.82, c.y() + math.sin(ang + 0.3) * r * 0.82))
    elif design == "rift":
        p.drawLine(QPointF(c.x(), c.y() - r * 0.85), QPointF(c.x(), c.y() + r * 0.85))
    else:
        for side in (-1, 1):
            p.drawArc(QRectF(c.x() + (0 if side > 0 else -r * 0.9), c.y() - r * 0.5, r * 0.9, r * 0.9), 16 * (20 if side > 0 else 110), 16 * 50)
    p.restore()


_NAMES = {"ball": dict(BALLS), "line": dict(LINES), "font": {f[0]: f[1] for f in FONTS},
          "theme": {t[0]: t[1] for t in THEME_LOOKS}, "banner": dict(BANNERS), "frame": dict(FRAMES), "tag": dict(TAGS)}
ANIM_DESIGNS = [(d + ("-" + f if f else ""), (tn + " " + n if f else n)) for d, n in ANIMS for f, tn in ANIM_FINS]
_NAMES["anim"] = dict(ANIM_DESIGNS)
_themes: dict = {}


def parts(item: str) -> tuple:
    bits = (item or "").split(":") + ["", "", ""]
    return bits[0], bits[1], bits[2]


def colour_of(item: str) -> QColor:
    return QColor(SHOP_COLOURS.get(parts(item)[2], "#FFFFFF"))


def item_name(item: str) -> str:
    """"Orbit ball · Blue", "Ocean theme"... (badges are named in collection.py)."""
    kind, base, var = parts(item)
    if kind == "badge":
        pass
        return badge_label(item)
    if kind == "tag":
        return tr("{name} tag", name=_NAMES["tag"].get(base, base.upper()))
    name = f"{tr(_NAMES.get(kind, {}).get(base, base.capitalize()))} ({tr(KIND_NAMES.get(kind, kind)).lower()})"
    return name + (f" · {tr(COLOUR_NAMES.get(var, var))}" if var else "")


def shop_theme(ident: str):
    """The theme dict (same shape as extras.THEMES) of a shop theme, e.g. "theme:ocean"."""
    if not _themes:
        pass
        for tid, name, c1, c2, sky in THEME_LOOKS:
            th = _theme("theme:" + tid, name, 0, glow=1, sparkles=sky.get("sparkles", 0) // 2,
                        halo=1.0 + 0.1 * sky.get("glow", 2), edge=sky.get("edge", ""))
            th["tint"] = (c1, c2)
            th["scene"] = tid                              # 3.1: its own picture instead of the night sky
            _themes["theme:" + tid] = th
    return _themes.get(ident)


def font_families(item: str) -> list:
    base = parts(item)[1]
    return next((list(f[2]) for f in FONTS if f[0] == base), [])


# --------------------------------------------------------------------------- #
# Balls: the R in the item's colour, with a design around it
# --------------------------------------------------------------------------- #
def _r_text(p: QPainter, box: QRectF, d: float, col: QColor, dark: bool) -> None:
    f = font(20, QFont.Weight.ExtraBold)
    f.setPixelSize(max(8, int(d * 0.46)))
    p.setFont(f)
    centre = int(Qt.AlignmentFlag.AlignCenter)
    p.setPen(alpha("#FFFFFF" if dark else col, 0.45))
    p.drawText(box.translated(0, d * 0.022), centre, "R")
    p.setPen(col if not dark else QColor("#C9D2DA"))
    p.drawText(box, centre, "R")


def paint_shop_ball(p: QPainter, box: QRectF, d: float, item: str, now: float = 0.0) -> None:
    _k, design, var = parts(item)
    col = colour_of(item)
    dark = var == "black"
    line = QColor("#AEB8C2") if dark else col
    c = box.center()
    r = d / 2
    p.save()
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    p.setBrush(Qt.BrushStyle.NoBrush)
    if design == "orbit":
        p.setPen(QPen(alpha(line, 0.45), max(1.0, d * 0.02)))
        p.save()
        p.translate(c)
        p.rotate(-24)
        p.drawEllipse(QPointF(0, 0), r * 0.74, r * 0.34)
        ang = now * 1.6
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(line)
        p.drawEllipse(QPointF(r * 0.74 * math.cos(ang), r * 0.34 * math.sin(ang)), d * 0.045, d * 0.045)
        p.restore()
    elif design == "pixel":
        p.setPen(Qt.PenStyle.NoPen)
        s = d * 0.075
        for k, (dx, dy) in enumerate(((-1, -1), (1, -1), (-1, 1), (1, 1), (-1.45, 0), (1.45, 0))):
            p.setBrush(alpha(line, 0.85 if k < 4 else 0.45))
            p.drawRect(QRectF(c.x() + dx * r * 0.5 - s / 2, c.y() + dy * r * 0.5 - s / 2, s, s))
    elif design == "halo":
        p.setPen(QPen(line, max(1.4, d * 0.04), Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
        p.drawArc(QRectF(c.x() - r * 0.5, c.y() - r * 0.82, r, r * 0.36), 0, 180 * 16)
        p.setPen(QPen(alpha(line, 0.35), max(1.0, d * 0.02)))
        p.drawArc(QRectF(c.x() - r * 0.5, c.y() - r * 0.82, r, r * 0.36), 180 * 16, 180 * 16)
    elif design == "bubble":
        for k, (dx, dy, rr) in enumerate(((-0.52, 0.44, 0.15), (0.56, -0.38, 0.19), (0.5, 0.5, 0.09), (-0.5, -0.5, 0.08))):
            bob = math.sin(now * 1.3 + k * 1.7) * d * 0.015
            p.setPen(QPen(alpha(line, 0.75), max(1.0, d * 0.018)))
            p.setBrush(alpha(line, 0.16))
            p.drawEllipse(QPointF(c.x() + dx * r, c.y() + dy * r + bob), rr * r, rr * r)
    elif design == "spiral":
        path = QPainterPath()
        for n in range(64):
            t = n / 63
            ang = t * 4.2 * math.pi + now * 0.5
            pt = QPointF(c.x() + r * 0.8 * t * math.cos(ang), c.y() + r * 0.8 * t * math.sin(ang))
            path.lineTo(pt) if n else path.moveTo(pt)
        p.setPen(QPen(alpha(line, 0.42), max(1.0, d * 0.022), Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
        p.drawPath(path)
    elif design == "bullseye":
        for k, rr in enumerate((0.78, 0.6)):
            p.setPen(QPen(alpha(line, 0.6 - 0.25 * k), max(1.0, d * (0.03 - 0.008 * k))))
            p.drawEllipse(c, r * rr, r * rr)
    elif design == "hex":
        path = QPainterPath()
        for n in range(7):
            ang = math.radians(60 * n + now * 6)
            pt = QPointF(c.x() + r * 0.78 * math.cos(ang), c.y() + r * 0.78 * math.sin(ang))
            path.lineTo(pt) if n else path.moveTo(pt)
        p.setPen(QPen(alpha(line, 0.7), max(1.2, d * 0.03), Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap,
                      Qt.PenJoinStyle.RoundJoin))
        p.drawPath(path)
    elif design == "ripple":
        for k in range(3):
            t = (now * 0.35 + k / 3) % 1.0
            p.setPen(QPen(alpha(line, 0.7 * (1 - t)), max(1.0, d * 0.024)))
            p.drawEllipse(c, r * (0.3 + 0.55 * t), r * (0.3 + 0.55 * t))
    elif design == "shard":
        p.setPen(Qt.PenStyle.NoPen)
        for k in range(6):
            ang = math.radians(60 * k + 15)
            tip = QPointF(c.x() + r * 0.86 * math.cos(ang), c.y() + r * 0.86 * math.sin(ang))
            a1, a2 = ang - 0.2, ang + 0.2
            tri = QPainterPath()
            tri.moveTo(tip)
            tri.lineTo(c.x() + r * 0.6 * math.cos(a1), c.y() + r * 0.6 * math.sin(a1))
            tri.lineTo(c.x() + r * 0.6 * math.cos(a2), c.y() + r * 0.6 * math.sin(a2))
            tri.closeSubpath()
            p.setBrush(alpha(line, 0.85 if k % 2 == 0 else 0.4))
            p.drawPath(tri)
    elif design == "petal":                              # 3.2 Common: four soft petals
        p.setPen(Qt.PenStyle.NoPen)
        for k in range(4):
            ang = math.radians(45 + 90 * k)
            p.setBrush(alpha(line, 0.42))
            p.save()
            p.translate(c.x() + r * 0.62 * math.cos(ang), c.y() + r * 0.62 * math.sin(ang))
            p.rotate(45 + 90 * k)
            p.drawEllipse(QPointF(0, 0), r * 0.2, r * 0.11)
            p.restore()
    elif design == "gear":                               # 3.2 Rare: a turning cog, teeth and a hub ring
        teeth, outer, inner = 10, r * 0.86, r * 0.72
        path = QPainterPath()
        spin = now * 18
        for k in range(teeth * 4 + 1):
            ang = math.radians(spin + k * 360 / (teeth * 4))
            rr = outer if (k % 4) in (1, 2) else inner
            pt = QPointF(c.x() + rr * math.cos(ang), c.y() + rr * math.sin(ang))
            path.lineTo(pt) if k else path.moveTo(pt)
        p.setPen(QPen(alpha(line, 0.75), max(1.0, d * 0.022), Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap,
                      Qt.PenJoinStyle.RoundJoin))
        p.drawPath(path)
        p.setPen(QPen(alpha(line, 0.3), max(1.0, d * 0.015)))
        p.drawEllipse(c, r * 0.6, r * 0.6)
    elif design == "planet":                             # 3.2 Epic: a tilted ring, a moon and two little stars
        p.save()
        p.translate(c)
        p.rotate(-18)
        p.setPen(QPen(alpha(line, 0.35), max(1.0, d * 0.05)))
        p.drawArc(QRectF(-r * 0.92, -r * 0.3, r * 1.84, r * 0.6), 0, -180 * 16)      # back half, faint
        p.setPen(QPen(alpha(line, 0.85), max(1.0, d * 0.032)))
        p.drawArc(QRectF(-r * 0.92, -r * 0.3, r * 1.84, r * 0.6), 0, 180 * 16)
        p.restore()
        ang = now * 0.9
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(mix(line, QColor("#FFFFFF"), 0.35))
        p.drawEllipse(QPointF(c.x() + r * 0.8 * math.cos(ang), c.y() + r * 0.8 * math.sin(ang) * 0.9), d * 0.05, d * 0.05)
        for k, (sx, sy) in enumerate(((-0.62, -0.6), (0.66, 0.55))):
            tw = 0.5 + 0.5 * math.sin(now * 3 + k * 2)
            p.setBrush(alpha("#FFFFFF", 0.4 + 0.5 * tw))
            p.drawEllipse(QPointF(c.x() + sx * r, c.y() + sy * r), d * 0.018, d * 0.018)
    elif design == "eclipse":                            # 4.5: a dark moon over a burning ring of light
        turn = now * 0.5
        for k, (w_, a) in enumerate(((0.16, 0.12), (0.09, 0.3), (0.04, 0.9))):
            g = QConicalGradient(c, math.degrees(turn) + k * 40)
            g.setColorAt(0.0, alpha(line, a))
            g.setColorAt(0.5, alpha(mix(line, QColor("#FFFFFF"), 0.6), a))
            g.setColorAt(1.0, alpha(line, a))
            p.setPen(QPen(g, d * w_))
            p.drawEllipse(c, r * 0.66, r * 0.66)
        p.setPen(Qt.PenStyle.NoPen)
        moon = QPointF(c.x() + r * 0.06 * math.cos(turn * 0.7), c.y() + r * 0.06 * math.sin(turn * 0.7))
        p.setBrush(QColor("#07080B"))
        p.drawEllipse(moon, r * 0.62, r * 0.62)
        p.setBrush(alpha("#FFFFFF", 0.85))
        bead = QPointF(c.x() + r * 0.66 * math.cos(turn * 2.2), c.y() + r * 0.66 * math.sin(turn * 2.2))
        p.drawEllipse(bead, d * 0.03, d * 0.03)
    elif design in ("nova", "snowglobe"):              # 3.2 Legendary: a burst of rays and orbiting sparks
        if design == "snowglobe":                         # limited: a glass globe with falling snow
            p.setPen(QPen(alpha("#DDF3FF", 0.65), max(1.0, d * 0.025)))
            p.setBrush(alpha("#9FE3FF", 0.10))
            p.drawEllipse(c, r * 0.84, r * 0.84)
            p.setPen(Qt.PenStyle.NoPen)
            for k in range(12):
                fx = math.sin(k * 7.3) * 0.6
                fy = ((now * 0.12 + k / 12) % 1.0) * 1.4 - 0.7
                if fx * fx + fy * fy < 0.55:
                    p.setBrush(alpha("#FFFFFF", 0.85))
                    p.drawEllipse(QPointF(c.x() + fx * r, c.y() + fy * r), d * 0.016, d * 0.016)
            p.setBrush(alpha("#C8283D", 0.85))
            p.drawRoundedRect(QRectF(c.x() - r * 0.5, c.y() + r * 0.72, r, r * 0.18), r * 0.06, r * 0.06)
        else:
            p.setPen(Qt.PenStyle.NoPen)
            for k in range(12):
                ang = math.radians(k * 30 + now * 20)
                long_ = 0.9 if k % 2 == 0 else 0.7
                ray = QPainterPath()
                ray.moveTo(c.x() + r * 0.56 * math.cos(ang - 0.08), c.y() + r * 0.56 * math.sin(ang - 0.08))
                ray.lineTo(c.x() + r * long_ * math.cos(ang), c.y() + r * long_ * math.sin(ang))
                ray.lineTo(c.x() + r * 0.56 * math.cos(ang + 0.08), c.y() + r * 0.56 * math.sin(ang + 0.08))
                ray.closeSubpath()
                p.setBrush(alpha(line, 0.75 if k % 2 == 0 else 0.4))
                p.drawPath(ray)
            for k in range(3):
                ang = now * (1.4 + k * 0.5) + k * 2.1
                p.setBrush(mix(line, QColor("#FFFFFF"), 0.6))
                p.drawEllipse(QPointF(c.x() + r * 0.92 * math.cos(ang), c.y() + r * 0.92 * math.sin(ang)), d * 0.025, d * 0.025)
            glow = QRadialGradient(c, r * 0.62)
            glow.setColorAt(0, alpha(line, 0.25))
            glow.setColorAt(1, alpha(line, 0.0))
            p.setBrush(glow)
            p.drawEllipse(c, r * 0.62, r * 0.62)
    if design == "split":                                # the R in two halves: colour above, white below
        for top in (True, False):
            p.save()
            p.setClipRect(QRectF(box.left(), box.top() if top else c.y(), box.width(), box.height() / 2))
            _r_text(p, box, d, col if top else QColor(TEXT), dark and top)
            p.restore()
        p.setPen(QPen(alpha(line, 0.5), max(1.0, d * 0.016)))
        p.drawLine(QPointF(c.x() - r * 0.7, c.y()), QPointF(c.x() + r * 0.7, c.y()))
    else:
        _r_text(p, box, d, col, dark)
    p.restore()


# --------------------------------------------------------------------------- #
# Lines: the song-progress ring of the ball
# --------------------------------------------------------------------------- #
def _arc_points(ring: QRectF, frac: float, step_deg: float, wobble=None) -> list:
    c, r = ring.center(), ring.width() / 2
    n = max(2, int(360 * frac / step_deg) + 1)
    out = []
    for i in range(n):
        deg = min(360 * frac, i * step_deg)
        ang = math.radians(90 - deg)
        rr = r + (wobble(i) if wobble else 0.0)
        out.append(QPointF(c.x() + rr * math.cos(ang), c.y() - rr * math.sin(ang)))
    return out


def paint_shop_ring(p: QPainter, ring: QRectF, item: str, frac: float, width: float, now: float = 0.0) -> None:
    _k, design, var = parts(item)
    col = QColor("#8C96A0") if var == "black" else colour_of(item)
    frac = max(0.0, min(1.0, frac))
    span = int(-360 * 16 * frac)
    p.save()
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    p.setBrush(Qt.BrushStyle.NoBrush)
    p.setPen(QPen(alpha("#FFFFFF", 0.10), width))
    p.drawEllipse(ring)
    if frac <= 0.0:
        return p.restore()
    round_pen = lambda c, w: QPen(c, w, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap)      # noqa: E731
    if design in ("dash", "chain", "steps"):
        pen = QPen(col, width * (1.5 if design == "steps" else 1.0), Qt.PenStyle.CustomDashLine, Qt.PenCapStyle.FlatCap)
        pen.setDashPattern({"dash": [3.0, 2.0], "chain": [4.0, 1.4, 1.0, 1.4], "steps": [1.6, 1.0]}[design])
        p.setPen(pen)
        p.drawArc(ring, 90 * 16, span)
    elif design == "beads":
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(col)
        for pt in _arc_points(ring, frac, 14):
            p.drawEllipse(pt, width * 0.8, width * 0.8)
    elif design == "zigzag":
        pts = _arc_points(ring, frac, 7, lambda i: width * (0.9 if i % 2 else -0.9))
        path = QPainterPath(pts[0])
        for pt in pts[1:]:
            path.lineTo(pt)
        p.setPen(QPen(col, width * 0.7, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin))
        p.drawPath(path)
    elif design == "twin":
        for grow in (-width * 0.9, width * 0.9):
            p.setPen(round_pen(col, width * 0.5))
            p.drawArc(ring.adjusted(grow, grow, -grow, -grow), 90 * 16, span)
    elif design == "pulse":
        p.setPen(round_pen(alpha(col, 0.55), width * 0.6))
        p.drawArc(ring, 90 * 16, span)
        p.setPen(Qt.PenStyle.NoPen)
        for i, pt in enumerate(_arc_points(ring, frac, 24)):
            beat = 0.6 + 0.4 * math.sin(now * 4 - i * 0.8)
            p.setBrush(col)
            p.drawEllipse(pt, width * beat, width * beat)
    elif design == "ribbon":
        p.setPen(QPen(alpha(col, 0.3), width * 2.2, Qt.PenStyle.SolidLine, Qt.PenCapStyle.FlatCap))
        p.drawArc(ring, 90 * 16, span)
        p.setPen(round_pen(col, width * 0.6))
        p.drawArc(ring, 90 * 16, span)
    elif design == "laser":
        p.setPen(QPen(alpha(col, 0.28), width * 2.6, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
        p.drawArc(ring, 90 * 16, span)
        p.setPen(round_pen(col, width))
        p.drawArc(ring, 90 * 16, span)
        p.setPen(round_pen(mix(col, QColor("#FFFFFF"), 0.8), width * 0.35))
        p.drawArc(ring, 90 * 16, span)
    elif design == "wave":                                   # 3.2 Common: a soft wave
        pts = _arc_points(ring, frac, 3, lambda i: width * 0.8 * math.sin(i * 0.9 + now * 3))
        path = QPainterPath(pts[0])
        for pt in pts[1:]:
            path.lineTo(pt)
        p.setPen(QPen(col, width * 0.65, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin))
        p.drawPath(path)
    elif design == "stars":                                  # 3.2 Rare: a faint line dotted with little stars
        p.setPen(round_pen(alpha(col, 0.35), width * 0.45))
        p.drawArc(ring, 90 * 16, span)
        p.setPen(Qt.PenStyle.NoPen)
        for i, pt in enumerate(_arc_points(ring, frac, 20)):
            tw = 0.7 + 0.3 * math.sin(now * 3 + i)
            star = QPainterPath()
            size = width * 1.3 * tw
            for k in range(10):
                ang = math.radians(-90 + 36 * k)
                rr = size if k % 2 == 0 else size * 0.42
                q = QPointF(pt.x() + rr * math.cos(ang), pt.y() + rr * math.sin(ang))
                star.lineTo(q) if k else star.moveTo(q)
            star.closeSubpath()
            p.setBrush(col)
            p.drawPath(star)
    elif design == "helix":                                  # 3.2 Epic: two strands twisting round each other
        for phase, a in ((0.0, 1.0), (math.pi, 0.55)):
            pts = _arc_points(ring, frac, 3, lambda i, ph=phase: width * 1.1 * math.sin(i * 0.35 + ph + now * 2))
            path = QPainterPath(pts[0])
            for pt in pts[1:]:
                path.lineTo(pt)
            p.setPen(QPen(alpha(col, a), width * 0.5, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
            p.drawPath(path)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(mix(col, QColor("#FFFFFF"), 0.5))
        for pt in _arc_points(ring, frac, 26):
            p.drawEllipse(pt, width * 0.35, width * 0.35)
    elif design == "lightning":                              # 3.2 Legendary: a crackling bolt with a glow
        rnd_k = int(now * 12)
        pts = _arc_points(ring, frac, 6, lambda i: width * 1.2 * math.sin(i * 2.7 + rnd_k * 1.3) * (0.4 + 0.6 * ((i * 37 + rnd_k) % 5) / 4))
        path = QPainterPath(pts[0])
        for pt in pts[1:]:
            path.lineTo(pt)
        p.setPen(QPen(alpha(col, 0.25), width * 2.6, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin))
        p.drawPath(path)
        p.setPen(QPen(col, width * 0.8, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.MiterJoin))
        p.drawPath(path)
        p.setPen(QPen(mix(col, QColor("#FFFFFF"), 0.85), width * 0.3))
        p.drawPath(path)
    elif design == "comet":                                  # 4.5: a fading tail behind a bright head
        pts = _arc_points(ring, frac, 3)
        n = len(pts)
        tail = max(2, min(n, 40))
        p.setPen(round_pen(alpha(col, 0.18), width * 0.7))
        p.drawArc(ring, 90 * 16, span)
        for i in range(n - tail, n - 1):
            k = (i - (n - tail)) / tail
            p.setPen(round_pen(alpha(mix(col, QColor("#FFFFFF"), k * 0.6), 0.15 + 0.85 * k), width * (0.6 + 0.9 * k)))
            p.drawLine(pts[i], pts[i + 1])
        head = pts[-1]
        p.setPen(Qt.PenStyle.NoPen)
        glow = QRadialGradient(head, width * 3.2)
        glow.setColorAt(0, alpha("#FFFFFF", 0.95))
        glow.setColorAt(0.35, alpha(col, 0.6))
        glow.setColorAt(1, alpha(col, 0.0))
        p.setBrush(glow)
        p.drawEllipse(head, width * 3.2, width * 3.2)
    elif design == "garland":                                # limited: a green garland with red and gold baubles
        p.setPen(round_pen(QColor("#1F7A4A"), width * 1.3))
        p.drawArc(ring, 90 * 16, span)
        p.setPen(Qt.PenStyle.NoPen)
        for i, pt in enumerate(_arc_points(ring, frac, 22)):
            glow_ = 0.75 + 0.25 * math.sin(now * 3 + i * 1.3)
            p.setBrush(QColor("#E8384F") if i % 2 == 0 else QColor("#E8C26A"))
            p.setOpacity(glow_)
            p.drawEllipse(pt, width * 0.75, width * 0.75)
        p.setOpacity(1.0)
    else:                                                    # spark: a line with a star at its head
        p.setPen(round_pen(col, width))
        p.drawArc(ring, 90 * 16, span)
        head = _arc_points(ring, frac, 360 * frac or 1)[-1]
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(mix(col, QColor("#FFFFFF"), 0.6))
        star = QPainterPath()
        size = width * (2.2 + 0.5 * math.sin(now * 5))
        for k in range(8):
            ang = math.radians(45 * k)
            rr = size if k % 2 == 0 else size * 0.3
            pt = QPointF(head.x() + rr * math.cos(ang), head.y() + rr * math.sin(ang))
            star.lineTo(pt) if k else star.moveTo(pt)
        star.closeSubpath()
        p.drawPath(star)
    p.restore()


# --------------------------------------------------------------------------- #
# A small picture of any item (shop, inventory, market, trades)
# --------------------------------------------------------------------------- #
def paint_cosmetic(p: QPainter, item: str, rect: QRectF, now: float = 0.0, effects: bool = True, dim: float = 1.0) -> None:
    kind, base, var = parts(item)
    if kind == "badge":
        pass
        return show_item(p, item, rect, now, effects, dim)
    if kind in ("banner", "frame", "tag"):
        return paint_look_icon(p, item, rect, now if effects else 0.0, dim)
    if kind == "anim":
        p.save()
        p.setOpacity(p.opacity() * dim)
        dd = min(rect.width(), rect.height())
        paint_anim_thumb(p, item, QRectF(rect.center().x() - dd / 2, rect.center().y() - dd / 2, dd, dd), now if effects else 0.6)
        p.restore()
        return
    d = min(rect.width(), rect.height())
    box = QRectF(rect.center().x() - d / 2, rect.center().y() - d / 2, d, d)
    p.save()
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    p.setOpacity(p.opacity() * dim)
    if kind == "ball":
        p.setPen(QPen(alpha("#FFFFFF", 0.12), 1))
        p.setBrush(QColor("#0B0E10"))
        p.drawEllipse(box)
        paint_shop_ball(p, box.translated(0, -d * 0.02), d, item, now if effects else 0.6)
    elif kind == "line":
        w = max(1.6, d * 0.07)
        paint_shop_ring(p, box.adjusted(w * 2.4, w * 2.4, -w * 2.4, -w * 2.4), item, 0.72, w, now if effects else 0.6)
    elif kind == "font":
        f = QFont()
        f.setFamilies(font_families(item) + ["Segoe UI", "Arial"])
        f.setPixelSize(max(8, int(d * 0.52)))
        f.setWeight(QFont.Weight.Bold)
        p.setFont(f)
        p.setPen(QColor("#AEB8C2") if var == "black" else colour_of(item))
        p.drawText(box, int(Qt.AlignmentFlag.AlignCenter), "Aa")
    elif kind == "theme":
        look = next((t for t in THEME_LOOKS if t[0] == base), THEME_LOOKS[0])
        g = QLinearGradient(box.topLeft(), box.bottomRight())
        g.setColorAt(0.0, QColor(look[2]))
        g.setColorAt(1.0, QColor(look[3]))
        tile = box.adjusted(d * 0.08, d * 0.16, -d * 0.08, -d * 0.16)
        p.setPen(QPen(g, max(1.4, d * 0.06)))
        p.setBrush(QColor("#0B0E10"))
        p.drawRoundedRect(tile, d * 0.14, d * 0.14)
        p.setPen(Qt.PenStyle.NoPen)
        for k, (fx, fy, s) in enumerate(((0.3, 0.42, 0.05), (0.52, 0.6, 0.035), (0.7, 0.38, 0.045), (0.42, 0.68, 0.03))):
            p.setBrush(QColor(look[2 + k % 2]))
            tw = 0.7 + 0.3 * math.sin(now * 2 + k) if effects else 1.0
            p.drawEllipse(QPointF(box.left() + fx * d, box.top() + fy * d), s * d * tw, s * d * tw)
    p.restore()


# --------------------------------------------------------------------------- #
# Profile looks: banners, frames and tags
# --------------------------------------------------------------------------- #
_BANNER_COLS = {"dusk": ("#3A2A6B", "#C0587E"), "mint": ("#0F5F55", "#5CE0B8"), "steel": ("#2B3640", "#7D8C99"),
                "rose": ("#5B1E3A", "#FF8FB1"), "waves": ("#0B2447", "#2E8BFF"), "grid": ("#1A0B2E", "#35D6E6"),
                "stripes": ("#5A1A0A", "#FF8A3D"), "dots": ("#0D2E33", "#1ABC9C"), "aurora": ("#06121F", "#3DFFB0"),
                "circuit": ("#04170F", "#2ECC71"), "sunset": ("#2B0F3D", "#FF8A3D"), "peaks": ("#0E1A2B", "#8FA8FF"),
                "galaxy": ("#05040F", "#9B5CFF"), "lava": ("#1A0503", "#FF3D1F"), "matrix": ("#010A04", "#3DFF7A"),
                "prism": ("#101018", "#FF5CC8"), "snow": ("#16304A", "#BFE6FF"), "ember": ("#1A0806", "#FF7A2E"),
                "nebula": ("#07051A", "#4FE3FF"), "jungle": ("#06200F", "#2ECC71"), "sakura": ("#2A0E22", "#FF9CCB"),
                "carbon": ("#15181C", "#2C3238"), "dunes": ("#F2A65A", "#FFD9A0"), "honeycomb": ("#1A1204", "#FFB627"),
                "comet": ("#060B1E", "#4F8BFF"), "deepsea": ("#021226", "#1FB5D6"), "city": ("#0B0F2A", "#3A2A6B"),
                "neon": ("#0A0412", "#2A0F3D"), "fireflies": ("#0C2416", "#1B3D22"), "storm": ("#0D1220", "#3A4A6B"),
                "vortex": ("#08041A", "#4FE3FF"),
                "slate": ("#2A3138", "#56616B"), "pastel": ("#F7C6D9", "#B8D8FF"), "tides": ("#062A3A", "#33C4D8"),
                "canyon": ("#4A1E10", "#E07A3C"), "koi": ("#062A28", "#0E5B57"), "synthwave": ("#14052B", "#FF2BD6"),
                "supernova": ("#05030F", "#FFB347"), "dragon": ("#120406", "#C8283D"), "wreath": ("#5A0E18", "#C8283D"),
                "hearth": ("#1C0A05", "#FF8A3D"), "northstar": ("#050B1E", "#1B3A6B"),
                "mosaic": ("#1B2230", "#5A6B8A"), "reef": ("#03263A", "#12A3B8"), "thunder": ("#0B1022", "#2A3A6B"),
                "blackhole": ("#020205", "#120A24"), "crystal": ("#0A1424", "#2A4A7A"),
                "lagoon": ("#0FA3B8", "#7FE8D8"), "peach": ("#FFB48A", "#FFE3CC"), "zigzag": ("#2A1A5A", "#6B3FA8"),
                "waveform": ("#0A0F24", "#1A1A44"), "radar": ("#03130A", "#062414"), "constellations": ("#070B24", "#14204A"),
                "equalizer": ("#0A0612", "#1A0F2A"), "orbit": ("#04050F", "#0E1030"), "spirograph": ("#08040F", "#150A24"),
                "goldveins": ("#0A0805", "#1C150A"),
                "ripples": ("#052B3A", "#1FA6B8"), "pinwheel": ("#2B1A5A", "#FF5C8A"), "ticker": ("#06110C", "#2ECC71"), "lightleaks": ("#1A1014", "#FF9A3D"),
                "nixie": ("#0B0604", "#FF8A2B"), "tvstatic": ("#111417", "#8FA0AD"), "vinyl": ("#120A1A", "#C0587E"), "pendulum": ("#10151F", "#7D8C99"),
                "hologram": ("#02101A", "#35E6FF"), "mandala": ("#12041F", "#FF5CC8"),
                "meadow": ("#8FD3FF", "#E9F8FF"), "paper": ("#F3E9D6", "#D9C7A5"), "clouds": ("#2F7BFF", "#9AD0FF"),
                "bokeh": ("#120A24", "#2A1448"), "pixels": ("#0B1020", "#1B2A5A"), "ribbons": ("#1A0B3A", "#4A1A7A"),
                "glitch": ("#0A0A12", "#1A1030"), "sunbeams": ("#0D6E8C", "#06233A"), "stardesert": ("#0A0F2E", "#3A2358"),
                "kaleido": ("#120826", "#0A1A3A"), "liquidgold": ("#1A1004", "#4A2E08"), "meteors": ("#03040E", "#0F1640"),
                "sunrise": ("#2A1A4A", "#FF9E5C"), "bubbles": ("#06334A", "#1F8FB8"), "plasma": ("#12051F", "#5A1F8F"),
                "rain": ("#05060F", "#101A33"), "fireworks": ("#040612", "#0E1430"), "hyperspace": ("#020208", "#0A0A24")}

# --------------------------------------------------------------------------- #
# 6.4: twelve new profile banners (not seasonal): 3 Common, 3 Rare, 3 Special, 3 Epic
# --------------------------------------------------------------------------- #
_BANNERS_63 = ("meadow", "paper", "clouds", "bokeh", "pixels", "ribbons", "glitch", "sunbeams", "stardesert",
               "kaleido", "liquidgold", "meteors")


def _paint_banner_63(p: QPainter, base: str, rect: QRectF, c1: QColor, c2: QColor, now: float) -> None:
    w, h = rect.width(), rect.height()
    L, T = rect.left(), rect.top()
    p.setPen(Qt.PenStyle.NoPen)
    bg = QLinearGradient(rect.topLeft(), rect.bottomLeft())
    bg.setColorAt(0.0, c1)
    bg.setColorAt(1.0, c2)
    p.fillRect(rect, bg)
    if base == "meadow":                                       # Common: a sunny sky over swaying green hills and flowers
        sun = QPointF(L + w * 0.14, T + h * 0.26)
        glow = QRadialGradient(sun, h * 0.7)
        glow.setColorAt(0, alpha("#FFF3B0", 0.9))
        glow.setColorAt(1, alpha("#FFF3B0", 0.0))
        p.setBrush(glow)
        p.drawEllipse(sun, h * 0.7, h * 0.7)
        p.setBrush(QColor("#FFF6C8"))
        p.drawEllipse(sun, h * 0.1, h * 0.1)
        for n, (col, y0, amp) in enumerate((("#6FC26B", 0.62, 0.07), ("#3FA356", 0.74, 0.06), ("#2A7D45", 0.86, 0.05))):
            hill = QPainterPath(QPointF(L, rect.bottom()))
            for x in range(0, int(w) + 6, 6):
                hill.lineTo(L + x, T + h * y0 + math.sin(x / w * 5 + n * 1.7 + now * 0.3) * h * amp)
            hill.lineTo(rect.right(), rect.bottom())
            p.setBrush(QColor(col))
            p.drawPath(hill)
        for k in range(16):
            x = L + w * _rand(k, 5)
            y = T + h * (0.78 + 0.18 * _rand(k, 6))
            sway = math.sin(now * 1.6 + k) * 1.5
            p.setBrush(QColor(["#FFFFFF", "#FFD84D", "#FF8FB1", "#B79CFF"][k % 4]))
            p.drawEllipse(QPointF(x + sway, y), 2.2, 2.2)
    elif base == "paper":                                      # Common: folded cream paper, soft shadows
        for k in range(7):
            x0 = L + (k - 1) * w / 5 + math.sin(now * 0.2 + k) * 3
            fold = QPolygonF([QPointF(x0, T), QPointF(x0 + w * 0.2, T), QPointF(x0 + w * 0.2 - h * 0.45, rect.bottom()),
                              QPointF(x0 - h * 0.45, rect.bottom())])
            g = QLinearGradient(QPointF(x0, T), QPointF(x0 + w * 0.2, T))
            g.setColorAt(0, alpha("#FFFFFF", 0.35 if k % 2 else 0.0))
            g.setColorAt(1, alpha("#7A5A2A", 0.0 if k % 2 else 0.22))
            p.setBrush(g)
            p.drawPolygon(fold)
        p.setPen(QPen(alpha("#7A5A2A", 0.25), 1.0))
        for k in range(5):
            y = T + h * (0.2 + 0.16 * k)
            p.drawLine(QPointF(L + w * 0.06, y), QPointF(L + w * (0.4 + 0.1 * (k % 3)), y))
        p.setPen(Qt.PenStyle.NoPen)
    elif base == "clouds":                                     # Common: puffy white clouds drifting across a blue sky
        for k in range(6):
            t = (now * (0.012 + 0.006 * (k % 3)) + _rand(k, 1)) % 1.0
            cx = L + w * (t * 1.4 - 0.2)
            cy = T + h * (0.2 + 0.6 * _rand(k, 2))
            s = h * (0.22 + 0.16 * _rand(k, 3))
            p.setBrush(alpha("#FFFFFF", 0.55 + 0.3 * _rand(k, 4)))
            for dx, dy, rr in ((0, 0, 1.0), (-0.8, 0.15, 0.7), (0.85, 0.12, 0.75), (0.3, -0.35, 0.8), (-0.35, -0.25, 0.7)):
                p.drawEllipse(QPointF(cx + dx * s, cy + dy * s), s * rr, s * rr * 0.75)
    elif base == "bokeh":                                      # Rare: soft out-of-focus lights drifting and breathing
        for k in range(20):
            x = L + w * ((_rand(k, 1) + math.sin(now * 0.12 + k) * 0.03) % 1.0)
            y = T + h * ((_rand(k, 2) + math.cos(now * 0.1 + k * 1.3) * 0.05) % 1.0)
            r = h * (0.12 + 0.28 * _rand(k, 3)) * (0.9 + 0.1 * math.sin(now * 0.9 + k))
            col = QColor.fromHsvF((0.82 + 0.3 * _rand(k, 4)) % 1.0, 0.55, 1.0)
            g = QRadialGradient(QPointF(x, y), r)
            g.setColorAt(0, alpha(col, 0.05))
            g.setColorAt(0.8, alpha(col, 0.28))
            g.setColorAt(1, alpha(col, 0.0))
            p.setBrush(g)
            p.drawEllipse(QPointF(x, y), r, r)
    elif base == "pixels":                                     # Rare: a grid of 8-bit squares that twinkle
        cell = max(5.0, h / 8)
        cols, rows = int(w / cell) + 1, int(h / cell) + 1
        step = int(now * 3)
        for i in range(cols):
            for j in range(rows):
                v = _rand(i * 31 + j, 7) * 0.5 + 0.5 * _rand(i + j * 17, step % 6)
                if v < 0.5:
                    continue
                p.setBrush(alpha(mix(c2, QColor("#7FE9FF"), (v - 0.5) * 2), 0.18 + 0.5 * (v - 0.5)))
                p.drawRect(QRectF(L + i * cell + 0.5, T + j * cell + 0.5, cell - 1, cell - 1))
    elif base == "ribbons":                                    # Rare: silky ribbons of colour waving across
        for k, col in enumerate(("#FF5CB8", "#4FD8FF", "#FFC94D", "#9B5CFF")):
            for width, a in ((9, 0.12), (4, 0.35), (1.6, 0.9)):
                path = QPainterPath()
                for x in range(0, int(w) + 6, 6):
                    y = T + h * (0.5 + 0.28 * math.sin(x / w * 5.5 + now * (0.7 + k * 0.15) + k * 1.6)
                                 * math.cos(x / w * 2.2 + k))
                    path.lineTo(L + x, y) if x else path.moveTo(L + x, y)
                p.setPen(QPen(alpha(col, a), width, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
                p.setBrush(Qt.BrushStyle.NoBrush)
                p.drawPath(path)
        p.setPen(Qt.PenStyle.NoPen)
    elif base == "glitch":                                     # Special: a broken screen, slices that jump sideways
        step = int(now * 7)
        for k in range(14):
            seed = k * 13 + step
            if _rand(seed, 3) < 0.45:
                continue
            y = T + h * _rand(seed, 4)
            hh = h * (0.03 + 0.1 * _rand(seed, 5))
            sh = (_rand(seed, 6) - 0.5) * w * 0.2
            p.setBrush(alpha("#00FFE0", 0.35))
            p.drawRect(QRectF(L + sh, y, w * (0.2 + 0.5 * _rand(seed, 7)), hh))
            p.setBrush(alpha("#FF2BD6", 0.35))
            p.drawRect(QRectF(L - sh + w * 0.1, y + hh * 0.3, w * (0.2 + 0.4 * _rand(seed, 8)), hh))
        p.setBrush(alpha("#FFFFFF", 0.05))
        for y in range(0, int(h), 4):
            p.drawRect(QRectF(L, T + y, w, 1.2))
    elif base == "sunbeams":                                   # Special: light falling through deep water
        for k in range(6):
            x0 = L + w * (0.05 + 0.18 * k) + math.sin(now * 0.4 + k * 1.3) * w * 0.03
            ray = QPainterPath(QPointF(x0 - w * 0.025, T))
            ray.lineTo(x0 + w * 0.045, T)
            ray.lineTo(x0 + w * 0.17, rect.bottom())
            ray.lineTo(x0 - w * 0.01, rect.bottom())
            ray.closeSubpath()
            g = QLinearGradient(QPointF(0, T), QPointF(0, rect.bottom()))
            g.setColorAt(0, alpha("#CFF6FF", 0.30 + 0.1 * math.sin(now + k)))
            g.setColorAt(1, alpha("#CFF6FF", 0.0))
            p.setBrush(g)
            p.drawPath(ray)
        for k in range(22):
            t = (now * (0.03 + 0.04 * _rand(k, 1)) + _rand(k, 2)) % 1.0
            p.setBrush(alpha("#E8FCFF", 0.35 * (1 - t) + 0.1))
            p.drawEllipse(QPointF(L + w * _rand(k, 3) + math.sin(now + k) * 4, rect.bottom() - t * h), 1.4, 1.4)
    elif base == "stardesert":                                 # Special: twinkling stars over dark dunes, a moon
        for k in range(46):
            tw = 0.4 + 0.6 * abs(math.sin(now * (0.8 + _rand(k, 1)) + k))
            p.setBrush(alpha("#FFFFFF", 0.8 * tw))
            p.drawEllipse(QPointF(L + w * _rand(k, 2), T + h * 0.7 * _rand(k, 3)), 0.9 + _rand(k, 4), 0.9 + _rand(k, 4))
        moon = QPointF(L + w * 0.82, T + h * 0.28)
        mg = QRadialGradient(moon, h * 0.6)
        mg.setColorAt(0, alpha("#FFF1C8", 0.5))
        mg.setColorAt(1, alpha("#FFF1C8", 0.0))
        p.setBrush(mg)
        p.drawEllipse(moon, h * 0.6, h * 0.6)
        p.setBrush(QColor("#FFF1C8"))
        p.drawEllipse(moon, h * 0.12, h * 0.12)
        for n, (col, y0) in enumerate((("#4A2A3E", 0.7), ("#2B1830", 0.84))):
            dune = QPainterPath(QPointF(L, rect.bottom()))
            for x in range(0, int(w) + 8, 8):
                dune.lineTo(L + x, T + h * y0 + math.sin(x / w * 3.2 + n * 2.4) * h * 0.09)
            dune.lineTo(rect.right(), rect.bottom())
            p.setBrush(QColor(col))
            p.drawPath(dune)
    elif base == "kaleido":                                    # Epic: a turning kaleidoscope of mirrored colour
        cen = QPointF(L + w * 0.5, T + h * 0.5)
        rad = math.hypot(w, h) * 0.6
        n = 16
        for k in range(n):
            a0 = k * 360 / n + now * 14
            col = QColor.fromHsvF((k / n + now * 0.04) % 1.0, 0.7, 1.0)
            p.setBrush(alpha(col, 0.5 if k % 2 else 0.25))
            p.drawPie(QRectF(cen.x() - rad, cen.y() - rad, 2 * rad, 2 * rad), int(-a0 * 16), int(-360 / n * 16))
        core = QRadialGradient(cen, h * 0.5)
        core.setColorAt(0, alpha("#FFFFFF", 0.7))
        core.setColorAt(1, alpha("#FFFFFF", 0.0))
        p.setBrush(core)
        p.drawEllipse(cen, h * 0.5, h * 0.5)
    elif base == "liquidgold":                                 # Epic: molten gold flowing in slow waves
        for k in range(4):
            path = QPainterPath(QPointF(L, rect.bottom()))
            for x in range(0, int(w) + 6, 6):
                y = T + h * (0.28 + 0.17 * k) + math.sin(x / w * (3.0 + k) + now * (0.5 + 0.12 * k) + k * 1.4) * h * 0.11
                path.lineTo(L + x, y)
            path.lineTo(rect.right(), rect.bottom())
            g = QLinearGradient(QPointF(0, T + h * 0.2), QPointF(0, rect.bottom()))
            g.setColorAt(0, alpha("#FFE08A", 0.85 - 0.12 * k))
            g.setColorAt(1, alpha("#B8751A", 0.9))
            p.setBrush(g)
            p.setPen(QPen(alpha("#FFF6C8", 0.7), 1.2))
            p.drawPath(path)
        p.setPen(Qt.PenStyle.NoPen)
        glint = (now * 0.25) % 1.4 - 0.2
        sg = QLinearGradient(QPointF(L + w * glint, 0), QPointF(L + w * (glint + 0.18), 0))
        sg.setColorAt(0, alpha("#FFFFFF", 0.0))
        sg.setColorAt(0.5, alpha("#FFFFFF", 0.35))
        sg.setColorAt(1, alpha("#FFFFFF", 0.0))
        p.fillRect(rect, sg)
    elif base == "meteors":                                    # Epic: a shower of meteors tearing across a night sky
        for k in range(40):
            p.setBrush(alpha("#FFFFFF", 0.25 + 0.5 * abs(math.sin(now + k))))
            p.drawEllipse(QPointF(L + w * _rand(k, 1), T + h * _rand(k, 2)), 0.8, 0.8)
        for k in range(10):
            t = (now * (0.45 + 0.2 * _rand(k, 1)) + _rand(k, 2)) % 1.25
            x = L + w * (_rand(k, 3) * 0.9 + 0.1) - t * w * 0.55
            y = T - h * 0.2 + t * h * 0.95
            for j in range(18):
                f = j / 18
                p.setBrush(alpha(mix(QColor("#FFFFFF"), QColor("#FF8A3D"), f), 0.9 * (1 - f)))
                rr = 2.4 * (1 - f * 0.8)
                p.drawEllipse(QPointF(x + f * w * 0.12, y - f * h * 0.22), rr, rr)


# --------------------------------------------------------------------------- #
# 6.5: ten more profile banners (not seasonal)
# --------------------------------------------------------------------------- #
_BANNERS_65 = ("lagoon", "peach", "zigzag", "waveform", "radar", "constellations", "equalizer", "orbit", "spirograph", "goldveins")


def _paint_banner_65(p: QPainter, base: str, rect: QRectF, c1: QColor, c2: QColor, now: float) -> None:
    w, h = rect.width(), rect.height()
    L, T = rect.left(), rect.top()
    p.setPen(Qt.PenStyle.NoPen)
    bg = QLinearGradient(rect.topLeft(), rect.bottomRight())
    bg.setColorAt(0.0, c1)
    bg.setColorAt(1.0, c2)
    p.fillRect(rect, bg)
    if base == "lagoon":                                       # Common: turquoise water, light rippling on the surface
        for k in range(5):
            path = QPainterPath()
            for x in range(0, int(w) + 6, 6):
                y = T + h * (0.2 + 0.16 * k) + math.sin(x / w * 7 + now * 0.9 + k) * h * 0.04
                path.lineTo(L + x, y) if x else path.moveTo(L + x, y)
            p.setPen(QPen(alpha("#E6FFFB", 0.25), 1.6))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawPath(path)
        p.setPen(Qt.PenStyle.NoPen)
        for k in range(14):
            p.setBrush(alpha("#FFFFFF", 0.25 * abs(math.sin(now * 1.3 + k * 2.1))))
            p.drawEllipse(QPointF(L + w * _rand(k, 1), T + h * _rand(k, 2)), 1.6, 1.6)
    elif base == "peach":                                      # Common: soft peach light with slowly drifting round shapes
        for k in range(7):
            cx = L + w * ((_rand(k, 1) + math.sin(now * 0.1 + k) * 0.04) % 1.0)
            r = h * (0.3 + 0.5 * _rand(k, 2))
            g = QRadialGradient(QPointF(cx, T + h * _rand(k, 3)), r)
            col = ["#FFD2B0", "#FF9E8A", "#FFE9C8"][k % 3]
            g.setColorAt(0, alpha(col, 0.55))
            g.setColorAt(1, alpha(col, 0.0))
            p.setBrush(g)
            p.drawEllipse(QPointF(cx, T + h * _rand(k, 3)), r, r)
    elif base == "zigzag":                                     # Common: chevrons sliding sideways
        step = h * 0.5
        off = (now * 18) % (step * 2)
        for row in range(int(h / step) + 2):
            path = QPainterPath()
            for i in range(-2, int(w / step) + 4):
                x = L + i * step - off
                y = T + row * step + (step * 0.5 if i % 2 else 0)
                path.lineTo(x, y) if i > -2 else path.moveTo(x, y)
            p.setPen(QPen(alpha("#FFFFFF" if row % 2 else c2, 0.22), 2.0))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawPath(path)
        p.setPen(Qt.PenStyle.NoPen)
    elif base == "waveform":                                   # Rare: sound bars that move with a made-up song
        n = max(20, int(w / 7))
        for i in range(n):
            amp = abs(math.sin(i * 0.37 + now * 2.2) * math.cos(i * 0.11 - now * 1.1)) * 0.8 + 0.1
            bh = h * 0.8 * amp
            col = mix(QColor("#FF5CB8"), QColor("#4FD8FF"), i / n)
            p.setBrush(alpha(col, 0.85))
            p.drawRoundedRect(QRectF(L + i * w / n + 1, T + (h - bh) / 2, w / n - 2, bh), 1.5, 1.5)
    elif base == "radar":                                      # Rare: a green sweep over rings, blips appearing
        cen = QPointF(L + w * 0.5, T + h * 0.5)
        p.setBrush(Qt.BrushStyle.NoBrush)
        for k in range(1, 5):
            p.setPen(QPen(alpha("#3DFF9A", 0.22), 1.0))
            p.drawEllipse(cen, h * 0.28 * k, h * 0.28 * k)
        p.setPen(QPen(alpha("#3DFF9A", 0.18), 1.0))
        p.drawLine(QPointF(L, cen.y()), QPointF(L + w, cen.y()))
        p.drawLine(QPointF(cen.x(), T), QPointF(cen.x(), T + h))
        ang = (now * 90) % 360
        sweep = QConicalGradient(cen, -ang)
        sweep.setColorAt(0.0, alpha("#3DFF9A", 0.55))
        sweep.setColorAt(0.2, alpha("#3DFF9A", 0.0))
        sweep.setColorAt(1.0, alpha("#3DFF9A", 0.0))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(sweep)
        p.drawEllipse(cen, w, w)
        for k in range(5):
            a = _rand(k, 1) * 360
            f = ((ang - a) % 360) / 360
            p.setBrush(alpha("#B8FFD8", max(0.0, 1.0 - f * 2)))
            r = h * 0.12 + h * 0.8 * _rand(k, 2)
            p.drawEllipse(QPointF(cen.x() + math.cos(math.radians(a)) * r * 1.4, cen.y() + math.sin(math.radians(a)) * r * 0.45), 2.6, 2.6)
    elif base == "constellations":                             # Rare: stars joined into drifting shapes
        pts = [QPointF(L + w * ((_rand(k, 1) + now * 0.004 * (1 + k % 3)) % 1.0), T + h * (0.15 + 0.7 * _rand(k, 2)
               + math.sin(now * 0.5 + k) * 0.03)) for k in range(18)]
        p.setPen(QPen(alpha("#BFD8FF", 0.28), 1.0))
        for i in range(len(pts)):
            for j in range(i + 1, len(pts)):
                if math.hypot(pts[i].x() - pts[j].x(), pts[i].y() - pts[j].y()) < w * 0.17:
                    p.drawLine(pts[i], pts[j])
        p.setPen(Qt.PenStyle.NoPen)
        for k, pt in enumerate(pts):
            p.setBrush(alpha("#FFFFFF", 0.55 + 0.4 * math.sin(now * 2 + k)))
            p.drawEllipse(pt, 1.7, 1.7)
    elif base == "equalizer":                                  # Special: stacked colour blocks bouncing like a club equalizer
        n = max(10, int(w / 14))
        blocks = 8
        for i in range(n):
            lvl = int(blocks * (0.25 + 0.75 * abs(math.sin(i * 0.9 + now * (2.0 + (i % 3) * 0.6)))))
            for b in range(blocks):
                if b >= lvl:
                    continue
                col = QColor("#3DFF7A") if b < 4 else QColor("#FFD84D") if b < 6 else QColor("#FF4D4D")
                p.setBrush(alpha(col, 0.9))
                bh = h / blocks
                p.drawRect(QRectF(L + i * w / n + 1, T + h - (b + 1) * bh + 1, w / n - 3, bh - 2))
    elif base == "orbit":                                      # Special: planets circling a glowing sun
        cen = QPointF(L + w * 0.5, T + h * 0.5)
        sun = QRadialGradient(cen, h * 0.5)
        sun.setColorAt(0, alpha("#FFE8A0", 0.95))
        sun.setColorAt(0.25, alpha("#FFB627", 0.6))
        sun.setColorAt(1, alpha("#FFB627", 0.0))
        p.setBrush(sun)
        p.drawEllipse(cen, h * 0.5, h * 0.5)
        for k, (rx, ry, col, sz, sp) in enumerate(((0.18, 0.3, "#4FD8FF", 3.5, 1.4), (0.28, 0.4, "#FF7A9C", 4.5, 0.9),
                                                    (0.4, 0.46, "#B36BFF", 5.5, 0.6), (0.52, 0.49, "#7CFFB0", 4.0, 0.35))):
            p.setPen(QPen(alpha("#FFFFFF", 0.12), 1.0))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawEllipse(cen, w * rx, h * ry)
            a = now * sp + k * 1.7
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor(col))
            p.drawEllipse(QPointF(cen.x() + math.cos(a) * w * rx, cen.y() + math.sin(a) * h * ry), sz, sz)
    elif base == "spirograph":                                 # Epic: a drawing machine weaving glowing curves
        cen = QPointF(L + w * 0.5, T + h * 0.5)
        for layer, (R, r, d, col) in enumerate(((0.48, 0.17, 0.3, "#FF5CB8"), (0.44, 0.11, 0.22, "#4FD8FF"), (0.4, 0.23, 0.35, "#FFD84D"))):
            path = QPainterPath()
            k = R / r
            for i in range(0, 721):
                t = math.radians(i) + now * 0.25 * (1 + layer * 0.3)
                x = (R - r) * math.cos(t) + d * math.cos((R - r) / r * t)
                y = (R - r) * math.sin(t) - d * math.sin((R - r) / r * t)
                pt = QPointF(cen.x() + x * h * 1.1, cen.y() + y * h * 1.1)
                path.lineTo(pt) if i else path.moveTo(pt)
            for width, a in ((5, 0.10), (1.4, 0.8)):
                p.setPen(QPen(alpha(col, a), width))
                p.setBrush(Qt.BrushStyle.NoBrush)
                p.drawPath(path)
        p.setPen(Qt.PenStyle.NoPen)
    elif base == "goldveins":                                  # Epic: black stone with veins of gold that pulse
        for k in range(7):
            path = QPainterPath(QPointF(L + w * _rand(k, 1), T))
            x, y = L + w * _rand(k, 1), T
            for s in range(10):
                x += (math.sin(k * 3.1 + s * 1.7) * 0.07 + (_rand(k, 5) - 0.5) * 0.04) * w
                y += h / 9
                path.lineTo(x, y)
            pulse = 0.45 + 0.35 * math.sin(now * 1.5 + k)
            for width, a in ((6, 0.08), (2.2, 0.35 * pulse + 0.2), (0.9, 0.95)):
                p.setPen(QPen(alpha("#FFD36B" if width < 3 else "#FFB627", a), width, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
                p.setBrush(Qt.BrushStyle.NoBrush)
                p.drawPath(path)
        p.setPen(Qt.PenStyle.NoPen)


def look_moves(item: str) -> bool:
    return parts(item)[1] in MOVING


def _rand(i: int, k: int = 0) -> float:
    """A fixed pseudo random number in [0, 1) (so stars stay where they are between frames)."""
    x = math.sin(i * 12.9898 + k * 78.233) * 43758.5453
    return x - math.floor(x)


# --------------------------------------------------------------------------- #
# 6.7: ten more profile banners (not seasonal), all moving
# --------------------------------------------------------------------------- #
_BANNERS_66 = ("ripples", "pinwheel", "ticker", "lightleaks", "nixie", "tvstatic", "vinyl", "pendulum", "hologram", "mandala")


def _paint_banner_66(p: QPainter, base: str, rect: QRectF, c1: QColor, c2: QColor, now: float) -> None:
    w, h = rect.width(), rect.height()
    L, T = rect.left(), rect.top()
    p.setPen(Qt.PenStyle.NoPen)
    bg = QLinearGradient(rect.topLeft(), rect.bottomRight())
    bg.setColorAt(0.0, c1)
    bg.setColorAt(1.0, mix(c1, c2, 0.5) if base in ("nixie", "vinyl", "hologram", "ticker", "pendulum") else c2)
    p.fillRect(rect, bg)
    if base == "ripples":                                      # Common: rings spreading from drops that land on the water
        for k in range(6):
            u = now * 0.28 + k / 6
            idx, t = int(u), u % 1.0
            cx, cy = L + w * _rand(k * 13 + idx, 1), T + h * (0.2 + 0.6 * _rand(k * 13 + idx, 2))
            for ring in range(3):
                tt = t - ring * 0.12
                if tt <= 0:
                    continue
                r = tt * h * 1.7
                p.setPen(QPen(alpha("#DFFBFF", 0.55 * (1 - tt) ** 1.5), 1.4))
                p.setBrush(Qt.BrushStyle.NoBrush)
                p.drawEllipse(QPointF(cx, cy), r * 1.5, r * 0.6)
        p.setPen(Qt.PenStyle.NoPen)
    elif base == "pinwheel":                                   # Common: a colour fan that turns, with a second one turning back
        for cx, R, direction, col in ((0.3, w * 0.6, 1, c2), (0.78, w * 0.45, -1, QColor("#FFD27A"))):
            c = QPointF(L + w * cx, T + h * 0.5)
            n = 14
            rot = now * 0.45 * direction
            for k in range(n):
                a0 = rot + k * 2 * math.pi / n
                a1 = a0 + math.pi / n
                tri = QPolygonF([c, QPointF(c.x() + math.cos(a0) * R, c.y() + math.sin(a0) * R),
                                 QPointF(c.x() + math.cos(a1) * R, c.y() + math.sin(a1) * R)])
                p.setBrush(alpha(col, 0.34 if k % 2 else 0.10))
                p.drawPolygon(tri)
            p.setBrush(alpha("#FFFFFF", 0.7))
            p.drawEllipse(c, h * 0.06, h * 0.06)
    elif base == "ticker":                                     # Common: a stock chart scrolling past, candle after candle
        step = 9.0
        shift = now * 16
        first = int(shift // step)
        off = shift % step

        def val(i: int) -> float:
            return 0.5 + 0.26 * math.sin(i * 0.43) + 0.13 * math.sin(i * 1.13 + 2) + 0.07 * math.sin(i * 2.9)
        p.setPen(QPen(alpha("#FFFFFF", 0.06), 1, Qt.PenStyle.DashLine))
        for k in range(1, 4):
            p.drawLine(QPointF(L, T + h * k / 4), QPointF(rect.right(), T + h * k / 4))
        for i in range(int(w / step) + 3):
            idx = first + i
            a, b = val(idx), val(idx + 1)
            x = L + i * step - off
            col = QColor("#3DDC84" if b >= a else "#FF5C5C")
            p.setPen(QPen(col, 1))
            hi, lo = max(a, b) + 0.05 * abs(math.sin(idx)), min(a, b) - 0.05 * abs(math.cos(idx))
            p.drawLine(QPointF(x, T + h * (1 - hi)), QPointF(x, T + h * (1 - lo)))
            p.setBrush(col)
            p.drawRect(QRectF(x - 2.5, T + h * (1 - max(a, b)), 5, max(1.5, h * abs(b - a))))
        p.setPen(Qt.PenStyle.NoPen)
    elif base == "lightleaks":                                 # Rare: warm film light leaks drifting over grainy film
        for k, col in enumerate(("#FF9A3D", "#FF3D6E", "#FFD27A", "#FF7A2E", "#FFB0A0")):
            cx = L + w * (0.5 + 0.55 * math.sin(now * (0.17 + k * 0.05) + k * 2.1))
            cy = T + h * (0.5 + 0.45 * math.cos(now * (0.21 + k * 0.04) + k))
            r = h * (0.9 + 0.35 * math.sin(now * 0.4 + k))
            g = QRadialGradient(QPointF(cx, cy), r)
            g.setColorAt(0, alpha(col, 0.6))
            g.setColorAt(1, alpha(col, 0.0))
            p.setBrush(g)
            p.drawEllipse(QPointF(cx, cy), r, r)
        fr = int(now * 14)
        for k in range(70):
            p.setBrush(alpha("#FFFFFF", 0.05 + 0.14 * _rand(k + fr * 71, 5)))
            p.drawEllipse(QPointF(L + w * _rand(k + fr * 71, 3), T + h * _rand(k + fr * 71, 4)), 0.9, 0.9)
        flick = 0.04 + 0.04 * math.sin(now * 23) * math.sin(now * 7.3)
        p.fillRect(rect, alpha("#FFE9B0", max(0.0, flick)))
    elif base == "nixie":                                      # Rare: glass tubes with glowing digits that count and flicker
        n = max(4, int(w / (h * 0.62)))
        tw = w / n
        f = font(20, QFont.Weight.Bold)
        f.setPixelSize(max(8, int(h * 0.56)))
        p.setFont(f)
        for i in range(n):
            tube = QRectF(L + i * tw + tw * 0.14, T + h * 0.1, tw * 0.72, h * 0.8)
            p.setPen(QPen(alpha("#FFD9A8", 0.16), 1.2))
            p.setBrush(alpha("#000000", 0.30))
            p.drawRoundedRect(tube, tw * 0.3, tw * 0.3)
            ch = str(int(_rand(i, int(now * 0.9 + i * 0.37) + 11) * 10))
            fl = 0.8 + 0.2 * math.sin(now * 29 + i * 5) * math.sin(now * 3 + i)
            glow = QRadialGradient(tube.center(), tw * 0.9)
            glow.setColorAt(0, alpha("#FF8A2B", 0.35 * fl))
            glow.setColorAt(1, alpha("#FF8A2B", 0.0))
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(glow)
            p.drawEllipse(tube.center(), tw * 0.9, tw * 0.9)
            for dx, a in ((-1.2, 0.22), (1.2, 0.22), (0, 1.0)):
                p.setPen(alpha("#FFB04D", a * fl))
                p.drawText(tube.translated(dx, 0), int(Qt.AlignmentFlag.AlignCenter), ch)
        p.setPen(Qt.PenStyle.NoPen)
    elif base == "tvstatic":                                   # Rare: an old TV that lost its signal: snow, scanlines, a rolling bar
        cell = 5.0
        fr = int(now * 18)
        nx, ny = int(w / cell) + 1, int(h / cell) + 1
        for ix in range(nx):
            for iy in range(ny):
                v = _rand(ix + iy * 997 + fr * 131, 6)
                p.setBrush(QColor(int(120 * v + 20), int(130 * v + 22), int(140 * v + 28), 150))
                p.drawRect(QRectF(L + ix * cell, T + iy * cell, cell, cell))
        by = T + ((now * 0.32) % 1.5 - 0.25) * h
        g = QLinearGradient(QPointF(0, by - h * 0.18), QPointF(0, by + h * 0.18))
        g.setColorAt(0, alpha("#FFFFFF", 0.0))
        g.setColorAt(0.5, alpha("#FFFFFF", 0.16))
        g.setColorAt(1, alpha("#FFFFFF", 0.0))
        p.fillRect(QRectF(L, by - h * 0.18, w, h * 0.36).intersected(rect), g)
        p.setPen(QPen(alpha("#000000", 0.22), 1))
        for y in range(0, int(h), 3):
            p.drawLine(QPointF(L, T + y), QPointF(rect.right(), T + y))
        p.setPen(Qt.PenStyle.NoPen)
    elif base == "vinyl":                                      # Special: a record spinning under the needle, light gliding over the grooves
        c = QPointF(L + w * 0.74, T + h * 0.5)
        R = h * 1.05
        p.setBrush(QColor("#0B0B10"))
        p.drawEllipse(c, R, R)
        p.setBrush(Qt.BrushStyle.NoBrush)
        for k in range(1, 15):
            p.setPen(QPen(alpha("#FFFFFF", 0.07 if k % 3 else 0.14), 1))
            p.drawEllipse(c, R * (0.4 + 0.043 * k), R * (0.4 + 0.043 * k))
        g = QConicalGradient(c, 35)
        for pos, a in ((0.0, 0.0), (0.06, 0.22), (0.12, 0.0), (0.5, 0.0), (0.56, 0.22), (0.62, 0.0), (1.0, 0.0)):
            g.setColorAt(pos, alpha("#FFFFFF", a))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(g)
        p.drawEllipse(c, R, R)
        ang = now * 2.3
        p.setBrush(c2)
        p.drawEllipse(c, R * 0.34, R * 0.34)
        p.setBrush(alpha("#FFFFFF", 0.85))
        p.drawEllipse(QPointF(c.x() + math.cos(ang) * R * 0.22, c.y() + math.sin(ang) * R * 0.22), h * 0.03, h * 0.03)
        p.setBrush(QColor("#10101A"))
        p.drawEllipse(c, h * 0.04, h * 0.04)
        p.setPen(QPen(QColor("#C9D2DA"), 2.6, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
        p.drawLine(QPointF(L + w * 0.97, T + h * 0.05), QPointF(c.x() - R * 0.3, c.y() - R * 0.62))
        p.setPen(QPen(alpha("#FFFFFF", 0.10 * (1 + math.sin(now * 4))), 1))
        for k in range(3):
            u = (now * 0.5 + k / 3) % 1.0
            p.drawArc(QRectF(L + w * (0.2 - u * 0.15), T + h * (0.5 - 0.4 * u), h * 0.5 * (0.5 + u), h * 0.8 * (0.5 + u)), 120 * 16, 120 * 16)
        p.setPen(Qt.PenStyle.NoPen)
    elif base == "pendulum":                                   # Special: a Newton's cradle, the outer balls swinging in turn
        s = math.sin(now * 2.4)
        cx, top, r = L + w * 0.5, T + h * 0.08, h * 0.105
        ln = h * 0.62
        p.setPen(QPen(alpha("#FFFFFF", 0.5), 2.5, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
        p.drawLine(QPointF(cx - r * 6, top), QPointF(cx + r * 6, top))
        for i in range(5):
            px = cx + (i - 2) * 2 * r
            ang = -max(0.0, s) * 0.62 if i == 0 else (max(0.0, -s) * 0.62 if i == 4 else 0.0)
            bx, by = px + math.sin(ang) * ln, top + math.cos(ang) * ln
            p.setPen(QPen(alpha("#FFFFFF", 0.4), 1.1))
            p.drawLine(QPointF(px - r * 0.45, top), QPointF(bx, by))
            p.drawLine(QPointF(px + r * 0.45, top), QPointF(bx, by))
            g = QRadialGradient(QPointF(bx - r * 0.3, by - r * 0.35), r * 1.3)
            g.setColorAt(0, QColor("#FFFFFF"))
            g.setColorAt(0.45, mix(c2, QColor("#FFFFFF"), 0.35))
            g.setColorAt(1, mix(c1, QColor("#000000"), 0.5))
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(g)
            p.drawEllipse(QPointF(bx, by), r, r)
            p.setBrush(alpha("#000000", 0.18))
            p.drawEllipse(QPointF(bx, T + h * 0.97), r * 0.9, r * 0.18)
    elif base == "hologram":                                   # Epic: wireframe shapes turning in a cyan light, scanlines gliding over them
        def cube(cx: float, cy: float, size: float, a: float, b: float, col: QColor) -> None:
            pts = []
            for x in (-1, 1):
                for y in (-1, 1):
                    for z in (-1, 1):
                        x1, z1 = x * math.cos(a) - z * math.sin(a), x * math.sin(a) + z * math.cos(a)
                        y1, z2 = y * math.cos(b) - z1 * math.sin(b), y * math.sin(b) + z1 * math.cos(b)
                        k = 1 / (1 + z2 * 0.18)
                        pts.append(QPointF(cx + x1 * size * k, cy + y1 * size * k))
            edges = [(0, 1), (2, 3), (4, 5), (6, 7), (0, 2), (1, 3), (4, 6), (5, 7), (0, 4), (1, 5), (2, 6), (3, 7)]
            for wd, al in ((5.0, 0.10), (2.6, 0.25), (1.1, 0.95)):
                p.setPen(QPen(alpha(col, al), wd, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
                for i, j in edges:
                    p.drawLine(pts[i], pts[j])
        p.setBrush(Qt.BrushStyle.NoBrush)
        cube(L + w * 0.5, T + h * 0.5, h * 0.3, now * 0.9, now * 0.6, c2)
        cube(L + w * 0.22, T + h * 0.5, h * 0.17, -now * 1.2, now * 0.8, QColor("#7CF5FF"))
        cube(L + w * 0.78, T + h * 0.5, h * 0.17, now * 1.1, -now * 0.7, QColor("#7CF5FF"))
        p.setPen(QPen(alpha(c2, 0.35), 1))
        p.drawEllipse(QPointF(L + w * 0.5, T + h * 0.92), h * 0.9, h * 0.1)
        sy = T + ((now * 0.35) % 1.0) * h
        g = QLinearGradient(QPointF(0, sy - h * 0.15), QPointF(0, sy + h * 0.15))
        g.setColorAt(0, alpha(c2, 0.0))
        g.setColorAt(0.5, alpha(c2, 0.22))
        g.setColorAt(1, alpha(c2, 0.0))
        p.setPen(Qt.PenStyle.NoPen)
        p.fillRect(QRectF(L, sy - h * 0.15, w, h * 0.3).intersected(rect), g)
        p.setPen(QPen(alpha("#000000", 0.18), 1))
        for y in range(0, int(h), 3):
            p.drawLine(QPointF(L, T + y), QPointF(rect.right(), T + y))
        p.setPen(Qt.PenStyle.NoPen)
    elif base == "mandala":                                    # Epic: layers of petals turning against each other, colours slowly cycling
        for cxf, scale, direction in ((0.5, 1.0, 1), (0.1, 0.62, -1), (0.9, 0.62, -1)):
            c = QPointF(L + w * cxf, T + h * 0.5)
            for j in range(5):
                n = 8 + j * 2
                R = h * (0.22 + 0.2 * j) * scale
                rot = now * 0.22 * direction * (1 if j % 2 else -1) + j
                for k in range(n):
                    p.save()
                    p.translate(c)
                    p.rotate(math.degrees(rot) + k * 360 / n)
                    col = QColor.fromHsvF((now * 0.03 + j * 0.13 + k / n * 0.25) % 1.0, 0.65, 1.0)
                    p.setBrush(alpha(col, 0.30))
                    p.setPen(QPen(alpha("#FFFFFF", 0.22), 0.8))
                    p.drawEllipse(QPointF(R * 0.62, 0), R * 0.4, R * 0.15)
                    p.restore()
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(alpha("#FFF3C8", 0.85))
            p.drawEllipse(c, h * 0.05 * scale, h * 0.05 * scale)
    p.setPen(Qt.PenStyle.NoPen)


def paint_banner(p: QPainter, rect: QRectF, item: str, now: float = 0.0, radius: float = 10.0, dim: float = 1.0,
                 gold: int = 0) -> None:
    """A profile banner filling `rect` (rounded corners). `gold` 1-3: it turned gold with the hours it was worn."""
    base = parts(item)[1]
    cw = _CW.get(("banner", base))
    if cw:                                                     # 6.5: a colourway: the picture, recoloured
        return _paint_banner_cw(p, rect, cw, now, radius, dim, gold)
    c1, c2 = (QColor(c) for c in _BANNER_COLS.get(base, ("#1A2026", "#3A4650")))
    w, h = rect.width(), rect.height()
    p.save()
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    p.setOpacity(p.opacity() * dim)
    clip = QPainterPath()
    clip.addRoundedRect(rect, radius, radius)
    p.setClipPath(clip)
    g = QLinearGradient(rect.topLeft(), rect.bottomRight())
    g.setColorAt(0.0, c1)
    g.setColorAt(1.0, c2 if base in ("dusk", "mint", "steel", "rose", "sunset") else mix(c1, c2, 0.35))
    p.fillRect(rect, g)
    p.setPen(Qt.PenStyle.NoPen)
    L, T = rect.left(), rect.top()
    if base == "sunrise":                                      # Common: the sun climbs slowly over soft hills
        k = (math.sin(now * 0.25) + 1) / 2
        sun = QPointF(L + w * 0.68, T + h * (0.95 - 0.5 * k))
        glow = QRadialGradient(sun, h * 0.9)
        glow.setColorAt(0, alpha("#FFD27A", 0.75))
        glow.setColorAt(1, alpha("#FFD27A", 0.0))
        p.setBrush(glow)
        p.drawEllipse(sun, h * 0.9, h * 0.9)
        p.setBrush(QColor("#FFE6A8"))
        p.drawEllipse(sun, h * 0.16, h * 0.16)
        for n, (col, base_y) in enumerate((("#3A2350", 0.72), ("#24173A", 0.84))):
            hill = QPainterPath(QPointF(L, rect.bottom()))
            for x in range(0, int(w) + 8, 8):
                hill.lineTo(L + x, T + h * base_y + math.sin(x / w * 4 + n * 2) * h * 0.07)
            hill.lineTo(rect.right(), rect.bottom())
            p.setBrush(QColor(col))
            p.drawPath(hill)
    elif base == "bubbles":                                    # Common: bubbles drifting up
        for k in range(26):
            t = (now * (0.08 + 0.1 * _rand(k, 1)) + _rand(k, 2)) % 1.0
            x = L + w * _rand(k, 3) + math.sin(now * 1.5 + k) * 5
            r = 2 + 6 * _rand(k, 4)
            p.setPen(QPen(alpha("#BFF2FF", 0.55 * (1 - t) + 0.1), 1.2))
            p.setBrush(alpha("#BFF2FF", 0.10))
            p.drawEllipse(QPointF(x, rect.bottom() + r - t * (h + 2 * r)), r, r)
        p.setPen(Qt.PenStyle.NoPen)
    elif base == "plasma":                                     # Rare: glowing plasma blobs that melt into each other
        for k in range(5):
            cx = L + w * (0.5 + 0.42 * math.sin(now * (0.3 + k * 0.07) + k * 1.7))
            cy = T + h * (0.5 + 0.4 * math.cos(now * (0.4 + k * 0.05) + k))
            g2 = QRadialGradient(QPointF(cx, cy), h * 0.8)
            col = QColor.fromHsvF((0.78 + k * 0.06 + now * 0.02) % 1.0, 0.8, 1.0)
            g2.setColorAt(0, alpha(col, 0.55))
            g2.setColorAt(1, alpha(col, 0.0))
            p.setBrush(g2)
            p.drawEllipse(QPointF(cx, cy), h * 0.8, h * 0.8)
    elif base == "rain":                                       # Rare: neon rain over a dark street
        for k in range(48):
            t = (now * (0.9 + 0.6 * _rand(k, 1)) + _rand(k, 2)) % 1.0
            x = L + w * _rand(k, 3)
            y = T - h * 0.2 + t * h * 1.3
            col = ["#FF2BD6", "#35D6E6", "#8C7CFF"][k % 3]
            p.setPen(QPen(alpha(col, 0.75), 1.4, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
            p.drawLine(QPointF(x, y), QPointF(x - 2, y + h * 0.12))
        p.setPen(Qt.PenStyle.NoPen)
        street = QLinearGradient(QPointF(0, rect.bottom() - h * 0.18), QPointF(0, rect.bottom()))
        street.setColorAt(0, alpha("#FF2BD6", 0.0))
        street.setColorAt(1, alpha("#FF2BD6", 0.35))
        p.fillRect(QRectF(L, rect.bottom() - h * 0.18, w, h * 0.18), street)
    elif base == "fireworks":                                  # Epic: rockets burst into sparks
        for k in range(5):
            period = 2.6 + _rand(k, 1) * 1.6
            t = ((now + _rand(k, 2) * period) % period) / period
            cx, cy = L + w * (0.1 + 0.8 * _rand(k + int(now / period) * 7, 3)), T + h * (0.25 + 0.3 * _rand(k, 4))
            col = QColor.fromHsvF(_rand(k + int(now / period) * 3, 5), 0.75, 1.0)
            if t < 0.3:                                        # the rocket going up
                y = rect.bottom() - (rect.bottom() - cy) * (t / 0.3)
                p.setBrush(alpha("#FFFFFF", 0.9))
                p.drawEllipse(QPointF(cx, y), 1.6, 1.6)
            else:                                              # the burst
                b = (t - 0.3) / 0.7
                for j in range(18):
                    a = j * math.tau / 18
                    d = h * 0.38 * (1 - (1 - b) ** 2)
                    p.setBrush(alpha(col, max(0.0, 1 - b)))
                    p.drawEllipse(QPointF(cx + math.cos(a) * d, cy + math.sin(a) * d + b * b * h * 0.15), 1.7, 1.7)
    elif base == "hyperspace":                                 # Legendary: stars streaking past at light speed
        cen = QPointF(L + w * 0.5, T + h * 0.5)
        core = QRadialGradient(cen, h * 0.6)
        core.setColorAt(0, alpha("#9FD8FF", 0.45))
        core.setColorAt(1, alpha("#9FD8FF", 0.0))
        p.setBrush(core)
        p.drawEllipse(cen, h * 0.6, h * 0.6)
        reach = math.hypot(w, h) * 0.55
        for k in range(70):
            a = _rand(k, 1) * math.tau
            t = (now * (0.35 + 0.5 * _rand(k, 2)) + _rand(k, 3)) % 1.0
            d0, d1 = reach * t * t, reach * min(1.0, t * t + 0.08 + 0.25 * t)
            col = mix(QColor("#FFFFFF"), QColor("#6FB8FF"), _rand(k, 4))
            p.setPen(QPen(alpha(col, 0.2 + 0.8 * t), 0.6 + 1.6 * t, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
            p.drawLine(cen + QPointF(math.cos(a) * d0, math.sin(a) * d0), cen + QPointF(math.cos(a) * d1, math.sin(a) * d1))
        p.setPen(Qt.PenStyle.NoPen)
    elif base == "waves":
        for k in range(4):
            path = QPainterPath(QPointF(L, rect.bottom()))
            for x in range(0, int(w) + 8, 6):
                y = T + h * (0.35 + k * 0.17) + math.sin(x / w * 6.3 * (1 + k * 0.3) + now * (0.8 + k * 0.3) + k) * h * 0.07
                path.lineTo(L + x, y)
            path.lineTo(rect.right(), rect.bottom())
            p.setBrush(alpha(c2, 0.16 + k * 0.08))
            p.drawPath(path)
    elif base == "grid":
        horizon = T + h * 0.45
        p.setPen(QPen(alpha(c2, 0.55), 1))
        for k in range(-10, 11):
            p.drawLine(QPointF(L + w / 2 + k * w * 0.03, horizon), QPointF(L + w / 2 + k * w * 0.16, rect.bottom()))
        off = (now * 0.4) % 1.0
        for k in range(8):
            f = ((k + off) / 8) ** 2
            p.drawLine(QPointF(L, horizon + f * (rect.bottom() - horizon)), QPointF(rect.right(), horizon + f * (rect.bottom() - horizon)))
        sun = QLinearGradient(QPointF(0, T + h * 0.05), QPointF(0, horizon))
        sun.setColorAt(0, QColor("#FF5CB8"))
        sun.setColorAt(1, QColor("#FFC94D"))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(sun)
        p.drawEllipse(QPointF(L + w / 2, horizon), h * 0.3, h * 0.3)
        p.fillRect(QRectF(L, horizon, w, h), mix(c1, QColor("#000000"), 0.2))
        p.setPen(QPen(alpha(c2, 0.55), 1))
        for k in range(-10, 11):
            p.drawLine(QPointF(L + w / 2 + k * w * 0.03, horizon), QPointF(L + w / 2 + k * w * 0.16, rect.bottom()))
        for k in range(8):
            f = ((k + off) / 8) ** 2
            p.drawLine(QPointF(L, horizon + f * (rect.bottom() - horizon)), QPointF(rect.right(), horizon + f * (rect.bottom() - horizon)))
    elif base == "stripes":
        p.setBrush(alpha(c2, 0.45))
        step = h * 0.5
        off = (now * 20) % (step * 2)
        x = L - h - step * 2 + off
        while x < rect.right() + h:
            path = QPainterPath(QPointF(x, rect.bottom()))
            path.lineTo(x + h, T)
            path.lineTo(x + h + step, T)
            path.lineTo(x + step, rect.bottom())
            p.drawPath(path)
            x += step * 2
    elif base == "dots":
        n = 22
        for i in range(n * 3):
            cx, cy = L + _rand(i) * w, T + _rand(i, 1) * h
            r = h * (0.03 + _rand(i, 2) * 0.09)
            p.setBrush(alpha(c2, 0.15 + _rand(i, 3) * 0.4))
            p.drawEllipse(QPointF(cx, cy), r, r)
    elif base == "aurora":
        for i in range(30):
            p.setBrush(alpha("#FFFFFF", 0.3 + 0.5 * _rand(i, 4)))
            p.drawEllipse(QPointF(L + _rand(i) * w, T + _rand(i, 1) * h * 0.6), 0.8, 0.8)
        for k, col in enumerate(("#3DFFB0", "#9B5CFF", "#2EC5FF")):
            path = QPainterPath(QPointF(L, T + h))
            for x in range(0, int(w) + 8, 6):
                y = T + h * (0.45 + 0.12 * k) + math.sin(x / w * 5 + now * 0.7 + k * 2) * h * 0.14 \
                    + math.sin(x / w * 13 + now * 1.3) * h * 0.04
                path.lineTo(L + x, y)
            path.lineTo(rect.right(), T + h)
            band = QLinearGradient(QPointF(0, T + h * 0.2), QPointF(0, T + h))
            band.setColorAt(0, alpha(col, 0.0))
            band.setColorAt(0.5, alpha(col, 0.35))
            band.setColorAt(1, alpha(col, 0.0))
            p.setBrush(band)
            p.drawPath(path)
    elif base == "circuit":
        p.setPen(QPen(alpha(c2, 0.45), 1.3))
        for i in range(14):
            x0, y0 = L + _rand(i) * w, T + _rand(i, 1) * h
            x1 = x0 + (_rand(i, 2) - 0.5) * w * 0.4
            path = QPainterPath(QPointF(x0, y0))
            path.lineTo(x1, y0)
            path.lineTo(x1 + h * 0.15, y0 + h * 0.15 * (1 if _rand(i, 3) > 0.5 else -1))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawPath(path)
            glow = 0.4 + 0.6 * max(0.0, math.sin(now * 2 + i * 1.7))
            p.setBrush(alpha(c2, glow))
            p.drawEllipse(QPointF(x0, y0), 2.2, 2.2)
        p.setPen(Qt.PenStyle.NoPen)
    elif base == "sunset":
        p.setBrush(alpha("#FFC94D", 0.95))
        sun = QRectF(L + w * 0.62, T + h * 0.18, h * 0.62, h * 0.62)
        p.drawEllipse(sun)
        for k in range(5):
            p.fillRect(QRectF(sun.left(), sun.top() + sun.height() * (0.52 + k * 0.1), sun.width(), sun.height() * 0.035 * (k + 1)),
                       mix(QColor("#C0306E"), QColor("#FF8A3D"), 0.4))
        p.fillRect(QRectF(L, T + h * 0.78, w, h * 0.22), QColor("#1A0828"))
    elif base == "peaks":
        for k, (col, hh) in enumerate((("#2A3A5C", 0.35), ("#1B2740", 0.55), ("#101828", 0.75))):
            path = QPainterPath(QPointF(L, rect.bottom()))
            for i in range(9):
                x = L + i * w / 8
                y = T + h * (hh + (0.18 if (i + k) % 2 else -0.05) * (0.6 + _rand(i, k) * 0.6))
                path.lineTo(x, y)
            path.lineTo(rect.right(), rect.bottom())
            p.setBrush(QColor(col))
            p.drawPath(path)
        p.setBrush(alpha("#FFFFFF", 0.85))
        p.drawEllipse(QPointF(L + w * 0.18, T + h * 0.22), h * 0.08, h * 0.08)
    elif base == "galaxy":
        neb = QLinearGradient(rect.topLeft(), rect.bottomRight())
        neb.setColorAt(0.2, alpha("#9B5CFF", 0.0))
        neb.setColorAt(0.5, alpha("#9B5CFF", 0.35))
        neb.setColorAt(0.65, alpha("#FF5CB8", 0.22))
        neb.setColorAt(0.9, alpha("#2EC5FF", 0.0))
        p.fillRect(rect, neb)
        for i in range(60):
            tw = 0.35 + 0.65 * abs(math.sin(now * (0.8 + _rand(i, 5) * 2) + i))
            p.setBrush(alpha("#FFFFFF", tw * (0.4 + 0.6 * _rand(i, 2))))
            r = 0.6 + _rand(i, 3) * 1.4
            p.drawEllipse(QPointF(L + _rand(i) * w, T + _rand(i, 1) * h), r, r)
        sx = L + ((now * 0.25) % 1.6 - 0.3) * w
        p.setPen(QPen(alpha("#FFFFFF", 0.7), 1.2))
        p.drawLine(QPointF(sx, T + h * 0.2), QPointF(sx - w * 0.08, T + h * 0.32))
        p.setPen(Qt.PenStyle.NoPen)
    elif base == "lava":
        for i in range(9):
            cx = L + (_rand(i) + 0.05 * math.sin(now * 0.6 + i)) * w
            cy = T + h * (0.5 + 0.45 * math.sin(now * (0.3 + _rand(i, 1) * 0.4) + i * 1.3))
            r = h * (0.22 + _rand(i, 2) * 0.25)
            blob = QLinearGradient(QPointF(cx, cy - r), QPointF(cx, cy + r))
            blob.setColorAt(0, alpha("#FFC94D", 0.85))
            blob.setColorAt(1, alpha("#FF3D1F", 0.6))
            p.setBrush(blob)
            p.drawEllipse(QPointF(cx, cy), r, r)
    elif base == "matrix":
        f = QFont("Consolas")
        f.setPixelSize(max(6, int(h * 0.13)))
        p.setFont(f)
        cw = f.pixelSize() * 0.9
        cols = int(w / cw) + 1
        for c in range(cols):
            speed = 0.6 + _rand(c) * 1.2
            head = ((now * speed + _rand(c, 1) * 3) % 1.6) * h
            for k in range(8):
                y = head - k * f.pixelSize()
                if T - f.pixelSize() < T + y < rect.bottom() + f.pixelSize():
                    p.setPen(alpha("#C8FFD8" if k == 0 else "#3DFF7A", max(0.0, 1 - k / 8)))
                    ch = chr(0x30A0 + int(_rand(c * 31 + k, int(now * 3) % 7) * 90))
                    p.drawText(QPointF(L + c * cw, T + y), ch)
        p.setPen(Qt.PenStyle.NoPen)
    elif base == "prism":
        sweep = QLinearGradient(QPointF(L - w + (now * 0.3 % 1) * w * 2, T), QPointF(L + (now * 0.3 % 1) * w * 2, rect.bottom()))
        for k, col in enumerate(("#FF5CC8", "#FFC94D", "#3DFF7A", "#2EC5FF", "#9B5CFF", "#FF5CC8")):
            sweep.setColorAt(k / 5, alpha(col, 0.55))
        p.fillRect(rect, sweep)
        p.setBrush(alpha("#FFFFFF", 0.18))
        tri = QPainterPath(QPointF(L + w * 0.5, T + h * 0.15))
        tri.lineTo(L + w * 0.62, T + h * 0.85)
        tri.lineTo(L + w * 0.38, T + h * 0.85)
        tri.closeSubpath()
        p.drawPath(tri)
    elif base == "snow":                                       # snowy hills and falling snow
        for k, (col, hh) in enumerate((("#9CC7E8", 0.62), ("#DDEFFF", 0.74), ("#FFFFFF", 0.86))):
            path = QPainterPath(QPointF(L, rect.bottom()))
            for x in range(0, int(w) + 8, 8):
                path.lineTo(L + x, T + h * hh + math.sin(x / w * 5 + k * 1.7) * h * 0.06)
            path.lineTo(rect.right(), rect.bottom())
            p.setBrush(QColor(col))
            p.drawPath(path)
        for i in range(46):
            fall = (_rand(i, 1) + now * (0.06 + _rand(i, 2) * 0.08)) % 1.0
            x = L + (_rand(i) + 0.04 * math.sin(now * 1.3 + i)) * w
            r = 0.8 + _rand(i, 3) * 1.6
            p.setBrush(alpha("#FFFFFF", 0.55 + 0.45 * _rand(i, 4)))
            p.drawEllipse(QPointF(x, T + fall * h), r, r)
    elif base == "ember":                                      # sparks rising from a glowing floor
        floor = QLinearGradient(QPointF(0, T + h * 0.5), QPointF(0, rect.bottom()))
        floor.setColorAt(0, alpha("#FF3D1F", 0.0))
        floor.setColorAt(1, alpha("#FF7A2E", 0.65))
        p.fillRect(rect, floor)
        for i in range(36):
            rise = (_rand(i, 1) + now * (0.12 + _rand(i, 2) * 0.2)) % 1.0
            x = L + (_rand(i) + 0.05 * math.sin(now * 2 + i * 1.3)) * w
            r = 0.8 + _rand(i, 3) * 1.8
            p.setBrush(alpha("#FFC94D" if i % 3 else "#FF5C2E", (1 - rise) * 0.95))
            p.drawEllipse(QPointF(x, rect.bottom() - rise * h), r, r)
    elif base == "nebula":                                     # slowly turning clouds of colour, twinkling stars
        for k, col in enumerate(("#4FE3FF", "#B36BFF", "#FF5CC8")):
            a = now * 0.25 + k * 2.1
            cx, cy = L + w * (0.5 + 0.25 * math.cos(a)), T + h * (0.5 + 0.3 * math.sin(a * 1.3))
            g2 = QRadialGradient(QPointF(cx, cy), h * 0.9)
            g2.setColorAt(0, alpha(col, 0.45))
            g2.setColorAt(1, alpha(col, 0.0))
            p.fillRect(rect, g2)
        for i in range(50):
            tw = 0.3 + 0.7 * abs(math.sin(now * (1 + _rand(i, 5) * 2) + i))
            p.setBrush(alpha("#FFFFFF", tw))
            p.drawEllipse(QPointF(L + _rand(i) * w, T + _rand(i, 1) * h), 0.7 + _rand(i, 2), 0.7 + _rand(i, 2))
    elif base == "jungle":                                     # layers of swaying leaves, light through them
        for i in range(10):
            p.setBrush(alpha("#FFF6B0", 0.05 + 0.04 * math.sin(now + i)))
            x = L + _rand(i, 7) * w
            beam = QPainterPath(QPointF(x, T))
            beam.lineTo(x + w * 0.06, T)
            beam.lineTo(x + w * 0.16, rect.bottom())
            beam.lineTo(x + w * 0.1, rect.bottom())
            p.drawPath(beam)
        for k, col in enumerate(("#0F5B2A", "#1B8A3E", "#2ECC71")):
            for i in range(9):
                cx = L + (i + 0.5) / 9 * w + math.sin(now * 0.9 + i + k) * w * 0.012
                cy = (T + h * (0.15 + 0.35 * k)) if i % 2 else (rect.bottom() - h * (0.1 + 0.2 * k))
                p.save()
                p.translate(cx, cy)
                p.rotate(-35 + _rand(i, k) * 70 + math.sin(now * 1.2 + i) * 6)
                p.setBrush(QColor(col))
                p.drawEllipse(QPointF(0, 0), h * 0.09, h * 0.24)
                p.restore()
    elif base == "sakura":                                     # a branch and falling pink petals
        p.setPen(QPen(QColor("#4A2230"), max(1.5, h * 0.04)))
        path = QPainterPath(QPointF(L, T + h * 0.25))
        path.cubicTo(QPointF(L + w * 0.3, T + h * 0.05), QPointF(L + w * 0.5, T + h * 0.4), QPointF(L + w * 0.85, T + h * 0.15))
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawPath(path)
        p.setPen(Qt.PenStyle.NoPen)
        for i in range(12):
            t2 = (i + 0.5) / 12
            pt = path.pointAtPercent(t2)
            p.setBrush(QColor("#FFC1DE" if i % 2 else "#FF8FC2"))
            p.drawEllipse(pt, h * 0.06, h * 0.06)
        for i in range(30):
            fall = (_rand(i, 1) + now * (0.05 + _rand(i, 2) * 0.06)) % 1.0
            x = L + (_rand(i) + 0.08 * math.sin(now * 1.1 + i)) * w
            p.save()
            p.translate(x, T + fall * h)
            p.rotate(now * 90 + i * 40)
            p.setBrush(alpha("#FFC1DE", 0.85))
            p.drawEllipse(QPointF(0, 0), 2.4, 1.3)
            p.restore()
    elif base == "carbon":                                     # carbon fibre weave
        cell = max(6.0, h * 0.09)
        for gy in range(int(h / cell) + 2):
            for gx in range(int(w / cell) + 2):
                r_ = QRectF(L + gx * cell, T + gy * cell, cell, cell)
                g2 = QLinearGradient(r_.topLeft(), r_.bottomRight() if (gx + gy) % 2 else r_.bottomLeft())
                g2.setColorAt(0, alpha("#FFFFFF", 0.07))
                g2.setColorAt(1, alpha("#000000", 0.25))
                p.fillRect(r_.adjusted(0.5, 0.5, -0.5, -0.5), g2)
    elif base == "dunes":                                      # warm dunes under a low sun
        p.setBrush(alpha("#FFE2A8", 0.85))
        p.drawEllipse(QPointF(L + w * 0.78, T + h * 0.32), h * 0.16, h * 0.16)
        for k, (y0, col) in enumerate(((0.55, "#C98A4B"), (0.68, "#A86A35"), (0.82, "#7E4C24"))):
            path = QPainterPath(QPointF(L, rect.bottom()))
            for x in range(0, int(w) + 8, 8):
                path.lineTo(L + x, T + h * y0 + math.sin(x / w * 5.0 + k * 1.9) * h * 0.06)
            path.lineTo(rect.right(), rect.bottom())
            p.setBrush(QColor(col))
            p.drawPath(path)
    elif base == "honeycomb":                                  # hexagons that light up one after another
        rr = max(7.0, h * 0.13)
        dx, dy = rr * 1.73, rr * 1.5
        for gy in range(int(h / dy) + 2):
            for gx in range(int(w / dx) + 2):
                cx = L + gx * dx + (dx / 2 if gy % 2 else 0)
                cy = T + gy * dy
                glow = max(0.0, math.sin(now * 1.4 - gx * 0.45 + gy * 0.9)) ** 3
                hexp = QPainterPath()
                for n in range(7):
                    a = math.radians(60 * n + 30)
                    pt = QPointF(cx + rr * 0.92 * math.cos(a), cy + rr * 0.92 * math.sin(a))
                    hexp.lineTo(pt) if n else hexp.moveTo(pt)
                p.setPen(QPen(alpha(c2, 0.35 + 0.5 * glow), 1.1))
                p.setBrush(alpha(c2, 0.05 + 0.3 * glow))
                p.drawPath(hexp)
        p.setPen(Qt.PenStyle.NoPen)
    elif base == "comet":                                      # comets crossing a starry sky
        for i in range(30):
            p.setBrush(alpha("#FFFFFF", 0.25 + 0.5 * ((i * 37) % 10) / 10))
            p.drawEllipse(QPointF(L + (i * 97 % 1000) / 1000 * w, T + (i * 61 % 1000) / 1000 * h), 0.9, 0.9)
        for k in range(3):
            t = (now * 0.22 + k / 3) % 1.0
            head = QPointF(L - w * 0.2 + t * w * 1.4, T + h * (0.15 + 0.25 * k) + t * h * 0.35)
            tail = QPointF(head.x() - w * 0.22, head.y() - h * 0.055 * 1)
            g2 = QLinearGradient(tail, head)
            g2.setColorAt(0, alpha(c2, 0.0))
            g2.setColorAt(1, alpha("#FFFFFF", 0.9))
            p.setPen(QPen(g2, 2.2, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
            p.drawLine(tail, head)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor("#FFFFFF"))
            p.drawEllipse(head, 2.2, 2.2)
    elif base == "deepsea":                                    # light rays from above, bubbles rising
        for k in range(5):
            x0 = L + w * (0.1 + 0.2 * k) + math.sin(now * 0.4 + k) * w * 0.03
            ray = QPainterPath(QPointF(x0 - w * 0.03, T))
            ray.lineTo(x0 + w * 0.03, T)
            ray.lineTo(x0 + w * 0.12, rect.bottom())
            ray.lineTo(x0 - w * 0.02, rect.bottom())
            g2 = QLinearGradient(QPointF(0, T), QPointF(0, rect.bottom()))
            g2.setColorAt(0, alpha(c2, 0.28))
            g2.setColorAt(1, alpha(c2, 0.0))
            p.setBrush(g2)
            p.drawPath(ray)
        for i in range(16):
            t = (now * (0.12 + (i % 4) * 0.03) + i * 0.137) % 1.0
            x = L + (i * 131 % 1000) / 1000 * w + math.sin(now * 2 + i) * 3
            p.setPen(QPen(alpha("#BFF4FF", 0.7 * (1 - t)), 1))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawEllipse(QPointF(x, rect.bottom() - t * h), 1.5 + (i % 3), 1.5 + (i % 3))
        p.setPen(Qt.PenStyle.NoPen)
    elif base == "city":                                       # a skyline at night, windows switching on and off
        p.setBrush(alpha("#FFE9A8", 0.9))
        p.drawEllipse(QPointF(L + w * 0.85, T + h * 0.22), h * 0.09, h * 0.09)
        x, i = L, 0
        while x < rect.right():
            bw = w * (0.05 + ((i * 53) % 7) / 100)
            bh = h * (0.35 + ((i * 29) % 9) / 16)
            top_ = rect.bottom() - bh
            p.setBrush(QColor("#0A0D1A") if i % 2 else QColor("#121633"))
            p.drawRect(QRectF(x, top_, bw, bh))
            for wy in range(int(bh / 7)):
                for wx in range(max(1, int(bw / 6))):
                    lit = math.sin(i * 7.1 + wy * 3.3 + wx * 1.7 + math.floor(now * 0.5 + (i + wx) * 0.13)) > 0.35
                    if lit:
                        p.setBrush(alpha("#FFD36B", 0.85))
                        p.drawRect(QRectF(x + 2 + wx * 6, top_ + 3 + wy * 7, 2.4, 3))
            x += bw + 1
            i += 1
    elif base == "neon":                                       # glowing tubes that pulse
        for k, (col, y0) in enumerate((("#FF2BD6", 0.3), ("#2EF2FF", 0.55), ("#B6FF2E", 0.8))):
            pulse = 0.55 + 0.45 * math.sin(now * 2.2 + k * 2.1)
            path = QPainterPath(QPointF(L - 4, T + h * y0))
            for x in range(0, int(w) + 10, 10):
                path.lineTo(L + x, T + h * y0 + (h * 0.08 if (x // 40) % 2 else -h * 0.08))
            p.setBrush(Qt.BrushStyle.NoBrush)
            for width, a in ((7, 0.12), (3.5, 0.35), (1.6, 1.0)):
                p.setPen(QPen(alpha(col, a * pulse), width, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap,
                              Qt.PenJoinStyle.RoundJoin))
                p.drawPath(path)
        p.setPen(Qt.PenStyle.NoPen)
    elif base == "fireflies":                                  # a dark forest with drifting lights
        for k in range(9):
            x = L + w * (k / 8)
            p.setBrush(QColor("#06140C"))
            tri = QPainterPath(QPointF(x, T + h * (0.25 + 0.1 * (k % 3))))
            tri.lineTo(x - w * 0.07, rect.bottom())
            tri.lineTo(x + w * 0.07, rect.bottom())
            tri.closeSubpath()
            p.drawPath(tri)
        for i in range(22):
            x = L + ((i * 89 % 1000) / 1000 + 0.03 * math.sin(now * 0.5 + i)) * w
            y = T + ((i * 47 % 1000) / 1000 * 0.8 + 0.1 + 0.04 * math.cos(now * 0.7 + i * 2)) * h
            a = max(0.0, math.sin(now * 1.7 + i * 1.3))
            gl = QRadialGradient(QPointF(x, y), 6)
            gl.setColorAt(0, alpha("#E8FF7A", 0.9 * a))
            gl.setColorAt(1, alpha("#E8FF7A", 0.0))
            p.setBrush(gl)
            p.drawEllipse(QPointF(x, y), 6, 6)
    elif base == "storm":                                      # heavy clouds, rain and lightning
        flash = max(0.0, 1 - ((now * 0.45) % 1.0) * 9)        # a bright flash once every ~2 seconds
        for k in range(7):
            p.setBrush(alpha("#2A3550", 0.85))
            p.drawEllipse(QPointF(L + w * (k / 6) + math.sin(now * 0.2 + k) * 6, T + h * 0.12), w * 0.13, h * 0.32)
        p.setPen(QPen(alpha("#9FC3FF", 0.35), 1))
        for i in range(40):
            t = (now * 1.6 + i * 0.173) % 1.0
            x = L + (i * 113 % 1000) / 1000 * w
            p.drawLine(QPointF(x - t * 6, T + h * 0.3 + t * h * 0.7), QPointF(x - t * 6 - 3, T + h * 0.3 + t * h * 0.7 + 7))
        if flash > 0:
            bolt = QPainterPath(QPointF(L + w * 0.62, T + h * 0.25))
            for dxf, dyf in ((-0.04, 0.2), (0.03, 0.18), (-0.05, 0.22), (0.02, 0.2)):
                cur = bolt.currentPosition()
                bolt.lineTo(cur.x() + w * dxf, cur.y() + h * dyf)
            p.setBrush(Qt.BrushStyle.NoBrush)
            for width, a in ((6, 0.25), (2, 1.0)):
                p.setPen(QPen(alpha("#E6F0FF", a * flash), width, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
                p.drawPath(bolt)
            p.fillRect(rect, alpha("#CFE0FF", 0.18 * flash))
        p.setPen(Qt.PenStyle.NoPen)
    elif base == "vortex":                                     # a slowly turning spiral of light
        cen = QPointF(L + w * 0.5, T + h * 0.5)
        for arm in range(4):
            path = QPainterPath()
            for n in range(60):
                t = n / 59
                ang = arm * math.pi / 2 + t * 5.5 + now * 0.6
                rr = t * w * 0.55
                pt = QPointF(cen.x() + rr * math.cos(ang), cen.y() + rr * 0.45 * math.sin(ang))
                path.lineTo(pt) if n else path.moveTo(pt)
            p.setBrush(Qt.BrushStyle.NoBrush)
            for width, a in ((8, 0.10), (3, 0.35), (1.2, 0.9)):
                p.setPen(QPen(alpha(c2 if arm % 2 else QColor("#FF5CC8"), a), width, Qt.PenStyle.SolidLine,
                              Qt.PenCapStyle.RoundCap))
                p.drawPath(path)
        core = QRadialGradient(cen, h * 0.4)
        core.setColorAt(0, alpha("#FFFFFF", 0.85))
        core.setColorAt(1, alpha(c2, 0.0))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(core)
        p.drawEllipse(cen, h * 0.4, h * 0.4)
    elif base in _BANNERS_66:
        _paint_banner_66(p, base, rect, c1, c2, now)
    elif base in _BANNERS_65:
        _paint_banner_65(p, base, rect, c1, c2, now)
    elif base in _BANNERS_63:
        _paint_banner_63(p, base, rect, c1, c2, now)
    elif base in ("mosaic", "reef", "thunder", "blackhole", "crystal"):
        _paint_banner_45(p, base, rect, c1, c2, now)
    else:
        _paint_banner_32(p, base, rect, c1, c2, now)
    if gold > 0:
        paint_gold(p, rect, gold, now)
    shade = QLinearGradient(rect.topLeft(), rect.bottomLeft())       # a soft shade at the bottom, for text on top
    shade.setColorAt(0.55, alpha("#000000", 0.0))
    shade.setColorAt(1.0, alpha("#000000", 0.35))
    p.fillRect(rect, shade)
    p.restore()



def _paint_banner_cw(p: QPainter, rect: QRectF, cw: tuple, now: float, radius: float, dim: float, gold: int) -> None:
    img, ip = _cw_layer(p, rect.width(), rect.height())
    paint_banner(ip, QRectF(0, 0, rect.width(), rect.height()), "banner:" + cw[0], now, 0.0, 1.0, 0)
    ip.end()
    img = recolour_image(img, cw[1])
    p.save()
    p.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform)
    clip = QPainterPath()
    clip.addRoundedRect(rect, radius, radius)
    p.setClipPath(clip)
    p.setOpacity(p.opacity() * dim)
    p.drawImage(rect, img)
    if gold > 0:
        paint_gold(p, rect, gold, now)
    p.restore()


def _paint_banner_32(p: QPainter, base: str, rect: QRectF, c1: QColor, c2: QColor, now: float) -> None:
    """3.2 banners. The rarer, the more there is in them: Common are calm, Legendary are full scenes that move."""
    w, h = rect.width(), rect.height()
    L, T = rect.left(), rect.top()
    p.setPen(Qt.PenStyle.NoPen)
    if base == "slate":                                        # Common: two-tone slate with fine lines
        path = QPainterPath(QPointF(L + w * 0.55, T))
        path.lineTo(rect.right(), T)
        path.lineTo(rect.right(), rect.bottom())
        path.lineTo(L + w * 0.35, rect.bottom())
        p.setBrush(alpha(c2, 0.45))
        p.drawPath(path)
        p.setPen(QPen(alpha("#FFFFFF", 0.06), 1))
        for k in range(12):
            y = T + h * k / 12
            p.drawLine(QPointF(L, y), QPointF(rect.right(), y))
    elif base == "pastel":                                     # Common: soft blobs of colour
        for k, (x, y, rr, col) in enumerate(((0.2, 0.3, 0.5, "#FFD6E8"), (0.75, 0.7, 0.6, "#CFE6FF"), (0.5, 0.9, 0.4, "#E6D6FF"))):
            g = QRadialGradient(QPointF(L + w * x, T + h * y), w * rr)
            g.setColorAt(0, alpha(col, 0.8))
            g.setColorAt(1, alpha(col, 0.0))
            p.setBrush(g)
            p.drawEllipse(QPointF(L + w * x, T + h * y), w * rr, w * rr)
    elif base == "tides":                                      # Rare: tides rolling in with white foam
        for k in range(5):
            path = QPainterPath(QPointF(L, rect.bottom()))
            pts = []
            for x in range(0, int(w) + 8, 5):
                y = T + h * (0.3 + k * 0.14) + math.sin(x / w * 5 + now * (1 + k * 0.25) + k * 1.3) * h * 0.06
                pts.append(QPointF(L + x, y))
                path.lineTo(L + x, y)
            path.lineTo(rect.right(), rect.bottom())
            p.setBrush(alpha(mix(c2, QColor("#FFFFFF"), 0.1 * k), 0.15 + k * 0.08))
            p.drawPath(path)
            p.setPen(QPen(alpha("#FFFFFF", 0.35 - k * 0.04), 1.2))
            crest = QPainterPath(pts[0])
            for pt in pts[1:]:
                crest.lineTo(pt)
            p.drawPath(crest)
            p.setPen(Qt.PenStyle.NoPen)
    elif base == "canyon":                                     # Rare: layered red rock under a low sun
        sun = QRadialGradient(QPointF(L + w * 0.75, T + h * 0.3), h * 0.5)
        sun.setColorAt(0, alpha("#FFE2A8", 0.85))
        sun.setColorAt(1, alpha("#FFE2A8", 0.0))
        p.setBrush(sun)
        p.drawEllipse(QPointF(L + w * 0.75, T + h * 0.3), h * 0.5, h * 0.5)
        for k in range(4):
            path = QPainterPath(QPointF(L, rect.bottom()))
            for x in range(0, int(w) + 10, 10):
                step = (x // 40) % 2
                y = T + h * (0.35 + k * 0.15) + (h * 0.05 if step else 0) + _rand(x, k) * h * 0.02
                path.lineTo(L + x, y)
            path.lineTo(rect.right(), rect.bottom())
            p.setBrush(mix(c2, QColor("#2A0E06"), 0.2 + k * 0.22))
            p.drawPath(path)
    elif base == "koi":                                        # Epic: a pond with ripples and three koi swimming
        for k in range(3):
            t = (now * 0.25 + k / 3) % 1.0
            cen = QPointF(L + w * (0.25 + 0.25 * k), T + h * (0.35 + 0.2 * (k % 2)))
            p.setPen(QPen(alpha("#BFF8F0", 0.35 * (1 - t)), 1.2))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawEllipse(cen, w * 0.18 * t, h * 0.18 * t)
        p.setPen(Qt.PenStyle.NoPen)
        for k, col in enumerate(("#FF7A2E", "#FFFFFF", "#FFC14D")):
            ang = now * (0.35 + 0.08 * k) + k * 2.1
            cx, cy = L + w * 0.5 + math.cos(ang) * w * 0.32, T + h * 0.5 + math.sin(ang) * h * 0.28
            head = math.degrees(ang) + 90
            p.save()
            p.translate(cx, cy)
            p.rotate(head)
            fl = h * 0.12
            body = QPainterPath(QPointF(0, -fl))
            body.cubicTo(fl * 0.5, -fl * 0.5, fl * 0.4, fl * 0.6, 0, fl * 1.1)
            body.cubicTo(-fl * 0.4, fl * 0.6, -fl * 0.5, -fl * 0.5, 0, -fl)
            p.setBrush(QColor(col))
            p.drawPath(body)
            tail = QPainterPath(QPointF(0, fl * 1.0))
            sway = math.sin(now * 6 + k) * fl * 0.3
            tail.lineTo(-fl * 0.45 + sway, fl * 1.6)
            tail.lineTo(fl * 0.45 + sway, fl * 1.6)
            tail.closeSubpath()
            p.drawPath(tail)
            if col == "#FFFFFF":
                p.setBrush(QColor("#E8384F"))
                p.drawEllipse(QPointF(0, -fl * 0.3), fl * 0.25, fl * 0.3)
            p.restore()
        for k in range(4):                                     # lily pads
            pad = QPointF(L + w * _rand(k, 41), T + h * _rand(k, 42))
            p.setBrush(alpha("#2E8B3E", 0.75))
            p.drawPie(QRectF(pad.x() - h * 0.1, pad.y() - h * 0.08, h * 0.2, h * 0.16), 30 * 16, 300 * 16)
    elif base == "synthwave":                                  # Epic: striped sun, palms and a moving grid
        horizon = T + h * 0.55
        sun = QPointF(L + w * 0.5, horizon)
        sg = QLinearGradient(0, horizon - h * 0.42, 0, horizon)
        sg.setColorAt(0, QColor("#FFD36B"))
        sg.setColorAt(1, QColor("#FF2BD6"))
        p.setBrush(sg)
        p.drawEllipse(sun, h * 0.42, h * 0.42)
        p.save()
        disc = QPainterPath()
        disc.addEllipse(sun, h * 0.42, h * 0.42)
        p.setClipPath(disc, Qt.ClipOperation.IntersectClip)
        for k in range(5):
            p.fillRect(QRectF(sun.x() - h * 0.45, horizon - h * (0.05 + 0.07 * k), h * 0.9, h * 0.012 * (k + 1)), c1)
        p.restore()
        p.fillRect(QRectF(L, horizon, w, h), mix(c1, QColor("#000000"), 0.3))
        p.setPen(QPen(alpha("#2EF2FF", 0.7), 1))
        off = (now * 0.6) % 1.0
        for k in range(-12, 13):
            p.drawLine(QPointF(L + w / 2 + k * w * 0.025, horizon), QPointF(L + w / 2 + k * w * 0.14, rect.bottom()))
        for k in range(7):
            f = ((k + off) / 7) ** 2
            p.drawLine(QPointF(L, horizon + f * (rect.bottom() - horizon)), QPointF(rect.right(), horizon + f * (rect.bottom() - horizon)))
        p.setPen(Qt.PenStyle.NoPen)
        for side in (0.12, 0.88):                              # two palm trees
            base_x = L + w * side
            p.setPen(QPen(QColor("#0A0418"), max(1.5, h * 0.03), Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
            trunk = QPainterPath(QPointF(base_x, horizon + h * 0.05))
            trunk.quadTo(base_x + (h * 0.05 if side < 0.5 else -h * 0.05), T + h * 0.35, base_x, T + h * 0.2)
            p.drawPath(trunk)
            for k in range(5):
                ang = math.radians(-170 + k * 40) + math.sin(now * 1.5 + k) * 0.05
                leaf = QPainterPath(QPointF(base_x, T + h * 0.2))
                leaf.quadTo(base_x + math.cos(ang) * h * 0.18, T + h * 0.2 + math.sin(ang) * h * 0.1 - h * 0.05,
                            base_x + math.cos(ang) * h * 0.3, T + h * 0.2 + math.sin(ang) * h * 0.18 + h * 0.04)
                p.drawPath(leaf)
            p.setPen(Qt.PenStyle.NoPen)
    elif base == "supernova":                                  # Legendary: a star exploding, rings and debris
        cen = QPointF(L + w * 0.5, T + h * 0.5)
        for k in range(70):                                    # background stars
            p.setBrush(alpha("#FFFFFF", 0.2 + 0.6 * _rand(k, 5) * (0.6 + 0.4 * math.sin(now * 2 + k))))
            p.drawEllipse(QPointF(L + w * _rand(k, 1), T + h * _rand(k, 2)), 0.9, 0.9)
        cycle = (now * 0.35) % 1.0
        for k in range(3):                                     # shock rings racing out
            t = (cycle + k / 3) % 1.0
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.setPen(QPen(alpha(mix(c2, QColor("#FFFFFF"), 0.3), 0.8 * (1 - t)), 1.5 + 3 * (1 - t)))
            p.drawEllipse(cen, w * 0.6 * t, h * 0.6 * t * 0.9)
        p.setPen(Qt.PenStyle.NoPen)
        for k in range(48):                                    # debris flying out
            ang = _rand(k, 7) * math.tau
            t = (now * (0.2 + 0.3 * _rand(k, 8)) + _rand(k, 9)) % 1.0
            pos = QPointF(cen.x() + math.cos(ang) * w * 0.55 * t, cen.y() + math.sin(ang) * h * 0.55 * t)
            p.setBrush(alpha(QColor("#FFE2A8") if k % 3 else QColor("#FF5C8A"), 1 - t))
            p.drawEllipse(pos, 1.6 * (1 - t) + 0.6, 1.6 * (1 - t) + 0.6)
        core = QRadialGradient(cen, h * 0.5)
        core.setColorAt(0, alpha("#FFFFFF", 1.0))
        core.setColorAt(0.2, alpha(c2, 0.85))
        core.setColorAt(0.6, alpha("#FF2B6B", 0.25))
        core.setColorAt(1, alpha("#FF2B6B", 0.0))
        p.setBrush(core)
        p.drawEllipse(cen, h * 0.5, h * 0.5)
        p.save()                                               # a cross of light
        p.translate(cen)
        p.rotate(now * 8)
        for k in range(4):
            p.rotate(90)
            ray = QPainterPath(QPointF(0, -1.5))
            ray.lineTo(w * 0.4, 0)
            ray.lineTo(0, 1.5)
            p.setBrush(alpha("#FFFFFF", 0.55))
            p.drawPath(ray)
        p.restore()
    elif base == "dragon":                                     # Legendary: a dragon gliding over fire and embers
        glow = QLinearGradient(rect.bottomLeft(), rect.topLeft())
        glow.setColorAt(0, alpha("#FF5A1F", 0.55))
        glow.setColorAt(0.5, alpha("#FF5A1F", 0.0))
        p.fillRect(rect, glow)
        for k in range(40):                                    # embers
            t = (now * (0.15 + 0.2 * _rand(k, 3)) + _rand(k, 4)) % 1.0
            x = L + w * _rand(k, 5) + math.sin(now + k) * 4
            y = rect.bottom() - t * h
            p.setBrush(alpha("#FFC14D" if k % 2 else "#FF5A1F", 1 - t))
            p.drawEllipse(QPointF(x, y), 1.4, 1.4)
        sweep = (now * 0.08) % 1.4 - 0.2                       # the dragon crosses the banner
        hx, hy = L + w * sweep, T + h * 0.42 + math.sin(now * 1.3) * h * 0.06
        body = QPainterPath(QPointF(hx, hy))                   # a long serpent body behind its head
        for k in range(1, 14):
            body.lineTo(hx - k * h * 0.11, hy + math.sin(now * 3 - k * 0.6) * h * 0.08)
        p.setBrush(Qt.BrushStyle.NoBrush)
        for width, col in ((h * 0.13, QColor("#3A0A10")), (h * 0.08, c2), (h * 0.02, QColor("#FFC14D"))):
            p.setPen(QPen(col, width, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin))
            p.drawPath(body)
        p.setPen(Qt.PenStyle.NoPen)
        flap = math.sin(now * 5) * 0.5 + 0.5                   # wings
        for side in (-1, 1):
            wing = QPainterPath(QPointF(hx - h * 0.3, hy))
            wing.lineTo(hx - h * 0.15, hy + side * h * (0.25 + 0.2 * flap))
            wing.lineTo(hx - h * 0.45, hy + side * h * (0.15 + 0.15 * flap))
            wing.lineTo(hx - h * 0.62, hy + side * h * (0.3 + 0.15 * flap))
            wing.closeSubpath()
            p.setBrush(alpha("#5A0E18", 0.95))
            p.drawPath(wing)
        p.setBrush(c2)
        p.drawEllipse(QPointF(hx, hy), h * 0.07, h * 0.05)
        p.setBrush(QColor("#FFE26B"))
        p.drawEllipse(QPointF(hx + h * 0.02, hy - h * 0.012), h * 0.012, h * 0.012)
        fire = QRadialGradient(QPointF(hx + h * 0.18, hy), h * 0.16)  # a breath of fire
        fire.setColorAt(0, alpha("#FFF1B8", 0.9))
        fire.setColorAt(0.5, alpha("#FF8A3D", 0.6))
        fire.setColorAt(1, alpha("#FF3D1F", 0.0))
        p.setBrush(fire)
        p.drawEllipse(QPointF(hx + h * 0.18, hy), h * 0.18 * (0.8 + 0.2 * math.sin(now * 9)), h * 0.08)
    elif base == "wreath":                                     # limited Rare: a Christmas wreath with berries and a bow
        cen = QPointF(L + w * 0.5, T + h * 0.5)
        for k in range(36):
            ang = k / 36 * math.tau
            p.setBrush(QColor("#1F7A4A") if k % 2 else QColor("#2E9E5F"))
            p.save()
            p.translate(cen.x() + math.cos(ang) * h * 0.32, cen.y() + math.sin(ang) * h * 0.32)
            p.rotate(math.degrees(ang) + 45)
            p.drawEllipse(QPointF(0, 0), h * 0.07, h * 0.035)
            p.restore()
        for k in range(10):
            ang = k / 10 * math.tau + 0.3
            p.setBrush(QColor("#FF3B4E"))
            p.drawEllipse(QPointF(cen.x() + math.cos(ang) * h * 0.3, cen.y() + math.sin(ang) * h * 0.3), h * 0.025, h * 0.025)
        p.setBrush(QColor("#E8C26A"))
        p.drawEllipse(QPointF(cen.x() - h * 0.06, cen.y() + h * 0.3), h * 0.06, h * 0.04)
        p.drawEllipse(QPointF(cen.x() + h * 0.06, cen.y() + h * 0.3), h * 0.06, h * 0.04)
        for k in range(30):                                    # gentle snow
            t = (now * 0.08 + _rand(k, 1)) % 1.0
            p.setBrush(alpha("#FFFFFF", 0.7))
            p.drawEllipse(QPointF(L + w * _rand(k, 2) + math.sin(now + k) * 3, T + t * h), 1.2, 1.2)
    elif base == "hearth":                                     # limited Epic: a fireplace, stockings and a warm glow
        p.fillRect(QRectF(L, T, w, h), alpha("#2A120A", 0.6))
        for row in range(5):                                   # bricks
            for col in range(12):
                bx = L + (col + (0.5 if row % 2 else 0)) * w / 11
                p.setBrush(alpha("#5A2414", 0.6))
                p.drawRect(QRectF(bx, T + row * h * 0.12, w / 11 - 2, h * 0.1))
        fp = QRectF(L + w * 0.3, T + h * 0.35, w * 0.4, h * 0.65)
        p.setBrush(QColor("#0D0503"))
        p.drawRoundedRect(fp, 4, 4)
        for k in range(5):                                     # flames
            fx = fp.left() + fp.width() * (0.2 + 0.15 * k)
            fh = fp.height() * (0.45 + 0.2 * math.sin(now * 6 + k * 1.7))
            flame = QPainterPath(QPointF(fx - fp.width() * 0.06, fp.bottom()))
            flame.quadTo(fx - fp.width() * 0.08, fp.bottom() - fh * 0.5, fx, fp.bottom() - fh)
            flame.quadTo(fx + fp.width() * 0.08, fp.bottom() - fh * 0.5, fx + fp.width() * 0.06, fp.bottom())
            g = QLinearGradient(0, fp.bottom(), 0, fp.bottom() - fh)
            g.setColorAt(0, QColor("#FF5A1F"))
            g.setColorAt(1, QColor("#FFE26B"))
            p.setBrush(g)
            p.drawPath(flame)
        warm = QRadialGradient(fp.center(), w * 0.45)
        warm.setColorAt(0, alpha("#FF8A3D", 0.35 + 0.1 * math.sin(now * 4)))
        warm.setColorAt(1, alpha("#FF8A3D", 0.0))
        p.setBrush(warm)
        p.drawRect(rect)
        p.setBrush(QColor("#3A1A10"))                          # the mantel and three stockings
        p.drawRect(QRectF(L + w * 0.22, T + h * 0.28, w * 0.56, h * 0.07))
        for k, col in enumerate(("#E8384F", "#FFFFFF", "#1F7A4A")):
            sx = L + w * (0.3 + 0.2 * k)
            sway = math.sin(now * 2 + k) * 1.5
            p.setBrush(QColor(col))
            p.drawRoundedRect(QRectF(sx + sway, T + h * 0.35, w * 0.04, h * 0.22), 2, 2)
            p.drawEllipse(QPointF(sx + sway + w * 0.03, T + h * 0.56), w * 0.035, h * 0.05)
    elif base == "northstar":                                  # limited Legendary: the North Star over snowy pines and an aurora
        for k in range(3):                                     # aurora curtains
            path = QPainterPath(QPointF(L, T + h * 0.2))
            for x in range(0, int(w) + 8, 6):
                path.lineTo(L + x, T + h * (0.18 + 0.06 * k) + math.sin(x / w * 5 + now * 0.7 + k) * h * 0.08)
            path.lineTo(rect.right(), T)
            path.lineTo(L, T)
            g = QLinearGradient(0, T, 0, T + h * 0.4)
            g.setColorAt(0, alpha(["#3DFFB0", "#4FE3FF", "#B36BFF"][k], 0.0))
            g.setColorAt(1, alpha(["#3DFFB0", "#4FE3FF", "#B36BFF"][k], 0.25))
            p.setBrush(g)
            p.drawPath(path)
        for k in range(60):
            p.setBrush(alpha("#FFFFFF", 0.3 + 0.5 * _rand(k, 3) * (0.5 + 0.5 * math.sin(now * 2 + k))))
            p.drawEllipse(QPointF(L + w * _rand(k, 1), T + h * 0.6 * _rand(k, 2)), 0.9, 0.9)
        star = QPointF(L + w * 0.62, T + h * 0.28)
        glow = QRadialGradient(star, h * 0.45)
        glow.setColorAt(0, alpha("#FFF6C8", 0.75))
        glow.setColorAt(1, alpha("#FFF6C8", 0.0))
        p.setBrush(glow)
        p.drawEllipse(star, h * 0.45, h * 0.45)
        p.save()
        p.translate(star)
        p.rotate(math.sin(now * 0.8) * 4)
        shape = QPainterPath()
        for k in range(8):
            ang = math.radians(-90 + 45 * k)
            rr = h * (0.2 if k % 2 == 0 else 0.05) * (1.0 if k % 4 == 0 else 0.7 if k % 2 == 0 else 1.0)
            pt = QPointF(math.cos(ang) * rr, math.sin(ang) * rr)
            shape.lineTo(pt) if k else shape.moveTo(pt)
        shape.closeSubpath()
        p.setBrush(QColor("#FFF6C8"))
        p.drawPath(shape)
        p.restore()
        p.setBrush(alpha("#E8F4FF", 0.9))                       # snowy ground
        snow = QPainterPath(QPointF(L, rect.bottom()))
        for x in range(0, int(w) + 10, 10):
            snow.lineTo(L + x, T + h * 0.85 + math.sin(x / w * 4) * h * 0.04)
        snow.lineTo(rect.right(), rect.bottom())
        p.drawPath(snow)
        for k in range(9):                                     # pines
            px = L + w * (0.04 + k * 0.12) + _rand(k, 6) * 8
            ph = h * (0.3 + 0.2 * _rand(k, 7))
            tree = QPainterPath(QPointF(px, T + h * 0.9 - ph))
            tree.lineTo(px + ph * 0.25, T + h * 0.9)
            tree.lineTo(px - ph * 0.25, T + h * 0.9)
            tree.closeSubpath()
            p.setBrush(QColor("#0B2A1A"))
            p.drawPath(tree)
            p.setBrush(alpha("#FFFFFF", 0.8))
            cap = QPainterPath(QPointF(px, T + h * 0.9 - ph))
            cap.lineTo(px + ph * 0.07, T + h * 0.9 - ph * 0.72)
            cap.lineTo(px - ph * 0.07, T + h * 0.9 - ph * 0.72)
            cap.closeSubpath()
            p.drawPath(cap)


GOLD_NAMES = {1: "Gold I", 2: "Gold II", 3: "Gold III"}


def paint_gold(p: QPainter, rect: QRectF, level: int, now: float = 0.0) -> None:
    """A banner worn for many hours turns gold: I a gold tint and edge, II a richer gold with a moving shine,
    III solid gold with a bright sweep and sparkles."""
    level = max(0, min(3, int(level)))
    if not level:
        return
    p.save()
    p.setPen(Qt.PenStyle.NoPen)
    tint = QLinearGradient(rect.topLeft(), rect.bottomRight())
    k = (0.45, 0.7, 0.95)[level - 1]
    tint.setColorAt(0, alpha("#FFD978", k))
    tint.setColorAt(0.5, alpha("#E0A93A", k))
    tint.setColorAt(1, alpha("#8A5A14", k))
    p.setCompositionMode(QPainter.CompositionMode.CompositionMode_Overlay)
    p.fillRect(rect, tint)
    if level >= 2:                                         # the colours of the banner turn to gold
        gray = QLinearGradient(rect.topLeft(), rect.bottomLeft())
        gray.setColorAt(0, alpha("#FFE9A8", 0.5 if level == 2 else 0.95))
        gray.setColorAt(1, alpha("#C98F2A", 0.5 if level == 2 else 0.95))
        p.setCompositionMode(QPainter.CompositionMode.CompositionMode_Multiply)
        p.fillRect(rect, gray)
        p.setCompositionMode(QPainter.CompositionMode.CompositionMode_Screen)
        p.fillRect(rect, alpha("#6B4510", 0.35 if level == 2 else 0.7))
    p.setCompositionMode(QPainter.CompositionMode.CompositionMode_SourceOver)
    if level >= 2:                                         # a band of light sweeping across
        t = (now * (0.25 if level == 2 else 0.4)) % 1.6 - 0.3
        x = rect.left() + t * rect.width()
        sweep = QLinearGradient(QPointF(x - rect.width() * 0.15, 0), QPointF(x + rect.width() * 0.15, 0))
        sweep.setColorAt(0, alpha("#FFFFFF", 0.0))
        sweep.setColorAt(0.5, alpha("#FFF6D8", 0.35 if level == 2 else 0.55))
        sweep.setColorAt(1, alpha("#FFFFFF", 0.0))
        p.fillRect(rect, sweep)
    if level >= 3:                                         # sparkles
        for i in range(10):
            a = max(0.0, math.sin(now * 2.3 + i * 1.9))
            if a < 0.2:
                continue
            c = QPointF(rect.left() + (i * 157 % 1000) / 1000 * rect.width(),
                        rect.top() + (i * 83 % 1000) / 1000 * rect.height() * 0.8 + rect.height() * 0.05)
            s = 2.5 + 2.5 * a
            star = QPainterPath(QPointF(c.x(), c.y() - s))
            for pt in ((c.x() + s * 0.25, c.y() - s * 0.25), (c.x() + s, c.y()), (c.x() + s * 0.25, c.y() + s * 0.25),
                       (c.x(), c.y() + s), (c.x() - s * 0.25, c.y() + s * 0.25), (c.x() - s, c.y()),
                       (c.x() - s * 0.25, c.y() - s * 0.25)):
                star.lineTo(QPointF(*pt))
            star.closeSubpath()
            p.setBrush(alpha("#FFF6D8", 0.9 * a))
            p.drawPath(star)
    edge = QLinearGradient(rect.topLeft(), rect.bottomRight())
    edge.setColorAt(0, QColor("#FFE7A0"))
    edge.setColorAt(0.5, QColor("#E8C26A"))
    edge.setColorAt(1, QColor("#9C6B1E"))
    p.setPen(QPen(edge, (1.2, 2.0, 2.8)[level - 1]))
    p.setBrush(Qt.BrushStyle.NoBrush)
    p.drawRect(rect.adjusted(0.5, 0.5, -0.5, -0.5))      # clipped to the rounded banner
    p.restore()


def gold_steps_text(steps, minutes: int) -> str:
    """'Gold I in 6 h' / 'Gold III' for the progress of one banner."""
    hours = [int(h) for h in (steps or [])][:3]
    level = sum(1 for h in hours if minutes >= h * 60)
    if level >= len(hours) or not hours:
        return tr(GOLD_NAMES.get(level, "")) if level else ""
    left = max(1, math.ceil((hours[level] * 60 - minutes) / 60))
    return tr("{gold} in {h} h", gold=tr(GOLD_NAMES[level + 1]), h=left)

