def _snowflake(p: QPainter, at: QPointF, size: float, turn: float, col: QColor) -> None:
    """A six-armed snowflake with little side branches."""
    p.save()
    p.translate(at)
    p.rotate(turn)
    pen = QPen(col, max(0.8, size * 0.13))
    pen.setCapStyle(Qt.PenCapStyle.RoundCap)
    p.setPen(pen)
    for k in range(6):
        p.rotate(60)
        p.drawLine(QPointF(0, 0), QPointF(0, -size))
        p.drawLine(QPointF(0, -size * 0.55), QPointF(-size * 0.28, -size * 0.78))
        p.drawLine(QPointF(0, -size * 0.55), QPointF(size * 0.28, -size * 0.78))
    p.restore()


def _paint_firstfrost(p: QPainter, c: QPointF, r: float, wd: float, now: float) -> None:
    """4.2, advent door 1 of 2026 (Legendary, limited: it will never be made again). A ring of frosted crystal with
    an aurora sweeping through it, ice shards around it, three snowflakes slowly turning on their orbit, snow falling
    through and piling up at the bottom, glints that twinkle, and a small 2026 tag."""
    breathe = 0.6 + 0.4 * math.sin(now * 1.5)
    p.save()
    outer = r + wd * 6.0
    aura = QRadialGradient(c, outer)                            # an icy halo
    aura.setColorAt(0.0, QColor(0, 0, 0, 0))
    aura.setColorAt(max(0.01, r / outer - 0.05), QColor(0, 0, 0, 0))
    aura.setColorAt(r / outer, alpha("#BFF0FF", 0.50 * breathe))
    aura.setColorAt(min(0.99, r / outer + 0.22), alpha("#6FB8FF", 0.18 * breathe))
    aura.setColorAt(1.0, QColor(0, 0, 0, 0))
    p.setPen(Qt.PenStyle.NoPen)
    p.setBrush(aura)
    p.drawEllipse(c, outer, outer)
    for i in range(12):                                         # ice shards standing out of the ring
        a = i / 12 * math.tau + math.pi / 12
        long_ = wd * (2.3 if i % 2 == 0 else 1.5) * (1 + 0.06 * math.sin(now * 2 + i))
        base = r + wd * 0.2
        tip = QPointF(c.x() + math.cos(a) * (base + long_), c.y() + math.sin(a) * (base + long_))
        side = wd * 0.42
        left = QPointF(c.x() + math.cos(a - 0.09) * base - math.sin(a) * side * 0.2,
                       c.y() + math.sin(a - 0.09) * base + math.cos(a) * side * 0.2)
        right = QPointF(c.x() + math.cos(a + 0.09) * base + math.sin(a) * side * 0.2,
                        c.y() + math.sin(a + 0.09) * base - math.cos(a) * side * 0.2)
        shard = QPainterPath(left)
        shard.lineTo(tip)
        shard.lineTo(right)
        shard.closeSubpath()
        sg = QLinearGradient(QPointF(c.x() + math.cos(a) * base, c.y() + math.sin(a) * base), tip)
        sg.setColorAt(0, alpha("#E9FBFF", 0.95))
        sg.setColorAt(1, alpha("#7FD3FF", 0.55))
        p.setBrush(sg)
        p.drawPath(shard)
    ring = QRectF(c.x() - r, c.y() - r, 2 * r, 2 * r)          # the crystal band, an aurora running through it
    sweep = QConicalGradient(c, -now * 40)
    for k, col in enumerate(("#DFF8FF", "#7FE3FF", "#B9A6FF", "#7FFFD4", "#DFF8FF", "#9CD8FF", "#DFF8FF")):
        sweep.setColorAt(k / 6, QColor(col))
    p.setBrush(Qt.BrushStyle.NoBrush)
    p.setPen(QPen(sweep, wd * 0.95))
    p.drawEllipse(ring)
    p.setPen(QPen(alpha("#FFFFFF", 0.85), max(1.0, wd * 0.16)))   # its bright inner edge
    p.drawEllipse(ring.adjusted(wd * 0.42, wd * 0.42, -wd * 0.42, -wd * 0.42))
    p.setPen(Qt.PenStyle.NoPen)
    for i in range(3):                                          # three snowflakes on a slow orbit
        a = now * 0.35 + i * math.tau / 3
        at = QPointF(c.x() + math.cos(a) * (r + wd * 1.9), c.y() + math.sin(a) * (r + wd * 1.9))
        fg = QRadialGradient(at, wd * 1.6)
        fg.setColorAt(0, alpha("#FFFFFF", 0.45))
        fg.setColorAt(1, alpha("#FFFFFF", 0.0))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(fg)
        p.drawEllipse(at, wd * 1.6, wd * 1.6)
        _snowflake(p, at, wd * 1.05, now * 30 + i * 40, QColor("#FFFFFF"))
    p.setPen(Qt.PenStyle.NoPen)
    for i in range(14):                                         # snow falling through it
        k = (now * (0.10 + (i % 4) * 0.025) + i * 0.173) % 1.0
        x = c.x() + (((i * 0.618) % 1.0) * 2 - 1) * (r + wd * 3.2) + math.sin(now * 1.1 + i) * wd * 0.6
        y = c.y() - r - wd * 4 + k * (2 * r + wd * 7)
        size = wd * (0.16 + 0.10 * (i % 3))
        p.setBrush(alpha("#FFFFFF", 0.85 * math.sin(k * math.pi)))
        p.drawEllipse(QPointF(x, y), size, size)
    drift = QPainterPath()                                      # the snow that settled at the bottom of the ring
    bottom = c.y() + r
    drift.moveTo(c.x() - r * 0.62, bottom - wd * 0.1)
    drift.cubicTo(QPointF(c.x() - r * 0.35, bottom - wd * 1.5), QPointF(c.x() - r * 0.05, bottom - wd * 0.9),
                  QPointF(c.x() + r * 0.1, bottom - wd * 1.35))
    drift.cubicTo(QPointF(c.x() + r * 0.3, bottom - wd * 1.7), QPointF(c.x() + r * 0.5, bottom - wd * 0.8),
                  QPointF(c.x() + r * 0.62, bottom - wd * 0.1))
    drift.cubicTo(QPointF(c.x() + r * 0.3, bottom + wd * 0.9), QPointF(c.x() - r * 0.3, bottom + wd * 0.9),
                  QPointF(c.x() - r * 0.62, bottom - wd * 0.1))
    dg = QLinearGradient(QPointF(c.x(), bottom - wd * 1.7), QPointF(c.x(), bottom + wd * 0.9))
    dg.setColorAt(0, QColor("#FFFFFF"))
    dg.setColorAt(1, QColor("#BFE6FF"))
    p.setBrush(dg)
    p.drawPath(drift)
    for i in range(5):                                          # glints on the ice
        tw = max(0.0, math.sin(now * 2.7 + i * 2.1))
        if tw < 0.05:
            continue
        a = i / 5 * math.tau + 0.4
        gc = QPointF(c.x() + math.cos(a) * (r + wd * 0.1), c.y() + math.sin(a) * (r + wd * 0.1))
        p.setBrush(alpha("#FFFFFF", 0.95 * tw))
        s = wd * 0.9 * tw
        p.drawPolygon(QPolygonF([QPointF(gc.x(), gc.y() - s), QPointF(gc.x() + s * 0.22, gc.y()),
                                 QPointF(gc.x(), gc.y() + s), QPointF(gc.x() - s * 0.22, gc.y())]))
        p.drawPolygon(QPolygonF([QPointF(gc.x() - s, gc.y()), QPointF(gc.x(), gc.y() + s * 0.22),
                                 QPointF(gc.x() + s, gc.y()), QPointF(gc.x(), gc.y() - s * 0.22)]))
    if r > S(20):                                               # the year, on a little ice tag at the bottom
        tag = QRectF(c.x() - wd * 2.6, bottom + wd * 0.55, wd * 5.2, wd * 1.9)
        p.setBrush(alpha("#0B2A44", 0.85))
        p.setPen(QPen(alpha("#BFF0FF", 0.9), max(0.8, wd * 0.12)))
        p.drawRoundedRect(tag, wd * 0.9, wd * 0.9)
        p.setPen(QColor("#E9FBFF"))
        p.setFont(font(max(5.0, wd * 1.15 / S(1)), QFont.Weight.Black))
        p.drawText(tag, int(Qt.AlignmentFlag.AlignCenter), "2026")
    p.restore()


def _paint_yuletide(p: QPainter, c: QPointF, r: float, wd: float, now: float) -> None:
    """4.0, advent door 1 (Legendary): a warm gold and red aura that breathes, a holly wreath with berries, fairy
    lights that twinkle around it, a star on top and snow drifting through the glow."""
    breathe = 0.65 + 0.35 * math.sin(now * 1.8)
    p.save()
    aura = QRadialGradient(c, r + wd * 5.5)                   # the aura
    aura.setColorAt(0.0, QColor(0, 0, 0, 0))
    aura.setColorAt(max(0.01, r / (r + wd * 5.5) - 0.04), QColor(0, 0, 0, 0))
    aura.setColorAt(r / (r + wd * 5.5), alpha("#FFC94D", 0.42 * breathe))
    aura.setColorAt(min(0.99, r / (r + wd * 5.5) + 0.18), alpha("#E8384F", 0.20 * breathe))
    aura.setColorAt(1.0, QColor(0, 0, 0, 0))
    p.setPen(Qt.PenStyle.NoPen)
    p.setBrush(aura)
    p.drawEllipse(c, r + wd * 5.5, r + wd * 5.5)
    ring = QRectF(c.x() - r, c.y() - r, 2 * r, 2 * r)          # gold band under the wreath
    g = QLinearGradient(ring.topLeft(), ring.bottomRight())
    g.setColorAt(0.0, QColor("#FFF1C2"))
    g.setColorAt(0.5, QColor("#C8962E"))
    g.setColorAt(1.0, QColor("#FFE08A"))
    p.setBrush(Qt.BrushStyle.NoBrush)
    p.setPen(QPen(g, wd * 0.75))
    p.drawEllipse(ring)
    p.setPen(Qt.PenStyle.NoPen)
    for i in range(16):                                         # holly leaves, gently swaying
        a = i / 16 * math.tau
        lc = QPointF(c.x() + math.cos(a) * (r + wd * 0.2), c.y() + math.sin(a) * (r + wd * 0.2))
        p.save()
        p.translate(lc)
        p.rotate(math.degrees(a) + (60 if i % 2 else -60) + math.sin(now * 1.6 + i) * 6)
        leaf = QPainterPath(QPointF(-wd * 1.1, 0))
        leaf.cubicTo(QPointF(-wd * 0.5, -wd * 0.75), QPointF(wd * 0.5, -wd * 0.75), QPointF(wd * 1.1, 0))
        leaf.cubicTo(QPointF(wd * 0.5, wd * 0.75), QPointF(-wd * 0.5, wd * 0.75), QPointF(-wd * 1.1, 0))
        p.setBrush(QColor("#1F7A4A") if i % 2 else QColor("#2E9E5E"))
        p.drawPath(leaf)
        p.restore()
    for i in range(8):                                          # berries
        a = i / 8 * math.tau + math.pi / 8
        bc = QPointF(c.x() + math.cos(a) * r, c.y() + math.sin(a) * r)
        p.setBrush(QColor("#E8384F"))
        p.drawEllipse(bc, wd * 0.42, wd * 0.42)
        p.setBrush(alpha("#FFFFFF", 0.7))
        p.drawEllipse(QPointF(bc.x() - wd * 0.13, bc.y() - wd * 0.13), wd * 0.12, wd * 0.12)
    lights = ("#FF4B5C", "#FFC94D", "#3DDC84", "#4FC3FF", "#FF7AD9")
    for i in range(12):                                         # fairy lights, twinkling in turn
        a = i / 12 * math.tau + now * 0.25
        lc = QPointF(c.x() + math.cos(a) * (r + wd * 1.35), c.y() + math.sin(a) * (r + wd * 1.35))
        tw = 0.35 + 0.65 * max(0.0, math.sin(now * 3.2 + i * 1.7))
        col = QColor(lights[i % len(lights)])
        lg = QRadialGradient(lc, wd * 1.0)
        lg.setColorAt(0, alpha(col, 0.45 * tw))
        lg.setColorAt(1, alpha(col, 0.0))
        p.setBrush(lg)
        p.drawEllipse(lc, wd * 1.0, wd * 1.0)
        p.setBrush(mix(col, QColor("#FFFFFF"), 0.35 * tw))
        p.drawEllipse(lc, wd * 0.34, wd * 0.34)
    top = QPointF(c.x(), c.y() - r - wd * 0.9)                  # the star on top
    sg = QRadialGradient(top, wd * 2.4)
    sg.setColorAt(0, alpha("#FFE9A8", 0.55 * breathe))
    sg.setColorAt(1, alpha("#FFE9A8", 0.0))
    p.setBrush(sg)
    p.drawEllipse(top, wd * 2.4, wd * 2.4)
    pts = []
    for k in range(10):
        rr = wd * (1.35 if k % 2 == 0 else 0.55)
        b = k / 10 * math.tau - math.pi / 2
        pts.append(QPointF(top.x() + math.cos(b) * rr, top.y() + math.sin(b) * rr))
    star = QPainterPath(pts[0])
    for q in pts[1:]:
        star.lineTo(q)
    star.closeSubpath()
    p.setBrush(QColor("#FFE08A"))
    p.drawPath(star)
    for i in range(7):                                          # snow drifting through the glow
        k = ((now * 0.18 + i * 0.37) % 1.0)
        x = c.x() + math.sin(i * 2.3 + now * 0.7) * (r + wd * 2.2)
        y = c.y() - r - wd * 3 + k * (2 * r + wd * 6)
        p.setBrush(alpha("#FFFFFF", 0.75 * math.sin(k * math.pi)))
        p.drawEllipse(QPointF(x, y), wd * 0.22, wd * 0.22)
    p.restore()


def paint_frame(p: QPainter, face: QRectF, item: str, now: float = 0.0, dim: float = 1.0) -> None:
    """A frame around a round profile picture `face` (drawn on top of it, slightly outside)."""
    base = parts(item)[1]
    if not base:
        return
    cw = _CW.get(("frame", base))
    if cw:                                                     # 6.5: a colourway: the picture, recoloured
        m = face.width()
        box = face.adjusted(-m, -m, m, m)
        img, ip = _cw_layer(p, box.width(), box.height())
        ip.translate(-box.left(), -box.top())
        paint_frame(ip, face, "frame:" + cw[0], now, 1.0)
        ip.end()
        p.save()
        p.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform)
        p.setOpacity(p.opacity() * dim)
        p.drawImage(box, recolour_image(img, cw[1]))
        p.restore()
        return
    c1, c2 = (QColor(c) for c in _FRAME_COLS.get(base, ("#FFFFFF", "#9AA4AD")))
    d = face.width()
    wd = max(1.6, d * 0.085)
    c = face.center()
    r = d / 2 + wd * 0.35
    ring = QRectF(c.x() - r, c.y() - r, 2 * r, 2 * r)
    p.save()
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    p.setOpacity(p.opacity() * dim)
    p.setBrush(Qt.BrushStyle.NoBrush)
    if base in ("silver", "bronze", "laurel", "crown", "spikes"):
        g = QLinearGradient(ring.topLeft(), ring.bottomRight())
        g.setColorAt(0.0, c1)
        g.setColorAt(0.5, c2)
        g.setColorAt(1.0, c1)
        p.setPen(QPen(g, wd))
        p.drawEllipse(ring)
    elif base == "ink":
        p.setPen(QPen(c1, wd * 1.3))
        p.drawEllipse(ring)
        p.setPen(QPen(c2, max(1.0, wd * 0.25)))
        p.drawEllipse(ring.adjusted(wd * 0.75, wd * 0.75, -wd * 0.75, -wd * 0.75))
    elif base == "neon":
        pulse = 0.75 + 0.25 * math.sin(now * 3)
        for k in (3.2, 2.2, 1.4):
            p.setPen(QPen(alpha(c1, 0.12 * pulse * (4 - k)), wd * k))
            p.drawEllipse(ring)
        p.setPen(QPen(QColor("#E8FFFF"), wd * 0.6))
        p.drawEllipse(ring)
    elif base == "dashed":
        pen = QPen(c1, wd * 0.8)
        pen.setDashPattern([2.2, 1.6])
        pen.setDashOffset(-now * 4)
        pen.setCapStyle(Qt.PenCapStyle.RoundCap)
        p.setPen(pen)
        p.drawEllipse(ring)
    elif base == "twin":
        p.setPen(QPen(c1, wd * 0.5))
        p.drawEllipse(ring.adjusted(-wd * 0.45, -wd * 0.45, wd * 0.45, wd * 0.45))
        p.setPen(QPen(c2, wd * 0.5))
        p.drawEllipse(ring.adjusted(wd * 0.25, wd * 0.25, -wd * 0.25, -wd * 0.25))
    elif base == "flame":
        p.setPen(Qt.PenStyle.NoPen)
        n = 18
        for i in range(n):
            a = i / n * math.tau
            flick = 0.55 + 0.45 * abs(math.sin(now * 5 + i * 1.9))
            ln = wd * (1.4 + 1.6 * flick)
            tip = QPointF(c.x() + math.cos(a) * (r + ln), c.y() + math.sin(a) * (r + ln))
            left = QPointF(c.x() + math.cos(a - 0.17) * r, c.y() + math.sin(a - 0.17) * r)
            right = QPointF(c.x() + math.cos(a + 0.17) * r, c.y() + math.sin(a + 0.17) * r)
            g = QLinearGradient(QPointF(c.x() + math.cos(a) * r, c.y() + math.sin(a) * r), tip)
            g.setColorAt(0, c2)
            g.setColorAt(1, alpha(c1, 0.0))
            path = QPainterPath(left)
            path.quadTo(QPointF(c.x() + math.cos(a) * (r + ln * 0.6), c.y() + math.sin(a) * (r + ln * 0.6)), tip)
            path.lineTo(right)
            path.closeSubpath()
            p.setBrush(g)
            p.drawPath(path)
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.setPen(QPen(c1, wd * 0.8))
        p.drawEllipse(ring)
    elif base == "orbit":
        p.setPen(QPen(alpha(c1, 0.9), wd * 0.55))
        p.drawEllipse(ring)
        p.setPen(Qt.PenStyle.NoPen)
        for k in range(3):
            a = now * (1.6 + k * 0.4) + k * 2.1
            rr = r + wd * (0.9 + k * 0.5)
            p.setBrush(c2 if k % 2 else c1)
            p.drawEllipse(QPointF(c.x() + math.cos(a) * rr, c.y() + math.sin(a) * rr), wd * 0.55, wd * 0.55)
    elif base == "rainbow":
        from PyQt6.QtGui import QConicalGradient
        g = QConicalGradient(c, (now * 90) % 360)
        for k, col in enumerate(("#FF5CC8", "#FFC94D", "#3DFF7A", "#2EC5FF", "#9B5CFF", "#FF5CC8")):
            g.setColorAt(k / 5, QColor(col))
        p.setPen(QPen(g, wd))
        p.drawEllipse(ring)
    elif base == "frost":                                     # icy ring with crystals
        g = QLinearGradient(ring.topLeft(), ring.bottomRight())
        g.setColorAt(0, c1)
        g.setColorAt(1, c2)
        p.setPen(QPen(g, wd * 0.8))
        p.drawEllipse(ring)
        p.setPen(QPen(alpha("#FFFFFF", 0.9), max(1.0, wd * 0.25)))
        for i in range(6):
            a = i / 6 * math.tau + now * 0.2
            cx, cy = c.x() + math.cos(a) * r, c.y() + math.sin(a) * r
            for k in range(3):
                b = a + k * math.pi / 3
                p.drawLine(QPointF(cx - math.cos(b) * wd * 0.9, cy - math.sin(b) * wd * 0.9),
                           QPointF(cx + math.cos(b) * wd * 0.9, cy + math.sin(b) * wd * 0.9))
    elif base == "vine":                                      # a vine wrapped around, with leaves that sway
        p.setPen(QPen(c2, wd * 0.55))
        p.drawEllipse(ring)
        p.setPen(Qt.PenStyle.NoPen)
        for i in range(10):
            a = i / 10 * math.tau
            lc = QPointF(c.x() + math.cos(a) * r, c.y() + math.sin(a) * r)
            p.save()
            p.translate(lc)
            p.rotate(math.degrees(a) + 45 + math.sin(now * 2 + i) * 12)
            p.setBrush(c1 if i % 2 else c2)
            p.drawEllipse(QPointF(wd * 0.6, 0), wd * 0.9, wd * 0.45)
            p.restore()
    elif base == "star":                                      # gold ring with orbiting stars
        p.setPen(QPen(c2, wd * 0.7))
        p.drawEllipse(ring)
        p.setPen(Qt.PenStyle.NoPen)
        for i in range(5):
            a = i / 5 * math.tau + now * 0.6
            sc = QPointF(c.x() + math.cos(a) * r, c.y() + math.sin(a) * r)
            pts = []
            for k in range(10):
                rr = wd * (1.3 if k % 2 == 0 else 0.55)
                b = k / 10 * math.tau - math.pi / 2 + now
                pts.append(QPointF(sc.x() + math.cos(b) * rr, sc.y() + math.sin(b) * rr))
            path = QPainterPath(pts[0])
            for q in pts[1:]:
                path.lineTo(q)
            path.closeSubpath()
            p.setBrush(c1)
            p.drawPath(path)
    elif base == "halo":                                      # a soft glowing halo that breathes, and a light above
        breathe = 0.7 + 0.3 * math.sin(now * 2)
        for k in (4.0, 2.6, 1.6):
            p.setPen(QPen(alpha(c2, 0.10 * breathe * (5 - k)), wd * k))
            p.drawEllipse(ring)
        p.setPen(QPen(c1, wd * 0.5))
        p.drawEllipse(ring)
        top = QRectF(c.x() - r * 0.55, c.y() - r - wd * 2.6, r * 1.1, wd * 1.4)
        p.setPen(QPen(alpha("#FFF6C8", 0.6 + 0.4 * breathe), wd * 0.55))
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawEllipse(top)
    if base in ("wood", "pulse", "thorns", "gears", "phoenix", "holly", "snowflake", "northstar"):
        _paint_frame_32(p, base, c, r, wd, c1, c2, now)
    if base in ("chrome", "ripple", "comet", "eclipse"):
        _paint_frame_45(p, base, c, r, wd, c1, c2, now)
    if base in _FRAMES_63:
        _paint_frame_63(p, base, c, r, wd, c1, c2, now)
    if base in _FRAMES_65:
        _paint_frame_65(p, base, c, r, wd, c1, c2, now)
    if base == "firstfrost":
        _paint_firstfrost(p, c, r, wd, now)
    if base == "yuletide":
        _paint_yuletide(p, c, r, wd, now)
    if base == "laurel":                                      # leaves up both sides
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor("#E8C26A"))
        for side in (-1, 1):
            for k in range(5):
                a = math.pi / 2 + side * (0.45 + k * 0.38)
                lc = QPointF(c.x() + math.cos(a) * (r + wd * 0.9), c.y() + math.sin(a) * (r + wd * 0.9))
                p.save()
                p.translate(lc)
                p.rotate(math.degrees(a) + 90 + side * 30)
                p.drawEllipse(QPointF(0, 0), wd * 0.55, wd * 1.15)
                p.restore()
    elif base == "crown":
        p.setPen(Qt.PenStyle.NoPen)
        cw, ch = d * 0.46, d * 0.26
        top = c.y() - r - ch * 0.55
        path = QPainterPath(QPointF(c.x() - cw / 2, top + ch))
        for k, (fx, fy) in enumerate(((-0.5, 0.15), (-0.25, 0.55), (0.0, 0.0), (0.25, 0.55), (0.5, 0.15))):
            path.lineTo(c.x() + fx * cw, top + fy * ch)
        path.lineTo(c.x() + cw / 2, top + ch)
        path.closeSubpath()
        g = QLinearGradient(QPointF(0, top), QPointF(0, top + ch))
        g.setColorAt(0, QColor("#FFE9A8"))
        g.setColorAt(1, QColor("#C99A2E"))
        p.setBrush(g)
        p.drawPath(path)
        p.setBrush(QColor("#FF4B6E"))
        p.drawEllipse(QPointF(c.x(), top + ch * 0.62), ch * 0.12, ch * 0.12)
    elif base == "spikes":
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(c1)
        n = 12
        for i in range(n):
            a = i / n * math.tau + math.pi / n
            path = QPainterPath(QPointF(c.x() + math.cos(a - 0.12) * r, c.y() + math.sin(a - 0.12) * r))
            path.lineTo(c.x() + math.cos(a) * (r + wd * 2.0), c.y() + math.sin(a) * (r + wd * 2.0))
            path.lineTo(c.x() + math.cos(a + 0.12) * r, c.y() + math.sin(a + 0.12) * r)
            path.closeSubpath()
            p.drawPath(path)
    p.restore()


def _paint_frame_32(p: QPainter, base: str, c: QPointF, r: float, wd: float, c1: QColor, c2: QColor, now: float) -> None:
    """3.2 frames, simple for Common, busy for Legendary."""
    ring = QRectF(c.x() - r, c.y() - r, 2 * r, 2 * r)
    p.setBrush(Qt.BrushStyle.NoBrush)
    if base == "wood":                                        # Common: a wooden ring with its grain
        p.setPen(QPen(c2, wd * 1.2))
        p.drawEllipse(ring)
        p.setPen(QPen(c1, wd * 0.6))
        p.drawEllipse(ring)
        p.setPen(QPen(alpha("#3A1E0C", 0.6), max(1.0, wd * 0.12)))
        for k in range(8):
            a0 = k * 45 + 10
            p.drawArc(ring.adjusted(-wd * 0.2, -wd * 0.2, wd * 0.2, wd * 0.2), a0 * 16, 18 * 16)
    elif base == "pulse":                                     # Rare: a light runs round the ring
        p.setPen(QPen(alpha(c2, 0.9), wd))
        p.drawEllipse(ring)
        for k in range(3):
            ang = now * 2.4 - k * 0.25
            col = alpha(c1, 1.0 - k * 0.3)
            p.setPen(QPen(col, wd * (1.2 - 0.2 * k), Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
            p.drawArc(ring, int(math.degrees(-ang) * 16), 24 * 16)
    elif base == "thorns":                                    # Epic: a thorny vine and a red rose
        p.setPen(QPen(c1, wd * 0.6))
        p.drawEllipse(ring)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor("#22361C"))
        for k in range(16):
            a = k / 16 * math.tau + 0.1
            o = 1 if k % 2 else -1
            base_pt = QPointF(c.x() + math.cos(a) * r, c.y() + math.sin(a) * r)
            tip = QPointF(c.x() + math.cos(a + o * 0.12) * (r + o * wd * 1.4), c.y() + math.sin(a + o * 0.12) * (r + o * wd * 1.4))
            thorn = QPainterPath(QPointF(base_pt.x() + math.sin(a) * wd * 0.3, base_pt.y() - math.cos(a) * wd * 0.3))
            thorn.lineTo(tip)
            thorn.lineTo(base_pt.x() - math.sin(a) * wd * 0.3, base_pt.y() + math.cos(a) * wd * 0.3)
            thorn.closeSubpath()
            p.drawPath(thorn)
        rose = QPointF(c.x() + r * 0.72, c.y() - r * 0.72)
        bloom = 1 + 0.06 * math.sin(now * 2)
        for k in range(5):
            a = k / 5 * math.tau + now * 0.3
            p.setBrush(mix(c2, QColor("#FF8095"), 0.2 * (k % 2)))
            p.drawEllipse(QPointF(rose.x() + math.cos(a) * wd * 0.6, rose.y() + math.sin(a) * wd * 0.6), wd * 0.8 * bloom, wd * 0.8 * bloom)
        p.setBrush(QColor("#7A0F1E"))
        p.drawEllipse(rose, wd * 0.5, wd * 0.5)
    elif base == "gears":                                     # Epic: two cog rings turning against each other
        for k, (rr, teeth, speed, col) in enumerate(((r + wd * 0.5, 24, 12, c1), (r - wd * 0.4, 18, -16, c2))):
            path = QPainterPath()
            for n in range(teeth * 4 + 1):
                ang = math.radians(now * speed + n * 360 / (teeth * 4))
                rad = rr + (wd * 0.45 if (n % 4) in (1, 2) else 0)
                pt = QPointF(c.x() + rad * math.cos(ang), c.y() + rad * math.sin(ang))
                path.lineTo(pt) if n else path.moveTo(pt)
            p.setPen(QPen(col, max(1.0, wd * 0.4), Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin))
            p.drawPath(path)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(c1)
        for k in range(6):
            a = math.radians(k * 60 + now * 12)
            p.drawEllipse(QPointF(c.x() + math.cos(a) * r, c.y() + math.sin(a) * r), wd * 0.18, wd * 0.18)
    elif base == "phoenix":                                   # Legendary: a ring of fire and two burning wings
        for k in (3.0, 2.0, 1.2):
            p.setPen(QPen(alpha(c2, 0.14 * (4 - k)), wd * k))
            p.drawEllipse(ring)
        p.setPen(QPen(c1, wd * 0.6))
        p.drawEllipse(ring)
        p.setPen(Qt.PenStyle.NoPen)
        beat = math.sin(now * 3) * 0.12
        for side in (-1, 1):                                  # feathers fan out from each side, never over the face
            for k in range(5):
                root = QPointF(c.x() + side * (r + wd * 0.3), c.y() + r * (0.25 - k * 0.12))
                tip = QPointF(c.x() + side * (r + wd * (4.2 - k * 0.5)), c.y() - r * (0.15 + k * 0.2 + beat))
                feather = QPainterPath(root)
                feather.quadTo(c.x() + side * (r + wd * 2.6), c.y() + r * (0.2 - k * 0.1), tip.x(), tip.y())
                feather.quadTo(c.x() + side * (r + wd * 1.4), c.y() - r * (0.05 + k * 0.12), root.x(), root.y() - wd * 0.6)
                feather.closeSubpath()
                g = QLinearGradient(root, tip)
                g.setColorAt(0, alpha(c2, 0.95))
                g.setColorAt(1, alpha(c1, 0.75))
                p.setBrush(g)
                p.drawPath(feather)
        for k in range(10):                                   # sparks
            t = (now * 0.6 + k / 10) % 1.0
            a = k / 10 * math.tau
            p.setBrush(alpha("#FFE9A8", 1 - t))
            p.drawEllipse(QPointF(c.x() + math.cos(a) * (r + wd * 3 * t), c.y() + math.sin(a) * (r + wd * 3 * t) - t * wd * 2),
                          wd * 0.2, wd * 0.2)
    elif base == "holly":                                     # limited Rare: holly leaves and red berries
        p.setPen(QPen(c1, wd * 0.8))
        p.drawEllipse(ring)
        p.setPen(Qt.PenStyle.NoPen)
        for k in range(6):
            a = k / 6 * math.tau - math.pi / 2
            lc = QPointF(c.x() + math.cos(a) * r, c.y() + math.sin(a) * r)
            for side in (-1, 1):
                p.save()
                p.translate(lc)
                p.rotate(math.degrees(a) + 90 + side * 35)
                p.setBrush(QColor("#1F7A4A"))
                p.drawEllipse(QPointF(0, -wd * 0.9), wd * 0.45, wd * 0.95)
                p.restore()
            p.setBrush(c2)
            p.drawEllipse(lc, wd * 0.35, wd * 0.35)
    elif base == "snowflake":                                 # limited Epic: an icy ring with turning snowflakes
        p.setPen(QPen(alpha(c2, 0.8), wd))
        p.drawEllipse(ring)
        p.setPen(QPen(c1, wd * 0.35))
        p.drawEllipse(ring)
        for k in range(4):
            a = k / 4 * math.tau + now * 0.4
            fc = QPointF(c.x() + math.cos(a) * r, c.y() + math.sin(a) * r)
            p.save()
            p.translate(fc)
            p.rotate(now * 40 + k * 20)
            p.setPen(QPen(QColor("#FFFFFF"), max(1.0, wd * 0.18), Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
            for j in range(6):
                p.rotate(60)
                p.drawLine(QPointF(0, 0), QPointF(0, -wd * 1.2))
                p.drawLine(QPointF(0, -wd * 0.7), QPointF(wd * 0.3, -wd * 0.95))
                p.drawLine(QPointF(0, -wd * 0.7), QPointF(-wd * 0.3, -wd * 0.95))
            p.restore()
    elif base == "northstar":                                 # limited Legendary: gold ring, the star on top, orbiting light
        g = QLinearGradient(ring.topLeft(), ring.bottomRight())
        g.setColorAt(0, QColor("#FFF6C8"))
        g.setColorAt(0.5, c2)
        g.setColorAt(1, QColor("#FFF6C8"))
        p.setPen(QPen(g, wd))
        p.drawEllipse(ring)
        p.setPen(Qt.PenStyle.NoPen)
        top = QPointF(c.x(), c.y() - r - wd * 0.6)
        glow = QRadialGradient(top, wd * 3.5)
        glow.setColorAt(0, alpha("#FFF6C8", 0.9))
        glow.setColorAt(1, alpha("#FFF6C8", 0.0))
        p.setBrush(glow)
        p.drawEllipse(top, wd * 3.5, wd * 3.5)
        star = QPainterPath()
        for k in range(8):
            ang = math.radians(-90 + 45 * k)
            rr = wd * (2.2 if k % 2 == 0 else 0.6)
            pt = QPointF(top.x() + math.cos(ang) * rr, top.y() + math.sin(ang) * rr)
            star.lineTo(pt) if k else star.moveTo(pt)
        star.closeSubpath()
        p.setBrush(QColor("#FFFFFF"))
        p.drawPath(star)
        for k in range(3):
            a = now * (1.2 + k * 0.3) + k * 2
            p.setBrush(alpha("#FFE9A8", 0.9))
            p.drawEllipse(QPointF(c.x() + math.cos(a) * (r + wd * 0.9), c.y() + math.sin(a) * (r + wd * 0.9)), wd * 0.22, wd * 0.22)


def paint_tag(p: QPainter, x: float, cy: float, item: str, now: float = 0.0, size: float = 8.5,
              centre: bool = False, px: float = 0.0) -> float:
    """A tag after a name ("OG": gold, with a light running across). Returns its width. `px`: an exact pixel size."""
    text = _NAMES["tag"].get(parts(item)[1], parts(item)[1].upper()) or "?"
    p.save()
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    f = font(size, QFont.Weight.Black, 0.8)
    if px:
        f.setPixelSize(max(6, int(px)))
    p.setFont(f)
    hgt = f.pixelSize() * 1.75
    w = p.fontMetrics().horizontalAdvance(text) + hgt * 0.75
    if centre:
        x -= w / 2
    box = QRectF(x, cy - hgt / 2, w, hgt)
    rad = hgt * 0.32
    if parts(item)[1] == "og":                                 # 5.9: the OG tag is one of a kind: obsidian, a
        from PyQt6.QtGui import QBrush, QConicalGradient
        t = now or 0.0                                         # rainbow edge that turns, a breathing glow, sparkles
        pulse = 0.5 + 0.5 * math.sin(t * 2.4)
        for k in range(4, 0, -1):                              # the glow, stronger than any other tag
            grow = hgt * (0.10 + 0.09 * k) * (0.85 + 0.3 * pulse)
            col = QColor.fromHsvF((t * 0.08 + k * 0.07) % 1.0, 0.75, 1.0)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(alpha(col, 0.10 + 0.05 * pulse))
            p.drawRoundedRect(box.adjusted(-grow, -grow, grow, grow), rad + grow, rad + grow)
        body = QLinearGradient(box.topLeft(), box.bottomLeft())
        body.setColorAt(0.0, QColor("#2B1748"))
        body.setColorAt(1.0, QColor("#0A0614"))
        ring = QConicalGradient(box.center(), (t * 120) % 360)
        for k in range(7):
            ring.setColorAt(k / 6, QColor.fromHsvF((k / 6) % 1.0, 0.8, 1.0))
        p.setPen(QPen(QBrush(ring), max(1.2, hgt * 0.11)))
        p.setBrush(body)
        p.drawRoundedRect(box, rad, rad)
        txt = QLinearGradient(box.topLeft(), box.bottomRight())
        sh = (t * 0.25) % 1.0
        txt.setColorAt(0.0, QColor("#FFE9A8"))
        txt.setColorAt(min(0.99, 0.2 + sh * 0.6), QColor("#FFFFFF"))
        txt.setColorAt(1.0, QColor("#7FE8FF"))
        path = QPainterPath()
        fm = p.fontMetrics()
        tw = fm.horizontalAdvance(text)
        path.addText(QPointF(box.center().x() - tw / 2, box.center().y() + fm.ascent() / 2 - fm.descent() / 2), p.font(), text)
        p.setPen(QPen(alpha("#000000", 0.35), max(0.8, hgt * 0.04)))
        p.setBrush(QBrush(txt))
        p.drawPath(path)
        for k, (fx, fy) in enumerate(((0.08, 0.12), (0.93, 0.85))):   # two twinkles on the corners
            tw_ = max(0.0, math.sin(t * 3.1 + k * 2.3))
            if tw_ <= 0.05:
                continue
            c_ = QPointF(box.left() + box.width() * fx, box.top() + box.height() * fy)
            r_ = hgt * 0.32 * tw_
            star = QPainterPath()
            for n in range(8):
                ang = math.radians(45 * n)
                rr = r_ if n % 2 == 0 else r_ * 0.25
                pt = QPointF(c_.x() + math.cos(ang) * rr, c_.y() + math.sin(ang) * rr)
                star.lineTo(pt) if n else star.moveTo(pt)
            star.closeSubpath()
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(alpha("#FFFFFF", 0.95))
            p.drawPath(star)
        p.restore()
        return w
    g = QLinearGradient(box.topLeft(), box.bottomRight())
    g.setColorAt(0.0, QColor("#FFE9A8"))
    g.setColorAt(0.5, QColor("#E8B13A"))
    g.setColorAt(1.0, QColor("#B87A16"))
    p.setPen(QPen(QColor("#FFF4CF"), 0.8))
    p.setBrush(g)
    p.drawRoundedRect(box, hgt * 0.28, hgt * 0.28)
    if now:                                                    # a light running across
        clip = QPainterPath()
        clip.addRoundedRect(box, hgt * 0.28, hgt * 0.28)
        p.setClipPath(clip)
        sx = box.left() + ((now * 0.5) % 1.6 - 0.3) * box.width() * 1.4
        shine = QLinearGradient(QPointF(sx - hgt, 0), QPointF(sx + hgt, 0))
        shine.setColorAt(0, alpha("#FFFFFF", 0.0))
        shine.setColorAt(0.5, alpha("#FFFFFF", 0.65))
        shine.setColorAt(1, alpha("#FFFFFF", 0.0))
        p.fillRect(box, shine)
        p.setClipping(False)
    p.setPen(QColor("#3A2300"))
    p.drawText(box, int(Qt.AlignmentFlag.AlignCenter), text)
    p.restore()
    return w


def paint_blank_face(p: QPainter, face: QRectF) -> None:
    """A plain grey picture (for previews of frames)."""
    p.save()
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    p.setPen(Qt.PenStyle.NoPen)
    p.setBrush(QColor("#2A3238"))
    p.drawEllipse(face)
    clip = QPainterPath()
    clip.addEllipse(face)
    p.setClipPath(clip)
    p.setBrush(QColor("#55626C"))
    d = face.width()
    p.drawEllipse(QPointF(face.center().x(), face.top() + d * 0.4), d * 0.18, d * 0.18)
    p.drawEllipse(QPointF(face.center().x(), face.top() + d * 0.95), d * 0.34, d * 0.3)
    p.restore()


def paint_look_icon(p: QPainter, item: str, rect: QRectF, now: float = 0.0, dim: float = 1.0) -> None:
    """The small picture of a banner, frame or tag (shop, inventory, market, trades)."""
    kind = parts(item)[0]
    d = min(rect.width(), rect.height())
    box = QRectF(rect.center().x() - d / 2, rect.center().y() - d / 2, d, d)
    p.save()
    p.setOpacity(p.opacity() * dim)
    if kind == "banner":
        paint_banner(p, QRectF(box.left(), box.top() + d * 0.2, d, d * 0.6), item, now, d * 0.1)
    elif kind == "frame":
        face = box.adjusted(d * 0.22, d * 0.22, -d * 0.22, -d * 0.22)
        paint_blank_face(p, face)
        paint_frame(p, face, item, now)
    else:
        paint_tag(p, box.center().x(), box.center().y(), item, now, centre=True, px=d * 0.24)
    p.restore()


# --------------------------------------------------------------------------- #
# 4.5 banners and frames
# --------------------------------------------------------------------------- #
def _paint_banner_45(p: QPainter, base: str, rect: QRectF, c1: QColor, c2: QColor, now: float) -> None:
    w, h = rect.width(), rect.height()
    L, T = rect.left(), rect.top()
    p.setPen(Qt.PenStyle.NoPen)
    if base == "mosaic":                                       # Common: quiet tiles in three blues
        cols = [QColor("#2A3550"), QColor("#34466B"), QColor("#24304A"), QColor("#40557F")]
        size = h / 4
        y, row = T, 0
        while y < rect.bottom():
            x = L - (size / 2 if row % 2 else 0)
            i = 0
            while x < rect.right():
                p.setBrush(cols[int(_rand(row * 31 + i, 3) * 4) % 4])
                p.drawRoundedRect(QRectF(x + 1.5, y + 1.5, size - 3, size - 3), 3, 3)
                x += size
                i += 1
            y += size
            row += 1
    elif base == "reef":                                       # Rare: light from the surface and swaying coral
        for k in range(5):
            x = L + w * (0.1 + 0.2 * k) + math.sin(now * 0.5 + k) * w * 0.02
            g = QLinearGradient(QPointF(x, T), QPointF(x + w * 0.08, rect.bottom()))
            g.setColorAt(0, alpha("#BFF8FF", 0.22))
            g.setColorAt(1, alpha("#BFF8FF", 0.0))
            p.setBrush(g)
            p.drawPolygon(QPolygonF([QPointF(x, T), QPointF(x + w * 0.05, T), QPointF(x + w * 0.12, rect.bottom()),
                                     QPointF(x + w * 0.03, rect.bottom())]))
        for k in range(7):
            bx = L + w * (0.06 + k * 0.15)
            sway = math.sin(now * 1.2 + k) * w * 0.012
            col = ("#FF6F8E", "#FFB067", "#B36BFF")[k % 3]
            path = QPainterPath(QPointF(bx, rect.bottom()))
            path.cubicTo(QPointF(bx - w * 0.02 + sway, rect.bottom() - h * 0.25), QPointF(bx + w * 0.03 + sway, rect.bottom() - h * 0.35),
                         QPointF(bx + sway * 2, rect.bottom() - h * (0.35 + 0.15 * _rand(k, 5))))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.setPen(QPen(alpha(col, 0.85), max(2.0, w * 0.012), Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
            p.drawPath(path)
        p.setPen(Qt.PenStyle.NoPen)
        for k in range(6):                                     # bubbles drifting up
            y = rect.bottom() - ((now * 0.12 + _rand(k, 9)) % 1.0) * h
            p.setBrush(alpha("#DDFBFF", 0.5))
            p.drawEllipse(QPointF(L + w * _rand(k, 4), y), 1.6 + 1.2 * _rand(k, 2), 1.6 + 1.2 * _rand(k, 2))
    elif base == "thunder":                                    # Rare: clouds and a far flash now and then
        flash = max(0.0, 1.0 - ((now * 0.35) % 1.0) * 6)
        p.fillRect(rect, alpha("#CFE0FF", 0.10 * flash))
        for k in range(9):
            cx = L + ((_rand(k, 1) * w + now * 6 * (0.5 + _rand(k, 2))) % (w * 1.2)) - w * 0.1
            cy = T + h * (0.1 + 0.3 * _rand(k, 3))
            g = QRadialGradient(QPointF(cx, cy), w * 0.16)
            g.setColorAt(0, alpha("#3A4A6B", 0.85))
            g.setColorAt(1, alpha("#3A4A6B", 0.0))
            p.setBrush(g)
            p.drawEllipse(QPointF(cx, cy), w * 0.16, h * 0.3)
        if flash > 0.05:
            bolt = QPainterPath(QPointF(L + w * 0.68, T + h * 0.25))
            for k, (dx, dy) in enumerate(((-0.03, 0.2), (0.02, 0.18), (-0.04, 0.22), (0.01, 0.2))):
                bolt.lineTo(bolt.currentPosition() + QPointF(w * dx, h * dy))
            p.setBrush(Qt.BrushStyle.NoBrush)
            for width_, a in ((6, 0.25), (2, 1.0)):
                p.setPen(QPen(alpha("#E6F0FF", a * flash), width_, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
                p.drawPath(bolt)
        p.setPen(Qt.PenStyle.NoPen)
    elif base == "blackhole":                                  # Special: a disc of light bent around a black centre
        cen = QPointF(L + w * 0.62, T + h * 0.52)
        for k in range(60):
            a = _rand(k, 1) * math.tau + now * (0.2 + 0.6 * _rand(k, 2))
            rr = h * (0.3 + 0.9 * _rand(k, 3))
            p.setBrush(alpha("#FFFFFF", 0.25 + 0.5 * _rand(k, 4)))
            p.drawEllipse(QPointF(cen.x() + math.cos(a) * rr * 1.6, cen.y() + math.sin(a) * rr * 0.5), 0.9, 0.9)
        for width_, a in ((h * 0.22, 0.12), (h * 0.1, 0.35), (h * 0.04, 0.9)):
            g = QConicalGradient(cen, now * 40)
            g.setColorAt(0, alpha("#FFB347", a))
            g.setColorAt(0.5, alpha("#FF5C8A", a))
            g.setColorAt(1, alpha("#FFB347", a))
            p.setPen(QPen(g, width_))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawEllipse(cen, h * 0.62, h * 0.18)
        p.setPen(QPen(alpha("#FFD9A0", 0.7), h * 0.03))
        p.drawEllipse(cen, h * 0.24, h * 0.24)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor("#000000"))
        p.drawEllipse(cen, h * 0.22, h * 0.22)
    elif base == "crystal":                                    # Epic: a cluster of crystals catching moving light
        shine = (now * 0.25) % 1.6 - 0.3
        spikes = [(0.15, 0.55, 0.06), (0.24, 0.35, 0.08), (0.33, 0.6, 0.05), (0.62, 0.3, 0.09), (0.72, 0.5, 0.07),
                  (0.82, 0.62, 0.05), (0.46, 0.45, 0.07)]
        for k, (x, top, half) in enumerate(spikes):
            bx = L + w * x
            path = QPainterPath(QPointF(bx - w * half, rect.bottom()))
            path.lineTo(bx - w * half * 0.6, T + h * (top + 0.12))
            path.lineTo(bx, T + h * top)
            path.lineTo(bx + w * half * 0.6, T + h * (top + 0.12))
            path.lineTo(bx + w * half, rect.bottom())
            path.closeSubpath()
            g = QLinearGradient(QPointF(bx - w * half, T), QPointF(bx + w * half, rect.bottom()))
            lit = max(0.0, 1.0 - abs(shine - x) * 4)
            g.setColorAt(0, alpha(mix(QColor("#9FDBFF"), QColor("#FFFFFF"), lit), 0.75))
            g.setColorAt(0.5, alpha("#3A7BFF", 0.55))
            g.setColorAt(1, alpha("#1A2A5A", 0.85))
            p.setBrush(g)
            p.setPen(QPen(alpha("#DDF3FF", 0.35 + 0.5 * lit), 1))
            p.drawPath(path)
            p.setPen(QPen(alpha("#FFFFFF", 0.2 + 0.5 * lit), 1))
            p.drawLine(QPointF(bx, T + h * top), QPointF(bx, rect.bottom()))
        p.setPen(Qt.PenStyle.NoPen)


def _paint_frame_45(p: QPainter, base: str, c: QPointF, r: float, wd: float, c1: QColor, c2: QColor, now: float) -> None:
    ring = QRectF(c.x() - r, c.y() - r, 2 * r, 2 * r)
    p.setBrush(Qt.BrushStyle.NoBrush)
    if base == "chrome":                                       # Common: polished metal with one highlight
        g = QConicalGradient(c, 45)
        for k, col in enumerate((c1, c2, c1, c2, c1)):
            g.setColorAt(k / 4, col)
        p.setPen(QPen(g, wd))
        p.drawEllipse(ring)
    elif base == "ripple":                                     # Rare: rings spreading out like water
        p.setPen(QPen(c1, wd * 0.6))
        p.drawEllipse(ring)
        for k in range(3):
            f = ((now * 0.6 + k / 3) % 1.0)
            grow = wd * 2.4 * f
            p.setPen(QPen(alpha(c1, 0.7 * (1 - f)), max(1.0, wd * 0.35)))
            p.drawEllipse(ring.adjusted(-grow, -grow, grow, grow))
    elif base == "comet":                                      # Special: a comet circling with its tail
        p.setPen(QPen(alpha(c2, 0.35), wd * 0.45))
        p.drawEllipse(ring)
        head = now * 2.2
        for k in range(24):
            a = head - k * 0.06
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(alpha(mix(c2, c1, 1 - k / 24), (1 - k / 24) * 0.9))
            rr = wd * 0.55 * (1 - k / 30)
            p.drawEllipse(QPointF(c.x() + math.cos(a) * r, c.y() + math.sin(a) * r), rr, rr)
        glow = QRadialGradient(QPointF(c.x() + math.cos(head) * r, c.y() + math.sin(head) * r), wd * 2)
        glow.setColorAt(0, alpha("#FFFFFF", 0.9))
        glow.setColorAt(1, alpha(c2, 0.0))
        p.setBrush(glow)
        p.drawEllipse(QPointF(c.x() + math.cos(head) * r, c.y() + math.sin(head) * r), wd * 2, wd * 2)
    else:                                                      # Epic: eclipse, a burning corona behind a dark ring
        for k, (w_, a) in enumerate(((3.4, 0.12), (2.2, 0.25), (1.2, 0.6))):
            g = QConicalGradient(c, now * 30 + k * 60)
            g.setColorAt(0.0, alpha(c1, a))
            g.setColorAt(0.25, alpha("#FF8A3D", a * 0.6))
            g.setColorAt(0.5, alpha(c1, a))
            g.setColorAt(0.75, alpha("#FFFFFF", a))
            g.setColorAt(1.0, alpha(c1, a))
            p.setPen(QPen(g, wd * w_))
            p.drawEllipse(ring)
        p.setPen(QPen(c2, wd * 0.7))
        p.drawEllipse(ring)
        ang = now * 1.4
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(alpha("#FFFFFF", 0.95))
        p.drawEllipse(QPointF(c.x() + math.cos(ang) * r, c.y() + math.sin(ang) * r), wd * 0.35, wd * 0.35)


# --------------------------------------------------------------------------- #
# 6.4: twelve new profile frames (not seasonal): 3 Common, 3 Rare, 3 Special, 3 Epic
# --------------------------------------------------------------------------- #
_FRAMES_63 = ("gold", "emerald", "sapphire", "beads", "chain", "daisy", "plasma", "sparks", "constellation",
              "spectrum", "void", "wings")


def _paint_frame_63(p: QPainter, base: str, c: QPointF, r: float, wd: float, c1: QColor, c2: QColor, now: float) -> None:
    ring = QRectF(c.x() - r, c.y() - r, 2 * r, 2 * r)
    p.setBrush(Qt.BrushStyle.NoBrush)

    def at(a: float, rr: float = 0.0) -> QPointF:
        return QPointF(c.x() + math.cos(a) * (r + rr), c.y() + math.sin(a) * (r + rr))

    if base in ("gold", "emerald", "sapphire"):               # Common: a polished ring that catches the light
        g = QConicalGradient(c, 30 + now * 25)
        for k, col in enumerate((c1, c2, c1, c2, c1)):
            g.setColorAt(k / 4, col)
        p.setPen(QPen(g, wd * 1.1))
        p.drawEllipse(ring)
        p.setPen(Qt.PenStyle.NoPen)
        if base != "gold":                                     # a gem at the top (emerald) or a bead every 45° (sapphire)
            angles = (-math.pi / 2,) if base == "emerald" else tuple(k * math.pi / 4 for k in range(8))
            for a in angles:
                p.setBrush(QColor("#E8FFF4" if base == "emerald" else "#E6F2FF"))
                p.drawEllipse(at(a), wd * (0.75 if base == "emerald" else 0.32), wd * (0.75 if base == "emerald" else 0.32))
    elif base == "beads":                                      # Rare: a string of round beads
        p.setPen(QPen(alpha(c2, 0.6), wd * 0.25))
        p.drawEllipse(ring)
        p.setPen(Qt.PenStyle.NoPen)
        n = 16
        for k in range(n):
            a = k * 2 * math.pi / n + now * 0.25
            bead = at(a)
            g = QRadialGradient(QPointF(bead.x() - wd * 0.2, bead.y() - wd * 0.2), wd * 0.8)
            g.setColorAt(0, QColor("#FFFFFF"))
            g.setColorAt(0.35, c1 if k % 2 else c2)
            g.setColorAt(1, mix(c1 if k % 2 else c2, QColor("#000000"), 0.45))
            p.setBrush(g)
            p.drawEllipse(bead, wd * 0.62, wd * 0.62)
    elif base == "chain":                                      # Rare: metal links running round
        for col, off in ((c2, 0.0), (c1, 2.6)):
            pen = QPen(col, wd * 0.95)
            pen.setDashPattern([2.6, 2.6])
            pen.setDashOffset(-now * 2.0 + off)
            pen.setCapStyle(Qt.PenCapStyle.RoundCap)
            p.setPen(pen)
            p.drawEllipse(ring.adjusted(wd * 0.12, wd * 0.12, -wd * 0.12, -wd * 0.12) if off else ring)
    elif base == "daisy":                                      # Rare: a ring of white petals with a yellow heart
        p.setPen(QPen(alpha("#3FA356", 0.9), wd * 0.5))
        p.drawEllipse(ring)
        p.setPen(Qt.PenStyle.NoPen)
        n = 12
        for k in range(n):
            a = k * 2 * math.pi / n + now * 0.15
            p.save()
            p.translate(at(a, wd * 0.2))
            p.rotate(math.degrees(a))
            p.setBrush(QColor("#FFFFFF") if k % 2 == 0 else QColor("#FFE9F2"))
            p.drawEllipse(QPointF(wd * 0.5, 0), wd * 1.25, wd * 0.58)
            p.restore()
        p.setBrush(QColor("#FFD84D"))
        for k in range(n):
            p.drawEllipse(at(k * 2 * math.pi / n + now * 0.15), wd * 0.18, wd * 0.18)
    elif base == "plasma":                                     # Special: a ring of hot, shifting plasma
        for k, (w_, a) in enumerate(((3.6, 0.10), (2.4, 0.22), (1.4, 0.6), (0.8, 1.0))):
            g = QConicalGradient(c, now * 70 + k * 40)
            for j, col in enumerate(("#FF2BD6", "#7C4DFF", "#35D6E6", "#FFC14D", "#FF2BD6")):
                g.setColorAt(j / 4, alpha(col, a))
            p.setPen(QPen(g, wd * w_))
            p.drawEllipse(ring)
    elif base == "sparks":                                     # Special: a ring that throws off sparks
        p.setPen(QPen(c2, wd * 0.9))
        p.drawEllipse(ring)
        p.setPen(QPen(alpha("#FFFFFF", 0.8), wd * 0.25))
        p.drawEllipse(ring)
        for k in range(14):
            t = (now * (0.7 + 0.4 * _rand(k, 1)) + _rand(k, 2)) % 1.0
            a = _rand(k, 3) * 2 * math.pi
            p0, p1 = at(a, wd * 0.4 + wd * 2.8 * t), at(a, wd * 0.4 + wd * 2.8 * t + wd * 0.9 * (1 - t))
            p.setPen(QPen(alpha(c1, 1 - t), max(1.0, wd * 0.28), Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
            p.drawLine(p0, p1)
    elif base == "constellation":                              # Special: stars joined by thin lines
        pts = []
        for k in range(9):
            a = k * 2 * math.pi / 9 + math.sin(now * 0.3) * 0.05
            pts.append(at(a, (_rand(k, 4) - 0.5) * wd * 1.8))
        p.setPen(QPen(alpha(c2, 0.9), max(1.0, wd * 0.22)))
        for k in range(9):
            p.drawLine(pts[k], pts[(k + 1) % 9])
        p.setPen(Qt.PenStyle.NoPen)
        for k, pt in enumerate(pts):
            tw = 0.6 + 0.4 * math.sin(now * 2.4 + k * 1.7)
            glow = QRadialGradient(pt, wd * 1.1 * tw)
            glow.setColorAt(0, alpha("#FFFFFF", 0.95))
            glow.setColorAt(1, alpha(c1, 0.0))
            p.setBrush(glow)
            p.drawEllipse(pt, wd * 1.1 * tw, wd * 1.1 * tw)
    elif base == "spectrum":                                   # Epic: a rainbow that turns around the picture
        for w_, a in ((3.6, 0.12), (2.3, 0.28)):
            g = QConicalGradient(c, now * 60)
            for j in range(7):
                g.setColorAt(j / 6, alpha(QColor.fromHsvF(j / 6 % 1.0 * 0.999, 0.85, 1.0), a))
            p.setPen(QPen(g, wd * w_))
            p.drawEllipse(ring)
        g = QConicalGradient(c, now * 60)
        for j in range(7):
            g.setColorAt(j / 6, QColor.fromHsvF(j / 6 % 1.0 * 0.999, 0.8, 1.0))
        p.setPen(QPen(g, wd * 1.1))
        p.drawEllipse(ring)
        p.setPen(QPen(alpha("#FFFFFF", 0.7), max(1.0, wd * 0.2)))
        p.drawEllipse(ring)
    elif base == "void":                                       # Epic: a dark ring pulling light inwards
        for k, (w_, a) in enumerate(((3.6, 0.10), (2.4, 0.20), (1.5, 0.35))):
            p.setPen(QPen(alpha(c1, a), wd * w_))
            p.drawEllipse(ring)
        p.setPen(QPen(c2, wd * 1.3))
        p.drawEllipse(ring)
        p.setPen(Qt.PenStyle.NoPen)
        for k in range(10):
            t = (now * 0.35 + k / 10) % 1.0
            a = k * 2.4 + now * 0.8
            rr = wd * 2.6 * (1 - t)
            p.setBrush(alpha(c1, 0.15 + 0.8 * t))
            p.drawEllipse(at(a, rr), wd * 0.3, wd * 0.3)
    elif base == "wings":                                      # Epic: golden wings, flapping slowly
        flap = math.sin(now * 1.6) * 0.12
        p.setPen(Qt.PenStyle.NoPen)
        for side in (-1, 1):
            for k in range(6):
                a = math.radians(-12 - k * 16) + (flap * (k + 1) / 6)
                length = wd * (6.2 - k * 0.55)
                base_pt = QPointF(c.x() + side * r * 0.9, c.y() + r * 0.1)
                tip = QPointF(base_pt.x() + side * math.cos(a) * (r * 0.55 + length),
                              base_pt.y() + math.sin(a) * (r * 0.55 + length) - length * 0.4)
                feather = QPainterPath(base_pt)
                feather.quadTo(QPointF((base_pt.x() + tip.x()) / 2, (base_pt.y() + tip.y()) / 2 - wd * 1.3), tip)
                feather.quadTo(QPointF((base_pt.x() + tip.x()) / 2, (base_pt.y() + tip.y()) / 2 + wd * 1.3), base_pt)
                g = QLinearGradient(base_pt, tip)
                g.setColorAt(0, c2)
                g.setColorAt(1, c1)
                p.setBrush(g)
                p.drawPath(feather)
        g = QConicalGradient(c, 40)
        for k, col in enumerate((c1, c2, c1, c2, c1)):
            g.setColorAt(k / 4, col)
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.setPen(QPen(g, wd))
        p.drawEllipse(ring)



# --------------------------------------------------------------------------- #
# 6.5: ten more profile frames (not seasonal)
# --------------------------------------------------------------------------- #
_FRAMES_65 = ("rosegold", "onyx", "copper", "rope", "bubbles", "pixel", "lightning", "orbitals", "galaxy", "diamond")


def _paint_frame_65(p: QPainter, base: str, c: QPointF, r: float, wd: float, c1: QColor, c2: QColor, now: float) -> None:
    ring = QRectF(c.x() - r, c.y() - r, 2 * r, 2 * r)
    p.setBrush(Qt.BrushStyle.NoBrush)

    def at(a: float, rr: float = 0.0) -> QPointF:
        return QPointF(c.x() + math.cos(a) * (r + rr), c.y() + math.sin(a) * (r + rr))

    if base in ("rosegold", "onyx", "copper"):                 # Common: polished metal rings with a moving shine
        g = QConicalGradient(c, now * 40)
        for k, col in enumerate((c1, c2, c1, c2, c1)):
            g.setColorAt(k / 4, col)
        p.setPen(QPen(g, wd * 1.15))
        p.drawEllipse(ring)
        p.setPen(QPen(alpha("#FFFFFF", 0.35), max(1.0, wd * 0.18)))
        p.drawEllipse(ring.adjusted(wd * 0.3, wd * 0.3, -wd * 0.3, -wd * 0.3))
    elif base == "rope":                                       # Rare: a twisted rope
        for off, col in ((0.0, c1), (3.0, c2)):
            pen = QPen(col, wd * 0.95)
            pen.setDashPattern([3.0, 3.0])
            pen.setDashOffset(-now * 1.5 + off)
            p.setPen(pen)
            p.drawEllipse(ring.adjusted(wd * 0.15 * (1 if off else -1), wd * 0.15 * (1 if off else -1),
                                        -wd * 0.15 * (1 if off else -1), -wd * 0.15 * (1 if off else -1)))
    elif base == "bubbles":                                    # Rare: bubbles drifting around the picture
        p.setPen(QPen(alpha(c2, 0.5), wd * 0.3))
        p.drawEllipse(ring)
        for k in range(12):
            a = k * math.tau / 12 + now * 0.3
            rr = wd * (0.35 + 0.35 * abs(math.sin(now * 0.9 + k * 1.3)))
            p.setPen(QPen(alpha(c1, 0.85), max(1.0, wd * 0.14)))
            p.setBrush(alpha(c1, 0.15))
            p.drawEllipse(at(a, math.sin(now + k) * wd * 0.4), rr, rr)
    elif base == "pixel":                                      # Rare: a ring of 8-bit blocks that blink
        n = 20
        for k in range(n):
            a = k * math.tau / n
            on = (int(now * 2 + k * 7) % 3) != 0
            p.save()
            p.translate(at(a))
            p.rotate(math.degrees(a) + 90)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(c1 if k % 2 else c2)
            p.setOpacity(p.opacity() * (1.0 if on else 0.3))
            p.drawRect(QRectF(-wd * 0.5, -wd * 0.5, wd, wd))
            p.restore()
    elif base == "lightning":                                  # Special: electric arcs crackling round the ring
        p.setPen(QPen(alpha(c2, 0.5), wd * 0.7))
        p.drawEllipse(ring)
        step = int(now * 9)
        for k in range(6):
            a0 = _rand(step + k * 5, 1) * math.tau
            pts = []
            for j in range(7):
                a = a0 + j * 0.12
                pts.append(at(a, (_rand(step + k, j + 3) - 0.5) * wd * 2.6))
            p.setPen(QPen(alpha("#FFFFFF", 0.95), max(1.0, wd * 0.22), Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin))
            p.drawPolyline(QPolygonF(pts))
            p.setPen(QPen(alpha(c1, 0.35), wd * 0.8))
            p.drawPolyline(QPolygonF(pts))
    elif base == "orbitals":                                   # Special: three lights circling at different speeds, with tails
        p.setPen(QPen(alpha(c2, 0.35), wd * 0.35))
        p.drawEllipse(ring)
        p.setPen(Qt.PenStyle.NoPen)
        for k, (sp, col) in enumerate(((1.6, c1), (-1.1, c2), (0.7, QColor("#FFFFFF")))):
            for j in range(16):
                a = now * sp + k * 2.1 - j * 0.07 * (1 if sp > 0 else -1)
                p.setBrush(alpha(col, (1 - j / 16) * 0.9))
                rr = wd * 0.6 * (1 - j / 22)
                p.drawEllipse(at(a, (k - 1) * wd * 0.9), rr, rr)
    elif base == "galaxy":                                     # Epic: a spiral of stardust turning round the picture
        p.setPen(Qt.PenStyle.NoPen)
        for arm in range(3):
            for j in range(40):
                f = j / 40
                a = arm * math.tau / 3 + f * 2.4 + now * 0.5
                rr = (f - 0.5) * wd * 3.2
                col = mix(c1, c2, f)
                p.setBrush(alpha(col, 0.15 + 0.7 * (1 - abs(f - 0.5) * 2)))
                s = wd * (0.18 + 0.28 * _rand(j + arm * 40, 3))
                p.drawEllipse(at(a, rr), s, s)
        p.setPen(QPen(alpha(c1, 0.5), wd * 0.4))
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawEllipse(ring)
    elif base == "diamond":                                    # Epic: a ring of cut gems that flash in turn
        p.setPen(QPen(alpha(c2, 0.9), wd * 0.5))
        p.drawEllipse(ring)
        n = 10
        for k in range(n):
            a = k * math.tau / n
            flash = max(0.0, math.sin(now * 2.4 - k * 0.6))
            p.save()
            p.translate(at(a))
            p.rotate(math.degrees(a) + 90)
            gem = QPolygonF([QPointF(0, -wd * 0.95), QPointF(wd * 0.75, -wd * 0.1), QPointF(0, wd * 0.8), QPointF(-wd * 0.75, -wd * 0.1)])
            p.setPen(QPen(alpha("#FFFFFF", 0.8), max(1.0, wd * 0.12)))
            p.setBrush(mix(c1, QColor("#FFFFFF"), flash * 0.8))
            p.drawPolygon(gem)
            p.restore()


