import math
import random
import time

from PyQt6.QtCore import QPointF, QRectF, QTimer, Qt, pyqtSignal
from PyQt6.QtGui import QColor, QFont, QLinearGradient, QPainter, QPainterPath, QPen, QPolygonF, QRadialGradient
from PyQt6.QtWidgets import QGridLayout, QSizePolicy, QWidget


RNG = random.SystemRandom()
BETS = [10, 25, 50, 100, 250, 500, 1000]
WIN, LOSE = "#35E0A1", "#FF5C6C"
TABLE_H = 260


def ease_out(t: float, power: int = 3) -> float:
    t = max(0.0, min(1.0, t))
    return 1.0 - (1.0 - t) ** power


class Game(QWidget):
    """Base of every game: a painted table that animates only while something moves."""

    def __init__(self, page) -> None:
        super().__init__()
        self.page, self.ctx, self.wallet = page, page.ctx, page.ctx.wallet
        self.setFixedSize(page.W, S(TABLE_H))
        self.stake = 0
        self.busy = False                        # a round is running: the bet is locked
        self.waiting = False                     # a request to the server is on its way
        self.econ = page.ctx.econ
        self._flash = ("", "", 0.0)
        self._frames = QTimer(self)
        self._frames.setTimerType(Qt.TimerType.PreciseTimer)
        self._frames.setInterval(16)
        self._frames.timeout.connect(self.update)
        self._until = 0.0
        self._clk = None                         # 6.2: the big countdown (deadline, total seconds)
        self._clk_timer = None

    # -- 6.2: a big countdown. The server keeps its own clock too: this one only shows it (and sends "time is up")
    def clock_start(self, secs: float, on_end) -> None:
        self.clock_stop()
        secs = float(secs)
        self._clk = (time.monotonic() + secs, secs)
        t = QTimer(self)
        t.setSingleShot(True)
        t.timeout.connect(lambda: self._clock_end(t, on_end))
        t.start(int(max(0.0, secs) * 1000) + 40)
        self._clk_timer = t
        self.animate(secs + 1.0)

    def clock_stop(self) -> None:
        self._clk = None
        t, self._clk_timer = self._clk_timer, None
        if t is not None:
            try:
                t.stop()
                t.deleteLater()
            except RuntimeError:
                pass

    def _clock_end(self, t, on_end) -> None:
        if self._clk_timer is not t:
            return
        self._clk, self._clk_timer = None, None
        t.deleteLater()
        on_end()

    def clock_left(self):
        return None if self._clk is None else max(0.0, self._clk[0] - time.monotonic())

    def paint_clock(self, p: QPainter, c: QPointF, rad: float) -> None:
        left = self.clock_left()
        if left is not None:
            paint_ring_clock(p, c, rad, left, self._clk[1])

    # -- helpers
    def animate(self, seconds: float) -> None:
        self._until = max(self._until, time.monotonic() + seconds)
        if not self._frames.isActive():
            self._frames.start()

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        r = QRectF(self.rect()).adjusted(0.5, 0.5, -0.5, -0.5)
        clip = QPainterPath()
        clip.addRoundedRect(r, S(12), S(12))
        g = QLinearGradient(r.topLeft(), r.bottomLeft())
        g.setColorAt(0, QColor("#0C1113"))
        g.setColorAt(1, QColor("#080B0C"))
        p.fillPath(clip, g)
        p.save()
        p.setClipPath(clip)
        self.draw(p, r, time.monotonic())
        p.restore()
        p.setPen(QPen(alpha("#FFFFFF", 0.08), 1))
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawRoundedRect(r, S(12), S(12))
        self._draw_flash(p, r)
        if time.monotonic() > self._until and not self.always_moving():
            self._frames.stop()

    def always_moving(self) -> bool:
        return False

    def mousePressEvent(self, e) -> None:
        e.accept()                               # pressing the table never moves the menu

    def options(self):
        """(labels, index) of the choice row above the bet, or None."""
        return None

    def set_option(self, i: int) -> None: ...

    def showEvent(self, _e) -> None:
        if self.always_moving():
            self._frames.start()

    def hideEvent(self, _e) -> None:
        self._frames.stop()

    def take(self) -> bool:
        """Take the bet for a new round (on screen; the server takes it for real with the request)."""
        bet = self.page.bet()
        if not self.econ.ready:
            self.ctx.toast(tr("No internet connection"), "warn")
            return False
        if bet <= 0 or bet > self.econ.coins:
            self.ctx.toast(tr("Not enough coins"), "warn")
            return False
        if bet > BIG_BET and getattr(self.ctx, "big_bet_ok", 0) != bet and hasattr(self.ctx, "confirm"):
            # 6.3: a big stake is asked once (again whenever the amount changes)
            again = getattr(self, sys._getframe(1).f_code.co_name, None)
            pct = bet * 100 / max(1, self.econ.coins)
            text = tr("Bet {n} coins on this round? That is {p}% of your coins.", n=coins_text(bet), p=f"{pct:.0f}")
            if pct >= 25:
                text += "\n" + tr("Careful: you could lose a big part of your coins.")

            def yes() -> None:
                self.ctx.big_bet_ok = bet
                if callable(again) and not self.busy and not self.waiting:
                    again()
            self.ctx.confirm(text, yes, tr("Bet it"), tr("Cancel"))
            return False
        self.stake = bet
        self.busy = True
        self._srv_coins = None
        self.econ.hold_round(True)                 # 4.0: no balance from a poll lands in the middle of the round
        self.econ.adjust(-bet)
        self.page.sync()
        return True

    def ask(self, fn: str, args: dict, on_ok, once: bool = False, refund: int = 0) -> None:
        """Send a move to the server. On an error the coins taken on screen are put back."""
        self.waiting = True
        self.page.sync()

        def back(ok: bool, data) -> None:
            try:
                self.waiting = False
                if ok:
                    if isinstance(data, dict) and data.get("coins") is not None:
                        self._srv_coins = int(data["coins"])      # the real balance after this move
                    on_ok(data)
                else:
                    if refund:
                        self.econ.adjust(refund)
                    self.failed(str(data))
                self.page.sync()
            except RuntimeError:                      # the page was closed meanwhile
                pass
        self.econ.call(fn, args, back, once=once, hold=True)

    def failed(self, message: str) -> None:
        self.busy = False
        self.econ.hold_round(False)
        self.ctx.toast(tr(message), "warn")

    def finish(self, payout: int) -> None:
        """End of the round: pay what was won (0 = lost) and show it. 4.0: the balance shown is then set to the
        server's own number, so quick rounds one after another can never drift from the real balance."""
        payout = int(payout)
        srv = getattr(self, "_srv_coins", None)
        self.econ.hold_round(False)
        if srv is not None and not self.econ.rounds_held():
            self.econ.coins = max(0, srv)
            self.econ.changed.emit()
        elif payout > 0:
            self.econ.adjust(payout)
        gain = payout - self.stake
        if gain > 0:
            self.flash("+" + coins_text(gain), WIN)
            sfx.tune("bigwin" if self.stake and payout >= self.stake * 5 else "win")
        elif gain < 0:
            self.flash("−" + coins_text(-gain), LOSE)
            sfx.play("lose")
        else:
            self.flash("0", TEXT_DIM)
        self.busy = False
        self.page.sync()

    def flash(self, text: str, colour: str) -> None:
        self._flash = (text, colour, time.monotonic())
        self.animate(1.8)

    def _draw_flash(self, p: QPainter, r: QRectF) -> None:
        text, colour, born = self._flash
        age = time.monotonic() - born
        if not text or age > 1.7:
            return
        a = min(1.0, age / 0.15) * (1.0 - max(0.0, (age - 1.2) / 0.5))
        rise = S(10) * ease_out(age / 0.5)
        p.setFont(font(22, QFont.Weight.ExtraBold))
        w = p.fontMetrics().horizontalAdvance(text) + S(28)
        box = QRectF(r.center().x() - w / 2, r.center().y() - S(20) - rise, w, S(40))
        p.setOpacity(a)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor(6, 8, 9, 225))
        p.drawRoundedRect(box, S(12), S(12))
        p.setPen(QColor(colour))
        p.drawText(box, int(Qt.AlignmentFlag.AlignCenter), text)
        p.setOpacity(1.0)

    # -- for the page
    def buttons(self) -> list:
        """[(text, kind, callback, enabled)] for the row under the table."""
        return []

    def draw(self, p: QPainter, r: QRectF, now: float) -> None: ...


# --------------------------------------------------------------------------- #
# Blackjack
