    def _bot_market(self, lay, b: dict) -> None:
        """5.15: the bot's items, its market listings, and adding items to it."""
        name = b["username"]
        lay.addWidget(heading(en("Items and market")))
        got = self.fetch("rb_admin_bot_market", {"name": name, "action": "items"})
        items = (got or {}).get("items") if isinstance(got, dict) else None
        line = hbox(spacing=6)
        for text, n in ((en("Sell 3"), 3), (en("Sell 10"), 10)):
            bt = Button(text, "primary" if n == 3 else "ghost", 30, icon="coin" if n == 3 else "")
            bt.clicked.connect(lambda _=False, k=n: self.do("rb_admin_bot_market", {"name": name, "action": "auto", "n": k},
                                                           en("Listed near their worth")))
            line.addWidget(bt, 1)
        off = Button(en("Take all off"), "ghost", 30)
        off.clicked.connect(lambda: self.do("rb_admin_bot_market", {"name": name, "action": "cancel"}, en("Taken off the market")))
        line.addWidget(off, 1)
        lay.addLayout(line)
        if items is None:
            lay.addWidget(Label(en("Loading…"), 11, TEXT_DIM))
        elif not items:
            lay.addWidget(Label(en("No items yet: add some below."), 11, TEXT_FAINT))
        else:
            listed = sum(1 for it in items if it.get("listing"))
            lay.addWidget(Label(en("{n} items · {m} on the market · click one to sell it or take it off", n=len(items), m=listed),
                                10.5, TEXT_DIM, wrap_w=self.W))
            shown = items[:60]
            lay.addWidget(Table([(en_name(it["item"]),
                                  (en("on sale {p}", p=coins_text(int(it.get("price") or 0))) if it.get("listing") else
                                   (en("locked") if it.get("locked") else (en("worth {p}", p=coins_text(int(it.get("est") or 0)))
                                                                           if it.get("tradeable") else en("not tradeable")))),
                                  "", "#3DDC84" if it.get("listing") else TEXT_DIM) for it in shown], self.W,
                                lambda i: self._bot_sell(name, shown[i])))
        st = self.state("botgive")
        lay.addWidget(heading(en("Add items to {name}", name=name)))
        item_picker(self, lay, st)
        n = self._slide(lay, st, "count", "How many", 1, 100, 1)
        thing = en_name(st["item"]) if st.get("item") else ""
        add = Button(en("Add {n} × {what}", n=n, what=thing) if thing else en("Pick an item"), "primary" if thing else "ghost",
                     36, icon="gift")
        add.setEnabled(bool(thing))
        add.clicked.connect(lambda: self.do("rb_admin_give", {"name": name, "what": st.get("item"), "how_many": n},
                                            en("Added to {name}", name=name)))
        lay.addWidget(add)

    def _bot_sell(self, name: str, it: dict) -> None:
        if it.get("listing"):
            return self.ctx.window.confirm(en("Take {what} off the market?", what=en_name(it["item"])),
                                           lambda: self.do("rb_admin_bot_market", {"name": name, "action": "cancel",
                                                                                   "item_id": it["id"]}, en("Taken off")),
                                           yes=en("Take off"))
        if it.get("locked") or not it.get("tradeable"):
            return self.ctx.toast(en("This item cannot be sold now"), "warn")
        est = int(it.get("est") or 0)

        def go(v: dict, dlg) -> None:
            price = _int(v.get("price", ""), None)
            if price is None or price < 1:
                return dlg.say(en("A price in coins"))
            dlg.close()
            self.do("rb_admin_bot_market", {"name": name, "action": "list", "item_id": it["id"], "price": price},
                    en("On the market"))
        FormDialog(self.ctx, en("{name} sells {what}", name=name, what=en_name(it["item"])),
                   [("price", en("Price (worth about {p})", p=coins_text(est)), str(max(1, round(est * 1.05))))], en("Sell"), go)

    @staticmethod
    def _bot_random() -> dict:
        """Believable random numbers for a bot."""
        import random
        hours = int(random.triangular(5, 600, 60))
        start = random.choice([8, 12, 14, 16, 17, 18, 19, 20])
        return {"hours": hours, "days": max(1, int(hours / random.uniform(1.5, 5))), "coins": int(random.triangular(200, 80000, 6000)),
                "keys": random.randint(0, 5), "streak": random.choice([0, 1, 2, 3, 4, 5, 7, 9, 12, 15, 21, 30]),
                "badges": random.randint(3, 30), "active": random.randint(35, 90), "from": start,
                "to": min(23, start + random.randint(3, 7)),
                "level": max(1, min(100, int(random.triangular(2, 70, 14) * min(1.0, 0.35 + hours / 300))))}

    @staticmethod
    def _bot_random_stats(hours: int) -> dict:
        """Believable numbers for every game, bigger for a bot that played longer."""
        import random
        h = max(5, hours)
        f = lambda lo, hi: int(random.uniform(lo, hi) * h)              # noqa: E731
        won = f(40, 260)
        return {"friends": random.randint(1, 14), "cases": f(0.4, 2.2), "trades": f(0.02, 0.25), "rounds": f(1, 6),
                "won": won, "best": int(won * random.uniform(0.05, 0.25)), "spins": f(0.1, 0.5), "duels": f(0.02, 0.2),
                "flip": f(0.03, 0.3), "jackpot": f(0.0, 0.04), "golf": f(0.02, 0.2),
                "wave": int(random.triangular(120, 1600, 420)), "blocks": int(random.triangular(300, 9000, 1800)),
                "mini": f(0.2, 1.2), "park": f(0.1, 0.8), "memory": f(0.1, 0.6), "sweeper": f(0.02, 0.3),
                "tower": random.randint(2, 11)}

    def _bot_stats(self, b: dict) -> None:
        extra = dict((b.get("cfg") or {}).get("stats") or {})
        fields = [(k, en(t), str(int(extra.get(k) or 0))) for k, t in self.BOT_STATS]

        def go(v: dict, dlg) -> None:
            out = {}
            for k, t in self.BOT_STATS:
                n = _int(v.get(k, ""), None)
                if n is None or not 0 <= n <= 100000000:
                    return dlg.say(en("{what}: a number from {a} to {b}", what=en(t), a=0, b=100000000))
                out[k] = n
            dlg.close()
            self.do("rb_admin_bot_set", {"name": b["username"], "cfg": {"stats": out}}, en("Saved"))
        FormDialog(self.ctx, en("{name}: game stats (added on top of what it really did)", name=b["username"]), fields,
                   en("Save"), go)

    def _bot_picture(self, name: str) -> None:
        import base64
        from PyQt6.QtCore import QBuffer, QByteArray, QIODevice
        from PyQt6.QtGui import QImage
        path = self.ctx.pick_file(en("Choose a picture"), "Pictures (*.png *.jpg *.jpeg *.webp *.bmp)")
        if not path:
            return
        img = QImage(path)
        if img.isNull():
            return self.ctx.toast(en("This picture cannot be used"), "warn")
        side = min(img.width(), img.height())
        img = img.copy((img.width() - side) // 2, (img.height() - side) // 2, side, side).scaled(
            96, 96, Qt.AspectRatioMode.IgnoreAspectRatio, Qt.TransformationMode.SmoothTransformation)
        buf = QByteArray()
        dev = QBuffer(buf)
        dev.open(QIODevice.OpenModeFlag.WriteOnly)
        img.save(dev, "JPG", 82)
        self.do("rb_admin_bot_avatar", {"name": name, "picture": base64.b64encode(bytes(buf)).decode()}, en("Picture saved"))

    def _bot_new(self) -> None:
        fields = [("name", en("Username (3 to 10 letters or numbers)"), ""), ("pw", en("Password (8 characters at least)"), "")]
        rand = self._bot_random()                      # random, believable numbers to start from
        fields += [(k, en(t), str(rand.get(k, d))) for k, t, d in self.BOT_FIELDS]

        def go(v: dict, dlg) -> None:
            import re
            name, pw = v["name"], v["pw"]
            if not re.fullmatch(r"[A-Za-z0-9]{3,10}", name):
                return dlg.say(en("3 to 10 letters or numbers"))
            if len(pw) < 8:
                return dlg.say(en("8 characters at least"))
            cfg = self._bot_cfg(v, dlg)
            if not cfg:
                return
            dlg.say(en("Creating…"))

            def ticket(ok: bool, tk) -> None:
                if not ok:
                    return dlg.say(en(str(tk)))

                def made(ok2: bool, d) -> None:
                    if not ok2:
                        return dlg.say(en(str(d)) if "taken" not in str(d).lower() else en("This username is taken"))

                    def set_done(ok3: bool, d3) -> None:
                        if not ok3:
                            return dlg.say(en(str(d3)))
                        dlg.close()
                        sfx.play("on")
                        self.ctx.toast(en("Bot {name} created", name=name))
                        self.ctx.admin_bot = name
                        self.ctx.admin_cache = {}
                        QTimer.singleShot(300, lambda: self.ctx.reload_page("admin"))
                    self.ctx.econ.call("rb_admin_bot_set", {"name": name, "cfg": cfg}, set_done)
                self.ctx.online.make_bot(name, pw, str(tk), made)
            self.ctx.econ.call("rb_admin_bot_ticket", {}, ticket)
        FormDialog(self.ctx, en("Create a bot"), fields, en("Create"), go)

    def _bot_edit(self, b: dict) -> None:
        cfg = dict(b.get("cfg") or {})
        now = {"hours": int(b.get("minutes") or 0) // 60, "coins": int(b.get("coins") or 0), "keys": int(b.get("keys") or 0),
               "streak": int(b.get("streak") or 0), "badges": int(b.get("badges") or 0), "days": 30,
               "level": int(b.get("level") or 0)}
        try:
            from datetime import datetime, timezone
            since = datetime.fromisoformat(str(b.get("since")).replace("Z", "+00:00"))
            now["days"] = max(0, (datetime.now(timezone.utc) - since).days)
        except (TypeError, ValueError):
            pass
        fields = [(k, en(t), now.get(k, cfg.get(k, d))) for k, t, d in self.BOT_FIELDS]

        def go(v: dict, dlg) -> None:
            new = self._bot_cfg(v, dlg)
            if new:
                dlg.close()
                self.do("rb_admin_bot_set", {"name": b["username"], "cfg": new}, en("Saved"))
        FormDialog(self.ctx, en("Change {name}", name=b["username"]), fields, en("Save"), go)

