import math
import random
import time

from PyQt6.QtCore import QPointF, QRectF, Qt, QTimer
from PyQt6.QtGui import QColor, QFont, QLinearGradient, QPainter, QPainterPath, QPen, QPolygonF, QRadialGradient
from PyQt6.QtWidgets import QWidget


PAWN_GOLD = QColor("#E8C26A")


def pawn_chance(ratio: float, anger: float) -> float:
    """The same as the server's rb_pawn_chance."""
    if ratio <= 1:
        return 1.0
    return max(0.0, max(0.0, 1 - (ratio - 1) / 0.75) ** 1.15 * (1 - min(100.0, anger) / 300.0))     # 4.6: kinder


def pawn_rage(ratio: float) -> float:
    """How much a no adds to his anger (the server's rb_pawn_rage)."""
    return 15 + 50 * min(1.0, max(0.0, (ratio - 1) / 0.5))


def pawn_ease(t: float) -> float:
    t = max(0.0, min(1.0, t))
    return t * t * (3 - 2 * t)


def pawn_ease_out(t: float) -> float:
    t = max(0.0, min(1.0, t))
    return 1 - (1 - t) ** 3


def pawn_ease_in(t: float) -> float:
    t = max(0.0, min(1.0, t))
    return t * t * t


BIG_BET = 10000                      # 6.3: bets above this are confirmed and shown in gold / red


def pawn_clock(s: int) -> str:
    s = max(0, int(s))
    return f"{s // 60}:{s % 60:02d}"


# ---------------------------------------------------------------- the overlay
class PawnShop(QWidget):
    """Covers the whole menu while you are in the shop. Phases (seconds): fade 0.3 · close 0.45 · hold · open 0.6 ·
    shop · leave (close 0.4, open 0.5) · crack 1.5 · slam 0.25 + plaque 1.6 · banned (close 0.45, plaque 2.6, open 0.5)."""

    def __init__(self, ctx, ids: list, item: str, what: str) -> None:
        win = ctx.window
        super().__init__(win)
        self.ctx, self.win = ctx, win
        self.ids, self.item, self.what = list(ids), item, what
        self.base, self.anger, self.ban_left, self.max_ratio = 0, 0.0, 0, 1.5
        self.shown_anger = 0.0                      # the bar moves to the new level smoothly
        self.ask_mode = False
        self.ask = 0
        self.deal = 0                               # 4.7: the price he agreed to (not sold yet)
        self.market = 0                             # 4.7: what it goes for on the market, to compare
        self.busy = False
        self.line = tr("Let's see what you've got.")
        self.line_at = time.monotonic()
        self.phase, self.t0 = "fade", time.monotonic()
        self.loaded = False
        self.after = None                           # what happens when the doors have opened on the menu again
        self.shards: list = []
        self.snap = None
        self.sold_at = 0.0
        self.ban_end = 0.0
        self.props_left, self.props_end = 10, 0.0     # 6.2.7: exchanges you can still propose this hour
        self.setMouseTracking(True)
        self._build_controls()
        self._place()
        self.show()
        self.raise_()
        self.setFocus()
        self._timer = QTimer(self)
        self._timer.setTimerType(Qt.TimerType.PreciseTimer)
        self._timer.setInterval(16)
        self._timer.timeout.connect(self._frame)
        self._timer.start()
        ctx.econ.call("rb_pawn_enter", {"ids": self.ids}, self._entered)

    # -- geometry
    def _place(self) -> None:
        try:
            r = self.win._card_rect() if hasattr(self.win, "_card_rect") else QRectF(self.win.rect())
        except RuntimeError:
            return
        g = r.toRect()
        if self.geometry() != g:
            self.setGeometry(g)
            self._layout_controls()

    def _panel(self) -> QRectF:
        """The middle column everything in the shop lines up on."""
        w = min(float(self.width()) - S(40), S(560))
        return QRectF((self.width() - w) / 2, 0, w, self.height())

    def _counter_y(self) -> float:
        return self.height() * 0.50

    # -- controls (real buttons, shown only while you are in the shop)
    def _build_controls(self) -> None:
        self.box = QWidget(self)
        lay = vbox(self.box, 8)
        self.row_offer = QWidget()
        r1 = hbox(self.row_offer, 8)
        self.take = Button("", "primary", 40, icon="check")
        self.take.clicked.connect(lambda: self._sell(None))
        self.more = Button(tr("Ask for more"), "ghost", 40)
        self.more.clicked.connect(lambda: self._set_ask(True))
        r1.addWidget(self.take, 3)
        r1.addWidget(self.more, 2)
        self.swap_btn = Button(tr("Propose exchange"), "ghost", 40)     # 5.12: he offers one of his items for yours
        self.swap_btn.clicked.connect(lambda: self._trade("offer"))
        # 6.0: only for one tradeable item he can swap (worth 300 at least): no button that answers with an error
        info = self.ctx.econ.info(self.item) if len(self.ids) == 1 else None
        self.swap_btn.setVisible(len(self.ids) == 1 and bool(info and info.get("tradeable"))
                                 and self.ctx.econ.worth(self.item) >= 300)
        r1.addWidget(self.swap_btn, 2)
        lay.addWidget(self.row_offer)
        self.trade = None
        self.trade_confirm = False
        self.row_trade = QWidget()
        rt = hbox(self.row_trade, 8)
        self.trade_yes = Button(tr("Accept the exchange"), "primary", 40, icon="check")
        self.trade_yes.clicked.connect(lambda: self._trade("accept"))
        self.trade_more = Button(tr("Ask for more"), "ghost", 40)
        self.trade_more.clicked.connect(self._trade_more)
        self.trade_no = Button(tr("Refuse"), "ghost", 40)
        self.trade_no.clicked.connect(lambda: self._trade("refuse"))
        rt.addWidget(self.trade_yes, 3)
        rt.addWidget(self.trade_more, 3)
        rt.addWidget(self.trade_no, 2)
        lay.addWidget(self.row_trade)
        self.row_trade.hide()
        self.row_ask = QWidget()
        r2 = vbox(self.row_ask, 8)
        self.slider = Slider(0, 1, 0, 1)
        self.slider.changed.connect(self._slid)
        r2.addWidget(self.slider)
        btns = QWidget()
        r3 = hbox(btns, 8)
        self.offer = Button("", "primary", 40)
        self.offer.clicked.connect(lambda: self._sell(self.ask))
        self.back = Button(tr("Back"), "ghost", 40)
        self.back.clicked.connect(lambda: self._set_ask(False))
        r3.addWidget(self.offer, 3)
        r3.addWidget(self.back, 2)
        r2.addWidget(btns)
        lay.addWidget(self.row_ask)
        self.row_deal = QWidget()                   # 4.7: he said yes to your price: nothing is sold until you press Sell
        r4 = hbox(self.row_deal, 8)
        self.sell_deal = Button("", "primary", 40, icon="check")
        self.sell_deal.clicked.connect(lambda: self._sell(self.deal))
        self.no_deal = Button(tr("Not now"), "ghost", 40)
        self.no_deal.clicked.connect(self._drop_deal)
        r4.addWidget(self.sell_deal, 3)
        r4.addWidget(self.no_deal, 2)
        lay.addWidget(self.row_deal)
        self.row_deal.hide()
        self.leave_btn = Button(tr("Leave the shop"), "ghost", 32, icon="back", parent=self)
        self.leave_btn.clicked.connect(self.leave)
        self.box.hide()
        self.leave_btn.hide()
        self.row_ask.hide()

    def _layout_controls(self) -> None:
        pn = self._panel()
        top = self._counter_y() + S(150)
        h = S(40) + S(8) + S(26) + S(8) + S(40)
        self.box.setGeometry(int(pn.left()), int(top), int(pn.width()), int(h))
        self.leave_btn.adjustSize()
        self.leave_btn.setFixedWidth(max(S(150), self.leave_btn.sizeHint().width() + S(20)))
        self.leave_btn.move(int(S(16)), int(S(16)))

    def _controls(self, on: bool) -> None:
        self.box.setVisible(on)
        self.leave_btn.setVisible(on)
        if on:
            self._refresh_texts()

    def _refresh_texts(self) -> None:
        self.take.set_text(tr("Sell for {n}", n=coins_text(self.base)))
        trading = self.trade is not None
        self.row_trade.setVisible(trading)
        if trading:
            more = self.trade.get("more")
            self.trade_more.setEnabled(bool(more) and not self.busy)
            if not more:
                self.trade_more.set_text(tr("He won't go higher"))
            elif self.trade_confirm:
                self.trade_more.set_text(tr("Sure? {c}% yes", c=int(round(float(more.get("chance") or 0) * 100))))
                self.trade_more.set_kind("danger")
            else:
                self.trade_more.set_text(tr("Ask for more"))
                self.trade_more.set_kind("ghost")
            for b in (self.trade_yes, self.trade_no):
                b.setEnabled(not self.busy)
            self.row_offer.setVisible(False)
            self.row_ask.setVisible(False)
            self.row_deal.setVisible(False)
            self.leave_btn.setEnabled(not self.busy)
            return
        if self.props_left > 0:
            self.swap_btn.set_text(tr("Exchange · {n}/10 left", n=self.props_left))
        else:
            self.swap_btn.set_text(tr("No exchanges left"))
        self.swap_btn.setEnabled(not self.busy and self.props_left > 0)
        self.row_offer.setVisible(not self.ask_mode and not self.deal)
        self.row_ask.setVisible(self.ask_mode and not self.deal)
        self.row_deal.setVisible(bool(self.deal))
        self.sell_deal.set_text(tr("Sell for {n}", n=coins_text(self.deal)))
        at_his = self.ask <= self.base
        self.offer.set_text(tr("Sell for {n}", n=coins_text(self.ask)) if at_his else tr("Ask {n}", n=coins_text(self.ask)))
        for b in (self.take, self.more, self.offer, self.back, self.leave_btn, self.sell_deal, self.no_deal):
            b.setEnabled(not self.busy)

    def _drop_deal(self) -> None:
        if self.busy:
            return
        sfx.play("pick")
        self.deal = 0
        self.line, self.line_at = tr("Suit yourself."), time.monotonic()
        self._refresh_texts()
        self.update()

    def _set_ask(self, on: bool) -> None:
        if self.busy:
            return
        sfx.play("pick")
        self.ask_mode = on
        if on:
            lo, hi = self._ask_range()
            step = max(1, (hi - lo) // 100)
            self.slider.deleteLater()
            self.slider = Slider(lo, hi, lo, step)            # 4.7: starts on his price (100%), far left
            self.slider.changed.connect(self._slid)
            self.row_ask.layout().insertWidget(0, self.slider)
            self.ask = int(self.slider.value())
        self._refresh_texts()
        self.update()

    def _ask_range(self):
        lo = self.base
        hi = max(lo, int(math.floor(self.base * self.max_ratio)))
        return lo, hi

    def _slid(self, v: float) -> None:
        self.ask = int(v)
        self._refresh_texts()
        self.update()

    def _props(self, data) -> None:
        """6.2.7: how many exchange proposals are left this hour (the server counts), and when one comes back."""
        if not isinstance(data, dict) or data.get("props_left") is None:
            return
        self.props_left = int(data.get("props_left") or 0)   # the server says how many (10 an hour)
        reset = int(data.get("props_reset") or 0)
        self.props_end = time.time() + reset if self.props_left <= 0 and reset > 0 else 0.0
        try:
            self._refresh_texts()
        except RuntimeError:
            pass

    def _props_reload(self) -> None:
        self.ctx.econ.call("rb_pawn_props_left", {}, lambda ok, d: self._props(d) if ok else None)

    # -- the server
    def _entered(self, ok: bool, data) -> None:
        if not ok or not isinstance(data, dict):
            self.ctx.toast(tr(str(data)) if not ok else tr("Something went wrong: try again"), "warn")
            return self._go("leave_close")
        self.base = int(data.get("base") or 0)
        self.anger = self.shown_anger = float(data.get("anger") or 0)
        self.ban_left = int(data.get("ban_left") or 0)
        self.max_ratio = float(data.get("max_ratio") or 1.5)
        self._props(data)
        self.loaded = True
        if self.ban_left > 0:
            self.ban_end = time.monotonic() + self.ban_left
            self.ctx.pawn_ban_until = time.time() + self.ban_left
        elif int(data.get("n") or 0) == 0:
            self.ctx.toast(tr("This cannot be sold"), "warn")
            self.ban_left = -1                                    # nothing to sell: just open back on the menu
        self.line = tr("I'll give you {n} coins for {what}.", n=coins_text(self.base), what=self.what)
        self.line_at = time.monotonic()

        def priced(ok2: bool, d2) -> None:                    # 4.7: the market price, to compare
            if ok2 and isinstance(d2, dict):
                self.market = int(d2.get("estimate") or 0) * max(1, len(self.ids))
                try:
                    self.update()
                except RuntimeError:
                    pass
        if self.item and self.ban_left == 0:
            self.ctx.econ.call("rb_market_price", {"what": self.item}, priced)

    def _sell(self, ask) -> None:
        """Sell now: at his price (ask None or not above it), or at a price he already agreed to."""
        if ask is not None and ask > self.base and ask != self.deal:
            return self._ask(ask)
        if self.busy or self.phase != "shop":
            return
        self.busy = True
        self._refresh_texts()
        sfx.play("pick")

        def done(ok: bool, data) -> None:
            self.busy = False
            try:
                if not ok or not isinstance(data, dict):
                    self.ctx.toast(tr(str(data)), "warn")
                    return self._refresh_texts()
                res = data.get("result")
                self.anger = float(data.get("anger") or 0)
                if res == "yes":
                    sfx.play("on")
                    self.line, self.line_at = tr("Deal. Pleasure doing business."), time.monotonic()
                    self.sold_at = time.monotonic()
                    self.paid = int(data.get("paid") or 0)
                    ec = self.ctx.econ
                    gone = set(self.ids)
                    ec.items = [i for i in ec.items if i["id"] not in gone]
                    ec._index()
                    ec.refresh()
                    self.after = lambda: (self.ctx.toast(tr("Sold for {n} coins", n=coins_text(self.paid))),
                                          setattr(self.ctx, "inv_pick", ""), self.ctx.reload_page())
                    self._controls(False)
                    QTimer.singleShot(1500, lambda: self._go("leave_close"))
                elif res == "kicked":
                    self.anger = 100.0
                    self.line, self.line_at = tr("That's it. GET OUT!"), time.monotonic()
                    self.after = lambda: self.ctx.toast(tr("Thrown out of the pawn shop for 5 minutes"), "warn")
                    self._controls(False)
                    sfx.play("off")
                    QTimer.singleShot(500, self._crack)
                elif res == "banned":
                    self.ban_left = int(data.get("ban_left") or 0)
                    self.ban_end = time.monotonic() + self.ban_left
                    self.ctx.pawn_ban_until = time.time() + self.ban_left
                    self._controls(False)
                    self._go("ban_close")
                else:
                    sfx.play("off")
                    self.line = (tr("No way.") if self.anger < 45 else tr("You're pushing it.") if self.anger < 75
                                 else tr("One more and you're out."))
                    self.line_at = time.monotonic()
                    lo, hi = self._ask_range()
                    self.slider.set_value(max(lo, min(self.ask, hi)))
                    self._refresh_texts()
            except RuntimeError:
                pass
        self.ctx.econ.call("rb_pawn_sell", {"ids": self.ids, "ask": ask if ask and ask > self.base else None}, done, once=True)

    def _trade_more(self) -> None:
        """Asking for more needs a second click: the first shows the chance and the anger he would gain."""
        if self.busy or not self.trade or not self.trade.get("more"):
            return
        if not self.trade_confirm:
            self.trade_confirm = True
            sfx.play("pick")
            m = self.trade["more"]
            self.line = tr("Something worth {p}% of yours? {c}% chance I say yes. If I say no: +{r} anger.",
                           p=int(m.get("pct") or 0), c=int(round(float(m.get("chance") or 0) * 100)), r=int(round(float(m.get("rage") or 0))))
            self.line_at = time.monotonic()
            self._refresh_texts()
            return self.update()
        self.trade_confirm = False
        self._trade("more")

    def _trade(self, action: str) -> None:
        """5.12: swap your item for one of his (offer, more, accept, refuse)."""
        if self.busy or self.phase != "shop":
            return
        self.busy = True
        self.trade_confirm = False
        self._refresh_texts()
        sfx.play("pick")

        def done(ok: bool, data) -> None:
            self.busy = False
            try:
                if action == "offer" or not ok:
                    self._props_reload()
                if not ok or not isinstance(data, dict):
                    self.ctx.toast(tr(str(data)), "warn")
                    return self._refresh_texts()
                res = data.get("result")
                self.anger = float(data.get("anger") or self.anger)
                if res in ("offer", "no"):
                    first = self.trade is None
                    self.trade = data
                    if res == "no":
                        sfx.play("off")
                        self.line = (tr("No. Take it or leave it.") if self.anger < 45 else tr("You're pushing it.")
                                     if self.anger < 75 else tr("One more and you're out."))
                    else:
                        sfx.play("on")
                        self.line = (tr("I'll swap it for this {what}.", what=item_name(data.get("item", ""))) if first
                                     else tr("Fine. This {what} then.", what=item_name(data.get("item", ""))))
                    self.line_at = time.monotonic()
                elif res == "refused":
                    self.trade = None
                    self.line, self.line_at = tr("Suit yourself."), time.monotonic()
                elif res == "swapped":
                    sfx.play("on")
                    ec = self.ctx.econ
                    ec.items = [i for i in ec.items if i["id"] not in set(self.ids)]
                    ec._index()
                    ec.refresh()
                    got = data.get("item", "")
                    self.item, self.what, self.trade = got, item_name(got), None
                    self.line, self.line_at = tr("Deal. Enjoy your {what}.", what=item_name(got)), time.monotonic()
                    self.after = lambda: (self.ctx.toast(tr("You got {what}", what=item_name(got))),
                                          setattr(self.ctx, "inv_pick", ""), self.ctx.reload_page())
                    self._controls(False)
                    QTimer.singleShot(1800, lambda: self._go("leave_close"))
                elif res == "kicked":
                    self.anger, self.trade = 100.0, None
                    self.line, self.line_at = tr("That's it. GET OUT!"), time.monotonic()
                    self.after = lambda: self.ctx.toast(tr("Thrown out of the pawn shop for 5 minutes"), "warn")
                    self._controls(False)
                    sfx.play("off")
                    QTimer.singleShot(500, self._crack)
                    return
                elif res == "banned":
                    self.ban_left = int(data.get("ban_left") or 0)
                    self.ban_end = time.monotonic() + self.ban_left
                    self._controls(False)
                    return self._go("ban_close")
                self._refresh_texts()
                self.update()
            except RuntimeError:
                pass
        self.ctx.econ.call("rb_pawn_trade", {"ids": self.ids, "action": action}, done, once=True)

    def _ask(self, ask: int) -> None:
        """4.7: only asks. A yes keeps the price for you; the item stays yours until you press Sell."""
        if self.busy or self.phase != "shop":
            return
        self.busy = True
        self._refresh_texts()
        sfx.play("pick")

        def done(ok: bool, data) -> None:
            self.busy = False
            try:
                if not ok or not isinstance(data, dict):
                    self.ctx.toast(tr(str(data)), "warn")
                    return self._refresh_texts()
                res = data.get("result")
                self.anger = float(data.get("anger") or 0)
                if res == "yes":
                    sfx.play("on")
                    self.deal = int(data.get("price") or ask)
                    self.ask_mode = False
                    self.line, self.line_at = tr("Fine. {n} coins, if you want it.", n=coins_text(self.deal)), time.monotonic()
                    self._refresh_texts()
                elif res == "kicked":
                    self.anger = 100.0
                    self.line, self.line_at = tr("That's it. GET OUT!"), time.monotonic()
                    self.after = lambda: self.ctx.toast(tr("Thrown out of the pawn shop for 5 minutes"), "warn")
                    self._controls(False)
                    sfx.play("off")
                    QTimer.singleShot(500, self._crack)
                elif res == "banned":
                    self.ban_left = int(data.get("ban_left") or 0)
                    self.ban_end = time.monotonic() + self.ban_left
                    self.ctx.pawn_ban_until = time.time() + self.ban_left
                    self._controls(False)
                    self._go("ban_close")
                else:
                    sfx.play("off")
                    self.line = (tr("No way.") if self.anger < 45 else tr("You're pushing it.") if self.anger < 75
                                 else tr("One more and you're out."))
                    self.line_at = time.monotonic()
                    self._refresh_texts()
                self.update()
            except RuntimeError:
                pass
        self.ctx.econ.call("rb_pawn_ask", {"ids": self.ids, "ask": ask}, done, once=True)

    # -- phases
    def _go(self, phase: str) -> None:
        self.phase, self.t0 = phase, time.monotonic()
        if phase in ("close", "leave_close", "ban_close"):
            sfx.play("pick")
        if phase != "shop":
            self._controls(False)

    def leave(self) -> None:
        if self.phase == "shop" and not self.busy:
            self._go("leave_close")

    def keyPressEvent(self, e) -> None:
        if e.key() == Qt.Key.Key_Escape:
            return self.leave()
        super().keyPressEvent(e)

    def mousePressEvent(self, e) -> None:
        e.accept()                                     # nothing under the shop can be clicked

    def _crack(self) -> None:
        """The bar cracks, then the whole shop breaks into pieces that fall away."""
        self._go("crack")
        self.snap = None
        rnd = random.Random(int(time.time()))
        self.crack_seed = rnd.randrange(1 << 30)
        bar = self._bar_rect()
        self.crack_at = QPointF(bar.left() + bar.width() * rnd.uniform(0.55, 0.9), bar.center().y())

    def _make_shards(self) -> None:
        self.snap = self.grab()
        rnd = random.Random(self.crack_seed)
        c = self.crack_at
        n = 14
        angs = sorted(rnd.uniform(0, math.tau) for _ in range(n))
        far = math.hypot(self.width(), self.height()) * 1.2
        self.shards = []
        for i in range(n):
            a1, a2 = angs[i], angs[(i + 1) % n] + (math.tau if i == n - 1 else 0)
            mid = (a1 + a2) / 2
            poly = QPolygonF([c, c + QPointF(math.cos(a1) * far, math.sin(a1) * far),
                              c + QPointF(math.cos(mid) * far * 1.1, math.sin(mid) * far * 1.1),
                              c + QPointF(math.cos(a2) * far, math.sin(a2) * far)])
            self.shards.append((poly, math.cos(mid) * rnd.uniform(60, 220), rnd.uniform(-260, -40),
                                rnd.uniform(-90, 90), rnd.uniform(0, 0.15)))

    def _frame(self) -> None:
        self._place()
        now = time.monotonic()
        t = now - self.t0
        ph = self.phase
        if self.props_left <= 0 and self.props_end:
            if time.time() >= self.props_end:                   # an exchange came back: ask the server
                self.props_end = 0.0
                self._props_reload()
            elif int(time.time()) != getattr(self, "_props_sec", 0):
                self._props_sec = int(time.time())
                self._refresh_texts()
        if ph == "fade" and t >= 0.3:
            self._go("close")
        elif ph == "close" and t >= 0.45:
            self._go("hold")
            sfx.play("off")
        elif ph == "hold" and t >= 0.25 and self.loaded:
            if self.ban_left > 0:
                self._go("ban_close")
                self.t0 -= 0.45                              # the doors are shut already: straight to the plaque
            elif self.ban_left < 0:
                self._go("leave_open")
            else:
                self._go("open")
        elif ph == "open" and t >= 0.6:
            self._go("shop")
            self._controls(True)
        elif ph == "leave_close" and t >= 0.4:
            self._go("leave_open")
        elif ph == "ban_close" and t >= 0.45 + 2.6:
            self._go("leave_open")
        elif ph == "crack":
            if t >= 0.55 and self.snap is None:
                self._make_shards()
            if t >= 1.5:
                self._go("slam")
                self.ban_end = time.monotonic() + 300
                self.ctx.pawn_ban_until = time.time() + 300
        elif ph == "slam" and t >= 0.25 + 1.6:
            self._go("leave_open")
        elif ph == "leave_open" and t >= 0.5:
            return self._finish()
        self.shown_anger += (self.anger - self.shown_anger) * 0.12
        self.update()

    def _finish(self) -> None:
        self._timer.stop()
        after = self.after
        self.hide()
        self.deleteLater()
        if after:
            after()

    # -- drawing
    def _doors(self) -> float:
        """0: open (out of sight), 1: shut."""
        t = time.monotonic() - self.t0
        ph = self.phase
        if ph == "fade":
            return 0.0
        if ph in ("close", "leave_close", "ban_close"):
            return pawn_ease(t / (0.45 if ph != "leave_close" else 0.4))
        if ph in ("hold",):
            return 1.0
        if ph == "open":
            return 1 - pawn_ease(t / 0.6)
        if ph == "slam":
            return pawn_ease_in(t / 0.25)
        if ph == "leave_open":
            return 1 - pawn_ease(t / 0.5)
        return 0.0

    def _veil(self) -> float:
        """How dark the menu behind is."""
        t = time.monotonic() - self.t0
        if self.phase == "fade":
            return 0.9 * pawn_ease(t / 0.3)
        if self.phase == "leave_open":
            return 0.9 * (1 - pawn_ease(t / 0.5))
        return 0.9

    def _scene_on(self) -> bool:
        """The shop behind the doors: there while you are in it (and while it falls apart)."""
        return self.phase in ("open", "shop", "leave_close", "crack")

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        r = QRectF(self.rect())
        clip = QPainterPath()
        clip.addRoundedRect(r, S(14), S(14))
        p.setClipPath(clip)
        now = time.monotonic()
        p.fillRect(r, alpha("#000000", self._veil()))
        if self.phase == "crack" and self.snap is not None:
            p.fillRect(r, QColor("#000000"))
            self._paint_shards(p, now)
        elif self._scene_on():
            self._paint_scene(p, r, now)
            if self.phase == "crack":
                self._paint_cracks(p, now)
        d = self._doors()
        if d > 0.001:
            self._paint_doors(p, r, d, now)

    # the shop
    def _paint_scene(self, p, r, now) -> None:
        wall = QLinearGradient(r.topLeft(), r.bottomLeft())
        wall.setColorAt(0, QColor("#2A1C14"))
        wall.setColorAt(1, QColor("#120C09"))
        p.fillRect(r, wall)
        lamp = QRadialGradient(QPointF(r.center().x(), r.top() + r.height() * 0.18), r.width() * 0.55)
        lamp.setColorAt(0, alpha("#FFC874", 0.22))
        lamp.setColorAt(1, alpha("#FFC874", 0.0))
        p.fillRect(r, lamp)
        pn = self._panel()
        cy = self._counter_y()
        self._paint_shelves(p, r, cy)
        self._paint_sign(p, pn)
        self._paint_keeper(p, pn, cy, now)
        self._paint_counter(p, r, cy, now)
        self._paint_bar(p, now)
        self._paint_texts(p, pn, cy, now)
        self._paint_bubble(p, pn, now)
        if self.loaded and self.phase == "shop":
            self._paint_props(p, r)

    def _paint_props(self, p, r) -> None:
        """6.2.7: the exchange allowance, big and always on screen: 5 pips for 5 proposals an hour."""
        left = self.props_left
        w, h = S(300), S(34)
        box = QRectF(r.right() - S(16) - w, r.top() + S(16), w, h)
        col = QColor(LOSE) if left <= 0 else QColor(GOLD_TEXT) if left <= 3 else QColor("#FFFFFF")
        p.save()
        p.setPen(QPen(alpha(col, 0.8), S(1.5)))
        p.setBrush(alpha("#000000", 0.55))
        p.drawRoundedRect(box, S(10), S(10))
        p.setFont(font(8.5, QFont.Weight.ExtraBold, 0.6))
        p.setPen(alpha(col, 0.95))
        back = ""
        if left <= 0 and self.props_end:
            back = " · " + pawn_clock(int(self.props_end - time.time()))
        p.drawText(QRectF(box.left() + S(10), box.top(), box.width() - S(140), h), int(Qt.AlignmentFlag.AlignVCenter),
                   tr("EXCHANGES THIS HOUR") + back)
        for i in range(10):
            c = QPointF(box.right() - S(12) - (9 - i) * S(13), box.center().y())
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(col if i < left else alpha("#FFFFFF", 0.18))
            p.drawEllipse(c, S(4.5), S(4.5))
        p.restore()

    def _paint_shelves(self, p, r, cy) -> None:
        rnd = random.Random(7)
        p.setPen(Qt.PenStyle.NoPen)
        for row in range(3):
            y = r.top() + r.height() * (0.20 + row * 0.10)
            p.setBrush(QColor("#3B2819"))
            p.drawRect(QRectF(r.left(), y, r.width(), S(6)))
            x = r.left() + S(10)
            while x < r.right() - S(30):
                w = S(rnd.choice([14, 18, 22, 26]))
                h = S(rnd.choice([18, 24, 30, 36]))
                if abs((x + w / 2) - r.center().x()) > self._panel().width() * 0.42:     # keep the middle clear
                    p.setBrush(alpha(rnd.choice(["#7A5A3A", "#5C6B73", "#8C7A4A", "#6E4A5A", "#4A6A5A"]), 0.55))
                    if rnd.random() < 0.4:
                        p.drawEllipse(QRectF(x, y - h, w, h))
                    else:
                        p.drawRoundedRect(QRectF(x, y - h, w, h), S(3), S(3))
                x += w + S(rnd.choice([6, 10, 16]))

    def _paint_sign(self, p, pn) -> None:
        sign = QRectF(pn.center().x() - S(150), S(58), S(300), S(46))
        g = QLinearGradient(sign.topLeft(), sign.bottomLeft())
        g.setColorAt(0, QColor("#5A3A22"))
        g.setColorAt(1, QColor("#3A2414"))
        p.setPen(QPen(QColor("#2A190D"), S(2)))
        p.setBrush(g)
        p.drawRoundedRect(sign, S(6), S(6))
        p.setPen(PAWN_GOLD)
        p.setFont(font(17, QFont.Weight.Black, 2.0))
        p.drawText(sign, int(Qt.AlignmentFlag.AlignCenter), tr("PAWN SHOP"))
        p.setPen(QPen(alpha("#000000", 0.5), S(1.5)))
        p.drawLine(QPointF(sign.left() + S(30), sign.top()), QPointF(sign.left() + S(30), sign.top() - S(20)))
        p.drawLine(QPointF(sign.right() - S(30), sign.top()), QPointF(sign.right() - S(30), sign.top() - S(20)))

    def _paint_keeper(self, p, pn, cy, now) -> None:
        a = min(1.0, self.shown_anger / 100)
        c = QPointF(pn.center().x() + pn.width() * 0.26, cy - S(62))
        shake = math.sin(now * 40) * S(2) * max(0.0, a - 0.75) * 4
        c += QPointF(shake, 0)
        p.setPen(Qt.PenStyle.NoPen)
        body = QPainterPath()                              # shoulders
        body.moveTo(c.x() - S(62), cy)
        body.cubicTo(c.x() - S(58), c.y() + S(30), c.x() - S(30), c.y() + S(26), c.x(), c.y() + S(26))
        body.cubicTo(c.x() + S(30), c.y() + S(26), c.x() + S(58), c.y() + S(30), c.x() + S(62), cy)
        body.closeSubpath()
        p.setBrush(QColor("#3C4A3A"))
        p.drawPath(body)
        skin = mix(QColor("#D9A57A"), QColor("#E0523C"), a * 0.85)
        p.setBrush(skin)
        p.drawEllipse(c, S(30), S(34))
        p.setBrush(QColor("#2A1C14"))                      # hair and a cap
        p.drawChord(QRectF(c.x() - S(31), c.y() - S(36), S(62), S(40)), 0, 180 * 16)
        eye_y = c.y() - S(2)
        for sx in (-1, 1):
            e = QPointF(c.x() + sx * S(11), eye_y)
            p.setBrush(QColor("#FFFFFF"))
            p.drawEllipse(e, S(5), S(4.2) * (1 - 0.35 * a))
            p.setBrush(QColor("#1A1210"))
            p.drawEllipse(e + QPointF(sx * -S(1), S(0.5)), S(2.2), S(2.2))
            p.setPen(QPen(QColor("#2A1C14"), S(2.6), Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
            outer = QPointF(e.x() + sx * S(7), eye_y - S(10))       # the inner ends drop as he gets angry
            inner = QPointF(e.x() - sx * S(5), eye_y - S(9) + S(6) * a)
            p.drawLine(outer, inner)
            p.setPen(Qt.PenStyle.NoPen)
        mouth = QPainterPath()
        my = c.y() + S(16)
        bend = S(5) * (1 - 2 * a)                           # a smile, then a flat line, then a frown
        mouth.moveTo(c.x() - S(10), my)
        mouth.quadTo(QPointF(c.x(), my + bend), QPointF(c.x() + S(10), my))
        p.setPen(QPen(QColor("#5A2A1E"), S(2.4), Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawPath(mouth)
        self._head = QPointF(c)                             # 5.3: the bubble is painted last, on top

    def _paint_bubble(self, p, pn, now) -> None:
        """His speech bubble, to the left of his head, over everything else (5.3: nothing draws over it)."""
        c = getattr(self, "_head", None)
        if c is None:
            return
        a = min(1.0, self.shown_anger / 100)
        age = now - self.line_at
        if self.line:
            # 5.3: the bubble only uses the room left of his head (it used to slide over his face and the text)
            room = max(S(110), c.x() - S(46) - pn.left() - S(6))
            for size in (12, 11, 10, 9):
                p.setFont(font(size, QFont.Weight.Bold))
                fm = p.fontMetrics()
                br = fm.boundingRect(0, 0, int(room - S(30)), 400, int(Qt.TextFlag.TextWordWrap), self.line)
                if br.height() + S(22) <= S(96):
                    break
            bw, bh = br.width() + S(30), br.height() + S(22)      # 4.6: room for every line (no half-hidden words)
            b = QRectF(c.x() - S(46) - bw, max(c.y() - S(40), self._bar_rect().bottom() + S(8)), bw, bh)
            b.moveLeft(max(pn.left() + S(2), b.left()))
            k = pawn_ease_out(age / 0.25)
            p.save()
            p.translate(b.right(), b.bottom())
            p.scale(0.85 + 0.15 * k, 0.85 + 0.15 * k)
            p.translate(-b.right(), -b.bottom())
            p.setOpacity(k)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor("#F4EBDD"))
            p.drawRoundedRect(b, S(10), S(10))
            tail = QPolygonF([QPointF(b.right() - S(4), b.top() + S(12)), QPointF(b.right() + S(14), b.top() + S(20)),
                              QPointF(b.right() - S(4), b.top() + S(24))])
            p.drawPolygon(tail)
            p.setPen(QColor("#B3261E") if a > 0.7 else QColor("#2A1C14"))
            p.drawText(b.adjusted(S(13), S(8), -S(13), -S(8)), int(Qt.TextFlag.TextWordWrap | Qt.AlignmentFlag.AlignCenter),
                       self.line)
            p.restore()


    def _paint_counter(self, p, r, cy, now) -> None:
        top = QRectF(r.left(), cy, r.width(), S(14))
        g = QLinearGradient(top.topLeft(), top.bottomLeft())
        g.setColorAt(0, QColor("#8A5A34"))
        g.setColorAt(1, QColor("#5A3A20"))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(g)
        p.drawRect(top)
        front = QRectF(r.left(), cy + S(14), r.width(), r.height() - cy - S(14))
        g2 = QLinearGradient(front.topLeft(), front.bottomLeft())
        g2.setColorAt(0, QColor("#3E2716"))
        g2.setColorAt(1, QColor("#1E130B"))
        p.setBrush(g2)
        p.drawRect(front)
        p.setPen(QPen(alpha("#000000", 0.35), 1))
        for k in range(1, 8):
            x = r.left() + r.width() * k / 8
            p.drawLine(QPointF(x, front.top()), QPointF(x, front.bottom()))
        # the item on a velvet pad (it slides away once he buys it)
        pn = self._panel()
        pad = QRectF(pn.center().x() - pn.width() * 0.26 - S(56), cy - S(20), S(112), S(26))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor("#5A1E2A"))
        p.drawRoundedRect(pad, S(8), S(8))
        if self.item:
            pass
            k = pawn_ease_in((now - self.sold_at) / 0.8) if self.sold_at else 0.0
            box = QRectF(pad.center().x() - S(36), pad.top() - S(62), S(72), S(72))
            box.translate(pn.width() * 0.5 * k, -S(10) * math.sin(k * math.pi))
            p.setOpacity(1 - k)
            glow = QRadialGradient(box.center(), S(60))
            glow.setColorAt(0, alpha(PAWN_GOLD, 0.25))
            glow.setColorAt(1, alpha(PAWN_GOLD, 0.0))
            p.fillRect(box.adjusted(-S(30), -S(30), S(30), S(30)), glow)
            show_item(p, self.item, box, now)
            p.setOpacity(1.0)
            if self.trade:                                   # 5.12: his item on a plate, on his side of the counter
                plate = QRectF(pn.center().x() + pn.width() * 0.34 - S(56), cy - S(16), S(112), S(20))     # his side
                g3 = QLinearGradient(plate.topLeft(), plate.bottomLeft())
                g3.setColorAt(0, QColor("#E6EEF5"))
                g3.setColorAt(1, QColor("#8C98A3"))
                p.setPen(QPen(alpha("#000000", 0.4), 1))
                p.setBrush(g3)
                p.drawEllipse(plate)
                his = QRectF(plate.center().x() - S(28), plate.top() - S(50), S(56), S(56))
                glow2 = QRadialGradient(his.center(), S(60))
                glow2.setColorAt(0, alpha("#7FE8FF", 0.25))
                glow2.setColorAt(1, alpha("#7FE8FF", 0.0))
                p.fillRect(his.adjusted(-S(30), -S(30), S(30), S(30)), glow2)
                show_item(p, self.trade.get("item", ""), his, now)
                p.setPen(QColor(TEXT))
                p.setFont(font(10, QFont.Weight.Bold))
                p.drawText(QRectF(plate.left() - S(40), plate.bottom() + S(2), plate.width() + S(80), S(16)),
                           int(Qt.AlignmentFlag.AlignCenter), tr("His · worth {n} ({p}% of yours)", n=coins_text(int(self.trade.get("worth") or 0)),
                                                                 p=int(self.trade.get("pct") or 0)))
                p.setPen(QColor(TEXT_DIM))
                p.drawText(QRectF(pad.left() - S(40), pad.bottom() + S(2), pad.width() + S(80), S(16)),
                           int(Qt.AlignmentFlag.AlignCenter), tr("Yours · worth {n}", n=coins_text(int(self.trade.get("mine_worth") or 0))))
            if len(self.ids) > 1:
                p.setPen(QColor(TEXT))
                p.setFont(font(12, QFont.Weight.Black))
                p.drawText(QRectF(box.right() - S(6), box.bottom() - S(20), S(50), S(20)), int(Qt.AlignmentFlag.AlignVCenter),
                           f"×{len(self.ids)}")

    def _bar_rect(self) -> QRectF:
        pn = self._panel()
        return QRectF(pn.left() + S(80), S(126), pn.width() - S(160), S(16))

    def _paint_bar(self, p, now) -> None:
        bar = self._bar_rect()
        p.setPen(QColor(TEXT_DIM))
        p.setFont(font(9.5, QFont.Weight.Black, 1.2))
        p.drawText(QRectF(bar.left(), bar.top() - S(18), bar.width(), S(16)), int(Qt.AlignmentFlag.AlignCenter),
                   tr("HIS PATIENCE RUNS OUT"))
        shake = 0.0
        if self.phase == "crack":
            shake = math.sin(now * 60) * S(3) * min(1.0, (now - self.t0) / 0.2)
        bar = bar.translated(shake, 0)
        path = QPainterPath()
        path.addRoundedRect(bar, bar.height() / 2, bar.height() / 2)
        p.setPen(QPen(alpha("#000000", 0.6), S(1.5)))
        p.setBrush(QColor("#1A120C"))
        p.drawPath(path)
        grad = QLinearGradient(bar.topLeft(), bar.topRight())
        grad.setColorAt(0, QColor("#3DDC84"))
        grad.setColorAt(0.5, QColor("#F2C94C"))
        grad.setColorAt(1, QColor("#FF3B3B"))
        p.save()
        p.setClipPath(path)
        a = max(0.0, min(100.0, self.shown_anger)) / 100
        p.setPen(Qt.PenStyle.NoPen)
        rage = None
        if self.ask_mode and self.phase == "shop" and self.base:           # the next no, if he says no at this price
            rage = pawn_rage(self.ask / self.base)
        elif self.trade_confirm and self.trade and self.trade.get("more"):  # 5.12: asking him for a better item
            rage = float(self.trade["more"].get("rage") or 0)
        if rage is not None:
            nxt = min(1.0, a + rage / 100)
            p.setOpacity(0.32 + 0.1 * math.sin(now * 5))
            p.setBrush(grad)
            p.drawRect(QRectF(bar.left(), bar.top(), bar.width() * nxt, bar.height()))
            p.setOpacity(1.0)
        p.setBrush(grad)
        p.drawRect(QRectF(bar.left(), bar.top(), bar.width() * a, bar.height()))
        p.restore()
        if self.phase == "crack":                                      # the crack, then it splits
            self._paint_bar_crack(p, bar, now)

    def _paint_bar_crack(self, p, bar, now) -> None:
        k = min(1.0, (now - self.t0) / 0.35)
        rnd = random.Random(self.crack_seed)
        c = QPointF(self.crack_at.x(), bar.center().y())
        p.setPen(QPen(QColor("#FFFFFF"), S(1.6)))
        for _ in range(5):
            ang = rnd.uniform(0, math.tau)
            pt = QPointF(c)
            path = QPainterPath(pt)
            for _s in range(4):
                ang += rnd.uniform(-0.6, 0.6)
                pt = pt + QPointF(math.cos(ang) * S(9) * k, math.sin(ang) * S(5) * k)
                path.lineTo(pt)
            p.drawPath(path)

    def _paint_cracks(self, p, now) -> None:
        """Before it breaks: cracks run out from the bar across everything."""
        t = now - self.t0
        k = max(0.0, min(1.0, (t - 0.25) / 0.3))
        if k <= 0:
            return
        rnd = random.Random(self.crack_seed + 1)
        c = self.crack_at
        far = math.hypot(self.width(), self.height())
        for _ in range(14):
            ang = rnd.uniform(0, math.tau)
            pt = QPointF(c)
            path = QPainterPath(pt)
            n = 9
            for s in range(n):
                if s / n > k:
                    break
                ang += rnd.uniform(-0.35, 0.35)
                step = far / n * rnd.uniform(0.6, 1.2)
                pt = pt + QPointF(math.cos(ang) * step, math.sin(ang) * step)
                path.lineTo(pt)
            p.setPen(QPen(alpha("#FFFFFF", 0.85), S(1.4)))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawPath(path)
            p.setPen(QPen(alpha("#000000", 0.5), S(3)))
            p.drawPath(path.translated(S(1), S(1)))

    def _paint_shards(self, p, now) -> None:
        t = max(0.0, now - self.t0 - 0.55)
        for poly, vx, vy, spin, delay in self.shards:
            tt = max(0.0, t - delay)
            dx, dy = vx * tt * S(1), (vy * tt + 0.5 * 1800 * tt * tt) * S(1) / 2
            p.save()
            c = poly.boundingRect().center()
            p.translate(c.x() + dx, c.y() + dy)
            p.rotate(spin * tt)
            p.translate(-c.x(), -c.y())
            path = QPainterPath()
            path.addPolygon(poly)
            path.closeSubpath()
            p.setClipPath(path)
            p.setOpacity(max(0.0, 1 - tt / 0.95))
            p.drawPixmap(0, 0, self.snap)
            p.restore()

    def _paint_texts(self, p, pn, cy, now) -> None:
        if self.phase not in ("shop", "open", "leave_close"):
            return
        y = cy + S(34)
        p.setPen(QColor(TEXT))
        p.setFont(font(15, QFont.Weight.Black))
        p.drawText(QRectF(pn.left(), y, pn.width(), S(26)), int(Qt.AlignmentFlag.AlignCenter), self.what)
        p.setFont(font(12, QFont.Weight.Bold))
        if self.sold_at:
            p.setPen(QColor("#3DDC84"))
            p.drawText(QRectF(pn.left(), y + S(32), pn.width(), S(22)), int(Qt.AlignmentFlag.AlignCenter),
                       tr("Sold for {n} coins", n=coins_text(getattr(self, "paid", 0))))
        elif self.trade:                                    # 5.12: the exchange, in plain words
            his = item_name(self.trade.get("item", ""))
            p.setPen(QColor("#7FE8FF"))
            p.drawText(QRectF(pn.left(), y + S(32), pn.width(), S(22)), int(Qt.AlignmentFlag.AlignCenter),
                       tr("Exchange: yours for his {what}", what=his))
            p.setPen(QColor(TEXT_DIM))
            p.setFont(font(10.5, QFont.Weight.DemiBold))
            more = self.trade.get("more")
            line = (tr("Ask for more = ask for an item worth about {p}% of yours. {c}% chance he says yes. If he says no: +{r} anger "
                       "(the faint part of the bar) and no more asking.", p=int(more.get("pct") or 0),
                       c=int(round(float(more.get("chance") or 0) * 100)), r=int(round(float(more.get("rage") or 0))))
                    if more else tr("This is his last offer: accept or refuse."))
            p.drawText(QRectF(pn.left(), y + S(56), pn.width(), S(36)),
                       int(Qt.AlignmentFlag.AlignHCenter | Qt.AlignmentFlag.AlignTop | Qt.TextFlag.TextWordWrap), line)
            return
        elif self.deal:
            p.setPen(QColor("#3DDC84"))
            p.drawText(QRectF(pn.left(), y + S(32), pn.width(), S(22)), int(Qt.AlignmentFlag.AlignCenter),
                       tr("He agreed to {n} coins: press Sell to sell it", n=coins_text(self.deal)))
        elif self.ask_mode and self.base:
            ch = pawn_chance(self.ask / self.base, self.anger)
            col = QColor("#3DDC84") if ch >= 0.6 else QColor("#F2C94C") if ch >= 0.3 else QColor("#FF6B5C")
            p.setPen(col)
            p.drawText(QRectF(pn.left(), y + S(32), pn.width(), S(22)), int(Qt.AlignmentFlag.AlignCenter),
                       tr("Chance he says yes: {p}%", p=int(round(ch * 100))))
            p.setPen(QColor(TEXT_DIM))
            p.setFont(font(10.5, QFont.Weight.DemiBold))
            p.drawText(QRectF(pn.left(), y + S(56), pn.width(), S(20)), int(Qt.AlignmentFlag.AlignCenter),
                       tr("If he says no, the faint part of the bar is how angry he gets"))
        else:
            p.setPen(PAWN_GOLD)
            p.drawText(QRectF(pn.left(), y + S(32), pn.width(), S(22)), int(Qt.AlignmentFlag.AlignCenter),
                       tr("His offer: {n} coins", n=coins_text(self.base)) if self.base else "…")
            p.setPen(QColor(TEXT_DIM))
            p.setFont(font(10.5, QFont.Weight.DemiBold))
            p.drawText(QRectF(pn.left(), y + S(56), pn.width(), S(20)), int(Qt.AlignmentFlag.AlignCenter),
                       tr("Take it, or ask for more (up to +50%)"))
        if self.market and not self.sold_at:                   # 4.7: to compare with the market
            p.setPen(QColor(TEXT_DIM))
            p.setFont(font(10.5, QFont.Weight.Bold))
            p.drawText(QRectF(pn.left(), y + S(78), pn.width(), S(20)), int(Qt.AlignmentFlag.AlignCenter),
                       tr("Market price: about {n} coins (selling there takes longer, 5% fee)", n=coins_text(self.market)))
        # how it works, under the buttons
        foot = QRectF(pn.left(), self.box.geometry().bottom() + S(14), pn.width(), S(60))
        p.setPen(alpha(TEXT_DIM, 0.85))
        p.setFont(font(10, QFont.Weight.DemiBold))
        p.drawText(foot, int(Qt.TextFlag.TextWordWrap | Qt.AlignmentFlag.AlignHCenter | Qt.AlignmentFlag.AlignTop),
                   tr("His price always sells. Asking for more only asks: if he says yes, you still choose to sell. "
                      "Every no makes him angrier (he calms down over time); if his patience runs out, he throws you out "
                      "for 5 minutes."))

    # the doors
    def _paint_doors(self, p, r, d, now) -> None:
        half = r.width() / 2
        off = (1 - d) * (half + S(20))
        for side in (0, 1):
            x = (r.left() - off) if side == 0 else (r.center().x() + off)
            door = QRectF(x, r.top(), half, r.height())
            g = QLinearGradient(door.topLeft(), door.topRight())
            g.setColorAt(0, QColor("#4A2E1A") if side == 0 else QColor("#3A2414"))
            g.setColorAt(1, QColor("#3A2414") if side == 0 else QColor("#4A2E1A"))
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(g)
            p.drawRect(door)
            p.setPen(QPen(alpha("#000000", 0.35), S(1.2)))                 # planks
            for k in range(1, 6):
                xx = door.left() + door.width() * k / 6
                p.drawLine(QPointF(xx, door.top()), QPointF(xx, door.bottom()))
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor("#2A2A2E"))                                    # iron bands with rivets
            for fy in (0.14, 0.86):
                band = QRectF(door.left(), door.top() + door.height() * fy - S(9), door.width(), S(18))
                p.drawRect(band)
                p.setBrush(QColor("#55555C"))
                for k in range(1, 8):
                    p.drawEllipse(QPointF(band.left() + band.width() * k / 8, band.center().y()), S(2.6), S(2.6))
                p.setBrush(QColor("#2A2A2E"))
            edge = door.right() if side == 0 else door.left()                # the handles meet in the middle
            hc = QPointF(edge + (-S(26) if side == 0 else S(26)), door.center().y())
            p.setBrush(QColor("#C9A24A"))
            p.drawEllipse(hc, S(9), S(9))
            p.setBrush(QColor("#7A5A20"))
            p.drawEllipse(hc, S(4), S(4))
            p.setPen(QPen(alpha("#000000", 0.6), S(3)))
            p.drawLine(QPointF(edge, door.top()), QPointF(edge, door.bottom()))
        if d > 0.98 and self.phase in ("ban_close", "slam") and self.ban_end:
            self._paint_plaque(p, r, now)

    def _paint_plaque(self, p, r, now) -> None:
        """4.6: a big plaque with a big countdown, easy to read from across the room."""
        left = max(0, int(math.ceil(self.ban_end - now)))
        pl = QRectF(r.center().x() - S(190), r.center().y() - S(190), S(380), S(170))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(alpha("#000000", 0.45))
        p.drawRoundedRect(pl.translated(0, S(5)), S(10), S(10))
        p.setPen(QPen(QColor("#2A190D"), S(3)))
        p.setBrush(QColor("#EFE5CF"))
        p.drawRoundedRect(pl, S(10), S(10))
        p.setPen(QPen(alpha("#8A1C14", 0.5), S(1.5)))
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawRoundedRect(pl.adjusted(S(7), S(7), -S(7), -S(7)), S(6), S(6))
        p.setPen(QColor("#8A1C14"))
        p.setFont(font(16, QFont.Weight.Black, 2.0))
        p.drawText(QRectF(pl.left(), pl.top() + S(16), pl.width(), S(26)), int(Qt.AlignmentFlag.AlignCenter),
                   tr("CLOSED TO YOU"))
        pulse = 0.85 + 0.15 * math.sin(now * 3)
        p.setPen(QColor(int(178 * pulse), 30, 24))
        p.setFont(font(40, QFont.Weight.Black))
        p.drawText(QRectF(pl.left(), pl.top() + S(46), pl.width(), S(62)), int(Qt.AlignmentFlag.AlignCenter),
                   pawn_clock(left))
        p.setFont(font(11.5, QFont.Weight.Bold))
        p.setPen(QColor("#4A3A2A"))
        p.drawText(QRectF(pl.left(), pl.top() + S(112), pl.width(), S(20)), int(Qt.AlignmentFlag.AlignCenter),
                   tr("before you can come back in"))
        p.setFont(font(10, QFont.Weight.DemiBold))
        p.setPen(QColor("#6A5A4A"))
        p.drawText(QRectF(pl.left(), pl.top() + S(136), pl.width(), S(20)), int(Qt.AlignmentFlag.AlignCenter),
                   tr("You made him too angry"))


def open_pawn(ctx, ids: list, item: str, what: str) -> None:
    """Quick sell: ask first, then walk into the pawn shop."""
    if not ids:
        return
    old = getattr(ctx, "_pawn", None)
    try:
        if old is not None and old.isVisible():
            return
    except RuntimeError:
        pass

    ctx._pawn = PawnShop(ctx, ids, item, what)            # 5.0: no question first, straight into the shop


# ==================================================================================================
# SECTION: wave
# ==================================================================================================
import bisect
import math
import random
import time

from PyQt6.QtCore import QPointF, QRectF, Qt, QTimer
from PyQt6.QtGui import QColor, QFont, QLinearGradient, QPainter, QPainterPath, QPen, QPolygonF
from PyQt6.QtWidgets import QWidget


# ================================================================ the course (the server's rb_wave_sim, line for line)
WAVE_VX = 12              # units a tick, right and up/down
WAVE_R = 10               # hit radius
WAVE_H = 1000             # course height
WAVE_SW = 48              # half width of a spike
WAVE_TPS = 60             # ticks a second
WAVE_MAX = 60 * 900
GHOST_LAG = 84             # 6.4: the other player is shown 1.4 s behind, so we only ever draw what really happened
WAVE_SLIDE = 150          # 5.1 (033): the first 2.5 s you slide on the walls instead of crashing
WAVE_SPACE = 130          # 5.1 (033): two spikes in a row are never closer than this (they could close the gap)
WAVE_HUD = 46             # 5.1: the distance and the difficulty bar sit in their own strip above the course


class WaveRng:
    def __init__(self, seed: int) -> None:
        self.s = seed & 0x7FFFFFFF

    def next(self, n: int) -> int:
        self.s = (self.s * 1103515245 + 12345) & 0x7FFFFFFF
        return (self.s >> 8) % n


def wave_level(x: int) -> int:
    """5.13: 0 (start) to 1000. It jumps up at 250 m, 500 m, 750 m and 1 000 m (Medium, Hard, Insane, Extreme) and
    climbs a little inside each stage. The server (rb_wave_sim) does the same sums."""
    m = x // 100
    if m < 250:
        return m * 160 // 250
    if m < 500:
        return 300 + (m - 250) * 100 // 250
    if m < 750:
        return 500 + (m - 500) * 100 // 250
    if m < 1000:
        return 700 + (m - 750) * 100 // 250
    return min(1000, 880 + (m - 1000) * 120 // 500)


def wave_gap(d: int) -> int:
    f = d * (d + 1000) // 2000
    g = 420 - 300 * f // 1000
    return g - g % 2


class WaveCourse:
    """Segments [x0, length, c0, slope, gap, spikes]; spikes (x, side): 0 hangs from the top, 1 stands on the floor."""

    def __init__(self, seed: int) -> None:
        self.rng = WaveRng(seed)
        self.segs = [[0, 900, 500, 0, 420, []]]
        self.starts = [0]
        self.x_end, self.c_end = 900, 500

    def _add(self, length: int, slope: int, gap: int, spikes=None) -> None:
        self.segs.append([self.x_end, length, self.c_end, slope, gap, spikes or []])
        self.starts.append(self.x_end)
        self.x_end += length
        self.c_end += slope * length

    def _room(self, slope: int, gap: int) -> int:
        lo, hi = gap // 2 + 40, WAVE_H - gap // 2 - 40
        return hi - self.c_end if slope > 0 else self.c_end - lo

    def _pull(self, gap: int) -> None:
        lo, hi = gap // 2 + 40, WAVE_H - gap // 2 - 40
        if self.c_end < lo:
            self._add(lo - self.c_end, 1, gap)
        elif self.c_end > hi:
            self._add(self.c_end - hi, -1, gap)

    def grow(self) -> None:
        rnd = self.rng.next
        d = wave_level(self.x_end)
        gap = wave_gap(d)
        self._pull(gap)
        r = rnd(1000)
        p_zig = 200 + 400 * d // 1000
        p_flat = 450 - 200 * d // 1000
        if d >= 300 and r < 90:                                  # 5.13: a tunnel, a quarter narrower
            length = 300 + rnd(300)
            narrow = gap * 3 // 4
            self._add(length, 0, narrow - narrow % 2)
            return
        if r < p_flat:
            length = 300 + rnd(500)
            n = rnd(2 + 3 * d // 1000) if d >= 20 else 0
            n = min(n, max(0, length // WAVE_SPACE - 1))              # 5.1: never stacked in a tight space
            side = rnd(2)
            spikes = []                                               # 5.13: no more gates (above and below at once)
            for i in range(n):
                spikes.append((self.x_end + length * (i + 1) // (n + 1), side))
                side = 1 - side
            self._add(length, 0, gap, spikes)
        elif r < p_flat + p_zig:
            legs = 3 + rnd(4 + 4 * d // 1000)
            leg = max(100, 320 - 220 * d // 1000 + rnd(60))
            slope = 1 if self._room(1, gap) >= self._room(-1, gap) else -1
            for _ in range(legs):
                room = self._room(slope, gap)
                if room < 60:
                    slope = -slope
                    room = self._room(slope, gap)
                self._add(max(40, min(leg, room)), slope, gap)
                slope = -slope
        else:
            slope = 1 if rnd(2) else -1
            if self._room(slope, gap) < 120:
                slope = -slope
            length = max(60, min(150 + rnd(400), self._room(slope, gap)))
            spikes = []
            if d >= 500 and length >= 360:                            # 5.13: two on a long ramp, same side
                side = rnd(2)
                spikes = [(self.x_end + length // 3, side), (self.x_end + 2 * length // 3, side)]
            elif d >= 150 and length >= 200:                          # 4.5: ramps too
                spikes = [(self.x_end + length // 2, rnd(2))]
            self._add(length, slope, gap, spikes)

    def ensure(self, x: int) -> None:
        while self.x_end <= x + 4000:
            self.grow()

    def index(self, x: int) -> int:
        return max(0, bisect.bisect_right(self.starts, x) - 1)

    def bounds(self, i: int, x: int):
        x0, _ln, c0, slope, gap, spikes = self.segs[i]
        c = c0 + slope * (x - x0)
        half = gap // 2
        top, bot = c - half, c + half
        hh = gap * 38 // 100
        for xs, side in spikes:
            dx = abs(x - xs)
            if dx < WAVE_SW:
                k = hh * (WAVE_SW - dx) // WAVE_SW
                if side == 0:
                    top = max(top, c - half + k)
                else:
                    bot = min(bot, c + half - k)
        return top, bot


WAVE_FREE_X = 10000         # 5.3: the first 100 m (the walked start) pay nothing


def wave_pay(x: int) -> int:
    """Coins for a solo distance before the mini game limits (the server's rb_wave_pay_for)."""
    return (max(0, int(x) - WAVE_FREE_X) // 1000) * 5


def metres(x: int) -> int:
    return int(x) // 100


def level_colour(d: int) -> QColor:
    """The walls change colour as it gets harder: green, cyan, violet, then red."""
    stops = [(0, (0.40, 0.75)), (350, (0.52, 0.80)), (700, (0.76, 0.75)), (1000, (0.98, 0.85))]
    for (a, (ha, sa)), (b, (hb, sb)) in zip(stops, stops[1:]):
        if d <= b:
            t = (d - a) / max(1, b - a)
            return QColor.fromHsvF(ha + (hb - ha) * t, sa + (sb - sa) * t, 1.0)
    return QColor.fromHsvF(0.98, 0.85, 1.0)


WAVE_TIERS = [(0, "Easy"), (300, "Medium"), (500, "Hard"), (700, "Insane"), (880, "Extreme")]     # 250 / 500 / 750 / 1 000 m


def wave_tier_of(d: int) -> int:
    return max(i for i, (lo, _n) in enumerate(WAVE_TIERS) if d >= lo)


class WaveRunner:
    """4.5: another player's wave, rebuilt from the ticks where they pressed or let go (the server's maths). Past the
    last tick known it keeps going the same way, until newer ticks come in."""

    def __init__(self, course, name: str = "") -> None:
        self.course, self.name = course, name
        self.tg: list = []
        self.ys = [500]
        self.crash = None                    # the tick where this path hits a wall
        self.upto = 0
        self.done = False
        self.final = None                    # the last tick of a finished run
        self.shown_y = None
        self.fade_at = 0.0
        self.disp = None                     # 6.4: where this wave is shown (a smooth tick, always inside what is known)
        self.stamp = 0.0
        self.reached = False                 # a finished run: the crash is now shown
        self.reach_at = 0.0

    def set(self, toggles, upto: int, done: bool = False, final=None) -> None:
        tg = sorted({int(t) for t in (toggles or []) if int(t) > 0})
        if tg != self.tg:                    # 5.13: keep the path up to the first new toggle (it used to be rebuilt from
            k = 0                            # the start every time news came in: the stutter in long duels)
            while k < min(len(tg), len(self.tg)) and tg[k] == self.tg[k]:
                k += 1
            cut = min(tg[k] if k < len(tg) else 10 ** 9, self.tg[k] if k < len(self.tg) else 10 ** 9)
            self.tg = tg
            del self.ys[max(1, cut):]
            if self.crash is not None and self.crash >= cut:
                self.crash = None
        self.upto = max(self.upto, int(upto or 0))
        if done and not self.done:
            self.done, self.fade_at = True, time.monotonic()
        if final is not None:
            self.final = int(final)

    def y(self, t: int) -> int:
        t = max(0, int(t))
        while len(self.ys) <= t and self.crash is None:
            n = len(self.ys)
            held = bisect.bisect_right(self.tg, n) % 2 == 0
            y = self.ys[-1] + (-WAVE_VX if held else WAVE_VX)
            x = n * WAVE_VX
            self.course.ensure(x)
            top, bot = self.course.bounds(self.course.index(x), x)
            if n <= WAVE_SLIDE:                                     # 5.1: sliding on the start
                y = max(top + WAVE_R, min(bot - WAVE_R, y))
            self.ys.append(y)
            if n > WAVE_SLIDE and (y - WAVE_R < top or y + WAVE_R > bot):
                self.crash = n
        return self.ys[min(t, len(self.ys) - 1)]

    def held(self, t: int) -> bool:
        return bisect.bisect_right(self.tg, t) % 2 == 0


# ================================================================ the game view
class WaveView(QWidget):
    """The run. ready -> (press) -> run -> dead. on_end(ticks, toggles, x) is called once when a run ends."""

    def __init__(self, page, width: int, on_end=None, on_start=None) -> None:
        super().__init__()
        self.page, self.ctx = page, page.ctx
        self.setFixedSize(width, int(width * 0.66) + S(WAVE_HUD))
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
        self.on_end, self.on_start = on_end, on_start
        self.seed = None
        self.course = None
        self.state = "wait"                  # wait (no seed yet), ready, count, run, dead
        self.count_until = 0.0
        self.best = 0
        self.message = ""                    # under the result (coins, waiting for the other player…)
        self.message_col = TEXT_DIM
        self.other = None                    # duel: the other player's WaveRunner (seen see-through)
        self.auto_start = False              # duel: both start together when the countdown ends
        self.god = False                     # duel: the other one crashed and you are past them: nothing can hit you
        self.run_t0 = 0.0                    # when tick 0 was (for the other player's position)
        self.spectate = False                # duel: after you crash, you watch the other player until they crash too
        self._cam = None
        self._cam_t = 0.0
        self.watch = None                    # spectating: [runner a, runner b, t0]
        self.replay = None                   # dict: the last seconds before a crash, shown again
        self.can_retry = False               # solo: the next course is in, a press starts again
        self.result = None                   # duel: (title, line, colour) once it is over
        self.bot_on = bool(page.ctx.cfg["wave_bot"])       # 5.1: the practice bot
        self.bot = None
        self._reset()
        self._timer = QTimer(self)
        self._timer.setTimerType(Qt.TimerType.PreciseTimer)
        self._timer.setInterval(self._frame_ms())          # 6.0: one frame per screen refresh (no judder)
        self._timer.timeout.connect(self._frame)
        self._timer.start()
        self._idle_paint = 0.0
        self.keys = KeyPoll(["Space", "Up", "W"], self._key, lambda: self.state == "run")
        self.keys.setParent(self)

    # -- set up
    def _reset(self) -> None:
        self.t, self.x, self.y = 0, 0, 500
        self.held, self.held_in = True, False
        self.toggles: list = []
        self.trail: list = [(0, 500)]
        self.i = 0
        self.acc = 0.0
        self.last = time.monotonic()
        self.dead_at = 0.0
        self.parts: list = []
        self._cam = None

    def load(self, seed: int, count_until: float = 0.0) -> None:
        """A new course: ready to start (after a countdown in a duel)."""
        self.seed = int(seed)
        self.course = WaveCourse(self.seed)
        self.course.ensure(4000)
        self.bot = WaveBot(WaveCourse(self.seed))            # 5.1: its own copy of the same course
        self._reset()
        self.message = ""
        self.can_retry = False
        self.state = "count" if count_until > time.monotonic() else "ready"
        self.count_until = count_until
        self.update()

    def wait(self, text: str = "") -> None:
        self.state = "wait"
        self.message = text
        self.update()

    # -- input
    def _press(self, on: bool) -> None:
        self.held_in = on
        if on and self.state == "ready":
            self._go()

    def _go(self) -> None:
        self.state = "run"
        try:                                              # 5.3: Ruben's secret god mode: the wave flies itself
            ctx = self.page.ctx
            self.autopilot = bool(ctx.cfg["godmode"] and ctx.cfg["cheats"] and ctx.econ.admin
                                  and (ctx.online.username() or "").lower() == "ruben" and self.course is not None)
        except Exception:  # noqa: BLE001
            self.autopilot = False
        self.autobot = WaveBot(WaveCourse(self.seed)) if self.autopilot else None
        self.held, self.t = True, 0
        self.acc, self.last = 0.0, time.monotonic()
        self.run_t0 = self.last
        sfx.play("pick")
        GamePerf.enter(self.ctx)                          # 6.0: the hidden performance mode, for this run only
        if self.on_start:
            self.on_start()

    def finish_now(self) -> None:
        """Duel: the other player crashed and you are past them. Your run ends here, safely (no crash)."""
        if self.state != "run":
            return
        self.god = True
        self.state = "safe"
        self.dead_at = time.monotonic()
        sfx.play("on")
        QTimer.singleShot(0, lambda: GamePerf.leave(self.ctx))
        if self.on_end:
            self.on_end(self.t, list(self.toggles), self.x)

    def set_other(self, name: str, toggles, upto: int, done: bool, final=None) -> None:
        if self.course is None:
            return
        if self.other is None:
            self.other = WaveRunner(self.course, name)
        self.other.set(toggles, upto, done, final)

    def start_replay(self, loser: WaveRunner, winner, title: str) -> None:
        """The last seconds before the crash, again: both waves, black bars, REPLAY."""
        end = loser.final if loser.final is not None else (loser.crash or loser.upto)
        loser.y(end + 40)
        if winner is not None:
            winner.y(end + 40)
        now = time.monotonic()
        wait = 0.0                                      # the other player first fades out where they crashed
        if self.other is not None and self.other.done and self.other.fade_at:
            wait = max(0.0, self.other.fade_at + 1.5 - now)
        rp = {"loser": loser, "winner": winner, "t0": max(0, end - 330), "t1": end, "at": now + wait + 0.5, "title": title}

        def go() -> None:
            try:
                self.replay = rp
                self.state = "replay"
                self.update()
            except RuntimeError:
                pass
        self._pending_replay = rp
        try:
            self.page.ctx.notifier.hold(wait + 0.5 + (rp["t1"] - rp["t0"]) / WAVE_TPS + 2.0)   # 4.6: no spoiler
        except AttributeError:
            pass
        QTimer.singleShot(int(wait * 1000), go)

    def mousePressEvent(self, e) -> None:
        e.accept()
        self.setFocus()
        if e.button() == Qt.MouseButton.LeftButton:
            self._press(True)

    def mouseReleaseEvent(self, e) -> None:
        if e.button() == Qt.MouseButton.LeftButton:
            self._press(False)

    def _key(self, _name: str, _down: bool) -> None:
        held = any(self.keys.down.values())
        if held != self.held_in or held:
            self._press(held)

    def keyPressEvent(self, e) -> None:
        if e.key() in (Qt.Key.Key_Space, Qt.Key.Key_Up, Qt.Key.Key_W):
            if not e.isAutoRepeat() and not self.keys.live:
                self._press(True)
            return e.accept()
        super().keyPressEvent(e)

    def keyReleaseEvent(self, e) -> None:
        if e.key() in (Qt.Key.Key_Space, Qt.Key.Key_Up, Qt.Key.Key_W):
            if not e.isAutoRepeat() and not self.keys.live:
                self._press(False)
            return e.accept()
        super().keyReleaseEvent(e)

    def hideEvent(self, _e) -> None:
        if self.state == "run":                       # no pausing in the middle of a run: hiding it ends it
            self._crash()
        self._timer.stop()
        GamePerf.leave(self.ctx)

    def showEvent(self, _e) -> None:
        self._timer.setInterval(self._frame_ms())
        self._timer.start()

    def _frame_ms(self) -> int:
        """6.0: the timer follows the screen's refresh rate (60, 75, 120, 144 Hz…), so every frame shown is a new
        position the same distance apart: no more judder from 125 frames a second on a 60 Hz screen."""
        try:
            scr = self.screen() or QGuiApplication.primaryScreen()
            hz = float(scr.refreshRate()) if scr is not None else 60.0
        except Exception:  # noqa: BLE001
            hz = 60.0
        hz = max(50.0, min(240.0, hz or 60.0))
        return max(4, int(1000.0 / hz))

    def closeEvent(self, e) -> None:
        GamePerf.leave(self.ctx)
        super().closeEvent(e)

    # -- the run: fixed 60 ticks a second
    def _tick(self) -> bool:
        b = getattr(self, "autobot", None)
        if b is not None:                                 # 5.3: god mode: a perfect path, real inputs (the server agrees)
            if not (len(b.ys) > self.t and b.ys[self.t] == self.y):
                b.ys = [self.y] * (self.t + 1)            # plan again from exactly where the wave is
            self.held_in = b.y(self.t + 1) < self.y
        self.t += 1
        if self.held_in != self.held:
            self.toggles.append(self.t)
            self.held = self.held_in
        self.x += WAVE_VX
        self.y += -WAVE_VX if self.held else WAVE_VX
        self.course.ensure(self.x)
        segs = self.course.segs
        while self.x >= segs[self.i][0] + segs[self.i][1]:
            self.i += 1
        top, bot = self.course.bounds(self.i, self.x)
        if self.t <= WAVE_SLIDE:                                   # 5.1: the start slides, it never crashes
            self.y = max(top + WAVE_R, min(bot - WAVE_R, self.y))
        self.trail.append((self.x, self.y))
        if len(self.trail) > 400:
            del self.trail[:100]
        if self.god:
            return True
        if getattr(self.ctx, "wave_god", False) and self.t < WAVE_MAX:     # 6.0: god mode: slide, never crash
            self.y = max(top + WAVE_R, min(bot - WAVE_R, self.y))
            if self.trail:
                self.trail[-1] = (self.x, self.y)
            return True
        if (self.t > WAVE_SLIDE and (self.y - WAVE_R < top or self.y + WAVE_R > bot)) or self.t >= WAVE_MAX:
            self._crash()
            return False
        return True

    def _crash(self) -> None:
        self.state = "dead"
        self.dead_at = time.monotonic()
        sfx.play("lose")
        QTimer.singleShot(0, lambda: GamePerf.leave(self.ctx))
        rnd = random.Random(self.t)
        self.parts = [(rnd.uniform(0, math.tau), rnd.uniform(90, 420), rnd.uniform(3, 7)) for _ in range(26)]
        if self.on_end:
            self.on_end(self.t, list(self.toggles), self.x)

    def _frame(self) -> None:
        now = time.monotonic()
        if self.state == "count" and now >= self.count_until:
            self.state = "ready"
            sfx.play("on")
            if self.auto_start:                   # duel: everyone starts at the same moment
                self._go()
        if self.state == "replay" and self.replay and now > self.replay["at"] + (self.replay["t1"] - self.replay["t0"]) / WAVE_TPS + 1.6:
            done, self.replay = self.replay.get("then"), None
            self.state = "wait"
            if done:
                done()
        if self.state == "run":
            self.acc += min(0.5, now - self.last)          # 5.13: a hitch of up to half a second is caught up, not lost
            self.last = now
            step = 1.0 / WAVE_TPS
            while self.acc >= step and self.state == "run":
                self.acc -= step
                self._tick()
            GamePerf.alive()
            try:
                self.ctx.notifier.hold(0.5)                # 6.0: no pop-up in the middle of a run
            except Exception:  # noqa: BLE001
                pass
        elif self.state in ("wait", "ready") and self.watch is None and self.replay is None:
            if now - self._idle_paint < 0.05:              # 6.0: nothing moving: 20 frames a second is plenty
                return
            self._idle_paint = now
        self.update()

    # -- drawing
    def _scale(self) -> float:
        return (self.height() - S(WAVE_HUD)) / WAVE_H

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        now = time.monotonic()
        full = QRectF(self.rect())
        hud_h = S(WAVE_HUD)
        clip = QPainterPath()
        clip.addRoundedRect(full.adjusted(0.5, 0.5, -0.5, -0.5), S(12), S(12))
        p.setClipPath(clip)
        p.fillRect(QRectF(0, 0, full.width(), hud_h), QColor("#07090C"))          # 5.1: the HUD's own strip
        p.fillRect(QRectF(0, hud_h - 1, full.width(), 1), alpha("#FFFFFF", 0.08))
        p.translate(0, hud_h)
        r = QRectF(0, 0, full.width(), full.height() - hud_h)
        clip2 = QPainterPath()
        clip2.addRect(r)
        p.setClipPath(clip2)
        sc = self._scale()
        focus = self._focus(now)
        d = wave_level(focus)
        col = level_colour(d)
        bg = QLinearGradient(r.topLeft(), r.bottomLeft())
        bg.setColorAt(0, mix(QColor("#06080C"), col, 0.10))
        bg.setColorAt(1, QColor("#050608"))
        p.fillRect(r, bg)
        cam = focus - r.width() * 0.28 / sc                 # course x at the left edge
        if self.state == "dead":                            # a short shake when it crashes
            k = max(0.0, 1.0 - (now - self.dead_at) / 0.35)
            p.translate(math.sin(now * 90) * S(5) * k, math.cos(now * 70) * S(4) * k)
        p.setPen(QPen(alpha("#FFFFFF", 0.035), 1))          # a grid that scrolls slower than the course
        step = 200
        first = int((cam * 0.5) // step) * step
        gx = first if self.state != "run" else 10 ** 9      # 6.0: skipped while running (performance mode)
        while (gx - cam * 0.5) * sc < r.width():
            xx = (gx - cam * 0.5) * sc
            p.drawLine(QPointF(xx, 0), QPointF(xx, r.height()))
            gx += step
        if self.course is not None:
            self._paint_course(p, r, cam, sc, col)
            if self.replay is None and self.watch is None:   # 5.3: where the coins start (the first 100 m pay nothing)
                self._paint_pay_line(p, r, cam, sc, now)
            if self.replay is not None:
                rp = self.replay
                t = self._replay_t(now)
                if rp["winner"] is not None:
                    self._paint_runner(p, r, cam, sc, rp["winner"], t, QColor("#FFB627"), 0.45, now)
                self._paint_runner(p, r, cam, sc, rp["loser"], t, col, 1.0, now, boom=True)
            elif self.watch is not None:
                ta = self._watch_t(0, now)
                tb = self._watch_t(1, now)
                self._paint_runner(p, r, cam, sc, self.watch[0], ta, ui.accent, 0.95, now, boom=True)
                self._paint_runner(p, r, cam, sc, self.watch[1], tb, QColor("#FFB627"), 0.95, now, boom=True)
            else:
                self._paint_bot(p, r, cam, sc, now)
                self._paint_ghost(p, r, cam, sc, now)
                self._paint_wave(p, r, cam, sc, col, now)
        if self.state == "run" and self.t <= WAVE_SLIDE and self.course is not None:     # 5.1: the start slide
            k = 1.0 - self.t / WAVE_SLIDE
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(alpha("#3DDC84", 0.18 * k))
            p.drawRect(QRectF(0, r.height() - S(8), r.width(), S(8)))
            p.drawRect(QRectF(0, 0, r.width(), S(8)))
            p.setPen(alpha("#FFFFFF", 0.85 * k))
            p.setFont(font(12, QFont.Weight.Bold))
            p.drawText(QRectF(0, r.height() * 0.12, r.width(), S(22)), int(Qt.AlignmentFlag.AlignCenter),
                       tr("Hold to go up, let go to go down"))
        p.setClipping(False)
        p.resetTransform()
        p.setClipPath(clip)
        play = QRectF(0, hud_h, full.width(), full.height() - hud_h)
        if self.replay is not None:
            p.translate(0, hud_h)
            return self._paint_replay_hud(p, QRectF(0, 0, play.width(), play.height()), now)
        self._paint_hud(p, play, col, now)

    def _paint_pay_line(self, p, r, cam, sc, now) -> None:
        xx = (WAVE_FREE_X - cam) * sc
        if xx < -S(80) or xx > r.width() + S(80):
            return
        gold = QColor("#FFC94D")
        pulse = 0.6 + 0.4 * math.sin(now * 3)
        p.setPen(QPen(alpha(gold, 0.25), S(8)))
        p.drawLine(QPointF(xx, 0), QPointF(xx, r.height()))
        p.setPen(QPen(alpha(gold, 0.55 + 0.35 * pulse), S(2), Qt.PenStyle.DashLine))
        p.drawLine(QPointF(xx, 0), QPointF(xx, r.height()))
        paint_coin(p, QPointF(xx, r.height() * 0.5), S(11))         # 6.0: the line and the coin say it, no words

    def _paint_course(self, p, r, cam, sc, col) -> None:
        c = self.course
        x_from, x_to = int(cam) - 20, int(cam + r.width() / sc) + 20
        c.ensure(x_to)
        xs, tops, bots = [], [], []
        i = c.index(max(0, x_from))
        x = max(0, x_from - x_from % 6)
        while x <= x_to:
            while i + 1 < len(c.segs) and x >= c.segs[i + 1][0]:
                i += 1
            t, b = c.bounds(i, x)
            xs.append((x - cam) * sc)
            tops.append(t * sc)
            bots.append(b * sc)
            x += 6
        if not xs:
            return
        if x_from < 0:                                     # before the start: a closed wall behind the wave
            p.fillRect(QRectF(0, 0, (0 - cam) * sc, r.height()), mix(QColor("#0B0F14"), col, 0.18))
        fill = QLinearGradient(QPointF(0, 0), QPointF(0, r.height()))
        fill.setColorAt(0, mix(QColor("#0B0F14"), col, 0.22))
        fill.setColorAt(0.5, mix(QColor("#0B0F14"), col, 0.10))
        fill.setColorAt(1, mix(QColor("#0B0F14"), col, 0.22))
        top_poly = QPolygonF([QPointF(xs[0], -S(4))] + [QPointF(a, b) for a, b in zip(xs, tops)] + [QPointF(xs[-1], -S(4))])
        bot_poly = QPolygonF([QPointF(xs[0], r.height() + S(4))] + [QPointF(a, b) for a, b in zip(xs, bots)] +
                             [QPointF(xs[-1], r.height() + S(4))])
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(fill)
        p.drawPolygon(top_poly)
        p.drawPolygon(bot_poly)
        for w, a in ((S(6), 0.18), (S(2.2), 1.0)):         # the glowing edge
            p.setPen(QPen(alpha(col, a), w, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawPolyline(QPolygonF([QPointF(a_, b_) for a_, b_ in zip(xs, tops)]))
            p.drawPolyline(QPolygonF([QPointF(a_, b_) for a_, b_ in zip(xs, bots)]))

    # -- the camera
    def _focus(self, now: float) -> float:
        if self.replay is not None:
            return self._replay_t(now) * WAVE_VX
        if self.watch is not None:
            return max(self._watch_t(0, now), self._watch_t(1, now)) * WAVE_VX
        if self._spectating():                             # 6.4: you crashed: the camera moves over to the other player
            gx = (self.other.disp if self.other.disp is not None else self.x / WAVE_VX) * WAVE_VX
            if self._cam is None:
                self._cam, self._cam_t = float(self.x), now
            self._cam += (gx - self._cam) * min(1.0, max(0.0, now - self._cam_t) * 5.0)
            self._cam_t = now
            return self._cam
        return self.x + self._sub() * WAVE_VX              # 5.7: smooth between two physics steps

    def _sub(self) -> float:
        """5.7: how far into the next 1/60 s step we are (0-1), to draw between steps: smooth at any frame rate."""
        if self.state != "run":
            return 0.0
        return max(0.0, min(1.0, self.acc * WAVE_TPS))

    def _replay_t(self, now: float) -> int:
        rp = self.replay
        return int(min(rp["t1"] + 30, rp["t0"] + max(0.0, now - rp["at"]) * WAVE_TPS))

    def _watch_t(self, i: int, now: float) -> float:
        """Spectating: where each player is shown (a little behind, so the path shown is the real one)."""
        return self._ghost_tick(self.watch[i], now, self.watch[2])

    def _ghost_tick(self, o, now: float, t0: float) -> float:
        """6.4: a smooth tick for another wave. It never goes past what the server told us (no guessing, so no waves
        running into walls) and it speeds up or slows down a little to stay about GHOST_LAG ticks behind real time."""
        cap = float(o.final) if (o.done and o.final is not None) else float(o.upto)
        if o.crash is not None:
            cap = min(cap, float(o.crash))
        target = (now - t0) * WAVE_TPS - GHOST_LAG if t0 else 0.0
        dt = min(0.25, max(0.0, now - o.stamp)) if o.stamp else 0.0
        o.stamp = now
        if o.disp is None or target - o.disp > WAVE_TPS * 6 or o.disp - target > WAVE_TPS * 3:
            o.disp = max(0.0, min(target, cap))
        else:
            gap = target - o.disp
            o.disp += dt * WAVE_TPS * max(0.3, min(2.5, 1.0 + gap / 30.0))
        o.disp = max(0.0, min(o.disp, cap))
        if o.done and o.final is not None and o.disp >= o.final - 0.01 and not o.reached:
            o.reached, o.reach_at, o.fade_at = True, now, now
        return o.disp

    def _spectating(self) -> bool:
        return (self.spectate and self.state == "dead" and self.other is not None
                and time.monotonic() - self.dead_at > 0.9)

    def ghost_ready(self) -> bool:
        """Duel: have we shown the other player's end (so the result can come up)?"""
        o = self.other
        if o is None or not o.done or o.final is None or not (self.spectate and self.state == "dead"):
            return True
        return o.reached or time.monotonic() - (o.fade_at or 0.0) > 7.0

    def _paint_runner(self, p, r, cam, sc, run: WaveRunner, t: int, col, opacity: float, now: float, boom=False) -> None:
        """Another wave: its trail and its arrow at tick t (or where it crashed)."""
        tf = float(t)
        end = int(tf)
        frac = tf - end
        if run.done and run.final is not None and end >= run.final:
            end, frac = int(run.final), 0.0
        if run.crash is not None and run.crash <= end + 1 and run.crash <= run.upto + 1:
            if end >= run.crash:
                end, frac = min(end, run.crash), 0.0
        if frac > 0 and end + 1 > run.upto:
            frac = 0.0
        first = max(0, end - 160)
        pts = [QPointF((k * WAVE_VX - cam) * sc, run.y(k) * sc) for k in range(first, end + 1, 2)]
        if not pts:
            return
        if frac > 0:
            run.y(end + 1)
            pts.append(QPointF(((end + frac) * WAVE_VX - cam) * sc, (run.y(end) + (run.y(end + 1) - run.y(end)) * frac) * sc))
        p.setOpacity(opacity)
        if len(pts) >= 2:
            for w, a in ((S(6), 0.12), (S(2.6), 0.8)):
                p.setPen(QPen(alpha(mix(col, QColor("#FFFFFF"), 0.45), a), w, Qt.PenStyle.SolidLine,
                              Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.MiterJoin))
                p.drawPolyline(QPolygonF(pts))
        c = pts[-1] if frac > 0 else QPointF((end * WAVE_VX - cam) * sc, run.y(end) * sc)
        crashed = run.done and run.final is not None and t >= run.final
        if crashed and boom:
            k = min(1.0, (t - run.final) / 25.0) if t > run.final else (
                min(1.0, (now - run.reach_at) / 0.5) if run.reach_at else 0.0)
            p.setPen(Qt.PenStyle.NoPen)
            for j in range(12):
                ang = j * math.tau / 12
                q = c + QPointF(math.cos(ang) * S(26) * k, math.sin(ang) * S(26) * k)
                p.setBrush(alpha(col, max(0.0, 1.0 - k)))
                p.drawEllipse(q, S(3), S(3))
        else:
            p.save()
            p.translate(c)
            p.rotate(-45 if run.held(end) else 45)
            size = S(10)
            head = QPolygonF([QPointF(size, 0), QPointF(-size * 0.8, -size * 0.7), QPointF(-size * 0.35, 0),
                              QPointF(-size * 0.8, size * 0.7)])
            p.setPen(QPen(QColor("#FFFFFF"), S(1.2)))
            p.setBrush(mix(QColor("#FFFFFF"), col, 0.5))
            p.drawPolygon(head)
            p.restore()
        if run.name:
            p.setPen(alpha(col, 0.95))
            p.setFont(font(9, QFont.Weight.Bold))
            p.drawText(QRectF(c.x() - S(60), c.y() - S(28), S(120), S(14)), int(Qt.AlignmentFlag.AlignCenter), run.name)
        p.setOpacity(1.0)

    def _paint_bot(self, p, r, cam, sc, now) -> None:
        """5.1: the practice bot, see-through, 40 ticks ahead of you."""
        if not self.bot_on or self.bot is None or self.state not in ("run", "ready", "count"):
            return
        t = (self.t + 40) if self.state == "run" else 40
        try:
            pts = [QPointF((k * WAVE_VX - cam) * sc, self.bot.y(k) * sc) for k in range(max(0, t - 90), t + 1, 2)]
        except Exception:  # noqa: BLE001
            return
        cyan = QColor("#4FE3FF")
        p.setOpacity(0.32)
        if len(pts) >= 2:
            p.setPen(QPen(cyan, S(2), Qt.PenStyle.DashLine, Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.MiterJoin))
            p.drawPolyline(QPolygonF(pts))
        c = pts[-1]
        up = len(pts) < 2 or pts[-1].y() < pts[-2].y()
        p.save()
        p.translate(c)
        p.rotate(-45 if up else 45)
        size = max(S(7), WAVE_R * sc * 2.2)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(cyan)
        p.drawPolygon(QPolygonF([QPointF(size, 0), QPointF(-size * 0.8, -size * 0.7), QPointF(-size * 0.35, 0),
                                 QPointF(-size * 0.8, size * 0.7)]))
        p.restore()
        p.setOpacity(0.55)
        p.setPen(cyan)
        p.setFont(font(8.5, QFont.Weight.Bold))
        p.drawText(QRectF(c.x() - S(40), c.y() - S(24), S(80), S(12)), int(Qt.AlignmentFlag.AlignCenter), "BOT")
        p.setOpacity(1.0)

    def _paint_ghost(self, p, r, cam, sc, now) -> None:
        """Duel: the other player, see-through (clear when you are watching them after your crash)."""
        o = self.other
        if o is None or self.state not in ("run", "safe", "dead") or not self.run_t0:
            return
        spec = self._spectating()
        tf = self._ghost_tick(o, now, self.run_t0)
        fade = 1.0
        if o.reached:                                 # they crashed: they fade out slowly where they crashed
            fade = max(0.0, 1.0 - (now - o.reach_at) / (3.0 if spec else 1.4))
            if fade <= 0:
                return
        t = int(tf)
        frac = tf - t
        o.y(t + 1)
        if o.crash is not None and t >= o.crash:
            t, frac = o.crash, 0.0
        y0 = o.y(t)
        hy = y0 + (o.y(t + 1) - y0) * frac if frac > 0 else y0
        first = max(0, t - 120)
        pts = [QPointF((k * WAVE_VX - cam) * sc, o.y(k) * sc) for k in range(first, t + 1, 3)]
        pts.append(QPointF(((t + frac) * WAVE_VX - cam) * sc, hy * sc))
        gold = QColor("#FFB627")
        base = 0.95 if spec else 0.38
        p.setOpacity(base * fade)
        if len(pts) >= 2:
            p.setPen(QPen(gold, S(3.0 if spec else 2.2), Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.MiterJoin))
            p.drawPolyline(QPolygonF(pts))
        c = pts[-1]
        if o.reached:
            k = min(1.0, (now - o.reach_at) / 0.5)
            p.setPen(Qt.PenStyle.NoPen)
            for j in range(12):
                ang = j * math.tau / 12
                p.setBrush(alpha(gold, max(0.0, 1.0 - k)))
                p.drawEllipse(c + QPointF(math.cos(ang) * S(26) * k, math.sin(ang) * S(26) * k), S(3), S(3))
        else:
            p.save()
            p.translate(c)
            p.rotate(-45 if o.held(t) else 45)
            size = S(12 if spec else 10)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(gold)
            p.drawPolygon(QPolygonF([QPointF(size, 0), QPointF(-size * 0.8, -size * 0.7), QPointF(-size * 0.35, 0),
                                     QPointF(-size * 0.8, size * 0.7)]))
            p.restore()
        p.setOpacity((0.95 if spec else 0.6) * fade)
        p.setPen(gold)
        p.setFont(font(8.5, QFont.Weight.Bold))
        p.drawText(QRectF(c.x() - S(50), c.y() - S(24), S(100), S(12)), int(Qt.AlignmentFlag.AlignCenter), o.name)
        p.setOpacity(1.0)

    def _paint_wave(self, p, r, cam, sc, col, now) -> None:
        f = self._sub()
        hx = self.x + f * WAVE_VX                          # 5.7: the head drawn between steps (never ahead of a wall hit)
        hy = self.y + f * (-WAVE_VX if self.held_in else WAVE_VX) if self.state == "run" else self.y
        pts = [QPointF((tx - cam) * sc, ty * sc) for tx, ty in self.trail if (tx - cam) * sc > -S(10)]
        if self.state == "run":
            pts.append(QPointF((hx - cam) * sc, hy * sc))
        if len(pts) >= 2:                                  # the trail: the zigzag you drew
            for w, a in (((S(3), 0.85),) if self.state == "run" else ((S(7), 0.12), (S(3), 0.85))):
                p.setPen(QPen(alpha(mix(col, QColor("#FFFFFF"), 0.55), a), w, Qt.PenStyle.SolidLine,
                              Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.MiterJoin))
                p.drawPolyline(QPolygonF(pts))
        c = QPointF((hx - cam) * sc, hy * sc)
        if self.state in ("wait",) and self.result:
            return
        if self.state == "dead":
            age = now - self.dead_at
            for ang, sp, sz in self.parts:
                k = min(1.0, age / 0.6)
                q = c + QPointF(math.cos(ang) * sp * sc * 0.6 * k * 2.2, math.sin(ang) * sp * sc * 0.6 * k * 2.2)
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(alpha(col if sz > 5 else QColor("#FFFFFF"), max(0.0, 1.0 - age / 0.9)))
                p.drawEllipse(q, S(sz) * (1 - 0.5 * k), S(sz) * (1 - 0.5 * k))
            return
        up = self.held if self.state == "run" else True
        p.save()
        p.translate(c)
        p.rotate(-45 if up else 45)
        size = max(S(7), WAVE_R * sc * 2.2)                      # 5.1: drawn the size of what can be hit
        head = QPolygonF([QPointF(size, 0), QPointF(-size * 0.8, -size * 0.7), QPointF(-size * 0.35, 0),
                          QPointF(-size * 0.8, size * 0.7)])
        p.setPen(QPen(alpha(col, 0.35), S(6)))
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawPolygon(head)
        p.setPen(QPen(QColor("#FFFFFF"), S(1.4)))
        p.setBrush(mix(QColor("#FFFFFF"), col, 0.35))
        p.drawPolygon(head)
        p.restore()

    def _paint_hud(self, p, r, col, now) -> None:
        if self.state == "wait":
            p.fillRect(r, alpha("#000000", 0.55))
            return self._paint_wait(p, r)
        x = self._focus(now)
        p.setPen(QColor(TEXT))
        p.setFont(font(17, QFont.Weight.Black))
        p.drawText(QRectF(S(12), S(2), r.width() * 0.28, S(26)), int(Qt.AlignmentFlag.AlignVCenter), f"{metres(int(x))} m")
        if getattr(self.ctx, "wave_god", False):         # 6.0: Ruben's god mode is on
            p.setPen(QColor("#FF5C8A"))
            p.setFont(font(10, QFont.Weight.Black, 1.5))
            p.drawText(QRectF(r.width() * 0.3, S(4), S(60), S(22)), int(Qt.AlignmentFlag.AlignVCenter), "GOD")
        p.setFont(font(9.5, QFont.Weight.Bold))
        p.setPen(QColor(TEXT_DIM))
        if self.watch is None and self.replay is None and self.state in ("run", "ready", "count") and x < WAVE_FREE_X:
            p.setPen(QColor("#FFC94D"))                   # 5.3: the first 100 m pay nothing
            p.drawText(QRectF(S(12), S(26), r.width() * 0.28, S(16)), int(Qt.AlignmentFlag.AlignVCenter),
                       tr("Coins from {n} m", n=metres(WAVE_FREE_X)))
        elif self.best and self.watch is None:
            p.drawText(QRectF(S(12), S(26), r.width() * 0.28, S(16)), int(Qt.AlignmentFlag.AlignVCenter),
                       tr("Best {n} m", n=metres(self.best)))
        self._paint_difficulty(p, r, self._focus(now), now)
        mid = QRectF(0, r.top() + r.height() * 0.30, r.width(), r.height() * 0.4)
        if self.state in ("ready", "count", "dead", "safe"):
            dim = 0.0 if (self.state in ("dead", "safe") and now - self.dead_at < 0.45) or self._spectating() else 0.55
            if dim:
                p.fillRect(r, alpha("#000000", dim))     # 5.1: r is the course only, the HUD strip stays readable
        if self.state == "count":
            n = max(1, math.ceil(self.count_until - now))
            self._big(p, mid, str(n), "#FFFFFF", 40)
        elif self.state == "ready":
            pulse = 0.75 + 0.25 * math.sin(now * 4)
            self._big(p, mid.adjusted(0, -S(14), 0, -S(14)), tr("Hold to start"), alpha("#FFFFFF", pulse), 20)
            pass
            labels = ["Hold", "Space", "Up", "W"]
            x = r.width() / 2 - S(62)
            for k in labels:
                x += paint_keycap(p, QPointF(x, mid.center().y() + S(24)), k) + S(6)
        elif self.state == "safe":
            self._big(p, mid.adjusted(0, -S(10), 0, -S(10)), tr("You outlasted them!"), "#3DDC84", 18)
            if self.message:
                self._big(p, mid.adjusted(0, S(20), 0, S(20)), self.message, self.message_col, 11.5)
        elif self.state == "dead" and self._spectating():
            self._big(p, QRectF(r.left(), r.top() + S(40), r.width(), S(22)),
                      tr("You crashed at {n} m  ·  watching {name}", n=metres(self.x), name=self.other.name), "#FFFFFF", 11.5)
        elif self.state == "dead" and now - self.dead_at >= 0.45:
            self._big(p, mid.adjusted(0, -S(22), 0, -S(22)), tr("Crashed at {n} m", n=metres(self.x)), "#FFFFFF", 20)
            if self.message:
                self._big(p, mid.adjusted(0, S(12), 0, S(12)), self.message, self.message_col, 12.5)
            if self.can_retry and now - self.dead_at > 0.9:
                pulse = 0.6 + 0.4 * math.sin(now * 4)
                self._big(p, mid.adjusted(0, S(44), 0, S(44)), tr("Press to go again"), alpha("#FFFFFF", pulse), 11)

    def _paint_difficulty(self, p, r, x: float, now: float) -> None:
        """4.5: no finish line, so no progress bar: a difficulty bar that keeps climbing, with the distance riding on it
        and the distance where the next level starts."""
        d = wave_level(int(x))
        bar = QRectF(r.width() * 0.30, S(13), r.width() * 0.66, S(7))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(alpha("#FFFFFF", 0.08))
        p.drawRoundedRect(bar, bar.height() / 2, bar.height() / 2)
        g = QLinearGradient(bar.topLeft(), bar.topRight())
        for k in range(5):
            g.setColorAt(k / 4, level_colour(k * 250))
        fill = QRectF(bar.left(), bar.top(), max(bar.height(), bar.width() * d / 1000), bar.height())
        p.setBrush(g)
        p.drawRoundedRect(fill, bar.height() / 2, bar.height() / 2)
        if d < 1000:                                         # a soft shine running along the fill
            sx = fill.left() + (now * 0.6 % 1.0) * fill.width()
            sh = QLinearGradient(QPointF(sx - S(14), 0), QPointF(sx + S(14), 0))
            sh.setColorAt(0, alpha("#FFFFFF", 0.0))
            sh.setColorAt(0.5, alpha("#FFFFFF", 0.35))
            sh.setColorAt(1, alpha("#FFFFFF", 0.0))
            p.setBrush(sh)
            p.drawRoundedRect(fill, bar.height() / 2, bar.height() / 2)
        p.setFont(font(8, QFont.Weight.Bold))
        for (lo, name), metres_at in zip(WAVE_TIERS[1:], (250, 500, 750, 1000)):    # where each level starts
            tx = bar.left() + bar.width() * lo / 1000
            p.setPen(QPen(alpha("#FFFFFF", 0.55 if d >= lo else 0.25), 1))
            p.drawLine(QPointF(tx, bar.top() - S(2)), QPointF(tx, bar.bottom() + S(2)))
            p.setPen(alpha("#FFFFFF", 0.55 if d >= lo else 0.35))
            p.drawText(QRectF(tx - S(30), bar.bottom() + S(2), S(60), S(12)), int(Qt.AlignmentFlag.AlignCenter),
                       f"{metres_at} m")
        ti = wave_tier_of(d)
        col = level_colour(d)
        p.setPen(col)
        p.setFont(font(9.5, QFont.Weight.Black))
        p.drawText(QRectF(bar.left(), bar.top() - S(13), bar.width(), S(12)), int(Qt.AlignmentFlag.AlignLeft |
                   Qt.AlignmentFlag.AlignVCenter), tr(WAVE_TIERS[ti][1]).upper())
        p.setPen(QColor(TEXT_DIM))
        p.setFont(font(8.5, QFont.Weight.Bold))
        nxt = tr("Next level at {n} m", n=WAVE_TIERS[ti + 1][0] * 110 // 100) if ti + 1 < len(WAVE_TIERS) else \
            (tr("Hardest level") if d >= 1000 else tr("Hardest at {n} m", n=1100))
        p.drawText(QRectF(bar.left(), bar.top() - S(13), bar.width(), S(12)), int(Qt.AlignmentFlag.AlignRight |
                   Qt.AlignmentFlag.AlignVCenter), nxt)

    def _paint_replay_hud(self, p, r, now: float) -> None:
        rp = self.replay
        k = min(1.0, max(0.0, (now - rp["at"] + 0.5) / 0.45))
        bh = r.height() * 0.11 * k                           # black bars slide in
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor(0, 0, 0, 235))
        p.drawRect(QRectF(0, 0, r.width(), bh))
        p.drawRect(QRectF(0, r.height() - bh, r.width(), bh))
        if now < rp["at"]:                                   # the fade in
            p.fillRect(r, QColor(0, 0, 0, max(0, min(255, int(255 * (rp["at"] - now) / 0.5)))))
        dot = 0.5 + 0.5 * math.sin(now * 6)
        p.setBrush(alpha("#FF3B3B", 0.4 + 0.6 * dot))
        p.drawEllipse(QPointF(S(16), bh / 2), S(4.5), S(4.5))
        p.setPen(QColor("#FFFFFF"))
        p.setFont(font(12, QFont.Weight.Black, 2.0))
        p.drawText(QRectF(S(26), 0, S(120), bh), int(Qt.AlignmentFlag.AlignVCenter), tr("REPLAY"))
        p.setPen(QColor(TEXT_DIM))
        p.setFont(font(10, QFont.Weight.Bold))
        p.drawText(QRectF(0, 0, r.width() - S(12), bh), int(Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignRight),
                   rp["title"])
        span = max(1, rp["t1"] + 30 - rp["t0"])
        f = (self._replay_t(now) - rp["t0"]) / span
        line = QRectF(S(12), r.height() - bh / 2 - S(1.5), r.width() - S(24), S(3))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(alpha("#FFFFFF", 0.15))
        p.drawRoundedRect(line, S(1.5), S(1.5))
        p.setBrush(QColor("#FF3B3B"))
        p.drawRoundedRect(QRectF(line.left(), line.top(), line.width() * min(1.0, f), line.height()), S(1.5), S(1.5))

    def _paint_wait(self, p, r) -> None:
        mid = QRectF(0, r.top() + r.height() * 0.30, r.width(), r.height() * 0.4)
        if self.result:
            title, line, colour = self.result
            self._big(p, mid.adjusted(0, -S(16), 0, -S(16)), title, colour, 24)
            self._big(p, mid.adjusted(0, S(20), 0, S(20)), line, TEXT, 12.5)
        else:
            self._big(p, mid, self.message or tr("Loading…"), TEXT_DIM, 13)

    def _big(self, p, rect, text, colour, size) -> None:
        p.setPen(QColor(colour) if not isinstance(colour, QColor) else colour)
        p.setFont(font(size, QFont.Weight.Black))
        p.drawText(rect, int(Qt.AlignmentFlag.AlignCenter), text)


